/// Fix (B) — per-caller MCS reply objects so the executive's dispatch composes with nested service.
/// The kernel has a SINGLE per-TCB `reply_to` stash; `finish_call` (endpoint.rs) UNCONDITIONALLY
/// overwrites it with the latest caller. When a win32k SSN handler FAULTS while the executive is
/// mid-servicing a csrss syscall, the fault Call clobbers `reply_to` from csrss -> win32k and
/// csrss's pending reply is orphaned. Binding each channel's caller to its OWN `Cap::Reply`
/// (recv-with-r12 + Send-on-reply-cap / decode_reply) resumes exactly that caller regardless of
/// `reply_to`. REPLY_MAIN backs the main service loop (csrss/smss); REPLY_W32 backs win32k's
/// demand-page faults during a dispatch. cptr 0 = "not yet retyped" (legacy reply_to fallback).
static REPLY_MAIN_SLOT: AtomicU64 = AtomicU64::new(0);
static REPLY_W32_SLOT: AtomicU64 = AtomicU64::new(0);
static REPLY_TRANSPORT_PROBE_SLOT: AtomicU64 = AtomicU64::new(0);

/// ★ COMPONENT-DISPATCH TRANSPORT (`docs/transport-migration.md`): ONE dedicated MCS reply object
/// per launched Family-A IRP driver instance. These back the `Call`(component) to `reply_on`
/// (executive) transport that replaces the hand-rolled Send/Recv dispatch pair.
///
/// One object per component is sufficient at any nesting depth: a component host has one TCB, so it
/// is blocked in at most one `Call` at a time. These reply objects are dedicated, never entered into
/// `WAIT_REPLY_POOL`, never rotated, and never stolen by wait/pipe/dbgk/iocp parking.
static mut REPLY_FSD_SLOTS: Option<Vec<u64>> = None;

/// The dedicated reply object backing driver instance `i`'s dispatch transport (0 = none).
#[allow(dead_code)] // Phase 0: additive, wired in Phase 1.
pub(crate) fn fsd_reply_slot(i: usize) -> u64 {
    unsafe {
        (*core::ptr::addr_of!(REPLY_FSD_SLOTS))
            .as_ref()
            .and_then(|slots| slots.get(i).copied())
            .unwrap_or(0)
    }
}

unsafe fn fsd_reply_slots_mut() -> &'static mut Vec<u64> {
    let slot = &mut *core::ptr::addr_of_mut!(REPLY_FSD_SLOTS);
    if slot.is_none() {
        *slot = Some(Vec::new());
    }
    slot.as_mut().unwrap()
}

pub(crate) fn ensure_fsd_reply_slot(i: usize) -> u64 {
    unsafe {
        let slots = fsd_reply_slots_mut();
        while slots.len() <= i {
            let rf = alloc_slot();
            if untyped_retype_r(CAP_INIT_UNTYPED, OBJ_REPLY, 0, 1, rf) != 0 || rf == 0 {
                return 0;
            }
            slots.push(rf);
        }
        slots[i]
    }
}

/// ═══ Checkpoint B: real reply-cap parking for NtWaitForSingleObject on unsignaled events ═══
/// A parked waiter = a hosted thread that issued `NtWaitForSingleObject` on an event whose
/// `signalled` flag is 0. Instead of returning STATUS_WAIT_0 with the thread still runnable (the
/// old immediate-return stub, which made rpcrt4/winlogon proceed on unsatisfied state), the service
/// loop DOESN'T reply — the thread stays blocked in-kernel on its Call. To keep it bound while the
/// loop keeps receiving other callers, we can't re-use the single REPLY_MAIN reply object for the
/// next recv (that would rebind + orphan the parked caller), so the loop STEALS the reply object that
/// received this caller into a waiter slot and rotates REPLY_MAIN_SLOT to a fresh POOL object for
/// subsequent recvs. On `NtSetEvent(that event)` the loop does `client_reply_on(stolen_cap, WAIT_0)` to
/// wake exactly that parked caller, then returns the reply object to the pool. No new kernel
/// primitive — reuses the existing MCS reply-cap machinery (recv-with-r12 + Send-on-reply).
const WAIT_REPLY_POOL_N: usize = HOSTED_THREAD_RUNTIME_CAP + 1;
const WAIT_REPLY_POOL_USED_WORDS: usize = (WAIT_REPLY_POOL_N + 63) / 64;
/// The pool of spare MCS Reply objects (cptrs) allocated at boot. Index 0 is the "active" one
/// currently installed in REPLY_MAIN_SLOT; the rest are free spares. A park swaps the active out
/// (into a waiter slot) and installs a free spare as the new active.
static WAIT_REPLY_POOL: [AtomicU64; WAIT_REPLY_POOL_N] =
    [const { AtomicU64::new(0) }; WAIT_REPLY_POOL_N];
/// Free/used bitmap for the pool (bit i set = pool[i] is currently the active REPLY_MAIN or is held
/// by a parked waiter). Managed by wait_park / wait_wake_event.
static WAIT_REPLY_POOL_USED: [AtomicU64; WAIT_REPLY_POOL_USED_WORDS] =
    [const { AtomicU64::new(0) }; WAIT_REPLY_POOL_USED_WORDS];

#[derive(Clone, Copy)]
struct ThreadWaitParkTable<const N: usize> {
    badges_plus_one: [u64; N],
}

impl<const N: usize> ThreadWaitParkTable<N> {
    const fn new() -> Self {
        Self {
            badges_plus_one: [0; N],
        }
    }

    fn reset(&mut self) {
        self.badges_plus_one = [0; N];
    }

    fn contains(&self, badge: u64) -> bool {
        let needle = badge.saturating_add(1);
        needle != 0 && self.badges_plus_one.contains(&needle)
    }

    fn park(&mut self, badge: u64) {
        let encoded = badge.saturating_add(1);
        if encoded == 0 || self.contains(badge) {
            return;
        }
        if let Some(slot) = self.badges_plus_one.iter_mut().find(|slot| **slot == 0) {
            *slot = encoded;
        }
    }

    fn clear(&mut self, badge: u64) {
        let encoded = badge.saturating_add(1);
        if encoded == 0 {
            return;
        }
        for slot in &mut self.badges_plus_one {
            if *slot == encoded {
                *slot = 0;
            }
        }
    }
}

static mut THREAD_WAIT_PARKED: ThreadWaitParkTable<HOSTED_THREAD_RUNTIME_CAP> =
    ThreadWaitParkTable::new();
/// Compact identity for an NT object that can satisfy a native wait.
///
/// Dispatcher namespace objects keep their historical raw encoding (the obj_ns index), so existing
/// wait counters and debug-object proofs stay readable. Process/thread objects and win32k's
/// client-visible event handles are tagged in the high bits.
#[derive(Copy, Clone, Eq, PartialEq)]
pub(crate) struct WaitObject(u64);

impl WaitObject {
    const KIND_SHIFT: u64 = 60;
    const ID_MASK: u64 = (1u64 << Self::KIND_SHIFT) - 1;
    pub(crate) const KIND_DISPATCHER: u64 = 0;
    pub(crate) const KIND_PROCESS: u64 = 1;
    pub(crate) const KIND_THREAD: u64 = 2;
    pub(crate) const KIND_WIN32K_EVENT: u64 = 3;
    pub(crate) const KIND_FILE: u64 = 4;

    pub(crate) const FREE: Self = Self(u64::MAX);

    pub(crate) const fn dispatcher(index: usize) -> Self {
        Self(index as u64)
    }

    pub(crate) const fn process(pid: nt_process::ProcessId) -> Self {
        Self((Self::KIND_PROCESS << Self::KIND_SHIFT) | pid as u64)
    }

    pub(crate) const fn thread(tid: nt_process::ThreadId) -> Self {
        Self((Self::KIND_THREAD << Self::KIND_SHIFT) | tid as u64)
    }

    pub(crate) const fn win32k_event_body(body: u64) -> Self {
        Self((Self::KIND_WIN32K_EVENT << Self::KIND_SHIFT) | (body & Self::ID_MASK))
    }

    pub(crate) const fn file(file_id: u64) -> Self {
        Self((Self::KIND_FILE << Self::KIND_SHIFT) | (file_id & Self::ID_MASK))
    }

    pub(crate) const fn raw(self) -> u64 {
        self.0
    }

    pub(crate) const fn from_raw(raw: u64) -> Option<Self> {
        if raw == Self::FREE.0 {
            None
        } else {
            Some(Self(raw))
        }
    }

    pub(crate) const fn kind(self) -> u64 {
        self.0 >> Self::KIND_SHIFT
    }

    pub(crate) const fn id(self) -> u64 {
        self.0 & Self::ID_MASK
    }

    pub(crate) fn describe(self) -> &'static [u8] {
        match self.kind() {
            Self::KIND_DISPATCHER => b"dispatcher",
            Self::KIND_PROCESS => b"process",
            Self::KIND_THREAD => b"thread",
            Self::KIND_WIN32K_EVENT => b"win32k-event",
            Self::KIND_FILE => b"file",
            _ => b"unknown",
        }
    }
}

/// The waiter queue: each slot parks one blocked caller.
///
/// A single-object wait (NtWaitForSingleObject) records ONE wait object in slot 0 of its set
/// (count 1); a multi-object wait (NtWaitForMultipleObjects) records up to `WAITER_MAX_EVENTS`
/// typed wait objects + a `wait_all` flag. `WAITER_EVENT_IDX[i]` == `WaitObject::FREE.raw()` means
/// the slot is free (it doubles as event[0]).
const WAITER_N: usize = HOSTED_THREAD_RUNTIME_CAP;
/// NT's architectural maximum for one multi-object wait.
const WAITER_MAX_EVENTS: usize = 64;
/// object[0] of each waiter's set (u64::MAX = free slot). Kept as the slot-free sentinel for backward
/// compat with the single-object callers/spec.
static WAITER_EVENT_IDX: [AtomicU64; WAITER_N] = [const { AtomicU64::new(u64::MAX) }; WAITER_N];
/// The FULL object set for a multi-object waiter (object[1..count]; object[0] is WAITER_EVENT_IDX).
static WAITER_EVENTS: [[AtomicU64; WAITER_MAX_EVENTS]; WAITER_N] =
    [const { [const { AtomicU64::new(u64::MAX) }; WAITER_MAX_EVENTS] }; WAITER_N];
/// Original caller-array index for each compacted real wait object.
static WAITER_RESULT_INDEX: [[AtomicU64; WAITER_MAX_EVENTS]; WAITER_N] =
    [const { [const { AtomicU64::new(0) }; WAITER_MAX_EVENTS] }; WAITER_N];
/// Serialized service-loop work buffers, kept off the bounded rootserver stack.
static mut PARK_WAIT_SET_WORK: [WaitObject; WAITER_MAX_EVENTS] =
    [WaitObject::FREE; WAITER_MAX_EVENTS];
static mut PARK_WAIT_INDEX_WORK: [u8; WAITER_MAX_EVENTS] = [0; WAITER_MAX_EVENTS];
/// Number of events in this waiter's set (1 for a single-object wait).
static WAITER_EVENT_COUNT: [AtomicU64; WAITER_N] = [const { AtomicU64::new(0) }; WAITER_N];
/// Wait mode: 0 = WaitAny (WAIT_TYPE WaitAnyObject — wake on the first signalled event, return its
/// index as STATUS_WAIT_0+i), 1 = WaitAll (wake only when ALL events are signalled, return WAIT_0).
static WAITER_WAIT_ALL: [AtomicU64; WAITER_N] = [const { AtomicU64::new(0) }; WAITER_N];
static WAITER_REPLY_CAP: [AtomicU64; WAITER_N] = [const { AtomicU64::new(0) }; WAITER_N];
static WAITER_TID: [AtomicU64; WAITER_N] = [const { AtomicU64::new(0) }; WAITER_N];
/// Monotonic 100ns deadline (`u64::MAX` = infinite) for finite event waits.
static WAITER_DEADLINE: [AtomicU64; WAITER_N] = [const { AtomicU64::new(u64::MAX) }; WAITER_N];
/// The parked waiter's syscall resume context (RCX/RSP/RFLAGS): a native-syscall (UnknownSyscall)
/// fault is resumed by an apply_fault_reply that restores RCX←resume_ip, RSP←sp, RFLAGS←flags and
/// RAX/r10←status. The service loop sets these in the IPC buffer at reply time, so we must snapshot
/// them per-waiter at park and re-install them (set_reply_mr 15/16/17) before the wake send.
static WAITER_RESUME_IP: [AtomicU64; WAITER_N] = [const { AtomicU64::new(0) }; WAITER_N];
static WAITER_RESUME_SP: [AtomicU64; WAITER_N] = [const { AtomicU64::new(0) }; WAITER_N];
static WAITER_RESUME_FLAGS: [AtomicU64; WAITER_N] = [const { AtomicU64::new(0) }; WAITER_N];
/// Diagnostics/proof counters for the specs: how many waiters have been parked and woken.
static WAIT_PARKED_COUNT: AtomicU64 = AtomicU64::new(0);
static WAIT_WOKEN_COUNT: AtomicU64 = AtomicU64::new(0);
static WAIT_WAKE_TRACE_COUNT: AtomicU64 = AtomicU64::new(0);
static WAIT_PARK_INVALID_SET: AtomicU64 = AtomicU64::new(0);
static WAIT_PARK_NO_WAITER_SLOT: AtomicU64 = AtomicU64::new(0);
static WAIT_PARK_NO_REPLY_CAP: AtomicU64 = AtomicU64::new(0);
static mut WAIT_WAKE_INDEX_WORK: [u64; WAITER_N] = [u64::MAX; WAITER_N];
static mut WAIT_WAKE_OBJECT_WORK: [u64; WAITER_N] = [WaitObject::FREE.raw(); WAITER_N];

/// Blocking `NtRemoveIoCompletion` calls. One reply object remains active so the executive can
/// continue receiving while every other reply cap is parked.
const IO_COMPLETION_WAITER_N: usize = WAIT_REPLY_POOL_N - 1;
static mut IO_COMPLETION_WAITERS: nt_io_completion::CompletionWaiterTable<IO_COMPLETION_WAITER_N> =
    nt_io_completion::CompletionWaiterTable::new();
static IO_COMPLETION_PARKED_COUNT: AtomicU64 = AtomicU64::new(0);
static IO_COMPLETION_WOKEN_COUNT: AtomicU64 = AtomicU64::new(0);
static IO_COMPLETION_TIMEOUT_COUNT: AtomicU64 = AtomicU64::new(0);

/// Keyed-event waiters (`NtWaitForKeyedEvent`) use the same reply-cap parking model as object-event
/// waits, but are keyed by an arbitrary user pointer instead of an object-namespace event index.
/// ReactOS condition variables pass the address of each stack wait-entry's `WaitKey` field and wake
/// with `NtReleaseKeyedEvent(..., &Entry->WaitKey, ...)`.
const KEYED_WAITER_N: usize = 16;
static KEYED_WAITER_KEY: [AtomicU64; KEYED_WAITER_N] =
    [const { AtomicU64::new(u64::MAX) }; KEYED_WAITER_N];
static KEYED_WAITER_REPLY_CAP: [AtomicU64; KEYED_WAITER_N] =
    [const { AtomicU64::new(0) }; KEYED_WAITER_N];
static KEYED_WAITER_TID: [AtomicU64; KEYED_WAITER_N] =
    [const { AtomicU64::new(0) }; KEYED_WAITER_N];
static KEYED_WAITER_DEADLINE: [AtomicU64; KEYED_WAITER_N] =
    [const { AtomicU64::new(u64::MAX) }; KEYED_WAITER_N];
static KEYED_WAITER_RESUME_IP: [AtomicU64; KEYED_WAITER_N] =
    [const { AtomicU64::new(0) }; KEYED_WAITER_N];
static KEYED_WAITER_RESUME_SP: [AtomicU64; KEYED_WAITER_N] =
    [const { AtomicU64::new(0) }; KEYED_WAITER_N];
static KEYED_WAITER_RESUME_FLAGS: [AtomicU64; KEYED_WAITER_N] =
    [const { AtomicU64::new(0) }; KEYED_WAITER_N];
/// Release-before-wait rendezvous slots for `NtReleaseKeyedEvent(..., Timeout = NULL)`. ReactOS
/// `RtlRunOnceComplete` releases stack wait keys after publishing the waiter list; a waiter can be
/// preempted between linking that key and entering `NtWaitForKeyedEvent`. A real keyed event pairs
/// those two sides instead of dropping the release.
const KEYED_RELEASE_N: usize = 16;
static KEYED_RELEASE_KEY: [AtomicU64; KEYED_RELEASE_N] =
    [const { AtomicU64::new(u64::MAX) }; KEYED_RELEASE_N];
static KEYED_RELEASE_COUNT: [AtomicU64; KEYED_RELEASE_N] =
    [const { AtomicU64::new(0) }; KEYED_RELEASE_N];
static KEYED_WAIT_PARKED_COUNT: AtomicU64 = AtomicU64::new(0);
static KEYED_WAIT_WOKEN_COUNT: AtomicU64 = AtomicU64::new(0);

// ─── BATCH 33: pipe-pending completion (park a pending pipe read, re-drive on peer write) ─────────
/// The parked-pipe-read table (host-tested `nt_io_manager::PipeWaiterTable`). A caller whose npfs
/// pipe read / FSCTL_PIPE_LISTEN / TRANSCEIVE returned STATUS_PENDING is parked here — its seL4 reply
/// cap withheld (stolen into a pool like the event waiters), keyed by the reading end's npfs file-id
/// — and re-driven when the peer writes. `.bss`-resident (no heap), single-threaded executive (no
/// races).
///
/// ★ PHASE 4 left this at 16 and MEASURED it instead. The LSA worker route adds a whole second
/// rpcrt4 connection on top of the SCM/CSR listeners already parked, so exhaustion was the first
/// suspect for the route's lost `LsarOpenPolicy` response — and it was WRONG: `PIPE_WAITERS_FULL` is
/// **0** on every route-ON boot (the real cause was per-connection park exclusivity, see
/// `PIPE_FULL_DUPLEX_PARK` in `exec_handler.rs`). Raising it to 32 was tried and reverted: it is
/// unneeded, and this boot is timing-sensitive enough that an unnecessary `.bss` change is not free.
/// What DID change is that a full table is no longer SILENT — it is a functional degrade (the park
/// site returns `STATUS_INSUFFICIENT_RESOURCES` for an I/O that should merely have completed later)
/// and it is now counted by `PIPE_WAITERS_FULL`, asserted 0 by `exec_lsa_worker_route`.
const PIPE_WAITER_N: usize = 16;
static mut PIPE_WAITERS: nt_io_manager::PipeWaiterTable<PIPE_WAITER_N> =
    nt_io_manager::PipeWaiterTable::new();
/// ★ Times an async pipe read/write park was REFUSED because [`PIPE_WAITERS`] was full. A refusal is
/// a silent functional degrade (the caller gets `STATUS_INSUFFICIENT_RESOURCES` for an I/O that
/// should have completed later), so this must be **0**. See `PIPE_WAITER_N`.
pub(crate) static PIPE_WAITERS_FULL: AtomicU64 = AtomicU64::new(0);
/// Proof/diagnostic counters (specs + boot log): pipe reads parked, and woken by a peer write.
static PIPE_WAIT_PARKED_COUNT: AtomicU64 = AtomicU64::new(0);
static PIPE_WAIT_WOKEN_COUNT: AtomicU64 = AtomicU64::new(0);
static PIPE_REDRIVE_TRACE_COUNT: AtomicU64 = AtomicU64::new(0);
// ─── BATCH 34: the async ncacn_np SERVER completion edge ──────────────────────────────────────────
/// Pending async server-side `FSCTL_PIPE_LISTEN`s (host-tested `nt_io_manager::AsyncListenTable`). The
/// ncacn_np rpcrt4 server posts an OVERLAPPED FSCTL_PIPE_LISTEN (STATUS_PENDING while no client) with a
/// completion EVENT, then parks on `NtWaitForMultipleObjects([mgr_event, listen_event])` — it does NOT
/// block on a pipe read. When the client (winlogon) connects/writes, the executive completes the
/// pending listen + signals its event through the shared dispatcher wake path so the
/// server's wait-array wakes → it reads the bind PDU → rpcrt4 emits bind_ack. `.bss`, cap 8.
const PIPE_ASYNC_LISTEN_N: usize = 8;
static mut PIPE_ASYNC_LISTENS: nt_io_manager::AsyncListenTable<PIPE_ASYNC_LISTEN_N> =
    nt_io_manager::AsyncListenTable::new();
const PIPE_NAME_WAITER_N: usize = WAIT_REPLY_POOL_N - 1;
static mut PIPE_NAME_WAITERS: nt_io_manager::PipeNameWaiterTable<PIPE_NAME_WAITER_N> =
    nt_io_manager::PipeNameWaiterTable::new();
static mut PIPE_IO_CANCEL_REPLY_CAPS_WORK: [u64; PIPE_WAITER_N] = [0; PIPE_WAITER_N];
static mut PIPE_NAME_CANCEL_REPLY_CAPS_WORK: [u64; PIPE_NAME_WAITER_N] = [0; PIPE_NAME_WAITER_N];
/// Proof/diagnostic counters: server listens armed, and completed (client connect → event signalled).
static PIPE_LISTEN_ARMED_COUNT: AtomicU64 = AtomicU64::new(0);
static PIPE_LISTEN_SIGNALLED_COUNT: AtomicU64 = AtomicU64::new(0);
static PIPE_LISTEN_TRACE_COUNT: AtomicU64 = AtomicU64::new(0);
static PIPE_NAME_WAIT_PARKED_COUNT: AtomicU64 = AtomicU64::new(0);
static PIPE_NAME_WAIT_WOKEN_COUNT: AtomicU64 = AtomicU64::new(0);
static PIPE_NAME_WAIT_TIMEOUT_COUNT: AtomicU64 = AtomicU64::new(0);
static PIPE_NAME_WAIT_TRACE_COUNT: AtomicU64 = AtomicU64::new(0);
/// A tiny fid → pipe-leaf-name-hash map, populated at `NtCreateNamedPipeFile` (server) and queried at
/// FSCTL_PIPE_LISTEN arm time — so the async-listen record carries the pipe name-hash and a client
/// connect completes ONLY the matching-name server listen. Fixed cap, `.bss`, single-threaded.
const PIPE_FID_NAME_N: usize = 32;
static PIPE_FID_NAME_FID: [AtomicU64; PIPE_FID_NAME_N] =
    [const { AtomicU64::new(0) }; PIPE_FID_NAME_N];
static PIPE_FID_NAME_HASH: [AtomicU64; PIPE_FID_NAME_N] =
    [const { AtomicU64::new(0) }; PIPE_FID_NAME_N];
/// Record (or update) `fid → name_hash`. Replaces an existing entry for `fid`.
pub(crate) fn pipe_fid_name_remember(fid: u64, name_hash: u64) {
    if fid == 0 {
        return;
    }
    // Update existing.
    for i in 0..PIPE_FID_NAME_N {
        if PIPE_FID_NAME_FID[i].load(Ordering::Relaxed) == fid {
            PIPE_FID_NAME_HASH[i].store(name_hash, Ordering::Relaxed);
            return;
        }
    }
    // Insert into a free slot.
    for i in 0..PIPE_FID_NAME_N {
        if PIPE_FID_NAME_FID[i].load(Ordering::Relaxed) == 0 {
            PIPE_FID_NAME_FID[i].store(fid, Ordering::Relaxed);
            PIPE_FID_NAME_HASH[i].store(name_hash, Ordering::Relaxed);
            return;
        }
    }
}

pub(crate) fn pipe_name_hash_known(name_hash: u64) -> bool {
    name_hash != 0
        && (0..PIPE_FID_NAME_N).any(|i| {
            PIPE_FID_NAME_FID[i].load(Ordering::Relaxed) != 0
                && PIPE_FID_NAME_HASH[i].load(Ordering::Relaxed) == name_hash
        })
}

/// The name-hash recorded for `fid` (0 = unknown).
pub(crate) fn pipe_fid_name_hash(fid: u64) -> u64 {
    for i in 0..PIPE_FID_NAME_N {
        if PIPE_FID_NAME_FID[i].load(Ordering::Relaxed) == fid {
            return PIPE_FID_NAME_HASH[i].load(Ordering::Relaxed);
        }
    }
    0
}
const DELAY_WAITER_N: usize = WAIT_REPLY_POOL_N - 1;
pub(crate) const DELAY_TIMER_BADGE: u64 = 0x4000_0000_0000_0000;
/// ★ A bound-notification TICK that the COMPONENT PUMP absorbed, deferred to the main service loop.
///
/// The executive's ROOT TCB has the HPET one-shot notification BOUND to it
/// (`LBL_TCB_BIND_NOTIFICATION`, `delay_timer_init`), so a timer signal can cancel ANY blocking
/// `Recv` the executive makes — that is the whole point, it is how `NtDelayExecution` wakes a parked
/// waiter while the loop sits in `recv`. The kernel's bound-notification pre-check
/// (`syscall_handler.rs::handle_recv`) returns `rdi = DELAY_TIMER_BADGE`, `rsi = 0` and **leaves the
/// message registers untouched**.
///
/// The main service loop has always handled that (`badge == DELAY_TIMER_BADGE` →
/// `delay_timer_interrupt` → re-recv). `component_pump` did NOT: it discarded the badge, so a tick
/// that landed on a pump's recv was read as a component message with label 0 and MR0 = the stale
/// request tag — and walled the component. That is exactly what killed the LSA route's npfs READ
/// (`[pump] WALL label=0 ip=0x771`): the route is the first thing that arms an HPET one-shot
/// (`NtDelayExecution` from the RPC worker) WHILE an IRP dispatch is in flight.
///
/// The pump now recognises the tick, counts it here and re-receives. The main service loop drains
/// the count at the top of its next iteration — `delay_timer_interrupt` wakes the due waiters,
/// re-arms the comparator and Acks the IRQ. Servicing may coalesce multiple absorbed deliveries,
/// but the gate accounting still records every tick that interrupted a component receive.
pub(crate) static DELAY_TIMER_TICKS_PENDING: AtomicU64 = AtomicU64::new(0);
/// Timer ticks absorbed by a component pump's recv and deferred (reported by `exec_lsa_worker_route`).
pub(crate) static PUMP_TIMER_TICKS_ABSORBED: AtomicU64 = AtomicU64::new(0);
/// Absorbed ticks accounted as drained by the main service loop.
pub(crate) static PUMP_TIMER_TICKS_DRAINED: AtomicU64 = AtomicU64::new(0);
// ═══ ★ A WATCHDOG THAT CAN FIRE WHILE THE LOOP IS BLOCKED IN `recv` ═════════════════════════════
//
// The wall-clock stall watchdog runs at the SERVICE-LOOP TOP, so it can only observe a boot that is
// still receiving messages. A genuine deadlock — every hosted thread parked, nobody left to signal —
// produces no messages at all, the executive blocks forever inside `seL4_Recv`, and the loop top is
// never reached again. That is precisely why two batches read `RUNEXIT=124` as "the TCG budget" and
// went looking for work to remove: there was no wall-clock evidence at all, only a silent tail.
//
// The mechanism that CAN interrupt a blocking `Recv` already exists: the executive's root TCB has
// the HPET one-shot notification BOUND to it (`delay_timer_init`), which is how `NtDelayExecution`
// wakes a parked waiter while the loop sits in `recv`. So the watchdog is a coarse deadline that
// joins the delay queue's own `min()` in `delay_timer_rearm`, and the check runs inside
// `recv_full_r12` — i.e. at EVERY blocking receive the executive makes, including the nested ones a
// component pump takes during a dispatch.
//
// ★ IT RESPECTS `exec_delay_timer_disarms`. The trigger-type bit is never used as an arm control
// (only `delay_timer_rearm`'s existing `Tn_INT_ENB` path arms/disarms), the period is 20 s so the
// whole post-logon window costs single-digit deliveries against that spec's 4096 ceiling, and a
// watchdog tick is counted as WORK rather than as a spurious wake (`WATCHDOG_TICK_IS_OURS`), so the
// `spurious <= 64` clause keeps meaning what it meant. The storm that cost 2.7 M deliveries came
// from a comparator left permanently BEHIND the main counter; every path here writes a comparator
// strictly ahead of `now`.
/// Ship switch: `false` removes the deadline from the rearm chain and the check from every recv.
pub(crate) const EXEC_DEADMAN_WATCHDOG: bool = true;
/// 20 s of wall clock. A TRIP needs two consecutive expiries with no message in between, so the
/// boot must have been completely silent for ~40 s — well past any single TCG-slow dispatch.
const WATCHDOG_PERIOD_100NS: u64 = 20 * 10_000_000;
pub(crate) static WATCHDOG_ARMED: AtomicU64 = AtomicU64::new(0);
static WATCHDOG_DEADLINE: AtomicU64 = AtomicU64::new(u64::MAX);
/// Every real (non-timer) message the executive has received. The deadlock predicate is simply
/// "this did not move across a whole watchdog period" — no clock read on the hot path.
pub(crate) static WATCHDOG_MSGS: AtomicU64 = AtomicU64::new(0);
static WATCHDOG_LAST_SEEN_MSGS: AtomicU64 = AtomicU64::new(u64::MAX);
pub(crate) static WATCHDOG_TICKS: AtomicU64 = AtomicU64::new(0);
pub(crate) static WATCHDOG_TRIPS: AtomicU64 = AtomicU64::new(0);
pub(crate) static WATCHDOG_TRIPPED: AtomicU64 = AtomicU64::new(0);
/// Ticks the watchdog re-armed itself from inside a NESTED component-pump receive (where the main
/// service loop's `delay_timer_interrupt` cannot run to re-arm it).
pub(crate) static WATCHDOG_NESTED_REARMS: AtomicU64 = AtomicU64::new(0);
/// Set by `watchdog_on_tick` when the delivery it saw was the watchdog's own deadline, consumed by
/// `delay_timer_interrupt` so the tick counts as work instead of as a spurious wake.
static WATCHDOG_TICK_IS_OURS: AtomicU64 = AtomicU64::new(0);

/// The watchdog's contribution to `delay_timer_rearm`'s deadline `min()`.
fn watchdog_deadline() -> Option<u64> {
    if !EXEC_DEADMAN_WATCHDOG || WATCHDOG_ARMED.load(Ordering::Relaxed) == 0 {
        return None;
    }
    let deadline = WATCHDOG_DEADLINE.load(Ordering::Relaxed);
    if deadline == u64::MAX {
        None
    } else {
        Some(deadline)
    }
}

/// Arm the deadman. Scoped ON at the POST-LOGON milestone: that is where the frontier is, it is past
/// every SM/CSR/LSA rendezvous (whose nested receive loops do not screen a bound-notification badge),
/// and it keeps the added deliveries to the handful this batch actually needs.
pub(crate) unsafe fn watchdog_arm(queue: &nt_delay_execution::Queue<DELAY_WAITER_N>) {
    if !EXEC_DEADMAN_WATCHDOG || WATCHDOG_ARMED.swap(1, Ordering::Relaxed) != 0 {
        return;
    }
    if !delay_timer_init() {
        WATCHDOG_ARMED.store(0, Ordering::Relaxed);
        return;
    }
    WATCHDOG_DEADLINE.store(
        monotonic_time_100ns().saturating_add(WATCHDOG_PERIOD_100NS),
        Ordering::Relaxed,
    );
    WATCHDOG_LAST_SEEN_MSGS.store(u64::MAX, Ordering::Relaxed);
    delay_timer_rearm(queue);
    print_str(b"[deadman] in-recv watchdog ARMED (period 20s, trip = two silent periods)\n");
}

/// Run at every bound-notification delivery, from inside `recv_full_r12` — so it fires even when the
/// executive is blocked in a NESTED receive that the service loop can never return from.
pub(crate) unsafe fn watchdog_on_tick() {
    if WATCHDOG_ARMED.load(Ordering::Relaxed) == 0 {
        return;
    }
    WATCHDOG_TICKS.fetch_add(1, Ordering::Relaxed);
    let now = monotonic_time_100ns();
    if now < WATCHDOG_DEADLINE.load(Ordering::Relaxed) {
        return; // an ordinary delay/wait tick; not our deadline
    }
    WATCHDOG_TICK_IS_OURS.fetch_add(1, Ordering::Relaxed);
    WATCHDOG_DEADLINE.store(now.saturating_add(WATCHDOG_PERIOD_100NS), Ordering::Relaxed);
    let messages = WATCHDOG_MSGS.load(Ordering::Relaxed);
    let previous = WATCHDOG_LAST_SEEN_MSGS.swap(messages, Ordering::Relaxed);
    if messages != previous {
        return; // the executive is still receiving real work
    }
    let trip = WATCHDOG_TRIPS.fetch_add(1, Ordering::Relaxed);
    WATCHDOG_TRIPPED.store(1, Ordering::Relaxed);
    if trip < 3 {
        watchdog_report(messages);
    }
}

/// What a deadlock now SAYS about itself, instead of a silent tail.
unsafe fn watchdog_report(messages: u64) {
    print_str(
        b"[deadman] ***** DEADLOCK: no IPC reached the executive for two 20s periods *****\n",
    );
    print_str(b"[deadman] messages-received=");
    print_u64(messages);
    print_str(b" ticks=");
    print_u64(WATCHDOG_TICKS.load(Ordering::Relaxed));
    print_str(b" nested-rearms=");
    print_u64(WATCHDOG_NESTED_REARMS.load(Ordering::Relaxed));
    print_str(b"\n");
    for slot in 0..WAITER_N {
        if WAITER_EVENT_IDX[slot].load(Ordering::Relaxed) == u64::MAX {
            continue;
        }
        print_str(b"[deadman] event-waiter tid=");
        print_u64(WAITER_TID[slot].load(Ordering::Relaxed));
        print_str(b" events=");
        print_u64(WAITER_EVENT_COUNT[slot].load(Ordering::Relaxed));
        print_str(b" wait-all=");
        print_u64(WAITER_WAIT_ALL[slot].load(Ordering::Relaxed));
        print_str(b" deadline=");
        print_u64(WAITER_DEADLINE[slot].load(Ordering::Relaxed));
        print_str(b" resume-ip=0x");
        print_hex_u64(WAITER_RESUME_IP[slot].load(Ordering::Relaxed));
        print_str(b"\n");
    }
    for slot in 0..KEYED_WAITER_N {
        if KEYED_WAITER_KEY[slot].load(Ordering::Relaxed) == u64::MAX {
            continue;
        }
        print_str(b"[deadman] keyed-waiter tid=");
        print_u64(KEYED_WAITER_TID[slot].load(Ordering::Relaxed));
        print_str(b" key=0x");
        print_hex_u64(KEYED_WAITER_KEY[slot].load(Ordering::Relaxed));
        print_str(b"\n");
    }
    print_str(b"[deadman] delay-timer deliveries=");
    print_u64(TIMER_TICKS_SEEN.load(Ordering::Relaxed));
    print_str(b" woke-nothing=");
    print_u64(TIMER_TICKS_SPURIOUS.load(Ordering::Relaxed));
    print_str(b" last-rearm-armed=");
    print_u64(LAST_REARM_ARMED.load(Ordering::Relaxed));
    print_str(b" src=");
    print_u64(LAST_REARM_SOURCE.load(Ordering::Relaxed));
    print_str(b"\n[deadman] -> the service loop will QUIESCE and run the gate rather than hang\n");
}

/// Re-arm the HPET from inside a NESTED component-pump receive. The main service loop's
/// `delay_timer_interrupt` (which owns the ordinary re-arm + IRQ Ack) cannot run while the pump is
/// blocked, and the IOAPIC line stays masked until that Ack — so without this a nested deadlock
/// would get exactly ONE tick and could never TRIP. The sequence mirrors `delay_timer_interrupt`'s
/// exactly: comparator strictly AHEAD of `now` first, then clear the level-triggered status, then
/// Ack — the ordering that keeps a still-asserted line from storming.
pub(crate) unsafe fn watchdog_nested_rearm() {
    if WATCHDOG_ARMED.load(Ordering::Relaxed) == 0 {
        return;
    }
    let handler = DELAY_TIMER_HANDLER.load(Ordering::Relaxed);
    let period = HPET_PERIOD_FS.load(Ordering::Relaxed);
    if handler == 0 || period == 0 {
        return;
    }
    let step = nt_delay_execution::hundred_ns_to_ticks_ceil(WATCHDOG_PERIOD_100NS, period).max(1);
    let now = core::ptr::read_volatile((HPET_VADDR + HPET_MAIN_COUNTER) as *const u64);
    core::ptr::write_volatile(
        (HPET_VADDR + HPET_T0_COMPARATOR) as *mut u64,
        now.saturating_add(step),
    );
    let config =
        core::ptr::read_volatile((HPET_VADDR + HPET_T0_CONFIG) as *const u64) | HPET_TN_INT_ENB;
    core::ptr::write_volatile((HPET_VADDR + HPET_T0_CONFIG) as *mut u64, config);
    core::ptr::write_volatile((HPET_VADDR + HPET_GEN_INT_STATUS) as *mut u64, 1);
    let _ = syscall5(SYS_SEND, handler, LBL_IRQ_ACK << 12, 0, 0, 0);
    WATCHDOG_NESTED_REARMS.fetch_add(1, Ordering::Relaxed);
}

