/// ═══ EVERY POOL THAT BACKS HOSTED PRIVATE MEMORY HAS MEASURED HEADROOM ══════════════════════════
///
/// The recurring wall in this codebase is a fixed-capacity resource that answers "no" in silence:
/// the bump heap at 93 %, `HEAP_FRAMES`, the VAD map, the frame registry. Each one is now measured
/// with a HIGH-WATER mark next to its capacity and printed at the gate (`[pools]`), and this spec
/// makes exhaustion a RED SPEC rather than a mystery. Thresholds are deliberately below capacity:
/// the point is to fail BEFORE the wall, while there is still room to diagnose.
fn vm_pool_headroom_spec(passed: &mut u64) {
    let untyped_used = UT_RETYPE_BYTES.load(Ordering::Relaxed);
    let untyped_total = UT_TOTAL_BYTES.load(Ordering::Relaxed);
    let untyped_free = untyped_total.saturating_sub(untyped_used);
    let slots_total =
        ROOT_CSPACE_END.load(Ordering::Relaxed) - ROOT_CSPACE_START.load(Ordering::Relaxed);
    let slots_available = root_slot_available_count();
    let registry = CSRSS_FRAME_HW.load(Ordering::Relaxed);
    let vad = VM_REGION_HW.load(Ordering::Relaxed);
    let committed_mappings = VM_COMMITTED_MAPPING_HW.load(Ordering::Relaxed);
    let committed_mapping_fails = VM_COMMITTED_MAPPING_REGISTRATION_FAILS.load(Ordering::Relaxed);
    let protection_overrides = VM_PROTECTION_OVERRIDE_HW.load(Ordering::Relaxed);
    let free_list = VM_FREE_FRAME_HW.load(Ordering::Relaxed);
    print_pool_census(b"gate");
    check(
        b"exec_vm_pool_headroom",
        // The boot Untyped's size was really read from BootInfo (so this is measured, not assumed) …
        untyped_total != 0
            // … and the full ReactOS desktop proof still leaves a substantial root-Untyped runway.
            && untyped_free >= MIN_BOOT_UNTYPED_HEADROOM_BYTES
            // Every executive-side fixed pool remains strictly under three quarters of its capacity.
            && slots_total != 0
            && registry * 4 < CSRSS_FRAME_CAP as u64 * 3
            && vad * 4 < VM_REGION_CAPACITY as u64 * 3
            && committed_mappings * 4 < PROCESS_COMMITTED_MAPPING_CAPACITY as u64 * 3
            && protection_overrides * 4
                < nt_address_space::VM_PROTECTION_OVERRIDE_CAPACITY as u64 * 3
            && free_list * 4 < VM_FREE_FRAME_CAPACITY as u64 * 3
            // ROOT-CSPACE SLOTS ARE THE BINDING CONSTRAINT. Measure real availability: slots left in
            // the bump range plus deleted root slots returned through the recycle stack.
            && slots_available >= 2048
            // … with nothing having been refused by any of them.
            && CSRSS_FRAME_FULL.load(Ordering::Relaxed) == 0
            && SHARED_IMAGE_MAPPING_FAILS.load(Ordering::Relaxed) == 0
            && committed_mapping_fails == 0
            && UT_RETYPE_FAILS.load(Ordering::Relaxed) == 0
            && VM_FAIL_PT.load(Ordering::Relaxed) == 0
            && VM_FAIL_FRAME.load(Ordering::Relaxed) == 0
            && VM_FAIL_MAP.load(Ordering::Relaxed) == 0
            && VM_FAIL_ALIAS.load(Ordering::Relaxed) == 0
            && VM_FAIL_REGISTRY.load(Ordering::Relaxed) == 0,
        passed,
    );
}

/// ═══ `CopyDirectory` REALLY RAN — the profile tree was COPIED, not just created ═════════════════
///
/// `userenv!CreateUserProfileExW` seeds a new profile by calling
/// `CopyDirectory(C:\Profiles\<user>, C:\Profiles\Default User)` (`profile.c:1000`), which
/// `FindFirstFileW`s the source, `CreateDirectoryExW`s every subdirectory and `CopyFileW`s every
/// file, recursing. Before this batch it returned at its FIRST `CreateDirectoryExW` with
/// `Error: 87`, because `NtQueryInformationFile` served exactly ONE information class.
///
/// The proof here is by CONTENT and by STRUCTURE, never by non-failure:
///   * the DESTINATION copy of a real ISO file reads back off the LIVE writable volume with the
///     source's exact 9 bytes — `CopyFileW` genuinely read the `Default User` original and wrote
///     those bytes into `C:\Profiles\<user>\My Documents\livecd_start.cmd`;
///   * the destination subdirectories BELOW `C:\Profiles\<user>` can only come from
///     `CopyDirectory`'s recursion (winlogon itself creates only the root and the per-user
///     directory, which the sibling spec already accounts for);
///   * and it happened off the REAL interactive logon, under the SID `NtCreateToken` minted.
unsafe fn winlogon_profile_copied_spec(passed: &mut u64) {
    use crate::writable_fs::*;
    let dirs = PROFILE_COPY_DIRS.load(Ordering::Relaxed);
    let files = PROFILE_COPY_FILES.load(Ordering::Relaxed);
    let content_ok = copied_profile_probe_ok();
    print_str(b"[wl-profile-copy] CopyDirectory: subdirectories created=");
    print_u64(dirs);
    print_str(b" files copied=");
    print_u64(files);
    print_str(b" destination-content-matches-source=");
    print_u64(content_ok as u64);
    print_str(b"\n");
    check(
        b"exec_winlogon_profile_copied",
        // Only meaningful when the profile source is really provisioned; with the route off the
        // copy has nothing to copy and the spec must not pretend otherwise.
        !PROVISION_DEFAULT_USER_PROFILE
            || (dirs >= 15
                && files >= 1
                && content_ok
                && LSA_LOGON_REPLY_STATUS.load(Ordering::Relaxed) == 0
                && PROFILE_USER_DIR_CREATED.load(Ordering::Relaxed) >= 1),
        passed,
    );
}

/// ═══ THE BLOCKING-`NtUserGetMessage` GUARD IS LIVE, AND IT REALLY FIRED ═════════════════════════
///
/// This is the batch's PERFORMANCE guard, and it is counted rather than timed on purpose: the
/// symptom it prevents is not "slow", it is a PERMANENT stop. win32k is driven synchronously by the
/// executive's single-threaded service loop, so `co_IntGetPeekMessage` waiting for a message that
/// nobody can post blocks the entire system — including the loop-top wall-clock stall watchdog, so
/// the boot cannot even quiesce to this gate (measured: output ceases at t=310 s and the harness
/// kills QEMU at 555 s, `RUNEXIT=124`).
///
/// `PREFLIGHT_PEEKS >= 1` proves the non-blocking `NtUserPeekMessage(PM_NOREMOVE)` really runs
/// ahead of every blocking GetMessage; `EMPTY_QUEUE_PARKS >= 1` proves it really caught a call that
/// would have blocked forever and parked the caller instead. The fact that this spec RUNS AT ALL is
/// the other half of the proof — with the guard bypassed the gate is never reached.
fn get_message_guard_spec(passed: &mut u64) {
    let peeks = GET_MESSAGE_PREFLIGHT_PEEKS.load(Ordering::Relaxed);
    let parks = GET_MESSAGE_EMPTY_QUEUE_PARKS.load(Ordering::Relaxed);
    print_str(b"[wl-getmessage] preflight PeekMessage(PM_NOREMOVE) calls=");
    print_u64(peeks);
    print_str(b" empty-queue parks (hangs prevented)=");
    print_u64(parks);
    print_str(b" guard=");
    print_u64(GET_MESSAGE_EMPTY_QUEUE_GUARD as u64);
    print_str(b"\n");
    check(
        b"exec_win32k_blocking_getmessage_guarded",
        !GET_MESSAGE_EMPTY_QUEUE_GUARD || (peeks >= 1 && parks >= 1 && peeks >= parks),
        passed,
    );
}

/// ═══ THE PROFILE SOURCE — the ISO's OWN `Profiles/` TREE, WHICH OUR STAGING WAS DROPPING ══════
///
/// `CreateUserProfileExW` seeds a new profile by COPYING `C:\Profiles\Default User`
/// (`profile.c:1000` → `CopyDirectory` → `FindFirstFileW`), and that copy failed at
/// `profile.c:1002  Error: 3` (ERROR_PATH_NOT_FOUND) because the disk image had no profile tree.
///
/// **The tree was never missing from the media — it was missing from our STAGING.** The ReactOS
/// LiveCD ISO carries a real 76-entry `Profiles/` tree (`Default User/…`, `All Users/…`) as a
/// TOP-LEVEL sibling of `reactos/`, and every extraction in `fetch_reactos.sh` was scoped to
/// `reactos`, so it never reached the image. It is now extracted and laid down at `::Profiles` —
/// exactly where `%SystemDrive%\Profiles` (the real SOFTWARE hive's `ProfileList\ProfilesDirectory`)
/// resolves — and the executive MATERIALISES it onto the writable volume at mount, by walking it
/// off the read-only FAT volume with the same reader every hosted binary is loaded with.
///
/// The proof is by CONTENT and by ENUMERATION, off the LIVE volume: the tree's real directory and
/// file counts, `Default User`'s real child list through the same record encoder `FindFirstFileW`
/// reaches, and a REAL staged file's bytes (`Default User\My Documents\livecd_start.cmd` is the
/// ISO's 9-byte `@start %1`). Nothing here is synthesised — every byte came off the image.
/// Read the STAGED `\Profiles` tree straight off the read-only FAT volume, BY PATH — independent of
/// the writable overlay. Returns (is `Default User` a real directory?, does a real file inside it
/// hold the ISO's exact bytes?). This is what proves the staging gap is closed on the IMAGE.
unsafe fn staged_profiles_by_path() -> (bool, bool) {
    let Some(fat) = crate::fs_loader::exec_fs() else {
        return (false, false);
    };
    let is_dir = crate::fs_loader::fat_open_path_entry(&fat, b"Profiles\\Default User")
        .is_some_and(|(_, _, attr)| attr & 0x10 != 0);
    let mut probe_ok = false;
    if let Some((cluster, size, attr)) = crate::fs_loader::fat_open_path_entry(
        &fat,
        b"Profiles\\Default User\\My Documents\\livecd_start.cmd",
    ) {
        if attr & 0x10 == 0 && size == 9 {
            let mut bytes = [0u8; 9];
            if crate::fs_loader::fat_read_file(&fat, cluster, size, bytes.as_mut_ptr() as u64) == 9
            {
                probe_ok = &bytes == b"@start %1";
            }
        }
    }
    (is_dir, probe_ok)
}

unsafe fn default_user_profile_spec(passed: &mut u64) {
    use crate::writable_fs::*;
    let dirs = PROFILE_SOURCE_DIRS.load(Ordering::Relaxed);
    let files = PROFILE_SOURCE_FILES.load(Ordering::Relaxed);
    let bytes = PROFILE_SOURCE_BYTES.load(Ordering::Relaxed);
    let entries = PROFILE_SOURCE_ENTRIES.load(Ordering::Relaxed);
    let probe = PROFILE_SOURCE_PROBE_OK.load(Ordering::Relaxed);
    // The one file this executive deliberately adds to the ISO's own `Default User` tree.
    let provisioned_ntuser = (NTUSER_DAT_PROVISIONED.load(Ordering::Relaxed) != 0) as u64;
    let (staged_default_user_dir, staged_probe_ok) = staged_profiles_by_path();
    print_str(b"[profile-source] on-image \\Profiles: `Default User` dir=");
    print_u64(staged_default_user_dir as u64);
    print_str(b" probe-file-bytes-match=");
    print_u64(staged_probe_ok as u64);
    print_str(b" | materialised: dirs=");
    print_u64(dirs);
    print_str(b" files=");
    print_u64(files);
    print_str(b" bytes=");
    print_u64(bytes);
    print_str(b" `Default User` entries=");
    print_u64(entries);
    print_str(b" probe-content-ok=");
    print_u64(probe);
    print_str(b"\n");
    check(
        b"exec_default_user_profile_staged",
        // The ISO's real tree is really ON THE IMAGE, resolvable BY PATH through the ordinary
        // read-only FAT reader: `\Profiles\Default User` is a directory, and a REAL file inside it
        // (`My Documents\livecd_start.cmd`) reads back with the ISO's exact 9 bytes.
        staged_default_user_dir && staged_probe_ok
            // When the runtime materialisation is ON, the whole tree really came across too — all
            // 45 directories and all 31 files (5307 bytes of genuine `.lnk`/`.cmd` content),
            // `Default User` enumerating `.`, `..` and its 15 real children through the same `Zw*`
            // record encoder `FindFirstFileW` reaches, and the same file readable off the volume.
            //
            // ★ Plus EXACTLY ONE deliberate addition when `PROVISION_NTUSER_DAT` is on: the
            // `ntuser.dat` the LiveCD's skipped setup step would have left in this profile (see
            // `writable_fs::PROVISION_NTUSER_DAT`). The counts stay EXACT — they are the ISO tree's
            // own numbers plus that one file — so a staging regression still turns this spec red.
            && (!crate::writable_fs::PROVISION_DEFAULT_USER_PROFILE
                || (dirs >= 45
                    && files >= 31 + provisioned_ntuser
                    && bytes >= 5307 + crate::writable_fs::NTUSER_DAT_PROVISIONED.load(Ordering::Relaxed)
                    && entries == 17 + provisioned_ntuser
                    && probe == 1)),
        passed,
    );
}

/// ═══ winlogon REALLY BUILT THE USER PROFILE TREE — `CreateDirectoryW` no longer returns `Error: 1`
///
/// This is the batch's user-visible advance, and it is named for exactly what was MEASURED — not
/// for what would be nicer to claim.
///
/// `HandleLogon` → `LoadUserProfileW` → (`GetFileAttributesW("C:\Profiles\<user>\ntuser.dat")`
/// MISSES, honestly, on the writable volume) → `CreateUserProfileW`, under the REAL profile SID the
/// `NtCreateToken` service minted (`profile.c:2056  Loading profile S-1-5-21-…-500`), which now:
///   1. resolves `C:\Profiles` — `CreateDirectoryW(szProfilesPath)`, `profile.c:929`. THIS is the
///      call that returned `Error: 1` (`STATUS_NOT_IMPLEMENTED` ⇒ ERROR_INVALID_FUNCTION) for every
///      boot before the writable volume existed and ended the logon. It now gets a real answer from
///      a real file system: `FILE_CREATED` on a volume whose profiles root is absent, or the
///      `ERROR_ALREADY_EXISTS` arm (a genuine `STATUS_OBJECT_NAME_COLLISION`) once the profile
///      SOURCE is provisioned — which is what the call returns on any installed system, since setup
///      creates the profiles directory. Either way winlogon really drove it and really got the
///      correct answer; a fabricated success would satisfy neither counter.
///   2. reads `ProfileList\DefaultUserProfile` out of the real SOFTWARE mount, and
///   3. creates `C:\Profiles\<UserName>` — `CreateDirectoryW(szUserProfilePath)`, `profile.c:963`.
/// Step 3 is only reachable if step 1 really returned one of those two answers, so the pair is a
/// structural witness.
fn winlogon_profile_directories_spec(passed: &mut u64) {
    let root = crate::writable_fs::PROFILE_ROOT_CREATED.load(Ordering::Relaxed);
    let collided = crate::writable_fs::PROFILE_ROOT_COLLIDED.load(Ordering::Relaxed);
    let user_dir = crate::writable_fs::PROFILE_USER_DIR_CREATED.load(Ordering::Relaxed);
    print_str(b"[wl-profile-dirs] winlogon: C:\\Profiles created=");
    print_u64(root);
    print_str(b" already-existed=");
    print_u64(collided);
    print_str(b" C:\\Profiles\\<user> created=");
    print_u64(user_dir);
    print_str(b"\n");
    check(
        b"exec_winlogon_profile_directories_created",
        // winlogon (pi 2) really drove the profiles-root create on the writable volume and got a
        // real answer (created it, or was correctly refused because it already exists) …
        root + collided >= 1
            // … and it really CREATED the per-user profile directory, only reachable past that.
            && user_dir >= 1
            // … off the real interactive logon this batch inherits: lsass returned SUCCESS and the
            // token it minted really crossed into winlogon (the SID the profile is being made for).
            && LSA_LOGON_REPLY_STATUS.load(Ordering::Relaxed) == 0
            && WINLOGON_LOGON_TOKEN_DUPLICATES.load(Ordering::Relaxed) >= 1
            // … and the profile flow reached them through the REAL SOFTWARE mount, not a synthetic.
            && WINLOGON_PROFILE_LIST_HITS.load(Ordering::Relaxed) >= 2,
        passed,
    );
}

/// ═══ THE 4TH `regf` MOUNT — `\Registry\Machine\SOFTWARE` IS REAL ═══════════════════════════════
///
/// The genuine ReactOS `\reactos\system32\config\software` hive (471040 B — ~57x the SECURITY/SAM
/// hives, so it needs its own 2 MiB window + dedicated page table, not the shared input PT) is read
/// BY PATH by the isolated storage host into SWHIVEBUF and mounted read-only through the SAME
/// general mechanism as the other three: a `HIVE_SEL_SOFTWARE` top-nibble tag on the `KeyRef`, so
/// `base_hive` / `registry_target_path` / `registry_value(s)` / `registry_subkeys` and the relative
/// open/create arms all serve it with no special-casing.
///
/// The proof is by CONTENT, not by non-failure: this reads the LIVE mapped bytes back through the
/// same `nt-hive-regf` parser the mount uses and asserts
/// `Microsoft\Windows NT\CurrentVersion\ProfileList\ProfilesDirectory` really is
/// `REG_EXPAND_SZ "%SystemDrive%\Profiles"` — the value `userenv!GetProfilesDirectoryW`
/// (`profile.c:1592`) reads, whose absence was the `ERROR_FILE_NOT_FOUND` that made winlogon's
/// `LoadUserProfileW` fail. Plus the live counters: winlogon really opened keys out of this mount,
/// and its ProfileList open was really SATISFIED from it.
unsafe fn software_hive_mount_spec(passed: &mut u64) {
    let size = SOFTWARE_HIVE_SIZE.load(Ordering::Relaxed);
    let opens = SOFTWARE_HIVE_KEY_OPENED.load(Ordering::Relaxed);
    let pl_hits = WINLOGON_PROFILE_LIST_HITS.load(Ordering::Relaxed);
    // Re-parse the LIVE mapped bytes (not a copy) and read the real value back.
    let mut root_subkeys = 0u64;
    let mut val_type = 0u64;
    let mut val_len = 0u64;
    let mut val_ok = false;
    if size != 0 {
        let bytes: &'static [u8] =
            core::slice::from_raw_parts(SWHIVEBUF_VADDR as *const u8, size as usize);
        if let Some(h) = RegfHive::new(bytes) {
            root_subkeys = h.subkeys(h.root()).len() as u64;
            if let Some(cell) = h.open_key(r"Microsoft\Windows NT\CurrentVersion\ProfileList") {
                if let Some((ty, data)) = h.value(cell, "ProfilesDirectory") {
                    val_type = ty as u64;
                    val_len = data.len() as u64;
                    // REG_EXPAND_SZ `%SystemDrive%\Profiles` + NUL, UTF-16LE = 46 bytes.
                    const EXPECT: &[u8] = b"%SystemDrive%\\Profiles";
                    val_ok = ty == 2
                        && data.len() == (EXPECT.len() + 1) * 2
                        && data
                            .chunks(2)
                            .zip(EXPECT.iter().map(|&c| c as u16).chain(core::iter::once(0)))
                            .all(|(got, want)| {
                                got.len() == 2 && u16::from_le_bytes([got[0], got[1]]) == want
                            });
                    print_str(b"[sw-hive] ProfileList\\ProfilesDirectory = \"");
                    for pair in data.chunks(2) {
                        if pair.len() == 2 {
                            let w = u16::from_le_bytes([pair[0], pair[1]]);
                            if w != 0 && w < 128 {
                                print_str(&[w as u8]);
                            }
                        }
                    }
                    print_str(b"\"\n");
                }
            }
        }
    }
    print_str(b"[sw-hive] SOFTWARE mount size=");
    print_u64(size);
    print_str(b"B root-subkeys=");
    print_u64(root_subkeys);
    print_str(b" value-type=");
    print_u64(val_type);
    print_str(b" value-bytes=");
    print_u64(val_len);
    print_str(b" content-ok=");
    print_u64(val_ok as u64);
    print_str(b" live-key-opens=");
    print_u64(opens);
    print_str(b" ProfileList-hits=");
    print_u64(pl_hits);
    print_str(b"\n");
    check(
        b"exec_software_hive_mounted",
        // The genuine 471040 B regf is staged + mapped, parses, and has its four real top-level
        // subkeys (Classes / Clients / Microsoft / ReactOS) …
        size == 471_040
            && root_subkeys == 4
            // … the ProfilesDirectory value reads back with the EXACT expected content …
            && val_ok
            // … and the LIVE registry served real keys out of this mount, including the
            // ProfileList open that used to be ERROR_FILE_NOT_FOUND.
            && opens >= 1
            && pl_hits >= 1,
        passed,
    );
    winlogon_profile_directory_spec(passed);
}

/// ═══ `GetProfilesDirectoryW` SUCCEEDS — the post-logon path is PAST its old wall ═══════════════
///
/// Before this batch: `HandleLogon` (`sas.c:571`) → `LoadUserProfileW` (`sas.c:626`) →
/// `userenv!GetProfilesDirectoryW` (`profile.c:1592`) →
