/// ═══ PERIODIC CENSUS (batch 58) ══════════════════════════════════════════════════════════════
///
/// [`print_progress_census`] only ever ran AFTER the loop quiesced — which is exactly the boot that
/// does NOT need diagnosing. A boot that blows the TCG budget (`RUNEXIT=124`) is killed before the
/// gate runs, so it produced no census at all and every claim about "where the time went" was a
/// guess. The service loop now dumps the same census every [`CENSUS_PERIOD_100NS`] of wall-clock,
/// so a NON-quiescing boot still says who spent the seconds — and the successive dumps make a
/// runaway visible as a RATE, not just a total.
pub(crate) const CENSUS_PERIOD_100NS: u64 = 30 * 10_000_000; // 30 s
pub(crate) static CENSUS_PERIODIC_DUMPS: AtomicU64 = AtomicU64::new(0);
/// The last dump's timestamp, as a STATIC rather than a service-loop local: the win32k dispatch arm
/// runs a NESTED pump (a user callback re-enters the client, whose next win32k syscall is received
/// inside the dispatch, not at the loop top), so a burst of nested callbacks can spend MINUTES
/// without the main loop top ever being reached — which is exactly why the previous batch's failing
/// boot produced no census at all past its 6th dump. The dispatch arm ticks the same clock.
pub(crate) static CENSUS_LAST_DUMP: AtomicU64 = AtomicU64::new(0);

/// ═══ PER-SSN WIN32K WALL-CLOCK ═══════════════════════════════════════════════════════════════
///
/// Counts alone cannot separate "the flow issued MORE win32k calls" from "each win32k call became
/// MORE EXPENSIVE" — and those two have completely different fixes. `W32_SSN_TIME_100NS`
/// attributes the wall-clock between two consecutive win32k dispatch ENTRIES to the SSN that was
/// dispatched in between (the same technique the per-badge census uses at the loop top), which is
/// correct under nesting: an SSN that re-enters simply keeps accruing until the next entry.
pub(crate) static W32_SSN_TIME_100NS: [AtomicU64; SSN_HIST_N] =
    [const { AtomicU64::new(0) }; SSN_HIST_N];
static W32_PREV_T: AtomicU64 = AtomicU64::new(0);
static W32_PREV_BUCKET: AtomicU64 = AtomicU64::new(u64::MAX);
/// Total win32k dispatch entries and the wall-clock they span, so an average per-dispatch cost is
/// directly readable and a per-dispatch REGRESSION (rather than a work increase) is unmistakable.
pub(crate) static W32_DISPATCH_SPAN_100NS: AtomicU64 = AtomicU64::new(0);
pub(crate) static W32_DISPATCH_SPANNED: AtomicU64 = AtomicU64::new(0);

/// ═══ THE BLOCKING-`NtUserGetMessage` GUARD ═══════════════════════════════════════════════════
///
/// `PREFLIGHT_PEEKS` counts the non-blocking `NtUserPeekMessage(PM_NOREMOVE)` the executive issues
/// before ever letting a blocking `NtUserGetMessage` into win32k; `EMPTY_QUEUE_PARKS` counts the
/// times that peek came back EMPTY and the caller was parked instead. Every one of those parks is a
/// PERMANENT system-wide hang that did not happen: win32k is driven synchronously by the
/// single-threaded service loop, so `co_IntGetPeekMessage`'s wait would stop the whole boot AND the
/// loop-top stall watchdog with it (measured: silent from t=310 s to the 555 s kill, `RUNEXIT=124`).
pub(crate) static PROFILE_FRONTIER_TRACED: AtomicU64 = AtomicU64::new(0);
/// The guard's kill switch — the BYPASS control. `false` restores the pre-batch behaviour exactly
/// (a blocking `NtUserGetMessage` is dispatched straight into win32k), which is a permanent
/// system-wide hang the moment one finds an empty queue.
pub(crate) const GET_MESSAGE_EMPTY_QUEUE_GUARD: bool = true;
pub(crate) static GET_MESSAGE_PREFLIGHT_PEEKS: AtomicU64 = AtomicU64::new(0);
pub(crate) static GET_MESSAGE_EMPTY_QUEUE_PARKS: AtomicU64 = AtomicU64::new(0);

/// Record a win32k dispatch entry for the census, and tick the periodic dump from inside the
/// nested pump. Called from the SSN >= 0x1000 arm of the service loop.
pub(crate) fn w32_census_enter(ssn: u64) {
    let now = monotonic_time_100ns();
    let prev = W32_PREV_BUCKET.load(Ordering::Relaxed);
    if prev != u64::MAX {
        let delta = now.wrapping_sub(W32_PREV_T.load(Ordering::Relaxed));
        W32_SSN_TIME_100NS[prev as usize].fetch_add(delta, Ordering::Relaxed);
        W32_DISPATCH_SPAN_100NS.fetch_add(delta, Ordering::Relaxed);
        W32_DISPATCH_SPANNED.fetch_add(1, Ordering::Relaxed);
    }
    W32_PREV_BUCKET.store(ssn_bucket(ssn) as u64, Ordering::Relaxed);
    W32_PREV_T.store(now, Ordering::Relaxed);
    // ★ A COUNT-triggered heartbeat as well as the wall-clock one. A wall-clock-only dump cannot
    // distinguish "no dispatches happened" from "the CLOCK stopped" — and the whole quiesce
    // watchdog is wall-clock based, so a stopped clock is precisely the failure that would make a
    // boot un-quiescable. Printing the RAW HPET counter next to the derived ms settles it.
    let n = W32_DISPATCH_SPANNED.load(Ordering::Relaxed);
    if n % 128 == 0 {
        let period = HPET_PERIOD_FS.load(Ordering::Relaxed);
        let raw = if period != 0 {
            unsafe { core::ptr::read_volatile((HPET_VADDR + HPET_MAIN_COUNTER) as *const u64) }
        } else {
            0
        };
        print_str(b"[w32-clock] dispatches=");
        print_u64(n);
        print_str(b" t_ms=");
        print_u64(now / 10_000);
        print_str(b" hpet=");
        print_u64(raw);
        print_str(b" period_fs=");
        print_u64(period);
        print_str(b"\n");
    }
    census_tick_static(now);
}

/// Dump the census if the period has elapsed, using the shared static clock.
pub(crate) fn census_tick_static(now: u64) {
    let last = CENSUS_LAST_DUMP.load(Ordering::Relaxed);
    if now.wrapping_sub(last) < CENSUS_PERIOD_100NS {
        return;
    }
    CENSUS_LAST_DUMP.store(now, Ordering::Relaxed);
    let n = CENSUS_PERIODIC_DUMPS.fetch_add(1, Ordering::Relaxed);
    print_str(b"[census] ---- periodic dump #");
    print_u64(n);
    print_str(b" ----\n");
    print_census_badges();
    print_census_counters(b"periodic");
    print_ssn_hist(b"winlogon", unsafe {
        &*core::ptr::addr_of!(WINLOGON_SSN_HIST)
    });
    print_ssn_hist(b"csrss", unsafe { &*core::ptr::addr_of!(CSRSS_SSN_HIST) });
    print_ssn_hist(b"lsass", unsafe { &*core::ptr::addr_of!(LSASS_SSN_HIST) });
    print_ssn_hist(b"explorer", unsafe {
        &*core::ptr::addr_of!(EXPLORER_SSN_HIST)
    });
    print_w32_ssn_time();
}

/// The 16 win32k SSNs that cost the most WALL-CLOCK (ms), plus the average per dispatch.
pub(crate) fn print_w32_ssn_time() {
    let span = W32_DISPATCH_SPAN_100NS.load(Ordering::Relaxed);
    let n = W32_DISPATCH_SPANNED.load(Ordering::Relaxed);
    print_str(b"[census] w32-time total_ms=");
    print_u64(span / 10_000);
    print_str(b" dispatches=");
    print_u64(n);
    print_str(b" avg_us=");
    print_u64(if n == 0 { 0 } else { span / 10 / n });
    print_str(b" top_ms:");
    let mut taken = [false; SSN_HIST_N];
    for _ in 0..16 {
        let mut best = usize::MAX;
        let mut best_n = 0u64;
        for (bucket, cell) in unsafe { &*core::ptr::addr_of!(W32_SSN_TIME_100NS) }
            .iter()
            .enumerate()
        {
            let v = cell.load(Ordering::Relaxed);
            if !taken[bucket] && v > best_n {
                best_n = v;
                best = bucket;
            }
        }
        if best == usize::MAX {
            break;
        }
        taken[best] = true;
        let ssn = if best < SSN_HIST_NATIVE {
            best as u32
        } else {
            0x1000 + (best - SSN_HIST_NATIVE) as u32
        };
        print_str(b" ");
        print_hex(ssn);
        print_str(b"=");
        print_u64(best_n / 10_000);
    }
    print_str(b"\n");
}

/// The operation classes the profile flow was suspected of multiplying. Printed with every census
/// dump so a per-operation cost (and a runaway RATE) can be computed from any two dumps.
pub(crate) fn print_census_counters(tag: &[u8]) {
    let (_, _, _, redirects, returns, pushes, unwinds, nested, _, _, seq) =
        win32k_glue::user_callback_proofs();
    print_str(b"[census] ");
    print_str(tag);
    print_str(b" t_ms=");
    print_u64(monotonic_time_100ns() / 10_000);
    print_str(b" demand-faults=");
    print_u64(DEMAND_FAULTS.load(Ordering::Relaxed));
    print_str(b" heap=");
    print_u64(allocator::mark() as u64);
    print_str(b"/");
    print_u64(allocator::HEAP_FRAMES * 0x1000);
    print_str(b" ucb-redirects=");
    print_u64(redirects);
    print_str(b" ucb-returns=");
    print_u64(returns);
    print_str(b" ucb-pushes=");
    print_u64(pushes);
    print_str(b" ucb-unwinds=");
    print_u64(unwinds);
    print_str(b" ucb-nested=");
    print_u64(nested);
    print_str(b" ucb-seq=");
    print_u64(seq);
    print_str(b" pipe-parked=");
    print_u64(PIPE_WAIT_PARKED_COUNT.load(Ordering::Relaxed));
    print_str(b" pipe-woken=");
    print_u64(PIPE_WAIT_WOKEN_COUNT.load(Ordering::Relaxed));
    print_str(b" w32-dispatch/pi=");
    for pi in 0..MAX_PI {
        if pi != 0 {
            print_str(b",");
        }
        print_u64(W32_TOTAL_DISPATCH[pi].load(Ordering::Relaxed));
    }
    print_str(b"\n[census] ");
    print_str(tag);
    print_str(b" overlay creates=");
    print_u64(writable_fs::OVERLAY_CREATES.load(Ordering::Relaxed));
    print_str(b" opens=");
    print_u64(writable_fs::OVERLAY_OPENS.load(Ordering::Relaxed));
    print_str(b" dirs=");
    print_u64(writable_fs::OVERLAY_DIRS_CREATED.load(Ordering::Relaxed));
    print_str(b" reads=");
    print_u64(writable_fs::OVERLAY_READS.load(Ordering::Relaxed));
    print_str(b" writes=");
    print_u64(writable_fs::OVERLAY_WRITES.load(Ordering::Relaxed));
    print_str(b" dir-queries=");
    print_u64(writable_fs::OVERLAY_DIR_QUERIES.load(Ordering::Relaxed));
    print_str(b" dir-entries=");
    print_u64(writable_fs::OVERLAY_DIR_ENTRIES.load(Ordering::Relaxed));
    print_str(b" attr-queries=");
    print_u64(writable_fs::OVERLAY_ATTR_QUERIES.load(Ordering::Relaxed));
    print_str(b" set-info=");
    print_u64(writable_fs::OVERLAY_SET_INFO.load(Ordering::Relaxed));
    print_str(b" closes=");
    print_u64(writable_fs::OVERLAY_CLOSES.load(Ordering::Relaxed));
    print_str(b"\n");
    print_pool_census(tag);
}

/// The per-badge table — factored out of [`print_progress_census`] so the periodic dump prints the
/// identical thing.
fn print_census_badges() {
    for badge in 0..BADGE_CENSUS_N {
        let events = BADGE_EVENTS[badge].load(Ordering::Relaxed);
        if events == 0 {
            continue;
        }
        print_str(b"[census] badge=");
        print_u64(badge as u64);
        print_str(b" events=");
        print_u64(events);
        print_str(b" ms=");
        print_u64(BADGE_TIME_100NS[badge].load(Ordering::Relaxed) / 10_000);
        print_str(b" last_ms=");
        print_u64(BADGE_LAST_T[badge].load(Ordering::Relaxed) / 10_000);
        print_str(b"\n");
    }
}

/// Print the census. Called once, after the loop quiesces, from the spec runner.
pub(crate) fn print_progress_census() {
    let quiesce_t = monotonic_time_100ns();
    print_str(b"[census] quiesce_t_ms=");
    print_u64(quiesce_t / 10_000);
    print_str(b"\n");
    print_census_counters(b"final");
    print_census_badges();
    print_str(b"[census] timer ticks-seen=");
    print_u64(TIMER_TICKS_SEEN.load(Ordering::Relaxed));
    print_str(b" spurious=");
    print_u64(TIMER_TICKS_SPURIOUS.load(Ordering::Relaxed));
    print_str(b" past-deadline-rearms=");
    print_u64(TIMER_PAST_DEADLINE_REARMS.load(Ordering::Relaxed));
    print_str(b" last-past-source=");
    print_u64(TIMER_PAST_DEADLINE_SOURCE.load(Ordering::Relaxed));
    print_str(b" (1=delay 2=event 3=keyed 4=iocp)\n");
    print_ssn_hist(b"lsass", unsafe { &*core::ptr::addr_of!(LSASS_SSN_HIST) });
    print_ssn_hist(b"winlogon", unsafe {
        &*core::ptr::addr_of!(WINLOGON_SSN_HIST)
    });
    print_ssn_hist(b"csrss", unsafe { &*core::ptr::addr_of!(CSRSS_SSN_HIST) });
    print_ssn_hist(b"explorer", unsafe {
        &*core::ptr::addr_of!(EXPLORER_SSN_HIST)
    });
    print_w32_ssn_time();
}
/// Print the 16 hottest SSNs of a histogram (selection sort over the buckets — no alloc), with the
/// native / win32k-shadow split totalled separately so "which TABLE is the boot spending itself in"
/// is answerable at a glance. Shadow buckets print as their real `0x1xxx` SSN.
fn print_ssn_hist(who: &[u8], hist: &[AtomicU64; SSN_HIST_N]) {
    let mut native = 0u64;
    let mut shadow = 0u64;
    for (bucket, cell) in hist.iter().enumerate() {
        let n = cell.load(Ordering::Relaxed);
        if bucket < SSN_HIST_NATIVE {
            native += n;
        } else {
            shadow += n;
        }
    }
    print_str(b"[census] ssn-hist ");
    print_str(who);
    print_str(b" total=");
    print_u64(native + shadow);
    print_str(b" native=");
    print_u64(native);
    print_str(b" win32k=");
    print_u64(shadow);
    print_str(b" top:");
    let mut taken = [false; SSN_HIST_N];
    for _ in 0..16 {
        let mut best = usize::MAX;
        let mut best_n = 0u64;
        for (bucket, cell) in hist.iter().enumerate() {
            let n = cell.load(Ordering::Relaxed);
            if !taken[bucket] && n > best_n {
                best_n = n;
                best = bucket;
            }
        }
        if best == usize::MAX {
            break;
        }
        taken[best] = true;
        let ssn = if best < SSN_HIST_NATIVE {
            best as u32
        } else {
            0x1000 + (best - SSN_HIST_NATIVE) as u32
        };
        print_str(b" ");
        print_hex(ssn);
        print_str(b"=");
        print_u64(best_n);
    }
    print_str(b"\n");
}
/// RPC PDUs the LSA per-connection worker READ off the accepted `\pipe\lsarpc` connection, and the
/// PDU type byte (offset 2) of the first one. A real MS-RPC bind is type 0x0b.
pub(crate) static LSA_WORKER_PDU_READS: AtomicU64 = AtomicU64::new(0);
pub(crate) static LSA_WORKER_FIRST_PDU_TYPE: AtomicU64 = AtomicU64::new(0xFF);
/// PDUs the worker WROTE back onto the connection, and the first one's PDU type (bind_ack = 0x0c).
pub(crate) static LSA_WORKER_PDU_WRITES: AtomicU64 = AtomicU64::new(0);
pub(crate) static LSA_WORKER_FIRST_REPLY_TYPE: AtomicU64 = AtomicU64::new(0xFF);
/// The `\pipe\lsarpc` CLIENT side inside lsass itself (the self-RPC): PDUs written by lsass' main
/// thread (advapi32's auto-bind + the `LsarOpenPolicy` request) and PDUs it read back.
pub(crate) static LSA_SELF_RPC_CLIENT_WRITES: AtomicU64 = AtomicU64::new(0);
pub(crate) static LSA_SELF_RPC_CLIENT_READS: AtomicU64 = AtomicU64::new(0);
/// `pipe_name_hash` of the `\lsarpc` leaf, so the self-RPC instrumentation is NAME-SCOPED (the same
/// hash the async-listen table + connect re-drive already key on). The leaf carries its leading
/// backslash exactly as `pipe_leaf16` produces it.
pub(crate) fn lsarpc_pipe_name_hash() -> u64 {
    const LEAF: [u16; 7] = [
        b'\\' as u16,
        b'l' as u16,
        b's' as u16,
        b'a' as u16,
        b'r' as u16,
        b'p' as u16,
        b'c' as u16,
    ];
    nt_io_manager::pipe_name_hash(&LEAF)
}
/// Multiplex-event counter for winlogon's rpcrt4 server WORKER thread (badge WINLOGON_WORKER_BADGE).
/// Proves the worker actually RUNS (not suspended) — spec `exec_winlogon_worker_multiplex`.
static WL_WORKER_FAULTS: AtomicU64 = AtomicU64::new(0);
/// Set once the main thread has queried the real listener thread's TEB/ClientId via
/// NtQueryInformationThread(ThreadBasicInformation) — proves the NULL-deref is gone.
static WL_LISTENER_TEB_QUERIED: AtomicU64 = AtomicU64::new(0);

/// Per-hosted-process demand-fill bookkeeping (page VA per fault index), one row per process
/// (0 = smss, 1 = csrss, 2 = winlogon, 3 = services, 4 = lsass; MAX_PI rows for post-login growth).
/// Kept off the bounded rootserver stack — this array as a local plus service_sec_image's other
/// arrays would risk the guard page. In `.bss`, so growth to MAX_PI is free (no stack cost).
/// Zeroed at service_sec_image entry; only that single loop touches it.
static mut PFILLED: [[u64; 512]; MAX_PI] = [[0u64; 512]; MAX_PI];
/// SERVICE 10 stack relief: the per-iteration `filled_pages` WORKING buffer (loaded from / saved to
/// `PFILLED[pi]` around each dispatch) lives in a static, not on the rootserver stack. Adding a
/// 5th hosted process pushed `service_sec_image`'s frame — its `[u64;256]` working array plus the
/// ~20 DLL-PE locals — over the stack guard on the DEEP FS-walk call chain (fat_open_path →
/// dir_find_lfn), corrupting that loop's cluster variable → an infinite FAT cluster-chain spin
/// (100% CPU, no panic). Single-threaded executive → one active pi per iteration → one shared buffer
/// is safe. Removing this 4 KiB from the frame keeps the boot within the 4-page stack (no kernel
/// change → sel4test byte-identical).
static mut FILLED_WORK: [u64; 512] = [0u64; 512];

/// Persistent directory FILE_OBJECT state. `ExecNtHandler` is a local in
/// `service_sec_image`; embedding this table there adds roughly 34 KiB and makes the
/// service function's frame exceed the bounded rootserver stack. The executive loop
/// is serialized, so one fixed table can be reset and exclusively borrowed by each
/// successive handler instance.
static mut DIRECTORY_OPEN_WORK: nt_fs::DirectoryOpenTable<64> = nt_fs::DirectoryOpenTable::new();

fn try_alloc_slot() -> Option<u64> {
    if let Some(slot) = try_recycled_root_slot() {
        return Some(slot);
    }
    let end = ROOT_CSPACE_END.load(Ordering::Relaxed);
    let mut current = NEXT_SLOT.load(Ordering::Relaxed);
    loop {
        if current >= end {
            return None;
        }
        match NEXT_SLOT.compare_exchange_weak(
            current,
            current + 1,
            Ordering::Relaxed,
            Ordering::Relaxed,
        ) {
            Ok(_) => {
                unsafe {
                    let _ = root_slot_mark_live(current);
                }
                return Some(current);
            }
            Err(observed) => current = observed,
        }
    }
}

fn alloc_slot() -> u64 {
    match try_alloc_slot() {
        Some(slot) => slot,
        None => {
            print_str(b"[cap] root CSpace exhausted\n");
            park()
        }
    }
}

fn try_alloc_slot_run(count: u64) -> Option<u64> {
    if count == 0 {
        return None;
    }
    let end = ROOT_CSPACE_END.load(Ordering::Relaxed);
    let mut current = NEXT_SLOT.load(Ordering::Relaxed);
    loop {
        let next = current.checked_add(count)?;
        if next > end {
            return None;
        }
        match NEXT_SLOT.compare_exchange_weak(current, next, Ordering::Relaxed, Ordering::Relaxed) {
            Ok(_) => {
                let mut slot = current;
                while slot < next {
                    unsafe {
                        let _ = root_slot_mark_live(slot);
                    }
                    slot += 1;
                }
                return Some(current);
            }
            Err(observed) => current = observed,
        }
    }
}

fn root_slot_bit(slot: u64) -> Option<(usize, u64)> {
    let start = ROOT_CSPACE_START.load(Ordering::Relaxed);
    let end = ROOT_CSPACE_END.load(Ordering::Relaxed);
    if slot < start || slot >= end {
        return None;
    }
    let index = (slot - start) as usize;
    let word = index / 64;
    if word >= ROOT_SLOT_LIVE_WORDS {
        return None;
    }
    Some((word, 1u64 << (index % 64)))
}

unsafe fn root_slot_mark_live(slot: u64) -> bool {
    let Some((word, bit)) = root_slot_bit(slot) else {
        return false;
    };
    let live = core::ptr::addr_of_mut!(ROOT_SLOT_LIVE_BITS) as *mut u64;
    let old = core::ptr::read(live.add(word));
    core::ptr::write(live.add(word), old | bit);
    old & bit == 0
}

unsafe fn root_slot_clear_live(slot: u64) -> bool {
    let Some((word, bit)) = root_slot_bit(slot) else {
        return false;
    };
    let live = core::ptr::addr_of_mut!(ROOT_SLOT_LIVE_BITS) as *mut u64;
    let old = core::ptr::read(live.add(word));
    if old & bit == 0 {
        return false;
    }
    core::ptr::write(live.add(word), old & !bit);
    true
}

unsafe fn root_slot_remove_recycled(slot: u64) -> bool {
    let n = ROOT_SLOT_RECYCLE_N.load(Ordering::Relaxed);
    let stack = core::ptr::addr_of_mut!(ROOT_SLOT_RECYCLE) as *mut u64;
    let mut i = 0;
    while i < n {
        if core::ptr::read(stack.add(i as usize)) == slot {
            let next = n - 1;
            if i != next {
                let last = core::ptr::read(stack.add(next as usize));
                core::ptr::write(stack.add(i as usize), last);
            }
            core::ptr::write(stack.add(next as usize), 0);
            ROOT_SLOT_RECYCLE_N.store(next, Ordering::Relaxed);
            return true;
        }
        i += 1;
    }
    false
}

unsafe fn root_slot_note_occupied(slot: u64) {
    if root_slot_mark_live(slot) {
        let _ = root_slot_remove_recycled(slot);
    }
}

fn try_recycled_root_slot() -> Option<u64> {
    loop {
        let n = ROOT_SLOT_RECYCLE_N.load(Ordering::Relaxed);
        if n == 0 {
            return None;
        }
        let next = n - 1;
        ROOT_SLOT_RECYCLE_N.store(next, Ordering::Relaxed);
        let slot = unsafe {
            core::ptr::read(
                (core::ptr::addr_of!(ROOT_SLOT_RECYCLE) as *const u64).add(next as usize),
            )
        };
        if unsafe { root_slot_mark_live(slot) } {
            ROOT_SLOT_RECYCLE_REUSED.fetch_add(1, Ordering::Relaxed);
            return Some(slot);
        }
        ROOT_SLOT_RECYCLE_DROPPED.fetch_add(1, Ordering::Relaxed);
    }
}

unsafe fn recycle_deleted_root_slot(slot: u64) {
    if !root_slot_clear_live(slot) {
        return;
    }
    let n = ROOT_SLOT_RECYCLE_N.load(Ordering::Relaxed);
    if n >= ROOT_SLOT_RECYCLE_CAP as u64 {
        ROOT_SLOT_RECYCLE_DROPPED.fetch_add(1, Ordering::Relaxed);
        return;
    }
    core::ptr::write(
        (core::ptr::addr_of_mut!(ROOT_SLOT_RECYCLE) as *mut u64).add(n as usize),
        slot,
    );
    let next = n + 1;
    ROOT_SLOT_RECYCLE_N.store(next, Ordering::Relaxed);
    note_high_water(&ROOT_SLOT_RECYCLE_HW, next);
}

fn root_slot_available_count() -> u64 {
    let end = ROOT_CSPACE_END.load(Ordering::Relaxed);
    let bump = NEXT_SLOT.load(Ordering::Relaxed);
    let bump_free = end.saturating_sub(bump);
    bump_free + ROOT_SLOT_RECYCLE_N.load(Ordering::Relaxed)
}

// --- Shared executable-page cache (generic DLL loader) --------------------------------------------
// A DLL's RX (text) page is identical across processes — each DLL is loaded at a fixed system-wide
// base and (for the ServerDlls) pre-relocated, so no per-process relocation touches its code. So we
// fill each such page ONCE into a frame and map THAT frame read-only into every process that faults
// it — real Windows image sharing (fewer frames, one fill). Keyed by page VA (base+rva). Frames
// persist for the run (no process teardown yet). Accessed via raw pointers to avoid the
// static_mut_refs lint; single-threaded executive, so no races.
const DLL_CACHE_CAP: usize = 4096;
static mut DLL_CACHE_VA: [u64; DLL_CACHE_CAP] = [0; DLL_CACHE_CAP];
static mut DLL_CACHE_FR: [u64; DLL_CACHE_CAP] = [0; DLL_CACHE_CAP];
static mut DLL_CACHE_N: usize = 0;
static DLL_SHARED_HITS: AtomicU64 = AtomicU64::new(0);
/// The shared frame cap for page VA `va`, or 0 if not yet cached.
unsafe fn dll_cache_get(va: u64) -> u64 {
    let n = core::ptr::read(core::ptr::addr_of!(DLL_CACHE_N));
    let vas = core::ptr::addr_of!(DLL_CACHE_VA) as *const u64;
    let frs = core::ptr::addr_of!(DLL_CACHE_FR) as *const u64;
    for i in 0..n {
        if core::ptr::read(vas.add(i)) == va {
            return core::ptr::read(frs.add(i));
        }
    }
    0
}
/// Record the shared frame `fr` for page VA `va` (once, on first fill).
unsafe fn dll_cache_put(va: u64, fr: u64) {
    let n = core::ptr::read(core::ptr::addr_of!(DLL_CACHE_N));
    if n < DLL_CACHE_CAP {
        let vas = core::ptr::addr_of_mut!(DLL_CACHE_VA) as *mut u64;
        let frs = core::ptr::addr_of_mut!(DLL_CACHE_FR) as *mut u64;
        core::ptr::write(vas.add(n), va);
        core::ptr::write(frs.add(n), fr);
        core::ptr::write(core::ptr::addr_of_mut!(DLL_CACHE_N), n + 1);
    }
}

// --- per-process private-page frame tracking ------------------------------------------------------
// win32k runs in its own component VSpace, but its NtUser/NtGdi handlers dereference the CALLING
// process's (the GUI client's) user pointers DIRECTLY — the authentic Windows model where win32k
// shares the caller's user address space. To emulate that we map the CURRENT dispatch client's OWN
// frame for a faulting page into win32k at the SAME VA (identity), so win32k reads/writes that
// caller's live memory (no per-SSN marshaling). This table is PER-CLIENT (pi-keyed): csrss (pi 1)
// and winlogon (pi 2) load an OVERLAPPING set of DLLs/stacks at IDENTICAL VAs but into DISTINCT
// frames, so the SAME VA resolves to a DIFFERENT frame per client. The win32k `attach` (see
// `w32_client_attach`) re-points win32k's client window to the current dispatch's client, mapping
// THIS pi's frame at each colliding VA (the KeStackAttachProcess model). It records the frame cap
// the fault-fill path allocated for each PER-PROCESS client page ((pi,page) -> frame cptr); the
// shared-DLL-text cache (`dll_cache`) covers RX pages (byte-identical across clients). The
// executive's scratch alias already shares these frames, so the client's runtime writes are visible.
// Every hosted process is recorded because bounded forward prefetch must also detect already-mapped
// private neighbours in services and LSASS. GUI attach consumes only the entries for its selected
// pi. Winlogon's runtime worker stacks are created late, after the former 8192-entry table could
// already be full; silently dropping those entries made win32k attach an unrelated page at the same
// user VA.
const CSRSS_FRAME_CAP: usize = 32768;
static mut CSRSS_FRAME_PI: [u8; CSRSS_FRAME_CAP] = [0; CSRSS_FRAME_CAP];
static mut CSRSS_FRAME_VA: [u64; CSRSS_FRAME_CAP] = [0; CSRSS_FRAME_CAP];
static mut CSRSS_FRAME_FR: [u64; CSRSS_FRAME_CAP] = [0; CSRSS_FRAME_CAP];
static mut CSRSS_FRAME_ALIAS: [u64; CSRSS_FRAME_CAP] = [0; CSRSS_FRAME_CAP];
static mut CSRSS_FRAME_ALIAS_CAP: [u64; CSRSS_FRAME_CAP] = [0; CSRSS_FRAME_CAP];
static mut CSRSS_FRAME_SOURCE_CAP: [u64; CSRSS_FRAME_CAP] = [0; CSRSS_FRAME_CAP];
static mut CSRSS_FRAME_OWNS_FRAME: [bool; CSRSS_FRAME_CAP] = [false; CSRSS_FRAME_CAP];
static mut CSRSS_FRAME_N: usize = 0;
static CLIENT_COPY_TEMP_CAP: AtomicU64 = AtomicU64::new(0);
#[derive(Copy, Clone)]
struct CsrssFrameRecord {
    frame: u64,
    alias: u64,
    source_cap: u64,
    owns_frame: bool,
}
/// Record GUI client `pi`'s frame cap `fr` for page VA `page` (once per (pi,page)).
unsafe fn csrss_frame_put(pi: u64, page: u64, fr: u64) {
    let _ = csrss_frame_put_at_cap_source(pi, page, fr, 0, 0, 0);
}
pub(crate) unsafe fn csrss_frame_put_with_source(
    pi: u64,
    page: u64,
    fr: u64,
    source_cap: u64,
) -> bool {
    csrss_frame_put_at_cap_source(pi, page, fr, 0, 0, source_cap)
}
/// Record a client frame and, for image pages, its permanent executive scratch alias. Keeping the
/// alias alongside the cap avoids remapping a copied cap merely to inspect live client data.
pub(crate) unsafe fn csrss_frame_put_at(pi: u64, page: u64, fr: u64, alias: u64) {
    let _ = csrss_frame_put_at_cap_source(pi, page, fr, alias, 0, 0);
}
unsafe fn csrss_frame_put_at_cap(pi: u64, page: u64, fr: u64, alias: u64, alias_cap: u64) -> bool {
    csrss_frame_put_at_cap_source(pi, page, fr, alias, alias_cap, 0)
}
unsafe fn csrss_frame_put_at_cap_source(
    pi: u64,
    page: u64,
    fr: u64,
    alias: u64,
    alias_cap: u64,
    source_cap: u64,
) -> bool {
    csrss_frame_put_at_cap_source_owned(pi, page, fr, alias, alias_cap, source_cap, true)
}

pub(crate) unsafe fn csrss_frame_put_section_mapping(
    pi: u64,
    page: u64,
    fr: u64,
    source_cap: u64,
) -> bool {
    csrss_frame_put_at_cap_source_owned(pi, page, fr, 0, 0, source_cap, false)
}

unsafe fn csrss_frame_put_at_cap_source_owned(
    pi: u64,
    page: u64,
    fr: u64,
    alias: u64,
    alias_cap: u64,
    source_cap: u64,
    owns_frame: bool,
) -> bool {
    let n = core::ptr::read(core::ptr::addr_of!(CSRSS_FRAME_N)).min(CSRSS_FRAME_CAP);
    let vas = core::ptr::addr_of!(CSRSS_FRAME_VA) as *const u64;
    let pis = core::ptr::addr_of!(CSRSS_FRAME_PI) as *const u8;
    let frs = core::ptr::addr_of!(CSRSS_FRAME_FR) as *const u64;
    for i in 0..n {
        if core::ptr::read(vas.add(i)) == page && core::ptr::read(pis.add(i)) as u64 == pi {
            if core::ptr::read(frs.add(i)) != fr {
                return false;
            }
            if alias != 0 {
                let aliases = core::ptr::addr_of_mut!(CSRSS_FRAME_ALIAS) as *mut u64;
                if core::ptr::read(aliases.add(i)) == 0 {
                    core::ptr::write(aliases.add(i), alias);
                }
            }
            if alias_cap != 0 {
                let alias_caps = core::ptr::addr_of_mut!(CSRSS_FRAME_ALIAS_CAP) as *mut u64;
                if core::ptr::read(alias_caps.add(i)) == 0 {
                    core::ptr::write(alias_caps.add(i), alias_cap);
                }
            }
            if source_cap != 0 {
                let source_caps = core::ptr::addr_of_mut!(CSRSS_FRAME_SOURCE_CAP) as *mut u64;
                if core::ptr::read(source_caps.add(i)) == 0 {
                    core::ptr::write(source_caps.add(i), source_cap);
                }
            }
            let owned = core::ptr::addr_of_mut!(CSRSS_FRAME_OWNS_FRAME) as *mut bool;
            if core::ptr::read(owned.add(i)) != owns_frame {
                return false;
            }
            return true;
        }
    }
    if n < CSRSS_FRAME_CAP {
        core::ptr::write(
            (core::ptr::addr_of_mut!(CSRSS_FRAME_PI) as *mut u8).add(n),
            pi as u8,
        );
        core::ptr::write(
            (core::ptr::addr_of_mut!(CSRSS_FRAME_VA) as *mut u64).add(n),
            page,
        );
        core::ptr::write(
            (core::ptr::addr_of_mut!(CSRSS_FRAME_FR) as *mut u64).add(n),
            fr,
        );
        core::ptr::write(
            (core::ptr::addr_of_mut!(CSRSS_FRAME_ALIAS) as *mut u64).add(n),
            alias,
        );
        core::ptr::write(
            (core::ptr::addr_of_mut!(CSRSS_FRAME_ALIAS_CAP) as *mut u64).add(n),
            alias_cap,
        );
        core::ptr::write(
            (core::ptr::addr_of_mut!(CSRSS_FRAME_SOURCE_CAP) as *mut u64).add(n),
            source_cap,
        );
        core::ptr::write(
            (core::ptr::addr_of_mut!(CSRSS_FRAME_OWNS_FRAME) as *mut bool).add(n),
            owns_frame,
        );
        core::ptr::write(core::ptr::addr_of_mut!(CSRSS_FRAME_N), n + 1);
        note_high_water(&CSRSS_FRAME_HW, (n + 1) as u64);
        true
    } else {
        CSRSS_FRAME_FULL.fetch_add(1, Ordering::Relaxed);
        false
    }
}
unsafe fn csrss_frame_take(pi: u64, page: u64) -> Option<(u64, u64, u64, bool)> {
    let n = core::ptr::read(core::ptr::addr_of!(CSRSS_FRAME_N)).min(CSRSS_FRAME_CAP);
    let vas = core::ptr::addr_of_mut!(CSRSS_FRAME_VA) as *mut u64;
    let pis = core::ptr::addr_of_mut!(CSRSS_FRAME_PI) as *mut u8;
    let frs = core::ptr::addr_of_mut!(CSRSS_FRAME_FR) as *mut u64;
    let aliases = core::ptr::addr_of_mut!(CSRSS_FRAME_ALIAS) as *mut u64;
    let alias_caps = core::ptr::addr_of_mut!(CSRSS_FRAME_ALIAS_CAP) as *mut u64;
    let source_caps = core::ptr::addr_of_mut!(CSRSS_FRAME_SOURCE_CAP) as *mut u64;
    let owns_frames = core::ptr::addr_of_mut!(CSRSS_FRAME_OWNS_FRAME) as *mut bool;
    for index in 0..n {
        if core::ptr::read(vas.add(index)) == page && core::ptr::read(pis.add(index)) as u64 == pi {
            let frame = core::ptr::read(frs.add(index));
            let alias_cap = core::ptr::read(alias_caps.add(index));
            let source_cap = core::ptr::read(source_caps.add(index));
            let owns_frame = core::ptr::read(owns_frames.add(index));
            let last = n - 1;
            if index != last {
                core::ptr::write(vas.add(index), core::ptr::read(vas.add(last)));
                core::ptr::write(pis.add(index), core::ptr::read(pis.add(last)));
                core::ptr::write(frs.add(index), core::ptr::read(frs.add(last)));
                core::ptr::write(aliases.add(index), core::ptr::read(aliases.add(last)));
                core::ptr::write(alias_caps.add(index), core::ptr::read(alias_caps.add(last)));
                core::ptr::write(
                    source_caps.add(index),
                    core::ptr::read(source_caps.add(last)),
                );
                core::ptr::write(
                    owns_frames.add(index),
                    core::ptr::read(owns_frames.add(last)),
                );
            }
            core::ptr::write(vas.add(last), 0);
            core::ptr::write(pis.add(last), 0);
            core::ptr::write(frs.add(last), 0);
            core::ptr::write(aliases.add(last), 0);
            core::ptr::write(alias_caps.add(last), 0);
            core::ptr::write(source_caps.add(last), 0);
            core::ptr::write(owns_frames.add(last), false);
            core::ptr::write(core::ptr::addr_of_mut!(CSRSS_FRAME_N), last);
            return Some((frame, alias_cap, source_cap, owns_frame));
        }
    }
    None
}
/// Exact per-process frame lookup. Unlike `csrss_frame_get`, this never falls back to the shared
/// executable-page cache, which is important when deciding whether a writable client page has a
/// persistent private backing frame.
unsafe fn csrss_frame_get_exact(pi: u64, page: u64) -> (u64, usize) {
    let n = core::ptr::read(core::ptr::addr_of!(CSRSS_FRAME_N)).min(CSRSS_FRAME_CAP);
    let vas = core::ptr::addr_of!(CSRSS_FRAME_VA) as *const u64;
    let frs = core::ptr::addr_of!(CSRSS_FRAME_FR) as *const u64;
    let pis = core::ptr::addr_of!(CSRSS_FRAME_PI) as *const u8;
    for i in 0..n {
        if core::ptr::read(vas.add(i)) == page && core::ptr::read(pis.add(i)) as u64 == pi {
            return (core::ptr::read(frs.add(i)), i);
        }
    }
    (0, usize::MAX)
}
unsafe fn csrss_frame_get_exact_record(pi: u64, page: u64) -> Option<CsrssFrameRecord> {
    let (frame, index) = csrss_frame_get_exact(pi, page);
    if index == usize::MAX || frame == 0 {
        return None;
    }
    Some(CsrssFrameRecord {
        frame,
        alias: core::ptr::read((core::ptr::addr_of!(CSRSS_FRAME_ALIAS) as *const u64).add(index)),
        source_cap: core::ptr::read(
            (core::ptr::addr_of!(CSRSS_FRAME_SOURCE_CAP) as *const u64).add(index),
        ),
        owns_frame: core::ptr::read(
            (core::ptr::addr_of!(CSRSS_FRAME_OWNS_FRAME) as *const bool).add(index),
        ),
    })
}
unsafe fn csrss_frame_next_page_after(pi: u64, page: u64) -> Option<u64> {
    let n = core::ptr::read(core::ptr::addr_of!(CSRSS_FRAME_N)).min(CSRSS_FRAME_CAP);
    let vas = core::ptr::addr_of!(CSRSS_FRAME_VA) as *const u64;
    let pis = core::ptr::addr_of!(CSRSS_FRAME_PI) as *const u8;
    let mut next = None;
    for i in 0..n {
        if core::ptr::read(pis.add(i)) as u64 == pi {
            let candidate = core::ptr::read(vas.add(i));
            if candidate > page && next.is_none_or(|current| candidate < current) {
                next = Some(candidate);
            }
        }
    }
    next
}
unsafe fn csrss_frame_alias_get(pi: u64, page: u64) -> u64 {
    let (_, index) = csrss_frame_get_exact(pi, page);
    if index == usize::MAX {
        0
    } else {
        core::ptr::read((core::ptr::addr_of!(CSRSS_FRAME_ALIAS) as *const u64).add(index))
    }
}
pub(crate) unsafe fn csrss_frame_source_cap_get(pi: u64, page: u64) -> u64 {
    let (_, index) = csrss_frame_get_exact(pi, page);
    if index == usize::MAX {
        0
    } else {
        core::ptr::read((core::ptr::addr_of!(CSRSS_FRAME_SOURCE_CAP) as *const u64).add(index))
    }
}
pub(crate) unsafe fn csrss_frame_clone_source_cap_get(pi: u64, page: u64) -> u64 {
    let (frame, index) = csrss_frame_get_exact(pi, page);
    if index == usize::MAX || frame == 0 {
        return 0;
    }
    let source_cap =
        core::ptr::read((core::ptr::addr_of!(CSRSS_FRAME_SOURCE_CAP) as *const u64).add(index));
    if source_cap != 0 {
        source_cap
    } else {
        frame
    }
}
unsafe fn copy_registered_frame_cap(source: u64) -> (u64, u64) {
    if source == 0 {
        return (0, 3);
    }
    let (copied, error) = copy_cap_r(source);
    if error == 0 {
        return (copied, 0);
    }
    if copied != 0 {
        let _ = cnode_delete_recycle_r(copied);
    }
    (0, error)
}
pub(crate) unsafe fn csrss_frame_create_source_copy(
    parent: u64,
    pi: u64,
    page: u64,
    what: &[u8],
) -> u64 {
    if parent == 0 {
        print_str(b"[frame-source] ");
        print_str(what);
        print_str(b" missing parent pi=");
        print_u64(pi);
        print_str(b" page=0x");
        print_hex((page >> 32) as u32);
        print_hex(page as u32);
        print_str(b"\n");
        return 0;
    }
    let (source, error) = copy_cap_r(parent);
    if error == 0 {
        return source;
    }
    if source != 0 {
        let _ = cnode_delete_recycle_r(source);
    }
    print_str(b"[frame-source] ");
    print_str(what);
    print_str(b" copy failed pi=");
    print_u64(pi);
    print_str(b" page=0x");
    print_hex((page >> 32) as u32);
    print_hex(page as u32);
    print_str(b" parent=0x");
    print_hex(parent as u32);
    print_str(b" error=");
    print_u64(error);
    print_str(b"\n");
    0
}

static FRAME_SOURCE_PROBE_OK_LOGS: AtomicU64 = AtomicU64::new(0);
static FRAME_SOURCE_PROBE_FAIL_LOGS: AtomicU64 = AtomicU64::new(0);
static FRAME_SOURCE_REMAP_FAIL_PROBES: AtomicU64 = AtomicU64::new(0);

unsafe fn csrss_frame_probe_source_copy(pi: u64, page: u64, source_cap: u64, what: &[u8]) {
    if source_cap == 0 {
        return;
    }
    let (probe, error) = copy_cap_r(source_cap);
    if error == 0 {
        let _ = cnode_delete_recycle_r(probe);
        if FRAME_SOURCE_PROBE_OK_LOGS.fetch_add(1, Ordering::Relaxed) < 16 {
            print_str(b"[frame-source] ");
            print_str(what);
            print_str(b" probe ok pi=");
            print_u64(pi);
            print_str(b" page=0x");
            print_hex((page >> 32) as u32);
            print_hex(page as u32);
            print_str(b" source=0x");
            print_hex(source_cap as u32);
            print_str(b"\n");
        }
        return;
    }
    if FRAME_SOURCE_PROBE_FAIL_LOGS.fetch_add(1, Ordering::Relaxed) < 16 {
        print_str(b"[frame-source] ");
        print_str(what);
        print_str(b" probe failed pi=");
        print_u64(pi);
        print_str(b" page=0x");
        print_hex((page >> 32) as u32);
        print_hex(page as u32);
        print_str(b" source=0x");
        print_hex(source_cap as u32);
        print_str(b" error=");
        print_u64(error);
        print_str(b"\n");
    }
}

unsafe fn csrss_frame_probe_primary_after_source_failure(
    pi: u64,
    page: u64,
    frame: u64,
    source_cap: u64,
    source_error: u64,
) {
    if FRAME_SOURCE_REMAP_FAIL_PROBES.fetch_add(1, Ordering::Relaxed) >= 16 {
        return;
    }
    let (root_cnode_probe, root_cnode_error) = copy_cap_r(CAP_INIT_THREAD_CNODE);
    if root_cnode_error == 0 {
        let _ = cnode_delete_recycle_r(root_cnode_probe);
    }
    let (root_vspace_probe, root_vspace_error) = copy_cap_r(CAP_INIT_THREAD_VSPACE);
    if root_vspace_error == 0 {
        let _ = cnode_delete_recycle_r(root_vspace_probe);
    }
    let (primary_probe, primary_error) = copy_cap_r(frame);
    if primary_error == 0 {
        let _ = cnode_delete_recycle_r(primary_probe);
    }
    print_str(b"[frame-source] remap source copy failed pi=");
    print_u64(pi);
    print_str(b" page=0x");
    print_hex((page >> 32) as u32);
    print_hex(page as u32);
    print_str(b" source=0x");
    print_hex(source_cap as u32);
    print_str(b" source-error=");
    print_u64(source_error);
    print_str(b" primary=0x");
    print_hex(frame as u32);
    print_str(b" primary-probe-error=");
    print_u64(primary_error);
    print_str(b" root-cnode-probe-error=");
    print_u64(root_cnode_error);
    print_str(b" root-vspace-probe-error=");
    print_u64(root_vspace_error);
    print_str(b"\n");
}

/// Copy the registered per-client frame cap for a win32k attach/remap. Records that have a separate
/// derivation source must copy from that source; source-less records copy their primary cap. Executive
/// scratch aliases are intentionally not consulted here, because a missing/invalid source is a real
/// frame-registration bug that should stay visible.
pub(crate) unsafe fn csrss_frame_copy_exact_for_win32k(pi: u64, page: u64) -> (u64, u64, u64) {
    let (frame, index) = csrss_frame_get_exact(pi, page);
    if index == usize::MAX || frame == 0 {
        return (0, 0, 3);
    }
    let source_cap = csrss_frame_source_cap_get(pi, page);
    if source_cap != 0 {
        let (source_copy, source_error) = copy_registered_frame_cap(source_cap);
        if source_error != 0 {
            csrss_frame_probe_primary_after_source_failure(
                pi,
                page,
                frame,
                source_cap,
                source_error,
            );
        }
        return (source_copy, source_cap, source_error);
    }
    let (copied, error) = copy_registered_frame_cap(frame);
    (copied, frame, error)
}
unsafe fn client_range_has_backing(pi: u64, va: u64, len: usize) -> bool {
    if len == 0 {
        return true;
    }
    let Some(end) = va.checked_add(len as u64 - 1) else {
        return false;
    };
    let mut page = va & !0xfff;
    let last = end & !0xfff;
    loop {
        if csrss_frame_get_exact(pi, page).0 == 0 {
            return false;
        }
        if page == last {
            return true;
        }
        page += 0x1000;
    }
}
unsafe fn client_copy_temp_cap() -> u64 {
    let cap = CLIENT_COPY_TEMP_CAP.load(Ordering::Relaxed);
    if cap != 0 {
        cap
    } else {
        let cap = alloc_slot();
        CLIENT_COPY_TEMP_CAP.store(cap, Ordering::Relaxed);
        cap
    }
}
/// GUI client `pi`'s frame cap for page VA `page`, or 0 if not backed by a recorded per-process
/// frame (falls back to the shared-DLL-text cache, which backs every client's RX pages identically).
unsafe fn csrss_frame_get(pi: u64, page: u64) -> u64 {
    let (frame, _) = csrss_frame_get_exact(pi, page);
    if frame != 0 {
        return frame;
    }
    dll_cache_get(page)
}

#[derive(Clone, Copy)]
struct SharedImageMapping {
    pi: u8,
    page: u64,
    map_cap: u64,
}

static mut SHARED_IMAGE_MAPPINGS: Option<Vec<SharedImageMapping>> = None;
static SHARED_IMAGE_MAPPING_DIRTY: AtomicBool = AtomicBool::new(false);

unsafe fn shared_image_mappings_mut() -> &'static mut Vec<SharedImageMapping> {
    let slot = &mut *core::ptr::addr_of_mut!(SHARED_IMAGE_MAPPINGS);
    if slot.is_none() {
        *slot = Some(Vec::new());
    }
    slot.as_mut().unwrap()
}

pub(crate) fn take_shared_image_mapping_dirty() -> bool {
    SHARED_IMAGE_MAPPING_DIRTY.swap(false, Ordering::Relaxed)
}

unsafe fn shared_image_mapping_put(pi: u64, page: u64, map_cap: u64) -> bool {
    if pi > u8::MAX as u64 || map_cap == 0 {
        SHARED_IMAGE_MAPPING_FAILS.fetch_add(1, Ordering::Relaxed);
        return false;
    }
    let table = shared_image_mappings_mut();
    for existing in table.iter() {
        if existing.pi as u64 == pi && existing.page == page {
            if existing.map_cap == map_cap {
                return true;
            }
            SHARED_IMAGE_MAPPING_FAILS.fetch_add(1, Ordering::Relaxed);
            return false;
        }
    }
    if table.len() == table.capacity() {
        if table.try_reserve(512).is_err() {
            SHARED_IMAGE_MAPPING_FAILS.fetch_add(1, Ordering::Relaxed);
            return false;
        }
        SHARED_IMAGE_MAPPING_DIRTY.store(true, Ordering::Relaxed);
    }
    table.push(SharedImageMapping {
        pi: pi as u8,
        page,
        map_cap,
    });
    note_high_water(&SHARED_IMAGE_MAPPING_HW, table.len() as u64);
    true
}

unsafe fn shared_image_mapping_get(pi: u64, page: u64) -> Option<u64> {
    let table = (*core::ptr::addr_of!(SHARED_IMAGE_MAPPINGS)).as_ref()?;
    table
        .iter()
        .find(|mapping| mapping.pi as u64 == pi && mapping.page == page)
        .map(|mapping| mapping.map_cap)
}

unsafe fn shared_image_mapping_take(pi: u64, page: u64) -> Option<u64> {
    let table = (*core::ptr::addr_of_mut!(SHARED_IMAGE_MAPPINGS)).as_mut()?;
    let index = table
        .iter()
        .position(|mapping| mapping.pi as u64 == pi && mapping.page == page)?;
    Some(table.swap_remove(index).map_cap)
}

unsafe fn shared_image_mapping_unmap_range(pi: u64, base: u64, end: u64) {
    let Some(table) = (*core::ptr::addr_of_mut!(SHARED_IMAGE_MAPPINGS)).as_mut() else {
        return;
    };
    let mut index = 0usize;
    while index < table.len() {
        let mapping = table[index];
        if mapping.pi as u64 == pi && mapping.page >= base && mapping.page < end {
            let map_cap = table.swap_remove(index).map_cap;
            let _ = page_unmap_r(map_cap);
            let _ = cnode_delete_recycle_r(map_cap);
        } else {
            index += 1;
        }
    }
}

const CLIENT_COPYIN_FRAME_CAP: usize = 256;
static mut CLIENT_COPYIN_FRAME_PI: [u8; CLIENT_COPYIN_FRAME_CAP] = [0; CLIENT_COPYIN_FRAME_CAP];
static mut CLIENT_COPYIN_FRAME_VA: [u64; CLIENT_COPYIN_FRAME_CAP] = [0; CLIENT_COPYIN_FRAME_CAP];
static mut CLIENT_COPYIN_FRAME_FR: [u64; CLIENT_COPYIN_FRAME_CAP] = [0; CLIENT_COPYIN_FRAME_CAP];
static mut CLIENT_COPYIN_FRAME_ALIAS: [u64; CLIENT_COPYIN_FRAME_CAP] = [0; CLIENT_COPYIN_FRAME_CAP];
static mut CLIENT_COPYIN_FRAME_N: usize = 0;

unsafe fn client_copyin_frame_put(pi: u64, page: u64, fr: u64, alias: u64) {
    let n = core::ptr::read(core::ptr::addr_of!(CLIENT_COPYIN_FRAME_N));
    let vas = core::ptr::addr_of!(CLIENT_COPYIN_FRAME_VA) as *const u64;
    let pis = core::ptr::addr_of!(CLIENT_COPYIN_FRAME_PI) as *const u8;
    for i in 0..n {
        if core::ptr::read(vas.add(i)) == page && core::ptr::read(pis.add(i)) as u64 == pi {
            return;
        }
    }
    if n < CLIENT_COPYIN_FRAME_CAP {
        core::ptr::write(
            (core::ptr::addr_of_mut!(CLIENT_COPYIN_FRAME_PI) as *mut u8).add(n),
            pi as u8,
        );
        core::ptr::write(
            (core::ptr::addr_of_mut!(CLIENT_COPYIN_FRAME_VA) as *mut u64).add(n),
            page,
        );
        core::ptr::write(
            (core::ptr::addr_of_mut!(CLIENT_COPYIN_FRAME_FR) as *mut u64).add(n),
            fr,
        );
        core::ptr::write(
            (core::ptr::addr_of_mut!(CLIENT_COPYIN_FRAME_ALIAS) as *mut u64).add(n),
            alias,
        );
        core::ptr::write(core::ptr::addr_of_mut!(CLIENT_COPYIN_FRAME_N), n + 1);
    }
}

unsafe fn client_copyin_frame_get(pi: u64, page: u64) -> u64 {
    let n = core::ptr::read(core::ptr::addr_of!(CLIENT_COPYIN_FRAME_N));
    let vas = core::ptr::addr_of!(CLIENT_COPYIN_FRAME_VA) as *const u64;
    let frs = core::ptr::addr_of!(CLIENT_COPYIN_FRAME_FR) as *const u64;
    let pis = core::ptr::addr_of!(CLIENT_COPYIN_FRAME_PI) as *const u8;
    for i in 0..n {
        if core::ptr::read(vas.add(i)) == page && core::ptr::read(pis.add(i)) as u64 == pi {
            return core::ptr::read(frs.add(i));
        }
    }
    0
}
unsafe fn client_copyin_frame_alias_get(pi: u64, page: u64) -> u64 {
    let n =
        core::ptr::read(core::ptr::addr_of!(CLIENT_COPYIN_FRAME_N)).min(CLIENT_COPYIN_FRAME_CAP);
    let vas = core::ptr::addr_of!(CLIENT_COPYIN_FRAME_VA) as *const u64;
    let aliases = core::ptr::addr_of!(CLIENT_COPYIN_FRAME_ALIAS) as *const u64;
    let pis = core::ptr::addr_of!(CLIENT_COPYIN_FRAME_PI) as *const u8;
    for i in 0..n {
        if core::ptr::read(vas.add(i)) == page && core::ptr::read(pis.add(i)) as u64 == pi {
            return core::ptr::read(aliases.add(i));
        }
    }
    0
}
// --- POOL CENSUS (batch 59) ------------------------------------------------------------------
// A fixed-capacity resource that silently returns "no" is this codebase's recurring wall (the bump
// heap at 93 %; `HEAP_FRAMES`; the VAD map). Every pool that backs a hosted process's private
// memory is now MEASURED — a high-water mark next to its capacity — and printed at the gate, so the
// NEXT exhaustion names itself instead of surfacing as a mysterious `STATUS_INSUFFICIENT_RESOURCES`.
/// Bytes carved out of the single boot Untyped (`CAP_INIT_UNTYPED`, 256 MiB) — the ONE pool with no
/// executive-side capacity constant, because the number lives in the kernel's `ROOTSERVER_UT_SIZE_BITS`.
/// seL4 aligns each retype to the object's own size, so this is a close lower bound, not exact.
pub(crate) static UT_RETYPE_BYTES: AtomicU64 = AtomicU64::new(0);
pub(crate) static UT_RETYPE_CALLS: AtomicU64 = AtomicU64::new(0);
/// The boot Untyped's size, published by the kernel in `BootInfo.untyped_list[..]` (the one
/// non-device untyped). Read at `_start`; 0 until then.
pub(crate) static UT_TOTAL_BYTES: AtomicU64 = AtomicU64::new(0);
/// Minimum root-Untyped runway that must remain after a full desktop proof boot. CSpace exhaustion
/// is now checked directly through live slot availability; Untyped pressure is a byte runway, not a
/// stale percentage tied to the earlier, smaller boot frontier.
pub(crate) const MIN_BOOT_UNTYPED_HEADROOM_BYTES: u64 = 48 * 1024 * 1024;
/// Retypes that came back with a real seL4 error label, and the last such label/object type.
/// `seL4_NotEnoughMemory` = 10 is "the boot Untyped is spent".
pub(crate) static UT_RETYPE_FAILS: AtomicU64 = AtomicU64::new(0);
pub(crate) static UT_LAST_FAIL_LABEL: AtomicU64 = AtomicU64::new(0);
pub(crate) static UT_LAST_FAIL_OBJ: AtomicU64 = AtomicU64::new(0);
/// High-water of the (pi, page) -> frame-cap registry (`CSRSS_FRAME_CAP`).
pub(crate) static CSRSS_FRAME_HW: AtomicU64 = AtomicU64::new(0);
/// Times the registry refused an insert because it was FULL — the failure that turns into
/// `STATUS_INSUFFICIENT_RESOURCES` out of `vm_map_private_page` with every seL4 call succeeding.
pub(crate) static CSRSS_FRAME_FULL: AtomicU64 = AtomicU64::new(0);
/// High-water of resident shared image process-map caps. These are not client frames: they exist so
/// mapped-image protect and write-copy faults can unmap/promote the exact PTE owner without
/// polluting the GUI/client frame registry.
pub(crate) static SHARED_IMAGE_MAPPING_HW: AtomicU64 = AtomicU64::new(0);
pub(crate) static SHARED_IMAGE_MAPPING_FAILS: AtomicU64 = AtomicU64::new(0);
/// High-water of the recycled-frame free list (`VM_FREE_FRAME_CAPACITY`).
pub(crate) static VM_FREE_FRAME_HW: AtomicU64 = AtomicU64::new(0);
/// Per-step failure tally for `vm_map_private_page`, so a refusal names its own sub-step.
pub(crate) static VM_FAIL_PT: AtomicU64 = AtomicU64::new(0);
pub(crate) static VM_FAIL_FRAME: AtomicU64 = AtomicU64::new(0);
pub(crate) static VM_FAIL_MAP: AtomicU64 = AtomicU64::new(0);
pub(crate) static VM_FAIL_ALIAS: AtomicU64 = AtomicU64::new(0);
pub(crate) static VM_FAIL_REGISTRY: AtomicU64 = AtomicU64::new(0);
/// High-water of the per-process VAD extent count (`VM_REGION_CAPACITY`).
pub(crate) static VM_REGION_HW: AtomicU64 = AtomicU64::new(0);
/// High-water of per-process committed mappings outside the private VAD allocator.
pub(crate) static VM_COMMITTED_MAPPING_HW: AtomicU64 = AtomicU64::new(0);
pub(crate) static VM_COMMITTED_MAPPING_REGISTRATION_FAILS: AtomicU64 = AtomicU64::new(0);
/// High-water of private per-page protection overrides.
pub(crate) static VM_PROTECTION_OVERRIDE_HW: AtomicU64 = AtomicU64::new(0);
/// User stack VADs released by thread teardown (`TEB.FreeStackOnTermination` semantics).
pub(crate) static USER_STACK_VAD_RELEASES: AtomicU64 = AtomicU64::new(0);
pub(crate) static USER_STACK_VAD_RELEASE_FAILS: AtomicU64 = AtomicU64::new(0);
/// Per-hosted-thread CSpace roots released after the owning TCB terminates. Short-lived ReactOS
/// RPC/TP workers create one private CNode each; failing to delete it exhausts the kernel CNode pool.
pub(crate) static HOSTED_THREAD_CNODE_RELEASES: AtomicU64 = AtomicU64::new(0);
pub(crate) static HOSTED_THREAD_CNODE_RELEASE_FAILS: AtomicU64 = AtomicU64::new(0);

/// Bytes one retyped object of `obj` (user size `bits`) consumes, mirroring the kernel's
/// `object_type::size_in_bits`.
fn retype_object_bytes(obj: u64, bits: u32) -> u64 {
    match obj {
        OBJ_TCB => 1 << 11,
        OBJ_ENDPOINT => 1 << 4,
        OBJ_NOTIFICATION => 1 << 5,
        OBJ_REPLY => 1 << 5,
        OBJ_CNODE => 1u64 << (bits + 5),
        OBJ_SCHED_CONTEXT | OBJ_UNTYPED => 1u64 << bits,
        // 4K page / PT / PD / PDPT / PML4 are each one 4 KiB page.
        _ => 1 << 12,
    }
}

fn note_retype(untyped: u64, obj: u64, bits: u32, num: u32) {
    if untyped != CAP_INIT_UNTYPED {
        return;
    }
    UT_RETYPE_CALLS.fetch_add(1, Ordering::Relaxed);
    UT_RETYPE_BYTES.fetch_add(
        retype_object_bytes(obj, bits) * num as u64,
        Ordering::Relaxed,
    );
}

fn note_retype_error(untyped: u64, obj: u64, label: u64) {
    if label == 0 || untyped != CAP_INIT_UNTYPED {
        return;
    }
    UT_RETYPE_FAILS.fetch_add(1, Ordering::Relaxed);
    UT_LAST_FAIL_LABEL.store(label, Ordering::Relaxed);
    UT_LAST_FAIL_OBJ.store(obj, Ordering::Relaxed);
}

/// Accounting shadow of `sel4_rt::untyped_retype`. An explicit item beats the `pub use sel4_rt::*`
/// glob, so every existing call site is measured with no edit. The SEND form cannot see an error
/// label (that is the documented `SYS_SEND` hazard) — only the bytes are counted here.
pub(crate) fn untyped_retype(untyped: u64, obj: u64, bits: u32, num: u32, dest: u64) -> u64 {
    note_retype(untyped, obj, bits, num);
    sel4_rt::untyped_retype(untyped, obj, bits, num, dest)
}

/// Monotone high-water helper.
pub(crate) fn note_high_water(cell: &AtomicU64, value: u64) {
    if cell.load(Ordering::Relaxed) < value {
        cell.store(value, Ordering::Relaxed);
    }
}

/// One line per pool: `used/capacity`. Printed with the periodic census AND at the gate, so an
/// exhaustion is visible in the SAME dump that shows the boot stalling.
pub(crate) fn print_pool_census(tag: &[u8]) {
    let slots_used = NEXT_SLOT.load(Ordering::Relaxed) - ROOT_CSPACE_START.load(Ordering::Relaxed);
    let slots_cap =
        ROOT_CSPACE_END.load(Ordering::Relaxed) - ROOT_CSPACE_START.load(Ordering::Relaxed);
    print_str(b"[pools] ");
    print_str(tag);
    print_str(b" untyped=");
    print_u64(UT_RETYPE_BYTES.load(Ordering::Relaxed) >> 10);
    print_str(b"KiB/");
    print_u64(UT_TOTAL_BYTES.load(Ordering::Relaxed) >> 10);
    print_str(b"KiB ut-free=");
    print_u64(
        UT_TOTAL_BYTES
            .load(Ordering::Relaxed)
            .saturating_sub(UT_RETYPE_BYTES.load(Ordering::Relaxed))
            >> 10,
    );
    print_str(b"KiB retypes=");
    print_u64(UT_RETYPE_CALLS.load(Ordering::Relaxed));
    print_str(b" ut-fails=");
    print_u64(UT_RETYPE_FAILS.load(Ordering::Relaxed));
    print_str(b" last-label=");
    print_u64(UT_LAST_FAIL_LABEL.load(Ordering::Relaxed));
    print_str(b" last-obj=");
    print_u64(UT_LAST_FAIL_OBJ.load(Ordering::Relaxed));
    print_str(b" cslots=");
    print_u64(slots_used);
    print_str(b"/");
    print_u64(slots_cap);
    print_str(b" slot-free=");
    print_u64(root_slot_available_count());
    print_str(b" slot-recycle=");
    print_u64(ROOT_SLOT_RECYCLE_N.load(Ordering::Relaxed));
    print_str(b"/");
    print_u64(ROOT_SLOT_RECYCLE_HW.load(Ordering::Relaxed));
    print_str(b" reused=");
    print_u64(ROOT_SLOT_RECYCLE_REUSED.load(Ordering::Relaxed));
    print_str(b" dropped=");
    print_u64(ROOT_SLOT_RECYCLE_DROPPED.load(Ordering::Relaxed));
    print_str(b" frame-reg=");
    print_u64(CSRSS_FRAME_HW.load(Ordering::Relaxed));
    print_str(b"/");
    print_u64(CSRSS_FRAME_CAP as u64);
    print_str(b" reg-full=");
    print_u64(CSRSS_FRAME_FULL.load(Ordering::Relaxed));
    print_str(b" image-mapcaps=");
    print_u64(SHARED_IMAGE_MAPPING_HW.load(Ordering::Relaxed));
    print_str(b" image-mapcap-fails=");
    print_u64(SHARED_IMAGE_MAPPING_FAILS.load(Ordering::Relaxed));
    print_str(b" freelist=");
    print_u64(VM_FREE_FRAME_HW.load(Ordering::Relaxed));
    print_str(b"/");
    print_u64(VM_FREE_FRAME_CAPACITY as u64);
    print_str(b" vad=");
    print_u64(VM_REGION_HW.load(Ordering::Relaxed));
    print_str(b"/");
    print_u64(VM_REGION_CAPACITY as u64);
    print_str(b" committed-map=");
    print_u64(VM_COMMITTED_MAPPING_HW.load(Ordering::Relaxed));
    print_str(b"/");
    print_u64(PROCESS_COMMITTED_MAPPING_CAPACITY as u64);
    print_str(b" committed-map-fails=");
    print_u64(VM_COMMITTED_MAPPING_REGISTRATION_FAILS.load(Ordering::Relaxed));
    print_str(b" prot-ovr=");
    print_u64(VM_PROTECTION_OVERRIDE_HW.load(Ordering::Relaxed));
    print_str(b"/");
    print_u64(nt_address_space::VM_PROTECTION_OVERRIDE_CAPACITY as u64);
    print_str(b" stack-vad-free=");
    print_u64(USER_STACK_VAD_RELEASES.load(Ordering::Relaxed));
    print_str(b"/");
    print_u64(USER_STACK_VAD_RELEASE_FAILS.load(Ordering::Relaxed));
    print_str(b" thread-cnode-free=");
    print_u64(HOSTED_THREAD_CNODE_RELEASES.load(Ordering::Relaxed));
    print_str(b"/");
    print_u64(HOSTED_THREAD_CNODE_RELEASE_FAILS.load(Ordering::Relaxed));
    print_str(b" vm-fail pt=");
    print_u64(VM_FAIL_PT.load(Ordering::Relaxed));
    print_str(b" frame=");
    print_u64(VM_FAIL_FRAME.load(Ordering::Relaxed));
    print_str(b" map=");
    print_u64(VM_FAIL_MAP.load(Ordering::Relaxed));
    print_str(b" alias=");
    print_u64(VM_FAIL_ALIAS.load(Ordering::Relaxed));
    print_str(b" registry=");
    print_u64(VM_FAIL_REGISTRY.load(Ordering::Relaxed));
    print_str(b" unmap-fails=");
    print_u64(VM_UNMAP_FAILS.load(Ordering::Relaxed));
    print_str(b" asids=");
    print_u64(ASID_ASSIGNED.load(Ordering::Relaxed));
    print_str(b" asid-fails=");
    print_u64(ASID_ASSIGN_FAILS.load(Ordering::Relaxed));
    print_str(b"\n");
}

/// `page_unmap` is a `SYS_SEND`, so a REFUSED unmap is invisible — and an unmap that does not clear
/// the leaf PTE turns into a `seL4_DeleteFirst` on the NEXT map at that VA, i.e. a phantom
/// "out of memory". This is the SYS_CALL form; the label comes back so the failure is countable.
pub(crate) unsafe fn page_unmap_r(frame: u64) -> u64 {
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") frame => _,
        inout("rsi") LBL_X86_PAGE_UNMAP << 12 => reply,
        inout("r10") 0u64 => _,
        inout("r8") 0u64 => _,
        inout("r9") 0u64 => _,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    let label = reply >> 12;
    if label != 0 {
        VM_UNMAP_FAILS.fetch_add(1, Ordering::Relaxed);
    }
    label
}
/// Unmaps that came back with a real error label (see [`page_unmap_r`]).
pub(crate) static VM_UNMAP_FAILS: AtomicU64 = AtomicU64::new(0);

// --- VSpace ASIDs ------------------------------------------------------------------------------
// ★ BATCH 59 ROOT CAUSE. seL4's `X86Page::Unmap` finds the VSpace to clear the leaf PTE in by
// looking the FRAME cap's recorded ASID up against every PML4 cap (`pml4_paddr_for_asid`), and a
// PML4 retyped out of an Untyped starts with `asid == 0` — for which that lookup returns "no
// vspace" and the unmap clears NOTHING while still reporting SUCCESS. The executive had never
// assigned ASIDs, so EVERY unmap of a hosted process's page was a silent no-op: the frame cap was
// freed and recycled, but the PTE stayed live. Nothing noticed until a VA was re-committed —
// `page_map` then found the leaf busy and returned `seL4_DeleteFirst`, which
// `vm_map_private_page` reported as `STATUS_INSUFFICIENT_RESOURCES`, i.e. a PHANTOM out-of-memory
// (winlogon's `CopyLoop` 64 KiB buffer → `userenv` `Error: 1450`). The fix is the piece seL4 always
// expected the root task to do: assign each process VSpace an ASID out of the initial pool.
/// Ship switch for the ASID assignment, so the BYPASS experiment is one constant: `false` restores
/// the pre-batch-59 behaviour (every process VSpace `asid == 0`, every unmap a silent no-op) and
/// `userenv`'s `Error: 1450` comes straight back.
pub(crate) const VSPACE_ASIDS: bool = true;
/// `seL4_CapInitThreadASIDPool` — canonical root-CSpace slot 6 (see `rootserver::rs_set`).
pub(crate) const CAP_INIT_ASID_POOL: u64 = 6;
/// `InvocationLabel::X86ASIDPoolAssign`.
pub(crate) const LBL_X86_ASID_POOL_ASSIGN: u64 = 56;
/// VSpaces that were given a real ASID, and assignments that came back with an error label.
pub(crate) static ASID_ASSIGNED: AtomicU64 = AtomicU64::new(0);
pub(crate) static ASID_ASSIGN_FAILS: AtomicU64 = AtomicU64::new(0);
/// Assign `pml4` (a root-CNode slot holding a freshly retyped PML4) the next ASID from the initial
/// pool, so `Page::Unmap` / cap deletion can find this VSpace and really clear its PTEs. Legacy
/// (non-extraCaps) ABI: the vspace's root-CNode slot index rides in `a2`. Returns the error label.
pub(crate) unsafe fn vspace_assign_asid(pml4: u64) -> u64 {
    if !VSPACE_ASIDS {
        return 0;
    }
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") CAP_INIT_ASID_POOL => _,
        inout("rsi") LBL_X86_ASID_POOL_ASSIGN << 12 => reply,
        inout("r10") pml4 => _,
        inout("r8") 0u64 => _,
        inout("r9") 0u64 => _,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    let label = reply >> 12;
    if label == 0 {
        ASID_ASSIGNED.fetch_add(1, Ordering::Relaxed);
    } else {
        ASID_ASSIGN_FAILS.fetch_add(1, Ordering::Relaxed);
        print_str(b"[asid] assign failed pml4=0x");
        print_hex(pml4 as u32);
        print_str(b" label=");
        print_u64(label);
        print_str(b"\n");
    }
    label
}

// --- THE CLIENT TEB TAIL IS SERVER-WRITABLE, SO ITS INVARIANTS MUST BE RE-ASSERTED ---------------
/// Times [`reassert_client_teb_tail`] checked, and times it really had to REPAIR the invariant.
pub(crate) static TEB_TAIL_REASSERTS: AtomicU64 = AtomicU64::new(0);
pub(crate) static TEB_TAIL_REPAIRS: AtomicU64 = AtomicU64::new(0);
/// The first bad `MaximumLength` observed (0xFFFF = none), so a repair is evidence, not a guess.
pub(crate) static TEB_TAIL_FIRST_BAD: AtomicU64 = AtomicU64::new(0xFFFF);

/// Re-assert `TEB.StaticUnicodeString` for a hosted process's MAIN thread.
///
/// ★ WHY THIS EXISTS. Both TEB pages of a GUI client are deliberately registered as win32k client
/// frames (the `KeStackAttachProcess` model — win32k dereferences the caller's TEB directly), so
/// win32k writes SERVER-side data straight through them; batch 53 measured winlogon's whole 2nd TEB
/// page coming back overwritten with USER metrics spanning `TEB+0x1000..0x18B8`. The x64 TEB tail
/// also holds `StaticUnicodeString` (`TEB+0x1258`), the fixed per-thread `UNICODE_STRING` the loader
/// and kernel32 convert names into — and kernel32 ASSERTs `MaximumLength == sizeof(StaticUnicodeBuffer)`
/// (`kernel32/client/file/fileutils.c:26`). That assertion is an `int 3`, so a clobbered field kills
/// the process the first time it takes a `Rtl*` path through fileutils — which is exactly where
/// batch 59's advanced profile flow ended up (`cpu-exception(3)` at `ntdll+0x34477`).
///
/// The repair goes through the executive's PERSISTENT alias of the client's 2nd TEB page
/// (`scratch_base + 0x5000`, mapped at spawn and never unmapped), the same technique the callback
/// window cache re-assert uses. Idempotent, and a no-op on every dispatch that did not clobber it.
///
/// `pi` selects the process's ENV-SCRATCH base — the `scr_base` its `spawn_sec_image` was given,
/// which is NOT `procs[pi].scratch_base` (that is the per-process demand-fill window).
pub(crate) fn env_scratch_base_for_pi(pi: usize) -> u64 {
    hosted_env_scratch_base_for_pi(pi)
}

// ═══ ★ BATCH 61 — `KeGdiFlushUserBatch`: THE MISSING KERNEL STEP THAT WAS EATING THE TEB ═══════
//
// **The measurement.** winlogon's post-`\lsarpc` `#GP(0)` at `RtlEnterCriticalSection+0x14`
// (`lock inc [rcx+8]`, `rcx = 0x0005_0005_0018_010F`, NON-canonical) is rpcrt4
// `RPCRT4_SetThreadCurrentConnection` → `get_or_create_threaddata()`, which returns
// `NtCurrentTeb()->ReservedForNtRpc` (**x64 TEB+0x1698**) WITHOUT validating it and then enters
// `tdata->cs` at `tdata+0x10`. A watch on that one slot showed it going
// `0 -> 0x…3003a240` (the REAL `HeapAlloc`'d `threaddata`, stored by rpcrt4 itself at
// `rpcrt4+0x5001f`) `-> 0x…300300ff -> 0x0000_0002_0058_00ff -> 0x0005_0005_0018_00ff`, with
// `TEB+0x1680 = 0xff`, `TEB+0x1690 = 0xffff00c8_d0d40000` and `TEB+0x16a0 = 0x8000` appearing
// alongside it. `0x00c8d0d4` is the SAME byte pattern batches 53/59/60 chased.
//
// **The cause, and it is neither win32k nor a mapping.** `gdi32!GdiAllocBatchCommand`
// (`win32ss/gdi/gdi32/include/gdi32p.h:406`) writes each deferred GDI command into
// `TEB.GdiTebBatch.Buffer` at `TEB + 0x300 + GdiTebBatch.Offset` and bumps `Offset` / `GdiBatchCount`.
// Its overflow guard (`Offset + cjSize > GDIBATCHBUFSIZE (0x4D8)`) calls `NtGdiFlush()` and then
// appends ANYWAY — because in real NT the flush is not what resets the buffer: the KERNEL does it.
// `KiSystemCallHandler` (`ntoskrnl/ke/amd64/traphandler.c:183`) reads `NtCurrentTeb()->GdiBatchCount`
// **before dispatching any win32k system call** and, if non-zero, calls `KeGdiFlushUserBatch()` —
// win32k's `NtGdiFlushUserBatch` (`win32ss/gdi/ntgdi/gdibatch.c:487`), whose last act is
// `GdiTebBatch.Offset = 0; GdiBatchCount = 0; GdiTebBatch.HDC = 0`.
//
// **Our host never did that step.** So `Offset` grew without bound and `GdiAllocBatchCommand`
// marched GDI batch records straight through the caller's TEB: `Win32ClientInfo` (0x800),
// `StaticUnicodeString` (0x1258 — `Offset` 0xF58), the TLS slots (0x1480) and `ReservedForNtRpc`
// (0x1698 — `Offset` 0x1398). That is the single root cause of the whole TEB-clobber family, and it
// is why win32k was measurably innocent every time it was accused (`w32 ro-maps = 0`,
// `store-faults = 0`): the writer was always the CLIENT's own gdi32, in the client's own window.
//
// **The fix is the kernel step, at the kernel's site, done by the kernel.** The executive is what
// plays `KiSystemCallHandler` for a hosted process' win32k syscalls, so it observes the caller's
// live `GdiBatchCount` and delegates execution to win32k's own registered
// `WIN32_CALLOUTS_FPNS.BatchFlushRoutine`. That routine walks the records, draws them, and clears
// `GdiTebBatch.Offset` / `.HDC` / `GdiBatchCount`, just like ReactOS expects.
//
// The one host-specific wrinkle is the TEB-tail protection below: `GdiBatchCount` lives on the
// second TEB page, which ordinary win32k dispatches see read-only. During this one registered
// callout the bridge maps that page writable, then restores the normal read-only policy before the
// next dispatch.
/// Ship switch for the `KeGdiFlushUserBatch` kernel step (bypass control).
pub(crate) const GDI_USER_BATCH_FLUSH: bool = true;
/// ★ WHAT BOUNDING `Offset` COSTS, MEASURED — and why the flush executes the records it finds.
///
/// `ExtTextOutW` (`objects/text.c:603`) and `PolyPatBlt` (`objects/painting.c:655`) re-check the LIVE
/// `GdiTebBatch.Offset` after `GdiAllocBatchCommand` and fall through to the real
/// `NtGdiExtTextOutW` / `NtGdiPolyPatBlt` **only when the record would not fit**. The runaway
/// `Offset` made that check fail every time, so those calls reached win32k as real system calls.
/// With `Offset` correctly bounded they start FITTING and are batched instead. The DATA did not
/// disappear, only its transport: the record in `GdiTebBatch` carries the same live
/// `EDITSTATE.text`, and the flush reads it through the executive's TEB alias before handing the
/// batch to win32k's registered `BatchFlushRoutine` for real drawing.
/// A control experiment that disabled batching outright (parking a non-HDC sentinel in
/// `GdiTebBatch.HDC`, so `gdi32p.h:443` refuses every DC) was measured and REJECTED: 226/99 with 27
/// FAILs — winlogon never reached its SAS post at all.
///
/// `GDIBATCHBUFSIZE` + the `TEB.GdiTebBatch` field offsets — the host-tested layout constants.
pub(crate) use nt_user_callback::{
    GDI_BATCH_BUF_SIZE, TEB_GDI_BATCH_COUNT, TEB_GDI_TEB_BATCH_BUFFER as GDI_TEB_BATCH_BUFFER,
    TEB_GDI_TEB_BATCH_OFFSET as GDI_TEB_BATCH_OFFSET,
};
/// Number of times the kernel step really ran on a live client win32k system call.
pub(crate) static GDI_BATCH_FLUSHES: AtomicU64 = AtomicU64::new(0);
/// Batch records handed to win32k's registered `BatchFlushRoutine`.
pub(crate) static GDI_BATCH_RECORDS_FLUSHED: AtomicU64 = AtomicU64::new(0);
/// Calls to the registered win32k batch flush routine that failed or walled.
pub(crate) static GDI_BATCH_FLUSH_FAILURES: AtomicU64 = AtomicU64::new(0);
/// Narrow writable mappings opened for `TEB.GdiBatchCount` while `NtGdiFlushUserBatch` runs.
pub(crate) static GDI_BATCH_TEB_TAIL_WRITE_WINDOWS: AtomicU64 = AtomicU64::new(0);
/// High-water `GdiTebBatch.Offset` ever OBSERVED at a win32k system call. With the kernel step in
/// place this must stay `<= GDI_BATCH_BUF_SIZE`; without it, it grew past the TEB's second page.
pub(crate) static GDI_BATCH_MAX_OFFSET: AtomicU64 = AtomicU64::new(0);
pub(crate) static EXPLORER_BEGIN_PAINTS: AtomicU64 = AtomicU64::new(0);
pub(crate) static EXPLORER_END_PAINTS: AtomicU64 = AtomicU64::new(0);
pub(crate) static EXPLORER_DIRECT_GDI_DRAW_RETURNS: AtomicU64 = AtomicU64::new(0);
pub(crate) static EXPLORER_GDI_BATCH_FLUSHES: AtomicU64 = AtomicU64::new(0);
pub(crate) static EXPLORER_GDI_BATCH_RECORDS: AtomicU64 = AtomicU64::new(0);

/// `KeGdiFlushUserBatch` — run at the win32k system-call entry for hosted client `client`, exactly
/// where `KiSystemCallHandler` runs it. The executive reads the live TEB only to decide whether
/// there is a batch and to keep the existing proof/readback counters; execution and clearing are
/// delegated to win32k's registered `BatchFlushRoutine`.
pub(crate) unsafe fn ke_gdi_flush_user_batch(
    client: win32k_glue::Win32kClientContext,
    teb_alias: u64,
) {
    if !GDI_USER_BATCH_FLUSH || client.teb == 0 || teb_alias == 0 {
        return;
    }
    // Main hosted processes use the historical env-scratch layout: page 1 at `alias + 0`, page 2 at
    // `alias + 0x5000`. Real worker TEB mirrors are contiguous.
    let tail_bias = if client.teb == SMSS_TEB_VA { 0x4000 } else { 0 };
    let count_field = (teb_alias + tail_bias + TEB_GDI_BATCH_COUNT) as *const u32;
    let count = core::ptr::read_volatile(count_field);
    if count == 0 {
        return;
    }
    let offset_field = (teb_alias + GDI_TEB_BATCH_OFFSET) as *const u32;
    let offset = core::ptr::read_volatile(offset_field);
    let previous = GDI_BATCH_MAX_OFFSET.load(Ordering::Relaxed);
    if offset as u64 > previous {
        GDI_BATCH_MAX_OFFSET.store(offset as u64, Ordering::Relaxed);
    }
    if client.process_role == Some(nt_exe_image::HostedProcessRole::InteractiveShell) {
        EXPLORER_GDI_BATCH_FLUSHES.fetch_add(1, Ordering::Relaxed);
        EXPLORER_GDI_BATCH_RECORDS.fetch_add(count as u64, Ordering::Relaxed);
    }
    GDI_BATCH_FLUSHES.fetch_add(1, Ordering::Relaxed);
    GDI_BATCH_RECORDS_FLUSHED.fetch_add(count as u64, Ordering::Relaxed);
    // Keep the existing host-tested walk as a measurement/readback hook; win32k performs the draw.
    let buffer = teb_alias + GDI_TEB_BATCH_BUFFER;
    let mut records = [0u8; nt_user_callback::GDI_BATCH_BUF_SIZE as usize];
    core::ptr::copy_nonoverlapping(buffer as *const u8, records.as_mut_ptr(), records.len());
    nt_user_callback::walk_gdi_batch(&records, offset, count, |record| {
        if let Some((chars, start)) = record.text {
            let want = nt_user_callback::LOGON_USERNAME.len();
            if chars as usize == want {
                let at = start as usize;
                winlogon_credential_observe_text_bytes(
                    &records[at..at + 2 * want],
                    chars as u64,
                    b"GdiBCTextOut batch record",
                );
            }
        }
    });
    let (status, ok) = win32k_glue::win32k_flush_user_gdi_batch(client);
    if !ok || status as u32 != 0 {
        let failures = GDI_BATCH_FLUSH_FAILURES.fetch_add(1, Ordering::Relaxed);
        if failures < 8 {
            print_str(b"[gdi-batch] BatchFlushRoutine failed pi=");
            print_u64(client.pi as u64);
            print_str(b" tid=");
            print_u64(client.tid);
            print_str(b" teb=0x");
            print_hex_u64(client.teb);
            print_str(if ok {
                b" status=0x"
            } else {
                b" WALL status=0x"
            });
            print_hex(status as u32);
            print_str(b"\n");
        }
    }
}

///
/// Kept as a TRIPWIRE now that the CLASS fix (`W32_CLIENT_TEB_TAIL_PROTECTED`, below) exists: with
/// the tail no longer part of win32k's writable client-frame surface this must never fire, and
/// `TEB_TAIL_REPAIRS` is asserted zero by `exec_teb_tail_protected_from_win32k`.
pub(crate) unsafe fn observe_client_teb_tail(pi: usize) {
    let env_scratch = env_scratch_base_for_pi(pi);
    if env_scratch == 0 || TEB_TAIL_ALIAS_LIVE.load(Ordering::Relaxed) & (1u64 << pi) == 0 {
        return;
    }
    const STATIC_UNICODE_STRING: u64 = 0x258; // TEB+0x1258, i.e. offset 0x258 of the 2nd TEB page
    const MAXIMUM_LENGTH: u16 = 522; // sizeof(StaticUnicodeBuffer) = 261 * sizeof(WCHAR)
    let tail = env_scratch + 0x5000 + STATIC_UNICODE_STRING;
    TEB_TAIL_REASSERTS.fetch_add(1, Ordering::Relaxed);
    let max = core::ptr::read_volatile((tail + 2) as *const u16);
    let buffer = core::ptr::read_volatile((tail + 8) as *const u64);
    if max == MAXIMUM_LENGTH && buffer == SMSS_TEB_VA + 0x1268 {
        return;
    }
    let _ = TEB_TAIL_FIRST_BAD.compare_exchange(
        0xFFFF,
        max as u64,
        Ordering::Relaxed,
        Ordering::Relaxed,
    );
    if TEB_TAIL_REPAIRS.fetch_add(1, Ordering::Relaxed) < 4 {
        print_str(b"[teb-tail] StaticUnicodeString CLOBBERED by win32k (MaximumLength=");
        print_u64(max as u64);
        print_str(b" Buffer=0x");
        print_hex((buffer >> 32) as u32);
        print_hex(buffer as u32);
        print_str(b") -- kernel32 fileutils.c:26 ASSERTs on this\n");
    }
}

// ═══ ★ THE CLIENT TEB TAIL IS NOT PART OF win32k's WRITABLE CLIENT-FRAME SURFACE ════════════════
//
// THE CLASS, not the field. Twice now a win32k dispatch has come back having overwritten the
// CALLER's second TEB page: batch 53 lost the `ACTIVATION_CONTEXT_STACK` that used to live at
// `TEB+0x1800` (fixed by moving the ACS to a private page — a FIELD fix), and batch 59 lost
// `TEB.StaticUnicodeString` at `TEB+0x1258`, which kernel32 `fileutils.c:26` ASSERTs on and whose
// `int 3` killed winlogon. `StaticUnicodeString` sits at a FIXED x64 TEB offset and cannot be moved,
// so a third field was guaranteed. The *shape* of the bug is the mapping, not any one field:
//
//   `spawn_sec_image` / `spawn_hosted_thread` register BOTH TEB pages with `csrss_frame_put`, so a
//   win32k demand fault at either VA is answered with the client's OWN frame, mapped RW at the same
//   VA (`map_csrss_page_into_win32k`, the KeStackAttachProcess model). Anything win32k stores at
//   `TEB+0x1000..0x1FFF` therefore lands in the client's real TEB.
//
// win32k has legitimate business in TEB page ONE — `CLIENTINFO` at `TEB+0x800` and
// `Win32ThreadInfo` at `TEB+0x78` are exactly what the model exists for, and both stay RW-shared.
// In page TWO the only field ReactOS' win32k touches by contract is `StaticUnicodeString`, and it
// touches it as SCRATCH: `BuildUserModeWindowStationName` (`win32ss/user/ntuser/winsta.c:649`)
// borrows the caller's `StaticUnicodeBuffer` to format `\Windows\WindowStations\Service-0x..-..$`
// for its own `ObOpenObjectByName`, and the client never reads the result back. Every other write
// there is server state that has no business in a user TEB at all.
//
// So the tail page is mapped into win32k **READ-ONLY**, and the FIRST write fault on it is answered
// with a private **copy-on-write shadow** seeded from the client's live page. win32k keeps reading
// consistent values (including a `StaticUnicodeString.Buffer` that still points into its own view of
// the tail) and keeps writing wherever it likes — into the shadow. The client's real TEB tail
// becomes STRUCTURALLY unreachable for a win32k store, which retires the whole class: no future
// field can be scribbled, because no byte of the page can. The shadow rides the ordinary attach
// table, so a client switch drops it and the next fault re-establishes the read-only view of the
// (by then current) real page.
/// Ship switch for the class fix — `false` restores the RW-shared tail and the clobber comes back.
pub(crate) const W32_CLIENT_TEB_TAIL_PROTECTED: bool = true;
/// `page_map` rights: bit1 = read, bit0 = write. Read-only + non-executable.
pub(crate) const RO_NX: u64 = 2 | PAGE_EXECUTE_NEVER;
/// The 64-byte spawn CANARY at the very end of every hosted thread's second TEB page
/// (`TEB+0x1FC0`, past the x64 TEB's own `0x1818` end and past the `spawn_hosted_thread` CONTEXT
/// scratch at `TEB+0x1900`). ★ THE GUARD THAT CATCHES A **NEW** FIELD: an assertion on
/// `StaticUnicodeString` alone would only ever re-catch the field we already know about, so the gate
/// spec also verifies these 64 bytes. Any win32k store anywhere in the tail's unused region breaks
/// them, whichever named field the next batch would otherwise have discovered by `int 3`.
pub(crate) const TEB_TAIL_CANARY_OFFSET: u64 = 0xFC0;
const TEB_TAIL_CANARY_SEED: u64 = 0x5445_425F_5441_494C; // "TEB_TAIL"
/// Write the canary through an executive alias of a second TEB page.
pub(crate) unsafe fn seed_teb_tail_canary(teb2_alias: u64) {
    let mut offset = 0u64;
    while offset < 64 {
        core::ptr::write_volatile(
            (teb2_alias + TEB_TAIL_CANARY_OFFSET + offset) as *mut u64,
            TEB_TAIL_CANARY_SEED ^ offset,
        );
        offset += 8;
    }
}
/// Is the canary still exactly what the spawn wrote?
pub(crate) unsafe fn teb_tail_canary_intact(teb2_alias: u64) -> bool {
    let mut offset = 0u64;
    while offset < 64 {
        if core::ptr::read_volatile((teb2_alias + TEB_TAIL_CANARY_OFFSET + offset) as *const u64)
            != TEB_TAIL_CANARY_SEED ^ offset
        {
            return false;
        }
        offset += 8;
    }
    true
}

/// Every OTHER key under which this process' TEB-tail FRAME is reachable. A second key is an alias:
/// a write anyone makes through it lands in this TEB, which is exactly the shape a "win32k scribbled
/// the TEB" symptom takes when win32k never actually touched the TEB's own VA.
pub(crate) unsafe fn teb_tail_alias_scan(pi: usize) {
    let frame = TEB2_FRAME_CAP[pi].load(Ordering::Relaxed);
    print_str(b"[teb-watch] alias scan pi=");
    print_u64(pi as u64);
    print_str(b" teb2-frame-cap=0x");
    print_hex_u64(frame);
    if frame == 0 {
        print_str(b" (unknown)\n");
        return;
    }
    let mut aliases = 0u64;
    let n = core::ptr::read(core::ptr::addr_of!(CSRSS_FRAME_N)).min(CSRSS_FRAME_CAP);
    let vas = core::ptr::addr_of!(CSRSS_FRAME_VA) as *const u64;
    let pis = core::ptr::addr_of!(CSRSS_FRAME_PI) as *const u8;
    let frames = core::ptr::addr_of!(CSRSS_FRAME_FR) as *const u64;
    for index in 0..n {
        if core::ptr::read(frames.add(index)) == frame {
            aliases += 1;
            print_str(b" | client-frame pi=");
            print_u64(core::ptr::read(pis.add(index)) as u64);
            print_str(b" va=0x");
            print_hex_u64(core::ptr::read(vas.add(index)));
        }
    }
    let dn = core::ptr::read(core::ptr::addr_of!(DLL_CACHE_N));
    let dvas = core::ptr::addr_of!(DLL_CACHE_VA) as *const u64;
    let dfrs = core::ptr::addr_of!(DLL_CACHE_FR) as *const u64;
    for index in 0..dn {
        if core::ptr::read(dfrs.add(index)) == frame {
            aliases += 1;
            print_str(b" | dll-cache va=0x");
            print_hex_u64(core::ptr::read(dvas.add(index)));
        }
    }
    print_str(b" aliases=");
    print_u64(aliases);
    print_str(b"\n");
}

// --- CLIENT-SIDE TEB-TAIL WRITE WATCH (the measurement that names the real writer) --------------
/// Diagnostic switch: map winlogon's SECOND TEB page READ-ONLY *in winlogon's own VSpace* from the
/// post-logon milestone on, so every store the CLIENT makes to it faults and reports its RIP. This
/// is the same trick as the win32k-side protection, aimed at the address space the evidence actually
/// points at.
pub(crate) const WL_TEB_TAIL_WRITE_WATCH: bool = true;
/// The cap winlogon's own TEB-tail mapping uses, so the protection can be toggled.
pub(crate) static WL_TEB2_CAP: AtomicU64 = AtomicU64::new(0);
pub(crate) static WL_TEB2_PML4: AtomicU64 = AtomicU64::new(0);
pub(crate) static WL_TEB2_PROTECTED: AtomicU64 = AtomicU64::new(0);
pub(crate) static WL_TEB2_WRITE_FAULTS: AtomicU64 = AtomicU64::new(0);
pub(crate) static WL_TEB2_CYCLES: AtomicU64 = AtomicU64::new(0);
pub(crate) static WL_TEB2_EMULATED: AtomicU64 = AtomicU64::new(0);
static WL_TEB2_PROTECT_REPORTS: AtomicU64 = AtomicU64::new(0);
static WL_TEB2_PROTECT_FAILS: AtomicU64 = AtomicU64::new(0);
static WL_TEB2_EMULATION_FAILS: AtomicU64 = AtomicU64::new(0);
const WL_TEB2_MAX_CYCLES: u64 = 60_000;
static RTL_LAST_STATUS_STORE_RVA: AtomicU64 = AtomicU64::new(0);

/// ★ THE ENFORCED INVARIANT. `TEB.StaticUnicodeString` is a per-thread SCRATCH descriptor whose
/// shape (`MaximumLength == sizeof(StaticUnicodeBuffer)`, `Buffer == &StaticUnicodeBuffer`) is set
/// once at thread creation and never legitimately changes — `RtlAnsiStringToUnicodeString(dst, src,
/// FALSE)` writes only `Length`. kernel32 ASSERTs exactly that shape on every ANSI file call
/// (`client/file/fileutils.c:26`), and its `int 3` is fatal. Re-assert it through the executive's
/// persistent alias whenever the protection is (re-)armed and after every store that faults on the
/// page: idempotent, and a no-op on a boot that never breaks it.
pub(crate) unsafe fn wl_teb2_reassert_descriptor() {
    if TEB_TAIL_ALIAS_LIVE.load(Ordering::Relaxed) & (1u64 << 2) == 0 {
        return;
    }
    let tail = WINLOGON_MAIN_TEB_MIRROR_VA + 0x5000 + 0x258;
    let maximum_length = core::ptr::read_volatile((tail + 2) as *const u16);
    let buffer = core::ptr::read_volatile((tail + 8) as *const u64);
    if maximum_length == 522 && buffer == SMSS_TEB_VA + 0x1268 {
        return;
    }
    core::ptr::write_volatile((tail + 2) as *mut u16, 522);
    core::ptr::write_volatile((tail + 8) as *mut u64, SMSS_TEB_VA + 0x1268);
    let n = TEB_TAIL_REPAIRS.fetch_add(1, Ordering::Relaxed);
    let _ = TEB_TAIL_FIRST_BAD.compare_exchange(
        0xFFFF,
        maximum_length as u64,
        Ordering::Relaxed,
        Ordering::Relaxed,
    );
    if n < 4 {
        print_str(b"[teb-tail] StaticUnicodeString descriptor RESTORED (was MaximumLength=");
        print_u64(maximum_length as u64);
        print_str(b" Buffer=0x");
        print_hex_u64(buffer);
        print_str(b")\n");
    }
}

/// Re-arm the read-only protection (idempotent, bounded).
pub(crate) unsafe fn wl_teb2_protect() {
    if !WL_TEB_TAIL_WRITE_WATCH {
        return;
    }
    // The invariant is enforced on EVERY service-loop event, not only when the protection re-arms —
    // a store that lands while the page happens to be writable is still caught before the client's
    // next kernel32 ANSI file call can assert on it.
    wl_teb2_reassert_descriptor();
    if WL_TEB2_PROTECTED.load(Ordering::Relaxed) != 0 {
        return;
    }
    let cap = WL_TEB2_CAP.load(Ordering::Relaxed);
    let pml4 = WL_TEB2_PML4.load(Ordering::Relaxed);
    if cap == 0 || pml4 == 0 || WL_TEB2_CYCLES.fetch_add(1, Ordering::Relaxed) >= WL_TEB2_MAX_CYCLES
    {
        return;
    }
    let unmap = page_unmap_r(cap);
    let map = page_map_r(cap, SMSS_TEB_VA + 0x1000, RO_NX, pml4);
    if map == 0 {
        WL_TEB2_PROTECTED.store(1, Ordering::Relaxed);
    }
    if WL_TEB2_PROTECT_REPORTS.fetch_add(1, Ordering::Relaxed) < 3 || map != 0 {
        if WL_TEB2_PROTECT_FAILS.load(Ordering::Relaxed) < 4 {
            if map != 0 {
                WL_TEB2_PROTECT_FAILS.fetch_add(1, Ordering::Relaxed);
            }
            print_str(b"[teb-writer] protect unmap=");
            print_u64(unmap);
            print_str(b" map=");
            print_u64(map);
            print_str(b"\n");
        }
    }
}

/// `RtlNtStatusToDosError`'s `mov [rax+0x1250], ecx`, the 4-byte `TEB.LastStatusValue` store. It is
/// BY FAR the most frequent write to the tail page (every failing syscall makes one) and it is
/// entirely legitimate. The RVA is still derived from the loaded ntdll image at boot; on a protected
/// write fault the executive copies ECX into the trusted TEB mirror and advances the fault frame so
/// the protection stays continuously armed.
const RTL_LAST_STATUS_STORE_LEN: u64 = 6;
const RTL_LAST_STATUS_STORE_OPCODE: [u8; RTL_LAST_STATUS_STORE_LEN as usize] =
    [0x89, 0x88, 0x50, 0x12, 0x00, 0x00];

unsafe fn derive_rtl_last_status_store_rva(pe: &nt_pe_loader::PeFile) -> u64 {
    let Some(rtl_nt_status_to_dos_error) = pe.exports().ok().and_then(|exports| {
        exports
            .into_iter()
            .find(|export| export.name == "RtlNtStatusToDosError")
            .map(|export| export.rva)
    }) else {
        return 0;
    };
    let mut offset = 0u32;
    while offset < 0x100 {
        let candidate = rtl_nt_status_to_dos_error.wrapping_add(offset);
        let mut matched = true;
        for (index, expected) in RTL_LAST_STATUS_STORE_OPCODE.iter().enumerate() {
            if img_spawn::pe_byte_at_rva(pe, candidate.wrapping_add(index as u32))
                != Some(*expected)
            {
                matched = false;
                break;
            }
        }
        if matched {
            return candidate as u64;
        }
        offset += 1;
    }
    0
}

/// A client store into the protected tail: report WHO (RIP + the byte it aimed at). Known-legitimate
/// ntdll status traffic is emulated in place; every other store drops the protection only long
/// enough for the original instruction to complete, then the service loop re-arms it.
pub(crate) unsafe fn wl_teb2_report_write(ip: u64, addr: u64, tcb: u64) -> bool {
    let offset = addr & 0xFFF;
    let last_status_store_rva = RTL_LAST_STATUS_STORE_RVA.load(Ordering::Relaxed);
    let last_status_store = offset == 0x250
        && last_status_store_rva != 0
        && ip == NTDLL_BASE.wrapping_add(last_status_store_rva);
    let n = WL_TEB2_WRITE_FAULTS.fetch_add(1, Ordering::Relaxed);
    let descriptor = (0x258..0x268).contains(&offset);
    if n < 48 || descriptor {
        print_str(if descriptor {
            b"[teb-writer] ***DESCRIPTOR*** client store TEB+0x1"
        } else {
            b"[teb-writer] client store TEB+0x1"
        });
        print_hex(offset as u32);
        print_str(b" from ip=0x");
        print_hex_u64(ip);
        print_str(b" ntdll+0x");
        print_hex(ip.wrapping_sub(NTDLL_BASE) as u32);
        print_str(b" image+0x");
        print_hex(ip.wrapping_sub(PE_LOAD_BASE) as u32);
        if last_status_store {
            print_str(b" last-status");
        }
        print_str(b" #");
        print_u64(n);
        print_str(b"\n");
    }
    if last_status_store && tcb != 0 {
        let mut regs = [0u64; 20];
        crate::win32k_glue::tcb_read_regs20(tcb, &mut regs);
        let rip = regs[nt_user_callback::USER_CONTEXT_RIP];
        let rax = regs[nt_user_callback::USER_CONTEXT_RAX];
        let value = regs[nt_user_callback::USER_CONTEXT_RCX] as u32;
        if rip == ip && rax.wrapping_add(0x1250) == addr {
            regs[nt_user_callback::USER_CONTEXT_RIP] =
                ip.wrapping_add(RTL_LAST_STATUS_STORE_LEN);
            let write_error = crate::win32k_glue::tcb_write_regs20(tcb, &regs, false);
            if write_error == 0 {
                core::ptr::write_volatile(
                    (WINLOGON_MAIN_TEB_MIRROR_VA + 0x5000 + offset) as *mut u32,
                    value,
                );
                WL_TEB2_EMULATED.fetch_add(1, Ordering::Relaxed);
                wl_teb2_reassert_descriptor();
                return true;
            }
            if WL_TEB2_EMULATION_FAILS.fetch_add(1, Ordering::Relaxed) < 8 {
                print_str(b"[teb-writer] last-status emulation TCB_WriteRegisters failed err=");
                print_u64(write_error);
                print_str(b"\n");
            }
        } else if WL_TEB2_EMULATION_FAILS.fetch_add(1, Ordering::Relaxed) < 8 {
            print_str(b"[teb-writer] last-status emulation context mismatch rip=0x");
            print_hex_u64(rip);
            print_str(b" rax=0x");
            print_hex_u64(rax);
            print_str(b" addr=0x");
            print_hex_u64(addr);
            print_str(b"\n");
        }
    }
    let cap = WL_TEB2_CAP.load(Ordering::Relaxed);
    let pml4 = WL_TEB2_PML4.load(Ordering::Relaxed);
    if cap != 0 && pml4 != 0 {
        let _ = page_unmap_r(cap);
        let _ = page_map_r(cap, SMSS_TEB_VA + 0x1000, RW_NX, pml4);
    }
    WL_TEB2_PROTECTED.store(0, Ordering::Relaxed);
    wl_teb2_reassert_descriptor();
    false
}

/// Tail pages that were really mapped READ-ONLY into win32k. Without this the "win32k took zero
/// write faults" reading would be unfalsifiable — it could just mean win32k never touched the page.
pub(crate) static W32_TEB_TAIL_RO_MAPS: AtomicU64 = AtomicU64::new(0);

// --- TAIL WATCH: WHICH EVENT turns the tail bad? -------------------------------------------------
/// Each process' MAIN-thread TEB tail frame cap, so a transition report can ask the decisive
/// question: is this frame ALIASED — registered/cached under some OTHER key, so that a write win32k
/// or a demand fill makes elsewhere lands in this TEB?
pub(crate) static TEB2_FRAME_CAP: [AtomicU64; MAX_PI] = [const { AtomicU64::new(0) }; MAX_PI];
/// Bit `pi` set once `spawn_sec_image` has actually MAPPED that process' `scr + 0x5000` TEB-tail
/// alias. Reading the alias before then is a #PF in the executive itself (measured).
pub(crate) static TEB_TAIL_ALIAS_LIVE: AtomicU64 = AtomicU64::new(0);
/// Per-pi "the tail was intact last time we looked" bit, so only the TRANSITION is reported.
static TEB_WATCH_GOOD: [AtomicU64; MAX_PI] = [const { AtomicU64::new(1) }; MAX_PI];
static TEB_WATCH_REPORTS: AtomicU64 = AtomicU64::new(0);
/// Last observed value of winlogon's `TEB.ReservedForNtRpc` (TEB+0x1698) + a bounded report budget.
pub(crate) static WL_NTRPC_SLOT: AtomicU64 = AtomicU64::new(0);
static WL_NTRPC_SLOT_REPORTS: AtomicU64 = AtomicU64::new(0);
static WL_NTRPC_LAST_TAG: AtomicU64 = AtomicU64::new(u64::MAX);
static WL_NTRPC_LAST_AUX: AtomicU64 = AtomicU64::new(0);
/// The PREVIOUS observation point, so a transition names the event boundary it happened inside.
static TEB_WATCH_LAST_TAG: AtomicU64 = AtomicU64::new(u64::MAX);
static TEB_WATCH_LAST_AUX: AtomicU64 = AtomicU64::new(0);
static TEB_WATCH_LAST_AUX2: AtomicU64 = AtomicU64::new(0);
/// Sample a process' live TEB tail and report the good→bad TRANSITION with the event that preceded
/// it. `tag`/`aux` name the call site (0 = service-loop event with `aux` = SSN, 1 = before a win32k
/// dispatch, 2 = after one) — the measurement that says whether a win32k dispatch is the writer at
/// all, rather than assuming it from the fact that the value looks like USER data.
pub(crate) unsafe fn teb_tail_watch(pi: usize, tag: u64, aux: u64, aux2: u64) {
    if pi >= MAX_PI || TEB_TAIL_ALIAS_LIVE.load(Ordering::Relaxed) & (1u64 << pi) == 0 {
        return;
    }
    let env_scratch = env_scratch_base_for_pi(pi);
    if env_scratch == 0 {
        return;
    }
    // ★ BATCH 61 — `TEB.ReservedForNtRpc` (x64 offset 0x1698) is rpcrt4's per-thread `threaddata`
    // cache: `get_or_create_threaddata` returns whatever it finds there WITHOUT validating it, and
    // then `RPCRT4_SetThreadCurrentConnection` does `EnterCriticalSection(&tdata->cs)` on
    // `tdata + 0x10`. Report EVERY change of that one slot, with the event boundary it happened
    // inside, so "who put a non-pointer there" is measured rather than attributed.
    if pi == 2 {
        let slot = core::ptr::read_volatile((env_scratch + 0x5000 + 0x698) as *const u64);
        let previous = WL_NTRPC_SLOT.swap(slot, Ordering::Relaxed);
        let prev_tag = WL_NTRPC_LAST_TAG.swap(tag, Ordering::Relaxed);
        let prev_aux = WL_NTRPC_LAST_AUX.swap(aux, Ordering::Relaxed);
        if slot != previous && WL_NTRPC_SLOT_REPORTS.fetch_add(1, Ordering::Relaxed) < 24 {
            print_str(b"[ntrpc] TEB+0x1698 0x");
            print_hex_u64(previous);
            print_str(b" -> 0x");
            print_hex_u64(slot);
            print_str(b" at tag=");
            print_u64(tag);
            print_str(b" aux=0x");
            print_hex_u64(aux);
            print_str(b" (prev pi=2 observation tag=");
            print_u64(prev_tag);
            print_str(b" aux=0x");
            print_hex_u64(prev_aux);
            // ★ THE DECISIVE BIT: was winlogon's OWN mapping of the page read-only across the
            // window in which the value changed? If it was, no CLIENT store could have done it
            // without faulting — which leaves win32k's view or an executive-side alias.
            print_str(b") client-protected=");
            print_u64(WL_TEB2_PROTECTED.load(Ordering::Relaxed));
            print_str(b" client-store-faults=");
            print_u64(WL_TEB2_WRITE_FAULTS.load(Ordering::Relaxed));
            print_str(b" w32-ro-maps=");
            print_u64(W32_TEB_TAIL_RO_MAPS.load(Ordering::Relaxed));
            print_str(b" w32-store-faults=");
            print_u64(W32_TEB_TAIL_WRITE_FAULTS.load(Ordering::Relaxed));
            print_str(b" neighbours 0x1680..0x16b0:");
            let mut off = 0u64;
            while off < 0x30 {
                print_str(b" ");
                print_hex_u64(core::ptr::read_volatile(
                    (env_scratch + 0x5000 + 0x680 + off) as *const u64,
                ));
                off += 8;
            }
            print_str(b"\n");
        }
    }
    let tail = env_scratch + 0x5000 + 0x258;
    let max = core::ptr::read_volatile((tail + 2) as *const u16);
    let buffer = core::ptr::read_volatile((tail + 8) as *const u64);
    let good = max == 522 && buffer == SMSS_TEB_VA + 0x1268;
    let was_good = TEB_WATCH_GOOD[pi].swap(good as u64, Ordering::Relaxed) != 0;
    if good || !was_good {
        TEB_WATCH_LAST_TAG.store(tag, Ordering::Relaxed);
        TEB_WATCH_LAST_AUX.store(aux, Ordering::Relaxed);
        TEB_WATCH_LAST_AUX2.store(aux2, Ordering::Relaxed);
        return;
    }
    if TEB_WATCH_REPORTS.fetch_add(1, Ordering::Relaxed) >= 8 {
        return;
    }
    print_str(b"[teb-watch] FIRST BAD pi=");
    print_u64(pi as u64);
    print_str(b" tag=");
    print_u64(tag);
    print_str(b" aux=0x");
    print_hex_u64(aux);
    print_str(b" aux2=0x");
    print_hex_u64(aux2);
    print_str(b" MaximumLength=");
    print_u64(max as u64);
    print_str(b" Buffer=0x");
    print_hex_u64(buffer);
    print_str(b" win32k-ro-maps=");
    print_u64(W32_TEB_TAIL_RO_MAPS.load(Ordering::Relaxed));
    print_str(b" win32k-store-faults=");
    print_u64(W32_TEB_TAIL_WRITE_FAULTS.load(Ordering::Relaxed));
    print_str(b" PREV-observation tag=");
    print_u64(TEB_WATCH_LAST_TAG.load(Ordering::Relaxed));
    print_str(b" aux=0x");
    print_hex_u64(TEB_WATCH_LAST_AUX.load(Ordering::Relaxed));
    print_str(b" aux2=0x");
    print_hex_u64(TEB_WATCH_LAST_AUX2.load(Ordering::Relaxed));
    print_str(b"\n");
    teb_tail_alias_scan(pi);
    print_str(b"[teb-watch] tail bytes TEB+0x1240..0x1280:");
    let mut offset = 0u64;
    while offset < 0x40 {
        print_str(b" ");
        print_hex_u64(core::ptr::read_volatile(
            (env_scratch + 0x5000 + 0x240 + offset) as *const u64,
        ));
        offset += 8;
    }
    print_str(b"\n");
}

/// Registered client TEB **tail** page VAs (the second page of every hosted thread's TEB). VAs
/// repeat across VSpaces by design, so this is a small de-duplicated VA set, not a (pi, VA) table.
const TEB_TAIL_PAGE_CAP: usize = 32;
static mut TEB_TAIL_PAGE: [u64; TEB_TAIL_PAGE_CAP] = [0; TEB_TAIL_PAGE_CAP];
static mut TEB_TAIL_PAGE_N: usize = 0;
/// Record `page` as a client TEB tail page (called by BOTH spawn paths, next to the
/// `csrss_frame_put` that makes it reachable from win32k at all).
pub(crate) unsafe fn teb_tail_register(page: u64) {
    let n = core::ptr::read(core::ptr::addr_of!(TEB_TAIL_PAGE_N));
    let pages = core::ptr::addr_of!(TEB_TAIL_PAGE) as *const u64;
    for index in 0..n {
        if core::ptr::read(pages.add(index)) == page {
            return;
        }
    }
    if n < TEB_TAIL_PAGE_CAP {
        core::ptr::write(
            (core::ptr::addr_of_mut!(TEB_TAIL_PAGE) as *mut u64).add(n),
            page,
        );
        core::ptr::write(core::ptr::addr_of_mut!(TEB_TAIL_PAGE_N), n + 1);
    }
}
pub(crate) unsafe fn is_teb_tail_page(page: u64) -> bool {
    let n = core::ptr::read(core::ptr::addr_of!(TEB_TAIL_PAGE_N));
    let pages = core::ptr::addr_of!(TEB_TAIL_PAGE) as *const u64;
    for index in 0..n {
        if core::ptr::read(pages.add(index)) == page {
            return true;
        }
    }
    false
}

/// Copy-on-write shadows of client TEB tail pages, keyed by (pi, page). Each entry keeps a
/// PERMANENT pair of executive aliases — the client's real frame and the shadow — so re-seeding a
/// shadow is a plain 4 KiB copy with no further capability work.
const TEB_TAIL_SHADOW_CAP: usize = 16;
/// Executive alias window for those pairs: a free 2 MiB page-table slot between `NTDLLBUF`
/// (`0x1440_0000` + 480 frames) and the file-buffer `POOL` (`0x1500_0000`).
pub const TEB_TAIL_ALIAS_BASE: u64 = 0x0000_0100_1460_0000;
static mut TEB_TAIL_SHADOW_PI: [u64; TEB_TAIL_SHADOW_CAP] = [0; TEB_TAIL_SHADOW_CAP];
static mut TEB_TAIL_SHADOW_PAGE: [u64; TEB_TAIL_SHADOW_CAP] = [0; TEB_TAIL_SHADOW_CAP];
static mut TEB_TAIL_SHADOW_FRAME: [u64; TEB_TAIL_SHADOW_CAP] = [0; TEB_TAIL_SHADOW_CAP];
static mut TEB_TAIL_SHADOW_N: usize = 0;
static TEB_TAIL_ALIAS_PT: AtomicU64 = AtomicU64::new(0);
/// win32k write faults on a protected tail page (each one is a scribble that DIDN'T happen).
pub(crate) static W32_TEB_TAIL_WRITE_FAULTS: AtomicU64 = AtomicU64::new(0);
/// Shadows created, and re-seeds (a shadow re-established after a client switch dropped it).
pub(crate) static W32_TEB_TAIL_SHADOWS: AtomicU64 = AtomicU64::new(0);
pub(crate) static W32_TEB_TAIL_RESEEDS: AtomicU64 = AtomicU64::new(0);
/// The first win32k image RVA measured storing into a client TEB tail — the evidence that names the
/// writer instead of guessing at it.
pub(crate) static W32_TEB_TAIL_FIRST_WRITER_RVA: AtomicU64 = AtomicU64::new(0);

/// The private shadow frame for (`pi`, `page`), seeded from the client's LIVE tail page. Returns 0
/// if the client frame is unknown or the executive is out of shadow slots (the caller then leaves
/// the read-only mapping in place, which is a wall, never a silent scribble).
pub(crate) unsafe fn teb_tail_shadow(pi: u64, page: u64) -> u64 {
    let (real_frame, _) = csrss_frame_get_exact(pi, page);
    if real_frame == 0 {
        return 0;
    }
    let real_source = {
        let source_cap = csrss_frame_source_cap_get(pi, page);
        if source_cap != 0 {
            source_cap
        } else {
            real_frame
        }
    };
    let n = core::ptr::read(core::ptr::addr_of!(TEB_TAIL_SHADOW_N));
    let pis = core::ptr::addr_of!(TEB_TAIL_SHADOW_PI) as *const u64;
    let pages = core::ptr::addr_of!(TEB_TAIL_SHADOW_PAGE) as *const u64;
    let frames = core::ptr::addr_of!(TEB_TAIL_SHADOW_FRAME) as *const u64;
    let mut slot = usize::MAX;
    for index in 0..n {
        if core::ptr::read(pis.add(index)) == pi && core::ptr::read(pages.add(index)) == page {
            slot = index;
            break;
        }
    }
    if slot == usize::MAX {
        if n >= TEB_TAIL_SHADOW_CAP {
            return 0;
        }
        if TEB_TAIL_ALIAS_PT.swap(1, Ordering::Relaxed) == 0 {
            let pt = alloc_slot();
            let retype = untyped_retype_r(CAP_INIT_UNTYPED, OBJ_X86_PAGE_TABLE, PAGING_BITS, 1, pt);
            if retype != 0 {
                let _ = cnode_delete_recycle_r(pt);
                TEB_TAIL_ALIAS_PT.store(0, Ordering::Relaxed);
                print_str(b"[teb-shadow] alias PT retype failed error=");
                print_u64(retype);
                print_str(b"\n");
                return 0;
            }
            let map = paging_struct_map_r(
                pt,
                LBL_X86_PAGE_TABLE_MAP,
                TEB_TAIL_ALIAS_BASE,
                CAP_INIT_THREAD_VSPACE,
            );
            if map != 0 {
                let _ = cnode_delete_recycle_r(pt);
                TEB_TAIL_ALIAS_PT.store(0, Ordering::Relaxed);
                print_str(b"[teb-shadow] alias PT map failed error=");
                print_u64(map);
                print_str(b"\n");
                return 0;
            }
        }
        let (shadow, shadow_retype) = alloc_frame_r();
        if shadow_retype != 0 {
            if shadow != 0 {
                let _ = cnode_delete_recycle_r(shadow);
            }
            print_str(b"[teb-shadow] shadow frame retype failed pi=");
            print_u64(pi);
            print_str(b" page=0x");
            print_hex((page >> 32) as u32);
            print_hex(page as u32);
            print_str(b" error=");
            print_u64(shadow_retype);
            print_str(b"\n");
            return 0;
        }
        let real_alias = TEB_TAIL_ALIAS_BASE + (2 * n as u64) * 0x1000;
        let shadow_alias = real_alias + 0x1000;
        let (real_copy, real_copy_error) = copy_cap_r(real_source);
        if real_copy_error != 0 {
            if real_copy != 0 {
                let _ = cnode_delete_recycle_r(real_copy);
            }
            let _ = cnode_delete_recycle_r(shadow);
            print_str(b"[teb-shadow] real alias copy failed pi=");
            print_u64(pi);
            print_str(b" page=0x");
            print_hex((page >> 32) as u32);
            print_hex(page as u32);
            print_str(b" source=0x");
            print_hex(real_source as u32);
            print_str(b" error=");
            print_u64(real_copy_error);
            print_str(b"\n");
            return 0;
        }
        let (shadow_copy, shadow_copy_error) = copy_cap_r(shadow);
        if shadow_copy_error != 0 {
            if shadow_copy != 0 {
                let _ = cnode_delete_recycle_r(shadow_copy);
            }
            let _ = cnode_delete_recycle_r(real_copy);
            let _ = cnode_delete_recycle_r(shadow);
            print_str(b"[teb-shadow] shadow alias copy failed pi=");
            print_u64(pi);
            print_str(b" page=0x");
            print_hex((page >> 32) as u32);
            print_hex(page as u32);
            print_str(b" shadow=0x");
            print_hex(shadow as u32);
            print_str(b" error=");
            print_u64(shadow_copy_error);
            print_str(b"\n");
            return 0;
        }
        let e_real = page_map_r(real_copy, real_alias, RW_NX, CAP_INIT_THREAD_VSPACE);
        let e_shadow = page_map_r(shadow_copy, shadow_alias, RW_NX, CAP_INIT_THREAD_VSPACE);
        if e_real != 0 || e_shadow != 0 {
            let _ = cnode_delete_recycle_r(real_copy);
            let _ = cnode_delete_recycle_r(shadow_copy);
            let _ = cnode_delete_recycle_r(shadow);
            print_str(b"[teb-shadow] alias map failed pi=");
            print_u64(pi);
            print_str(b" page=0x");
            print_hex((page >> 32) as u32);
            print_hex(page as u32);
            print_str(b" real/shadow=");
            print_u64(e_real);
            print_str(b"/");
            print_u64(e_shadow);
            print_str(b"\n");
            return 0;
        }
        core::ptr::write(
            (core::ptr::addr_of_mut!(TEB_TAIL_SHADOW_PI) as *mut u64).add(n),
            pi,
        );
        core::ptr::write(
            (core::ptr::addr_of_mut!(TEB_TAIL_SHADOW_PAGE) as *mut u64).add(n),
            page,
        );
        core::ptr::write(
            (core::ptr::addr_of_mut!(TEB_TAIL_SHADOW_FRAME) as *mut u64).add(n),
            shadow,
        );
        core::ptr::write(core::ptr::addr_of_mut!(TEB_TAIL_SHADOW_N), n + 1);
        slot = n;
        W32_TEB_TAIL_SHADOWS.fetch_add(1, Ordering::Relaxed);
    } else {
        W32_TEB_TAIL_RESEEDS.fetch_add(1, Ordering::Relaxed);
    }
    // (Re-)seed: the shadow starts life as an exact copy of what the client's tail holds RIGHT NOW,
    // so every value win32k may read there — `StaticUnicodeString`, `DeallocationStack`, TLS slots —
    // is the caller's real one. Only the WRITES diverge.
    let real_alias = TEB_TAIL_ALIAS_BASE + (2 * slot as u64) * 0x1000;
    let shadow_alias = real_alias + 0x1000;
    let mut offset = 0u64;
    while offset < 0x1000 {
        core::ptr::write_volatile(
            (shadow_alias + offset) as *mut u64,
            core::ptr::read_volatile((real_alias + offset) as *const u64),
        );
        offset += 8;
    }
    core::ptr::read(frames.add(slot))
}

// --- PRIVATE-VM UNMAP SELF-TEST (proves the ASID fix, by construction) --------------------------
/// Proof bits for [`private_vm_unmap_selftest`].
pub(crate) const VM_UNMAP_SELFTEST_MAPPED: u64 = 0x01;
/// The registry really recorded a frame for the test VA (the map went through the real path).
pub(crate) const VM_UNMAP_SELFTEST_REGISTERED: u64 = 0x02;
/// The unmap really released the frame (the registry entry is gone).
pub(crate) const VM_UNMAP_SELFTEST_RELEASED: u64 = 0x04;
/// ★ THE LOAD-BEARING BIT: the SAME VA can be committed AGAIN. With no ASID on the process VSpace,
/// seL4's `Page::Unmap` cannot find the vspace, leaves the leaf PTE live, and this second map comes
/// back `seL4_DeleteFirst` — which `vm_map_private_page` reports as STATUS_INSUFFICIENT_RESOURCES.
pub(crate) const VM_UNMAP_SELFTEST_REMAPPED: u64 = 0x08;
/// The released frame really went back through the recycling pool and was handed out again — the
/// decommit ran end-to-end (release → free list → re-acquire → zero → re-map), not just far enough
/// to drop the registry entry.
pub(crate) const VM_UNMAP_SELFTEST_RECYCLED: u64 = 0x10;
/// The VA was left clean (second unmap released it too).
pub(crate) const VM_UNMAP_SELFTEST_CLEAN: u64 = 0x20;
pub(crate) const VM_UNMAP_SELFTEST_ALL: u64 = 0x3f;
pub(crate) static VM_UNMAP_SELFTEST: AtomicU64 = AtomicU64::new(0);

// --- MAPPED-DATA SECTION WRITEBACK SELF-TEST ----------------------------------------------------
const MAPPED_SECTION_WRITEBACK_CREATED: u64 = 0x01;
const MAPPED_SECTION_WRITEBACK_SEEDED: u64 = 0x02;
const MAPPED_SECTION_WRITEBACK_VIEW: u64 = 0x04;
const MAPPED_SECTION_WRITEBACK_FRAME: u64 = 0x08;
const MAPPED_SECTION_WRITEBACK_DIRTY: u64 = 0x10;
const MAPPED_SECTION_WRITEBACK_WRITTEN: u64 = 0x20;
const MAPPED_SECTION_WRITEBACK_READBACK: u64 = 0x40;
const MAPPED_SECTION_WRITEBACK_ALL: u64 = 0x7f;
static MAPPED_SECTION_WRITEBACK_RAN: AtomicBool = AtomicBool::new(false);
static MAPPED_SECTION_WRITEBACK_SELFTEST: AtomicU64 = AtomicU64::new(0);
static MAPPED_SECTION_WRITEBACK_BYTES: AtomicU64 = AtomicU64::new(0);
static MAPPED_SECTION_WRITEBACK_STATUS: AtomicU64 =
    AtomicU64::new(nt_fs::STATUS_NOT_IMPLEMENTED as u64);
static mut MAPPED_SECTION_WRITEBACK_TABLE: GenericSectionTable = GenericSectionTable::new();
const MAPPED_SECTION_WRITEBACK_PAYLOAD: &[u8] = b"section writeback data";

// --- MAPPED-DATA SECTION WRITECOPY COW SELF-TEST -----------------------------------------------
const MAPPED_SECTION_WRITECOPY_COW_SOURCE: u64 = 0x001;
const MAPPED_SECTION_WRITECOPY_COW_SEEDED: u64 = 0x002;
const MAPPED_SECTION_WRITECOPY_COW_MAPPED_SHARED: u64 = 0x004;
const MAPPED_SECTION_WRITECOPY_COW_REGISTERED: u64 = 0x008;
const MAPPED_SECTION_WRITECOPY_COW_PROMOTED: u64 = 0x010;
const MAPPED_SECTION_WRITECOPY_COW_COPIED: u64 = 0x020;
const MAPPED_SECTION_WRITECOPY_COW_PRIVATE_MUTATED: u64 = 0x040;
const MAPPED_SECTION_WRITECOPY_COW_SHARED_UNCHANGED: u64 = 0x080;
const MAPPED_SECTION_WRITECOPY_COW_CLEANED: u64 = 0x100;
const MAPPED_SECTION_WRITECOPY_COW_ALL: u64 = 0x1ff;
static MAPPED_SECTION_WRITECOPY_COW_RAN: AtomicBool = AtomicBool::new(false);
static MAPPED_SECTION_WRITECOPY_COW_SELFTEST: AtomicU64 = AtomicU64::new(0);
static MAPPED_SECTION_WRITECOPY_COW_STATUS: AtomicU64 =
    AtomicU64::new(nt_fs::STATUS_NOT_IMPLEMENTED as u64);
const MAPPED_SECTION_WRITECOPY_COW_PATTERN: &[u8] = b"mapped writecopy shared source bytes";

// --- MEM_IMAGE WRITECOPY COW SELF-TEST ---------------------------------------------------------
const IMAGE_WRITECOPY_COW_SOURCE: u64 = 0x001;
const IMAGE_WRITECOPY_COW_SEEDED: u64 = 0x002;
const IMAGE_WRITECOPY_COW_MAPPED_SHARED: u64 = 0x004;
const IMAGE_WRITECOPY_COW_REGISTERED: u64 = 0x008;
const IMAGE_WRITECOPY_COW_PROMOTED: u64 = 0x010;
const IMAGE_WRITECOPY_COW_COPIED: u64 = 0x020;
const IMAGE_WRITECOPY_COW_PRIVATE_MUTATED: u64 = 0x040;
const IMAGE_WRITECOPY_COW_SHARED_UNCHANGED: u64 = 0x080;
const IMAGE_WRITECOPY_COW_CLEANED: u64 = 0x100;
const IMAGE_WRITECOPY_COW_ALL: u64 = 0x1ff;
static IMAGE_WRITECOPY_COW_RAN: AtomicBool = AtomicBool::new(false);
static IMAGE_WRITECOPY_COW_SELFTEST: AtomicU64 = AtomicU64::new(0);
static IMAGE_WRITECOPY_COW_STATUS: AtomicU64 = AtomicU64::new(nt_fs::STATUS_NOT_IMPLEMENTED as u64);
const IMAGE_WRITECOPY_COW_PATTERN: &[u8] = b"image writecopy shared source bytes";

// --- CROSS-AUTHORITY VM PLACEMENT SELF-TEST ----------------------------------------------------
const VM_CROSS_AUTH_RETRY_BOTTOM_UP: u64 = 0x01;
const VM_CROSS_AUTH_RETRY_TOP_DOWN: u64 = 0x02;
const VM_CROSS_AUTH_RETRY_EXPLICIT_CONFLICT: u64 = 0x04;
const VM_CROSS_AUTH_RETRY_FIXED_GAP_CLEAN: u64 = 0x08;
const VM_CROSS_AUTH_RETRY_ALL: u64 = 0x0f;

fn align_up_allocation_granularity(value: u64) -> Option<u64> {
    value
        .checked_add(nt_address_space::ALLOCATION_GRANULARITY - 1)
        .map(|value| value & !(nt_address_space::ALLOCATION_GRANULARITY - 1))
}

fn vm_cross_authority_placement_retry_selftest() -> (u64, u64, u64) {
    const LOWER: u64 = 0x10000;
    const UPPER: u64 = 0x10_0000;
    const PAGE: u64 = 0x1000;
    let mut proof = 0u64;

    let before = nt_address_space::VmRegionMap::<4>::new(LOWER, UPPER);
    let mut fixed = nt_address_space::VmCommittedRangeTable::<4>::new();
    if fixed
        .register(nt_address_space::VmCommittedRange::mapped(
            LOWER,
            PAGE,
            nt_address_space::PAGE_READONLY,
        ))
        .is_err()
    {
        return (proof, 0, 0);
    }

    let mut bottom_selected = 0u64;
    let mut lower_bound = 0u64;
    for _ in 0..4 {
        let mut after = before;
        let Ok(plan) = after.allocate_between(
            None,
            PAGE,
            nt_address_space::MEM_RESERVE | nt_address_space::MEM_COMMIT,
            nt_address_space::PAGE_READWRITE,
            lower_bound,
            UPPER,
        ) else {
            break;
        };
        match fixed
            .first_overlap_range(plan.base, plan.size)
            .ok()
            .flatten()
        {
            Some(range) => {
                let Some(next_lower) = align_up_allocation_granularity(range.end()) else {
                    break;
                };
                lower_bound = next_lower;
            }
            None => {
                bottom_selected = plan.base;
                break;
            }
        }
    }
    if bottom_selected == LOWER + nt_address_space::ALLOCATION_GRANULARITY {
        proof |= VM_CROSS_AUTH_RETRY_BOTTOM_UP;
    }

    let mut top_fixed = nt_address_space::VmCommittedRangeTable::<4>::new();
    if top_fixed
        .register(nt_address_space::VmCommittedRange::mapped(
            0xf_0000,
            PAGE,
            nt_address_space::PAGE_READONLY,
        ))
        .is_err()
    {
        return (proof, bottom_selected, 0);
    }
    let mut top_selected = 0u64;
    let mut upper_bound = UPPER;
    for _ in 0..4 {
        let mut after = before;
        let Ok(plan) = after.allocate_between(
            None,
            PAGE,
            nt_address_space::MEM_RESERVE
                | nt_address_space::MEM_COMMIT
                | nt_address_space::MEM_TOP_DOWN,
            nt_address_space::PAGE_READWRITE,
            LOWER,
            upper_bound,
        ) else {
            break;
        };
        match top_fixed
            .first_overlap_range(plan.base, plan.size)
            .ok()
            .flatten()
        {
            Some(range) => upper_bound = upper_bound.min(range.base),
            None => {
                top_selected = plan.base;
                break;
            }
        }
    }
    if top_selected == 0xe_0000 {
        proof |= VM_CROSS_AUTH_RETRY_TOP_DOWN;
    }

    let mut explicit = before;
    if explicit
        .allocate_between(
            Some(LOWER),
            PAGE,
            nt_address_space::MEM_RESERVE | nt_address_space::MEM_COMMIT,
            nt_address_space::PAGE_READWRITE,
            LOWER,
            UPPER,
        )
        .ok()
        .and_then(|plan| {
            fixed
                .first_overlap_range(plan.base, plan.size)
                .ok()
                .flatten()
        })
        .is_some()
    {
        proof |= VM_CROSS_AUTH_RETRY_EXPLICIT_CONFLICT;
    }
    if fixed.first_overlap_range(bottom_selected, PAGE) == Ok(None)
        && top_fixed.first_overlap_range(top_selected, PAGE) == Ok(None)
    {
        proof |= VM_CROSS_AUTH_RETRY_FIXED_GAP_CLEAN;
    }

    (proof, bottom_selected, top_selected)
}

/// Commit → decommit → RE-COMMIT one private page in a hosted process's VSpace, on the real
/// `vm_map_private_page` / `vm_unmap_private_page` path, at a VA the VAD allocator never reaches
/// (the very top of the private window — placements run upward from `SMSS_ALLOC_VA` and the boot's
/// highest measured selection is `…305b0000`). This is the direct, bypass-sensitive proof that an
/// unmap really clears the leaf PTE.
pub(crate) unsafe fn private_vm_unmap_selftest(pi: usize, pml4: u64, scratch_base: u64) {
    if pml4 == 0 || scratch_base == 0 {
        return;
    }
    let page = PRIVATE_VM_LIMIT - 0x1000;
    let mut proof = 0u64;
    if vm_map_private_page(
        pi,
        page,
        nt_address_space::PAGE_READWRITE,
        pml4,
        scratch_base,
    )
    .is_ok()
    {
        proof |= VM_UNMAP_SELFTEST_MAPPED;
    }
    let first = csrss_frame_get_exact(pi as u64, page).0;
    if first != 0 {
        proof |= VM_UNMAP_SELFTEST_REGISTERED;
    }
    vm_unmap_private_page(pi, page);
    if csrss_frame_get_exact(pi as u64, page).0 == 0 {
        proof |= VM_UNMAP_SELFTEST_RELEASED;
    }
    if vm_map_private_page(
        pi,
        page,
        nt_address_space::PAGE_READWRITE,
        pml4,
        scratch_base,
    )
    .is_ok()
    {
        proof |= VM_UNMAP_SELFTEST_REMAPPED;
    }
    let second = csrss_frame_get_exact(pi as u64, page).0;
    if second != 0 && second == first {
        proof |= VM_UNMAP_SELFTEST_RECYCLED;
    }
    vm_unmap_private_page(pi, page);
    if csrss_frame_get_exact(pi as u64, page).0 == 0 {
        proof |= VM_UNMAP_SELFTEST_CLEAN;
    }
    VM_UNMAP_SELFTEST.store(proof, Ordering::Relaxed);
    print_str(b"[vm-selftest] commit/decommit/RE-COMMIT of one private page: proof=0x");
    print_hex(proof as u32);
    print_str(b"/0x");
    print_hex(VM_UNMAP_SELFTEST_ALL as u32);
    print_str(b" first-frame=0x");
    print_hex(first as u32);
    print_str(b" second-frame=0x");
    print_hex(second as u32);
    print_str(b"\n");
}

pub(crate) unsafe fn mapped_section_writeback_selftest(scratch_base: u64) {
    const STATUS_UNSUCCESSFUL: u32 = 0xC000_0001;
    const RELATIVE_PATH: &[u8] = b".mapped-section-writeback.bin";
    const INITIAL: &[u8] = b"section writeback seed";
    if scratch_base == 0
        || MAPPED_SECTION_WRITEBACK_RAN
            .compare_exchange(false, true, Ordering::AcqRel, Ordering::Relaxed)
            .is_err()
    {
        return;
    }
    let mut proof = 0u64;
    let mut status: u32;
    let mut bytes_written = 0u64;
    let mut frame = 0u64;
    let mut file_id = 0u64;
    let mut section_index = usize::MAX;
    let table = &mut *core::ptr::addr_of_mut!(MAPPED_SECTION_WRITEBACK_TABLE);
    table.reset();
    let cleanup =
        |table: &mut GenericSectionTable, section_index: usize, frame: u64, file_id: u64| unsafe {
            if section_index != usize::MAX {
                table.clear_section(section_index);
            }
            if frame != 0 {
                vm_frame_release(frame, 0);
            }
            if file_id != 0 {
                crate::writable_fs::close(file_id);
            }
        };

    let (create_status, created_file, _info) = crate::writable_fs::create(
        RELATIVE_PATH,
        nt_fs::FILE_READ_DATA | nt_fs::FILE_WRITE_DATA,
        0,
        0,
        nt_fs::FILE_OVERWRITE_IF,
        nt_fs::FILE_NON_DIRECTORY_FILE,
    );
    status = create_status;
    let Some(created_file_id) = created_file else {
        cleanup(table, section_index, frame, file_id);
        MAPPED_SECTION_WRITEBACK_SELFTEST.store(proof, Ordering::Relaxed);
        MAPPED_SECTION_WRITEBACK_BYTES.store(bytes_written, Ordering::Relaxed);
        MAPPED_SECTION_WRITEBACK_STATUS.store(status as u64, Ordering::Relaxed);
        return;
    };
    file_id = created_file_id;
    proof |= MAPPED_SECTION_WRITEBACK_CREATED;

    let (seed_status, seeded) = crate::writable_fs::write(file_id, Some(0), INITIAL);
    status = seed_status;
    if seed_status != nt_fs::STATUS_SUCCESS || seeded != INITIAL.len() {
        cleanup(table, section_index, frame, file_id);
        MAPPED_SECTION_WRITEBACK_SELFTEST.store(proof, Ordering::Relaxed);
        MAPPED_SECTION_WRITEBACK_BYTES.store(bytes_written, Ordering::Relaxed);
        MAPPED_SECTION_WRITEBACK_STATUS.store(status as u64, Ordering::Relaxed);
        return;
    }
    proof |= MAPPED_SECTION_WRITEBACK_SEEDED;

    let Some(created_section) = table.create(
        0,
        0,
        MAPPED_SECTION_WRITEBACK_PAYLOAD.len() as u64,
        nt_address_space::PAGE_READWRITE,
        GenericSectionBacking::overlay(file_id),
    ) else {
        status = STATUS_UNSUCCESSFUL;
        cleanup(table, section_index, frame, file_id);
        MAPPED_SECTION_WRITEBACK_SELFTEST.store(proof, Ordering::Relaxed);
        MAPPED_SECTION_WRITEBACK_BYTES.store(bytes_written, Ordering::Relaxed);
        MAPPED_SECTION_WRITEBACK_STATUS.store(status as u64, Ordering::Relaxed);
        return;
    };
    section_index = created_section;
    let view_base = PRIVATE_VM_LIMIT - 0x20_0000;
    if !table.map_view(0, section_index, view_base, 0x1000, 0) {
        status = STATUS_UNSUCCESSFUL;
        cleanup(table, section_index, frame, file_id);
        MAPPED_SECTION_WRITEBACK_SELFTEST.store(proof, Ordering::Relaxed);
        MAPPED_SECTION_WRITEBACK_BYTES.store(bytes_written, Ordering::Relaxed);
        MAPPED_SECTION_WRITEBACK_STATUS.store(status as u64, Ordering::Relaxed);
        return;
    }
    let Some((_view_section, view)) = table.view_for_page(0, view_base) else {
        status = STATUS_UNSUCCESSFUL;
        cleanup(table, section_index, frame, file_id);
        MAPPED_SECTION_WRITEBACK_SELFTEST.store(proof, Ordering::Relaxed);
        MAPPED_SECTION_WRITEBACK_BYTES.store(bytes_written, Ordering::Relaxed);
        MAPPED_SECTION_WRITEBACK_STATUS.store(status as u64, Ordering::Relaxed);
        return;
    };
    proof |= MAPPED_SECTION_WRITEBACK_VIEW;

    match vm_frame_acquire(scratch_base) {
        Ok(acquired) => frame = acquired,
        Err(error) => {
            status = error;
            cleanup(table, section_index, frame, file_id);
            MAPPED_SECTION_WRITEBACK_SELFTEST.store(proof, Ordering::Relaxed);
            MAPPED_SECTION_WRITEBACK_BYTES.store(bytes_written, Ordering::Relaxed);
            MAPPED_SECTION_WRITEBACK_STATUS.store(status as u64, Ordering::Relaxed);
            return;
        }
    }
    let scratch = scratch_base + DEMAND_SCRATCH_WINDOW - 0x5000;
    if page_map_r(frame, scratch, RW_NX, CAP_INIT_THREAD_VSPACE) != 0 {
        status = nt_address_space::STATUS_INSUFFICIENT_RESOURCES;
        cleanup(table, section_index, frame, file_id);
        MAPPED_SECTION_WRITEBACK_SELFTEST.store(proof, Ordering::Relaxed);
        MAPPED_SECTION_WRITEBACK_BYTES.store(bytes_written, Ordering::Relaxed);
        MAPPED_SECTION_WRITEBACK_STATUS.store(status as u64, Ordering::Relaxed);
        return;
    }
    core::ptr::copy_nonoverlapping(
        MAPPED_SECTION_WRITEBACK_PAYLOAD.as_ptr(),
        scratch as *mut u8,
        MAPPED_SECTION_WRITEBACK_PAYLOAD.len(),
    );
    let _ = page_unmap_r(frame);
    if !table.set_page_frame(section_index, 0, frame) {
        status = nt_address_space::STATUS_INSUFFICIENT_RESOURCES;
        cleanup(table, section_index, frame, file_id);
        MAPPED_SECTION_WRITEBACK_SELFTEST.store(proof, Ordering::Relaxed);
        MAPPED_SECTION_WRITEBACK_BYTES.store(bytes_written, Ordering::Relaxed);
        MAPPED_SECTION_WRITEBACK_STATUS.store(status as u64, Ordering::Relaxed);
        return;
    }
    proof |= MAPPED_SECTION_WRITEBACK_FRAME;
    if !table.mark_page_dirty(section_index, 0) {
        status = STATUS_UNSUCCESSFUL;
        cleanup(table, section_index, frame, file_id);
        MAPPED_SECTION_WRITEBACK_SELFTEST.store(proof, Ordering::Relaxed);
        MAPPED_SECTION_WRITEBACK_BYTES.store(bytes_written, Ordering::Relaxed);
        MAPPED_SECTION_WRITEBACK_STATUS.store(status as u64, Ordering::Relaxed);
        return;
    }
    proof |= MAPPED_SECTION_WRITEBACK_DIRTY;

    match service_generic_section_writeback_view(table, view, scratch_base) {
        Ok(written) => {
            bytes_written = written;
            if written == MAPPED_SECTION_WRITEBACK_PAYLOAD.len() as u64 {
                proof |= MAPPED_SECTION_WRITEBACK_WRITTEN;
            }
        }
        Err(error) => {
            status = error;
            cleanup(table, section_index, frame, file_id);
            MAPPED_SECTION_WRITEBACK_SELFTEST.store(proof, Ordering::Relaxed);
            MAPPED_SECTION_WRITEBACK_BYTES.store(bytes_written, Ordering::Relaxed);
            MAPPED_SECTION_WRITEBACK_STATUS.store(status as u64, Ordering::Relaxed);
            return;
        }
    }
    let (read_status, read_back) =
        crate::writable_fs::read(file_id, Some(0), MAPPED_SECTION_WRITEBACK_PAYLOAD.len());
    status = read_status;
    if read_status == nt_fs::STATUS_SUCCESS
        && read_back.as_slice() == MAPPED_SECTION_WRITEBACK_PAYLOAD
    {
        proof |= MAPPED_SECTION_WRITEBACK_READBACK;
    }

    cleanup(table, section_index, frame, file_id);
    MAPPED_SECTION_WRITEBACK_SELFTEST.store(proof, Ordering::Relaxed);
    MAPPED_SECTION_WRITEBACK_BYTES.store(bytes_written, Ordering::Relaxed);
    MAPPED_SECTION_WRITEBACK_STATUS.store(status as u64, Ordering::Relaxed);
    print_str(b"[section-writeback-selftest] proof=0x");
    print_hex(proof as u32);
    print_str(b"/0x");
    print_hex(MAPPED_SECTION_WRITEBACK_ALL as u32);
    print_str(b" bytes=");
    print_u64(bytes_written);
    print_str(b" status=0x");
    print_hex(status);
    print_str(b"\n");
}

unsafe fn finish_mapped_section_writecopy_cow_selftest(
    pi: usize,
    page: u64,
    source_frame: u64,
    loose_map_cap: u64,
    mut proof: u64,
    status: u32,
) {
    if loose_map_cap != 0 {
        let _ = page_unmap_r(loose_map_cap);
        let _ = cnode_delete_recycle_r(loose_map_cap);
    }
    vm_unmap_private_page(pi, page);
    let clean = csrss_frame_get_exact(pi as u64, page).0 == 0;
    if source_frame != 0 {
        vm_frame_release(source_frame, 0);
    }
    if clean {
        proof |= MAPPED_SECTION_WRITECOPY_COW_CLEANED;
    }
    MAPPED_SECTION_WRITECOPY_COW_SELFTEST.store(proof, Ordering::Relaxed);
    MAPPED_SECTION_WRITECOPY_COW_STATUS.store(status as u64, Ordering::Relaxed);
    print_str(b"[section-writecopy-cow-selftest-run] proof=0x");
    print_hex(proof as u32);
    print_str(b"/0x");
    print_hex(MAPPED_SECTION_WRITECOPY_COW_ALL as u32);
    print_str(b" status=0x");
    print_hex(status);
    print_str(b"\n");
}

pub(crate) unsafe fn mapped_section_writecopy_cow_selftest(
    pi: usize,
    pml4: u64,
    scratch_base: u64,
) {
    const STATUS_UNSUCCESSFUL: u32 = 0xC000_0001;
    if pml4 == 0
        || scratch_base == 0
        || MAPPED_SECTION_WRITECOPY_COW_RAN
            .compare_exchange(false, true, Ordering::AcqRel, Ordering::Relaxed)
            .is_err()
    {
        return;
    }
    let page = PRIVATE_VM_LIMIT - 0x60_0000;
    let mut proof = 0u64;
    let mut source_frame = 0u64;
    let mut loose_map_cap = 0u64;
    vm_unmap_private_page(pi, page);

    match vm_frame_acquire(scratch_base) {
        Ok(frame) => source_frame = frame,
        Err(status) => {
            finish_mapped_section_writecopy_cow_selftest(
                pi,
                page,
                source_frame,
                loose_map_cap,
                proof,
                status,
            );
            return;
        }
    }
    proof |= MAPPED_SECTION_WRITECOPY_COW_SOURCE;

    if let Err(status) = cow_seed_source_frame(
        source_frame,
        scratch_base,
        MAPPED_SECTION_WRITECOPY_COW_PATTERN,
    ) {
        finish_mapped_section_writecopy_cow_selftest(
            pi,
            page,
            source_frame,
            loose_map_cap,
            proof,
            status,
        );
        return;
    }
    proof |= MAPPED_SECTION_WRITECOPY_COW_SEEDED;
    match cow_frame_prefix_matches(
        source_frame,
        scratch_base,
        MAPPED_SECTION_WRITECOPY_COW_PATTERN,
    ) {
        Ok(true) => {}
        Ok(false) => {
            finish_mapped_section_writecopy_cow_selftest(
                pi,
                page,
                source_frame,
                loose_map_cap,
                proof,
                STATUS_UNSUCCESSFUL,
            );
            return;
        }
        Err(status) => {
            finish_mapped_section_writecopy_cow_selftest(
                pi,
                page,
                source_frame,
                loose_map_cap,
                proof,
                status,
            );
            return;
        }
    }

    let read_plan =
        nt_address_space::mapped_view_fault_plan(nt_address_space::PAGE_WRITECOPY, false);
    let write_plan =
        nt_address_space::mapped_view_fault_plan(nt_address_space::PAGE_WRITECOPY, true);
    if !write_plan.copy_on_write || write_plan.mark_dirty {
        finish_mapped_section_writecopy_cow_selftest(
            pi,
            page,
            source_frame,
            loose_map_cap,
            proof,
            STATUS_UNSUCCESSFUL,
        );
        return;
    }
    if let Err(status) = vm_ensure_private_pt(pi, page, pml4) {
        finish_mapped_section_writecopy_cow_selftest(
            pi,
            page,
            source_frame,
            loose_map_cap,
            proof,
            status,
        );
        return;
    }
    let (map_cap, copy_error) = copy_cap_r(source_frame);
    if copy_error != 0 {
        if map_cap != 0 {
            let _ = cnode_delete_recycle_r(map_cap);
        }
        finish_mapped_section_writecopy_cow_selftest(
            pi,
            page,
            source_frame,
            loose_map_cap,
            proof,
            nt_address_space::STATUS_INSUFFICIENT_RESOURCES,
        );
        return;
    }
    loose_map_cap = map_cap;
    if page_map_r(
        map_cap,
        page,
        vm_page_rights(read_plan.map_protection),
        pml4,
    ) != 0
    {
        finish_mapped_section_writecopy_cow_selftest(
            pi,
            page,
            source_frame,
            loose_map_cap,
            proof,
            nt_address_space::STATUS_INSUFFICIENT_RESOURCES,
        );
        return;
    }
    proof |= MAPPED_SECTION_WRITECOPY_COW_MAPPED_SHARED;
    let source_cap = csrss_frame_create_source_copy(map_cap, pi as u64, page, b"mapped-cow");
    if source_cap == 0 || !csrss_frame_put_section_mapping(pi as u64, page, map_cap, source_cap) {
        if source_cap != 0 {
            let _ = cnode_delete_recycle_r(source_cap);
        }
        finish_mapped_section_writecopy_cow_selftest(
            pi,
            page,
            source_frame,
            loose_map_cap,
            proof,
            nt_address_space::STATUS_INSUFFICIENT_RESOURCES,
        );
        return;
    }
    loose_map_cap = 0;
    proof |= MAPPED_SECTION_WRITECOPY_COW_REGISTERED;

    if let Err(status) = vm_promote_mapped_cow_page(
        pi,
        page,
        0,
        read_plan.map_protection,
        write_plan.map_protection,
        pml4,
        scratch_base,
    ) {
        finish_mapped_section_writecopy_cow_selftest(
            pi,
            page,
            source_frame,
            loose_map_cap,
            proof,
            status,
        );
        return;
    }

    let Some(record) = csrss_frame_get_exact_record(pi as u64, page) else {
        finish_mapped_section_writecopy_cow_selftest(
            pi,
            page,
            source_frame,
            loose_map_cap,
            proof,
            STATUS_UNSUCCESSFUL,
        );
        return;
    };
    if record.owns_frame && record.frame != source_frame {
        proof |= MAPPED_SECTION_WRITECOPY_COW_PROMOTED;
    }
    match cow_frame_prefix_matches(
        record.frame,
        scratch_base,
        MAPPED_SECTION_WRITECOPY_COW_PATTERN,
    ) {
        Ok(true) => proof |= MAPPED_SECTION_WRITECOPY_COW_COPIED,
        Ok(false) => {}
        Err(status) => {
            finish_mapped_section_writecopy_cow_selftest(
                pi,
                page,
                source_frame,
                loose_map_cap,
                proof,
                status,
            );
            return;
        }
    }

    let mutated = MAPPED_SECTION_WRITECOPY_COW_PATTERN[0] ^ 0xff;
    if let Err(status) = cow_write_frame_byte(record.frame, scratch_base, 0, mutated) {
        finish_mapped_section_writecopy_cow_selftest(
            pi,
            page,
            source_frame,
            loose_map_cap,
            proof,
            status,
        );
        return;
    }
    match cow_frame_byte(record.frame, scratch_base, 0) {
        Ok(value) if value == mutated => proof |= MAPPED_SECTION_WRITECOPY_COW_PRIVATE_MUTATED,
        Ok(_) => {}
        Err(status) => {
            finish_mapped_section_writecopy_cow_selftest(
                pi,
                page,
                source_frame,
                loose_map_cap,
                proof,
                status,
            );
            return;
        }
    }
    match cow_frame_byte(source_frame, scratch_base, 0) {
        Ok(value) if value == MAPPED_SECTION_WRITECOPY_COW_PATTERN[0] => {
            proof |= MAPPED_SECTION_WRITECOPY_COW_SHARED_UNCHANGED;
        }
        Ok(_) => {}
        Err(status) => {
            finish_mapped_section_writecopy_cow_selftest(
                pi,
                page,
                source_frame,
                loose_map_cap,
                proof,
                status,
            );
            return;
        }
    }
    let status = if proof
        & (MAPPED_SECTION_WRITECOPY_COW_ALL & !MAPPED_SECTION_WRITECOPY_COW_CLEANED)
        == (MAPPED_SECTION_WRITECOPY_COW_ALL & !MAPPED_SECTION_WRITECOPY_COW_CLEANED)
    {
        nt_address_space::STATUS_SUCCESS
    } else {
        STATUS_UNSUCCESSFUL
    };
    finish_mapped_section_writecopy_cow_selftest(
        pi,
        page,
        source_frame,
        loose_map_cap,
        proof,
        status,
    );
}

unsafe fn cow_seed_source_frame(frame: u64, scratch_base: u64, pattern: &[u8]) -> Result<(), u32> {
    let alias = scratch_base + DEMAND_SCRATCH_WINDOW - 0x8000;
    if page_map_r(frame, alias, RW_NX, CAP_INIT_THREAD_VSPACE) != 0 {
        return Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES);
    }
    core::ptr::copy_nonoverlapping(pattern.as_ptr(), alias as *mut u8, pattern.len());
    let _ = page_unmap_r(frame);
    Ok(())
}

unsafe fn cow_frame_prefix_matches(
    frame: u64,
    scratch_base: u64,
    expected: &[u8],
) -> Result<bool, u32> {
    let alias = scratch_base + DEMAND_SCRATCH_WINDOW - 0x8000;
    let (copy, copy_error) = copy_cap_r(frame);
    if copy_error != 0 {
        if copy != 0 {
            let _ = cnode_delete_recycle_r(copy);
        }
        return Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES);
    }
    if page_map_r(copy, alias, RO_NX, CAP_INIT_THREAD_VSPACE) != 0 {
        let _ = cnode_delete_recycle_r(copy);
        return Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES);
    }
    let mut index = 0usize;
    let mut matches = true;
    while index < expected.len() {
        if core::ptr::read_volatile((alias + index as u64) as *const u8) != expected[index] {
            matches = false;
            break;
        }
        index += 1;
    }
    let _ = page_unmap_r(copy);
    let _ = cnode_delete_recycle_r(copy);
    Ok(matches)
}

unsafe fn cow_frame_byte(frame: u64, scratch_base: u64, offset: u64) -> Result<u8, u32> {
    let alias = scratch_base + DEMAND_SCRATCH_WINDOW - 0x8000;
    let (copy, copy_error) = copy_cap_r(frame);
    if copy_error != 0 {
        if copy != 0 {
            let _ = cnode_delete_recycle_r(copy);
        }
        return Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES);
    }
    if page_map_r(copy, alias, RO_NX, CAP_INIT_THREAD_VSPACE) != 0 {
        let _ = cnode_delete_recycle_r(copy);
        return Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES);
    }
    let value = core::ptr::read_volatile((alias + offset) as *const u8);
    let _ = page_unmap_r(copy);
    let _ = cnode_delete_recycle_r(copy);
    Ok(value)
}

unsafe fn cow_write_frame_byte(
    frame: u64,
    scratch_base: u64,
    offset: u64,
    value: u8,
) -> Result<(), u32> {
    let alias = scratch_base + DEMAND_SCRATCH_WINDOW - 0x8000;
    let (copy, copy_error) = copy_cap_r(frame);
    if copy_error != 0 {
        if copy != 0 {
            let _ = cnode_delete_recycle_r(copy);
        }
        return Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES);
    }
    if page_map_r(copy, alias, RW_NX, CAP_INIT_THREAD_VSPACE) != 0 {
        let _ = cnode_delete_recycle_r(copy);
        return Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES);
    }
    core::ptr::write_volatile((alias + offset) as *mut u8, value);
    let _ = page_unmap_r(copy);
    let _ = cnode_delete_recycle_r(copy);
    Ok(())
}

unsafe fn finish_image_writecopy_cow_selftest(
    pi: usize,
    page: u64,
    source_frame: u64,
    loose_map_cap: u64,
    mut proof: u64,
    status: u32,
) {
    let mut loose_map_cap = loose_map_cap;
    if let Some(map_cap) = shared_image_mapping_take(pi as u64, page) {
        let _ = page_unmap_r(map_cap);
        let _ = cnode_delete_recycle_r(map_cap);
        if loose_map_cap == map_cap {
            loose_map_cap = 0;
        }
    }
    if loose_map_cap != 0 {
        let _ = page_unmap_r(loose_map_cap);
        let _ = cnode_delete_recycle_r(loose_map_cap);
    }
    vm_unmap_private_page(pi, page);
    let clean = csrss_frame_get_exact(pi as u64, page).0 == 0
        && shared_image_mapping_get(pi as u64, page).is_none();
    if source_frame != 0 {
        vm_frame_release(source_frame, 0);
    }
    if clean {
        proof |= IMAGE_WRITECOPY_COW_CLEANED;
    }
    IMAGE_WRITECOPY_COW_SELFTEST.store(proof, Ordering::Relaxed);
    IMAGE_WRITECOPY_COW_STATUS.store(status as u64, Ordering::Relaxed);
    print_str(b"[image-cow-selftest-run] proof=0x");
    print_hex(proof as u32);
    print_str(b"/0x");
    print_hex(IMAGE_WRITECOPY_COW_ALL as u32);
    print_str(b" status=0x");
    print_hex(status);
    print_str(b"\n");
}

pub(crate) unsafe fn image_writecopy_cow_selftest(pi: usize, pml4: u64, scratch_base: u64) {
    const STATUS_UNSUCCESSFUL: u32 = 0xC000_0001;
    if pml4 == 0
        || scratch_base == 0
        || IMAGE_WRITECOPY_COW_RAN
            .compare_exchange(false, true, Ordering::AcqRel, Ordering::Relaxed)
            .is_err()
    {
        return;
    }
    let page = PRIVATE_VM_LIMIT - 0x40_0000;
    let mut proof = 0u64;
    let mut source_frame = 0u64;
    let mut loose_map_cap = 0u64;
    if let Some(map_cap) = shared_image_mapping_take(pi as u64, page) {
        let _ = page_unmap_r(map_cap);
        let _ = cnode_delete_recycle_r(map_cap);
    }
    vm_unmap_private_page(pi, page);

    match vm_frame_acquire(scratch_base) {
        Ok(frame) => source_frame = frame,
        Err(status) => {
            finish_image_writecopy_cow_selftest(
                pi,
                page,
                source_frame,
                loose_map_cap,
                proof,
                status,
            );
            return;
        }
    }
    proof |= IMAGE_WRITECOPY_COW_SOURCE;

    if let Err(status) =
        cow_seed_source_frame(source_frame, scratch_base, IMAGE_WRITECOPY_COW_PATTERN)
    {
        finish_image_writecopy_cow_selftest(pi, page, source_frame, loose_map_cap, proof, status);
        return;
    }
    proof |= IMAGE_WRITECOPY_COW_SEEDED;
    match cow_frame_prefix_matches(source_frame, scratch_base, IMAGE_WRITECOPY_COW_PATTERN) {
        Ok(true) => {}
        Ok(false) => {
            finish_image_writecopy_cow_selftest(
                pi,
                page,
                source_frame,
                loose_map_cap,
                proof,
                STATUS_UNSUCCESSFUL,
            );
            return;
        }
        Err(status) => {
            finish_image_writecopy_cow_selftest(
                pi,
                page,
                source_frame,
                loose_map_cap,
                proof,
                status,
            );
            return;
        }
    }

    let read_plan =
        nt_address_space::image_view_fault_plan(nt_address_space::PAGE_EXECUTE_WRITECOPY, false);
    let write_plan =
        nt_address_space::image_view_fault_plan(nt_address_space::PAGE_EXECUTE_WRITECOPY, true);
    if !write_plan.copy_on_write {
        finish_image_writecopy_cow_selftest(
            pi,
            page,
            source_frame,
            loose_map_cap,
            proof,
            STATUS_UNSUCCESSFUL,
        );
        return;
    }
    if let Err(status) = vm_ensure_private_pt(pi, page, pml4) {
        finish_image_writecopy_cow_selftest(pi, page, source_frame, loose_map_cap, proof, status);
        return;
    }
    let (map_cap, copy_error) = copy_cap_r(source_frame);
    if copy_error != 0 {
        if map_cap != 0 {
            let _ = cnode_delete_recycle_r(map_cap);
        }
        finish_image_writecopy_cow_selftest(
            pi,
            page,
            source_frame,
            loose_map_cap,
            proof,
            nt_address_space::STATUS_INSUFFICIENT_RESOURCES,
        );
        return;
    }
    loose_map_cap = map_cap;
    if page_map_r(
        map_cap,
        page,
        vm_page_rights(read_plan.map_protection),
        pml4,
    ) != 0
    {
        finish_image_writecopy_cow_selftest(
            pi,
            page,
            source_frame,
            loose_map_cap,
            proof,
            nt_address_space::STATUS_INSUFFICIENT_RESOURCES,
        );
        return;
    }
    proof |= IMAGE_WRITECOPY_COW_MAPPED_SHARED;
    if !shared_image_mapping_put(pi as u64, page, map_cap) {
        finish_image_writecopy_cow_selftest(
            pi,
            page,
            source_frame,
            loose_map_cap,
            proof,
            nt_address_space::STATUS_INSUFFICIENT_RESOURCES,
        );
        return;
    }
    loose_map_cap = 0;
    proof |= IMAGE_WRITECOPY_COW_REGISTERED;

    if let Err(status) = vm_promote_image_cow_page(
        pi,
        page,
        read_plan.map_protection,
        write_plan.map_protection,
        pml4,
        scratch_base,
    ) {
        finish_image_writecopy_cow_selftest(pi, page, source_frame, loose_map_cap, proof, status);
        return;
    }

    let Some(record) = csrss_frame_get_exact_record(pi as u64, page) else {
        finish_image_writecopy_cow_selftest(
            pi,
            page,
            source_frame,
            loose_map_cap,
            proof,
            STATUS_UNSUCCESSFUL,
        );
        return;
    };
    if record.owns_frame
        && record.frame != source_frame
        && shared_image_mapping_get(pi as u64, page).is_none()
    {
        proof |= IMAGE_WRITECOPY_COW_PROMOTED;
    }
    match cow_frame_prefix_matches(record.frame, scratch_base, IMAGE_WRITECOPY_COW_PATTERN) {
        Ok(true) => proof |= IMAGE_WRITECOPY_COW_COPIED,
        Ok(false) => {}
        Err(status) => {
            finish_image_writecopy_cow_selftest(
                pi,
                page,
                source_frame,
                loose_map_cap,
                proof,
                status,
            );
            return;
        }
    }

    let mutated = IMAGE_WRITECOPY_COW_PATTERN[0] ^ 0xff;
    if let Err(status) = cow_write_frame_byte(record.frame, scratch_base, 0, mutated) {
        finish_image_writecopy_cow_selftest(pi, page, source_frame, loose_map_cap, proof, status);
        return;
    }
    match cow_frame_byte(record.frame, scratch_base, 0) {
        Ok(value) if value == mutated => proof |= IMAGE_WRITECOPY_COW_PRIVATE_MUTATED,
        Ok(_) => {}
        Err(status) => {
            finish_image_writecopy_cow_selftest(
                pi,
                page,
                source_frame,
                loose_map_cap,
                proof,
                status,
            );
            return;
        }
    }
    match cow_frame_byte(source_frame, scratch_base, 0) {
        Ok(value) if value == IMAGE_WRITECOPY_COW_PATTERN[0] => {
            proof |= IMAGE_WRITECOPY_COW_SHARED_UNCHANGED;
        }
        Ok(_) => {}
        Err(status) => {
            finish_image_writecopy_cow_selftest(
                pi,
                page,
                source_frame,
                loose_map_cap,
                proof,
                status,
            );
            return;
        }
    }
    let status = if proof & (IMAGE_WRITECOPY_COW_ALL & !IMAGE_WRITECOPY_COW_CLEANED)
        == (IMAGE_WRITECOPY_COW_ALL & !IMAGE_WRITECOPY_COW_CLEANED)
    {
        nt_address_space::STATUS_SUCCESS
    } else {
        STATUS_UNSUCCESSFUL
    };
    finish_image_writecopy_cow_selftest(pi, page, source_frame, loose_map_cap, proof, status);
}

unsafe fn alloc_frame() -> u64 {
    let s = alloc_slot();
    let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_X86_4K_PAGE, PAGING_BITS, 1, s);
    s
}

unsafe fn vm_frame_acquire(scratch_base: u64) -> Result<u64, u32> {
    let count = core::ptr::read(core::ptr::addr_of!(VM_FREE_FRAME_N));
    if count == 0 {
        let (frame, error) = alloc_frame_r();
        return if error == 0 {
            Ok(frame)
        } else {
            let _ = cnode_delete_recycle_r(frame);
            Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES)
        };
    }
    let index = count - 1;
    let frames = core::ptr::addr_of_mut!(VM_FREE_FRAMES) as *mut u64;
    let frame = core::ptr::read(frames.add(index));
    core::ptr::write(frames.add(index), 0);
    core::ptr::write(core::ptr::addr_of_mut!(VM_FREE_FRAME_N), index);
    let scratch = scratch_base + DEMAND_SCRATCH_WINDOW - 0x2000;
    if page_map_r(frame, scratch, RW_NX, CAP_INIT_THREAD_VSPACE) != 0 {
        core::ptr::write(frames.add(index), frame);
        core::ptr::write(core::ptr::addr_of_mut!(VM_FREE_FRAME_N), count);
        return Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES);
    }
    core::ptr::write_bytes(scratch as *mut u8, 0, 0x1000);
    let _ = page_unmap_r(frame);
    Ok(frame)
}

unsafe fn vm_frame_release(frame: u64, alias_cap: u64) {
    let _ = page_unmap_r(frame);
    if alias_cap != 0 {
        let _ = page_unmap_r(alias_cap);
        let _ = cnode_delete_recycle_r(alias_cap);
    }
    let count = core::ptr::read(core::ptr::addr_of!(VM_FREE_FRAME_N));
    if count < VM_FREE_FRAME_CAPACITY {
        core::ptr::write(
            (core::ptr::addr_of_mut!(VM_FREE_FRAMES) as *mut u64).add(count),
            frame,
        );
        core::ptr::write(core::ptr::addr_of_mut!(VM_FREE_FRAME_N), count + 1);
        note_high_water(&VM_FREE_FRAME_HW, (count + 1) as u64);
    } else {
        let _ = cnode_delete_recycle_r(frame);
    }
}

fn heap_mirror_for_pi(pi: usize) -> u64 {
    hosted_heap_mirror_for_pi(pi)
}

fn vm_page_rights(protection: u32) -> u64 {
    let base = protection & 0xff;
    let writable = matches!(
        base,
        nt_address_space::PAGE_READWRITE | nt_address_space::PAGE_EXECUTE_READWRITE
    );
    let executable = matches!(
        base,
        nt_address_space::PAGE_EXECUTE
            | nt_address_space::PAGE_EXECUTE_READ
            | nt_address_space::PAGE_EXECUTE_READWRITE
            | nt_address_space::PAGE_EXECUTE_WRITECOPY
    );
    (if base == nt_address_space::PAGE_NOACCESS || protection & nt_address_space::PAGE_GUARD != 0 {
        0
    } else if writable {
        3
    } else {
        2
    }) | if executable { 0 } else { PAGE_EXECUTE_NEVER }
}

unsafe fn vm_ensure_private_pt(pi: usize, page: u64, pml4: u64) -> Result<(), u32> {
    let offset = page
        .checked_sub(SMSS_ALLOC_VA)
        .filter(|offset| *offset < PRIVATE_VM_LIMIT - SMSS_ALLOC_VA)
        .ok_or(nt_address_space::STATUS_CONFLICTING_ADDRESSES)?;
    let index = (offset / 0x20_0000) as usize;
    let caps = core::ptr::addr_of_mut!(PROCESS_VM_PT_CAPS) as *mut [u64; PRIVATE_VM_PT_COUNT];
    let slot = (*caps.add(pi)).as_mut_ptr().add(index);
    if core::ptr::read(slot) != 0 {
        return Ok(());
    }
    let pt = alloc_slot();
    if untyped_retype_r(CAP_INIT_UNTYPED, OBJ_X86_PAGE_TABLE, PAGING_BITS, 1, pt) != 0 {
        let _ = cnode_delete_recycle_r(pt);
        VM_FAIL_PT.fetch_add(1, Ordering::Relaxed);
        return Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES);
    }
    if paging_struct_map_r(pt, LBL_X86_PAGE_TABLE_MAP, page & !0x1f_ffff, pml4) != 0 {
        let _ = cnode_delete_recycle_r(pt);
        VM_FAIL_PT.fetch_add(1, Ordering::Relaxed);
        return Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES);
    }
    core::ptr::write(slot, pt);
    Ok(())
}

unsafe fn vm_map_private_page(
    pi: usize,
    page: u64,
    protection: u32,
    pml4: u64,
    scratch_base: u64,
) -> Result<(), u32> {
    vm_ensure_private_pt(pi, page, pml4)?;
    let frame = match vm_frame_acquire(scratch_base) {
        Ok(frame) => frame,
        Err(status) => {
            VM_FAIL_FRAME.fetch_add(1, Ordering::Relaxed);
            return Err(status);
        }
    };
    let map_label = page_map_r(frame, page, vm_page_rights(protection), pml4);
    if map_label != 0 {
        vm_frame_release(frame, 0);
        if VM_FAIL_MAP.fetch_add(1, Ordering::Relaxed) < 8 {
            // Name the refusal instead of collapsing it into STATUS_INSUFFICIENT_RESOURCES:
            // label 8 (`seL4_DeleteFirst`) = the leaf PTE is ALREADY occupied, i.e. a VA collision,
            // not an exhausted pool. `known` says whether the frame registry knows that mapping.
            let known = csrss_frame_get_exact(pi as u64, page).0;
            print_str(b"[vm-map-fail] pi=");
            print_u64(pi as u64);
            print_str(b" page=0x");
            print_hex((page >> 32) as u32);
            print_hex(page as u32);
            print_str(b" prot=0x");
            print_hex(protection);
            print_str(b" label=");
            print_u64(map_label);
            print_str(b" known-frame=0x");
            print_hex(known as u32);
            print_str(b"\n");
        }
        return Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES);
    }
    let mut alias = 0;
    let mut alias_cap = 0;
    if page >= SMSS_ALLOC_VA && page < SMSS_ALLOC_VA + SMSS_HEAP_MIRROR_WINDOW {
        alias = heap_mirror_for_pi(pi) + (page - SMSS_ALLOC_VA);
        let (copied, copy_error) = copy_cap_r(frame);
        if copy_error != 0 || page_map_r(copied, alias, RW_NX, CAP_INIT_THREAD_VSPACE) != 0 {
            let _ = cnode_delete_recycle_r(copied);
            vm_frame_release(frame, 0);
            VM_FAIL_ALIAS.fetch_add(1, Ordering::Relaxed);
            return Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES);
        }
        alias_cap = copied;
    }
    if !csrss_frame_put_at_cap(pi as u64, page, frame, alias, alias_cap) {
        vm_frame_release(frame, alias_cap);
        VM_FAIL_REGISTRY.fetch_add(1, Ordering::Relaxed);
        return Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES);
    }
    vm_watch(b"map", pi, page, frame);
    Ok(())
}

/// A bounded map/unmap WATCH over one private-VM page window, so the LIFE of a colliding VA is
/// readable in a single boot (who mapped it, who released it, with which frame cap). Off unless
/// [`VM_WATCH_LO`] < [`VM_WATCH_HI`]; both zero in the shipping build.
const VM_WATCH_LO: u64 = 0;
const VM_WATCH_HI: u64 = 0;
static VM_WATCH_N: AtomicU64 = AtomicU64::new(0);
fn vm_watch(what: &[u8], pi: usize, page: u64, frame: u64) {
    if page < VM_WATCH_LO || page >= VM_WATCH_HI || VM_WATCH_N.fetch_add(1, Ordering::Relaxed) > 64
    {
        return;
    }
    print_str(b"[vm-watch] ");
    print_str(what);
    print_str(b" pi=");
    print_u64(pi as u64);
    print_str(b" page=0x");
    print_hex((page >> 32) as u32);
    print_hex(page as u32);
    print_str(b" frame=0x");
    print_hex(frame as u32);
    print_str(b"\n");
}

unsafe fn vm_unmap_private_page(pi: usize, page: u64) {
    if let Some((frame, alias_cap, source_cap, owns_frame)) = csrss_frame_take(pi as u64, page) {
        vm_watch(b"unmap", pi, page, frame);
        if owns_frame {
            vm_frame_release(frame, alias_cap);
        } else {
            let _ = page_unmap_r(frame);
            let _ = cnode_delete_recycle_r(frame);
            if alias_cap != 0 {
                let _ = page_unmap_r(alias_cap);
                let _ = cnode_delete_recycle_r(alias_cap);
            }
        }
        if source_cap != 0 && source_cap != frame && source_cap != alias_cap {
            let _ = cnode_delete_recycle_r(source_cap);
        }
    } else {
        vm_watch(b"unmap-miss", pi, page, 0);
    }
}

fn vm_protection_writable(protection: u32) -> bool {
    matches!(
        protection & 0xff,
        nt_address_space::PAGE_READWRITE | nt_address_space::PAGE_EXECUTE_READWRITE
    )
}

unsafe fn vm_reprotect_private_page(
    pi: usize,
    page: u64,
    old_protection: u32,
    new_protection: u32,
    pml4: u64,
) -> Result<(), u32> {
    let frame = csrss_frame_get_exact(pi as u64, page).0;
    if frame == 0 {
        return Err(nt_address_space::STATUS_MEMORY_NOT_ALLOCATED);
    }
    let _ = page_unmap_r(frame);
    if page_map_r(frame, page, vm_page_rights(new_protection), pml4) == 0 {
        Ok(())
    } else {
        let _ = page_map_r(frame, page, vm_page_rights(old_protection), pml4);
        Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES)
    }
}

unsafe fn vm_copy_frame_4k(source_cap: u64, dest_frame: u64, scratch_base: u64) -> Result<(), u32> {
    let source_alias = scratch_base + DEMAND_SCRATCH_WINDOW - 0x6000;
    let dest_alias = scratch_base + DEMAND_SCRATCH_WINDOW - 0x7000;
    let (source_copy, source_error) = copy_cap_r(source_cap);
    if source_error != 0 {
        if source_copy != 0 {
            let _ = cnode_delete_recycle_r(source_copy);
        }
        return Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES);
    }
    let source_map = page_map_r(source_copy, source_alias, RO_NX, CAP_INIT_THREAD_VSPACE);
    if source_map != 0 {
        let _ = cnode_delete_recycle_r(source_copy);
        return Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES);
    }
    let dest_map = page_map_r(dest_frame, dest_alias, RW_NX, CAP_INIT_THREAD_VSPACE);
    if dest_map != 0 {
        let _ = page_unmap_r(source_copy);
        let _ = cnode_delete_recycle_r(source_copy);
        return Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES);
    }

    let mut offset = 0u64;
    while offset < 0x1000 {
        core::ptr::write_volatile(
            (dest_alias + offset) as *mut u64,
            core::ptr::read_volatile((source_alias + offset) as *const u64),
        );
        offset += 8;
    }

    let _ = page_unmap_r(dest_frame);
    let _ = page_unmap_r(source_copy);
    let _ = cnode_delete_recycle_r(source_copy);
    Ok(())
}

unsafe fn recycle_unmapped_frame_record_caps(
    frame: u64,
    alias_cap: u64,
    source_cap: u64,
    owns_frame: bool,
) {
    if owns_frame {
        vm_frame_release(frame, alias_cap);
    } else {
        let _ = cnode_delete_recycle_r(frame);
        if alias_cap != 0 {
            let _ = page_unmap_r(alias_cap);
            let _ = cnode_delete_recycle_r(alias_cap);
        }
    }
    if source_cap != 0 && source_cap != frame && source_cap != alias_cap {
        let _ = cnode_delete_recycle_r(source_cap);
    }
}

unsafe fn vm_unmap_shared_image_mapping_range(pi: usize, base: u64, end: u64) {
    let mut page = base;
    while page < end {
        vm_unmap_private_page(pi, page);
        page += 0x1000;
    }
    shared_image_mapping_unmap_range(pi as u64, base, end);
}

unsafe fn vm_reprotect_shared_image_mapping(
    pi: usize,
    page: u64,
    old_protection: u32,
    new_protection: u32,
    pml4: u64,
) -> Result<(), u32> {
    let Some(map_cap) = shared_image_mapping_get(pi as u64, page) else {
        return Ok(());
    };
    let new_rights = vm_page_rights(new_protection);
    if new_rights == 0 {
        let Some(map_cap) = shared_image_mapping_take(pi as u64, page) else {
            return Ok(());
        };
        let _ = page_unmap_r(map_cap);
        let _ = cnode_delete_recycle_r(map_cap);
        return Ok(());
    }
    let old_rights = vm_page_rights(old_protection);
    let _ = page_unmap_r(map_cap);
    if page_map_r(map_cap, page, new_rights, pml4) == 0 {
        Ok(())
    } else {
        let _ = page_map_r(map_cap, page, old_rights, pml4);
        Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES)
    }
}

unsafe fn vm_promote_image_cow_page(
    pi: usize,
    page: u64,
    old_protection: u32,
    new_protection: u32,
    pml4: u64,
    scratch_base: u64,
) -> Result<(), u32> {
    enum OldImageMapping {
        Exact {
            alias: u64,
            alias_cap: u64,
            source_cap: u64,
            owns_frame: bool,
        },
        Shared,
    }

    let exact_record = csrss_frame_get_exact_record(pi as u64, page);
    if let Some(record) = exact_record {
        if record.owns_frame {
            return vm_reprotect_private_page(pi, page, old_protection, new_protection, pml4);
        }
    }

    let source_cap = if let Some(record) = exact_record {
        if record.source_cap != 0 {
            record.source_cap
        } else {
            record.frame
        }
    } else if let Some(map_cap) = shared_image_mapping_get(pi as u64, page) {
        map_cap
    } else {
        return Err(nt_address_space::STATUS_MEMORY_NOT_ALLOCATED);
    };
    let new_frame = match vm_frame_acquire(scratch_base) {
        Ok(frame) => frame,
        Err(status) => return Err(status),
    };
    if let Err(status) = vm_copy_frame_4k(source_cap, new_frame, scratch_base) {
        vm_frame_release(new_frame, 0);
        return Err(status);
    }

    let (old_map_cap, old_mapping) = if let Some(record) = exact_record {
        let Some((old_frame, old_alias_cap, old_source_cap, old_owns_frame)) =
            csrss_frame_take(pi as u64, page)
        else {
            vm_frame_release(new_frame, 0);
            return Err(nt_address_space::STATUS_MEMORY_NOT_ALLOCATED);
        };
        (
            old_frame,
            OldImageMapping::Exact {
                alias: record.alias,
                alias_cap: old_alias_cap,
                source_cap: old_source_cap,
                owns_frame: old_owns_frame,
            },
        )
    } else {
        let Some(map_cap) = shared_image_mapping_take(pi as u64, page) else {
            vm_frame_release(new_frame, 0);
            return Err(nt_address_space::STATUS_MEMORY_NOT_ALLOCATED);
        };
        (map_cap, OldImageMapping::Shared)
    };
    let _ = page_unmap_r(old_map_cap);
    let map_error = page_map_r(new_frame, page, vm_page_rights(new_protection), pml4);
    if map_error != 0 {
        let _ = page_map_r(old_map_cap, page, vm_page_rights(old_protection), pml4);
        match old_mapping {
            OldImageMapping::Exact {
                alias,
                alias_cap,
                source_cap,
                owns_frame,
            } => {
                let _ = csrss_frame_put_at_cap_source_owned(
                    pi as u64,
                    page,
                    old_map_cap,
                    alias,
                    alias_cap,
                    source_cap,
                    owns_frame,
                );
            }
            OldImageMapping::Shared => {
                let _ = shared_image_mapping_put(pi as u64, page, old_map_cap);
            }
        }
        vm_frame_release(new_frame, 0);
        return Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES);
    }
    if !csrss_frame_put_at_cap_source_owned(pi as u64, page, new_frame, 0, 0, 0, true) {
        let _ = page_unmap_r(new_frame);
        vm_frame_release(new_frame, 0);
        let _ = page_map_r(old_map_cap, page, vm_page_rights(old_protection), pml4);
        match old_mapping {
            OldImageMapping::Exact {
                alias,
                alias_cap,
                source_cap,
                owns_frame,
            } => {
                let _ = csrss_frame_put_at_cap_source_owned(
                    pi as u64,
                    page,
                    old_map_cap,
                    alias,
                    alias_cap,
                    source_cap,
                    owns_frame,
                );
            }
            OldImageMapping::Shared => {
                let _ = shared_image_mapping_put(pi as u64, page, old_map_cap);
            }
        }
        return Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES);
    }

    match old_mapping {
        OldImageMapping::Exact {
            alias_cap,
            source_cap,
            owns_frame,
            ..
        } => {
            recycle_unmapped_frame_record_caps(old_map_cap, alias_cap, source_cap, owns_frame);
        }
        OldImageMapping::Shared => {
            let _ = cnode_delete_recycle_r(old_map_cap);
        }
    }
    Ok(())
}

unsafe fn vm_promote_mapped_cow_page(
    pi: usize,
    page: u64,
    source_frame: u64,
    old_protection: u32,
    new_protection: u32,
    pml4: u64,
    scratch_base: u64,
) -> Result<(), u32> {
    let exact_record = csrss_frame_get_exact_record(pi as u64, page);
    if let Some(record) = exact_record {
        if record.owns_frame {
            return vm_reprotect_private_page(pi, page, old_protection, new_protection, pml4);
        }
    }

    let source_cap = if let Some(record) = exact_record {
        if record.source_cap != 0 {
            record.source_cap
        } else {
            record.frame
        }
    } else if source_frame != 0 {
        source_frame
    } else {
        return Err(nt_address_space::STATUS_MEMORY_NOT_ALLOCATED);
    };

    let new_frame = vm_frame_acquire(scratch_base)?;
    if let Err(status) = vm_copy_frame_4k(source_cap, new_frame, scratch_base) {
        vm_frame_release(new_frame, 0);
        return Err(status);
    }

    let old_mapping = if exact_record.is_some() {
        let Some((old_frame, old_alias_cap, old_source_cap, old_owns_frame)) =
            csrss_frame_take(pi as u64, page)
        else {
            vm_frame_release(new_frame, 0);
            return Err(nt_address_space::STATUS_MEMORY_NOT_ALLOCATED);
        };
        let _ = page_unmap_r(old_frame);
        Some((old_frame, old_alias_cap, old_source_cap, old_owns_frame))
    } else {
        None
    };

    if let Err(status) = vm_ensure_private_pt(pi, page, pml4) {
        if let Some((old_frame, old_alias_cap, old_source_cap, old_owns_frame)) = old_mapping {
            let _ = page_map_r(old_frame, page, vm_page_rights(old_protection), pml4);
            let _ = csrss_frame_put_at_cap_source_owned(
                pi as u64,
                page,
                old_frame,
                0,
                old_alias_cap,
                old_source_cap,
                old_owns_frame,
            );
        }
        vm_frame_release(new_frame, 0);
        return Err(status);
    }

    let map_error = page_map_r(new_frame, page, vm_page_rights(new_protection), pml4);
    if map_error != 0 {
        if let Some((old_frame, old_alias_cap, old_source_cap, old_owns_frame)) = old_mapping {
            let _ = page_map_r(old_frame, page, vm_page_rights(old_protection), pml4);
            let _ = csrss_frame_put_at_cap_source_owned(
                pi as u64,
                page,
                old_frame,
                0,
                old_alias_cap,
                old_source_cap,
                old_owns_frame,
            );
        }
        vm_frame_release(new_frame, 0);
        return Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES);
    }

    if !csrss_frame_put_at_cap_source_owned(pi as u64, page, new_frame, 0, 0, 0, true) {
        let _ = page_unmap_r(new_frame);
        vm_frame_release(new_frame, 0);
        if let Some((old_frame, old_alias_cap, old_source_cap, old_owns_frame)) = old_mapping {
            let _ = page_map_r(old_frame, page, vm_page_rights(old_protection), pml4);
            let _ = csrss_frame_put_at_cap_source_owned(
                pi as u64,
                page,
                old_frame,
                0,
                old_alias_cap,
                old_source_cap,
                old_owns_frame,
            );
        }
        return Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES);
    }

    if let Some((old_frame, old_alias_cap, old_source_cap, old_owns_frame)) = old_mapping {
        recycle_unmapped_frame_record_caps(
            old_frame,
            old_alias_cap,
            old_source_cap,
            old_owns_frame,
        );
    }
    Ok(())
}

unsafe fn vm_reprotect_resident_image_page(
    pi: usize,
    page: u64,
    old_protection: u32,
    new_protection: u32,
    pml4: u64,
    scratch_base: u64,
) -> Result<(), u32> {
    if let Some(record) = csrss_frame_get_exact_record(pi as u64, page) {
        if vm_protection_writable(new_protection) && !record.owns_frame {
            return vm_promote_image_cow_page(
                pi,
                page,
                old_protection,
                new_protection,
                pml4,
                scratch_base,
            );
        }
        return vm_reprotect_private_page(pi, page, old_protection, new_protection, pml4);
    }
    if shared_image_mapping_get(pi as u64, page).is_none() {
        return Ok(());
    }
    if vm_protection_writable(new_protection) {
        vm_promote_image_cow_page(pi, page, old_protection, new_protection, pml4, scratch_base)
    } else {
        vm_reprotect_shared_image_mapping(pi, page, old_protection, new_protection, pml4)
    }
}

unsafe fn copy_cap(src: u64) -> u64 {
    let d = alloc_slot();
    let _ = syscall5(
        SYS_SEND,
        CAP_INIT_THREAD_CNODE,
        LBL_CNODE_COPY << 12,
        d,
        src,
        0,
    );
    d
}
/// Mint a copy of `src` carrying `badge`. For an endpoint cap, the badge is delivered to the
/// receiver on every message/fault sent through it — the 2-process service loop mints each hosted
/// thread's fault cap with a distinct badge so it can tell whose fault this is.
unsafe fn mint_badged(src: u64, badge: u64) -> u64 {
    let d = alloc_slot();
    let _ = syscall5(
        SYS_SEND,
        CAP_INIT_THREAD_CNODE,
        LBL_CNODE_MINT << 12,
        d,
        src,
        badge,
    );
    d
}

// --- SYS_CALL variants that RETURN the invocation error label (0 = success) ---
// The SYS_SEND helpers above are fire-and-forget: a failed retype/copy/map is invisible, so a
// resource exhaustion (or a bad precondition) silently leaves a page unmapped/zero. These mirror
// the same register layout via seL4_Call and hand back the reply's error label so callers can
// detect and react. The reply's message-info comes back in rsi; its label is `reply >> 12`.
unsafe fn untyped_retype_r(untyped: u64, obj: u64, bits: u32, num: u32, dest: u64) -> u64 {
    note_retype(untyped, obj, bits, num);
    let size_num = ((bits as u64) << 32) | (num as u64);
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") untyped => _,
        inout("rsi") LBL_UNTYPED_RETYPE << 12 => reply,
        inout("r10") obj => _,
        inout("r8") size_num => _,
        inout("r9") dest => _,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    let label = reply >> 12;
    note_retype_error(untyped, obj, label);
    if label == 0 {
        root_slot_note_occupied(dest);
    }
    label
}
unsafe fn copy_cap_r(src: u64) -> (u64, u64) {
    let Some(d) = try_alloc_slot() else {
        return (0, 4);
    };
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") CAP_INIT_THREAD_CNODE => _,
        inout("rsi") LBL_CNODE_COPY << 12 => reply,
        inout("r10") d => _,
        inout("r8") src => _,
        inout("r9") 0u64 => _,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    let label = reply >> 12;
    if label != 0 {
        recycle_deleted_root_slot(d);
        return (0, label);
    }
    (d, 0)
}
unsafe fn copy_cap_into_r(src: u64, dest: u64) -> u64 {
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") CAP_INIT_THREAD_CNODE => _,
        inout("rsi") LBL_CNODE_COPY << 12 => reply,
        inout("r10") dest => _,
        inout("r8") src => _,
        inout("r9") 0u64 => _,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    let label = reply >> 12;
    if label == 0 {
        root_slot_note_occupied(dest);
    }
    label
}
unsafe fn cnode_copy_at_r(cnode: u64, dest: u64, src: u64) -> u64 {
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") cnode => _,
        inout("rsi") LBL_CNODE_COPY << 12 => reply,
        inout("r10") dest => _,
        inout("r8") src => _,
        inout("r9") 0u64 => _,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    reply >> 12
}
unsafe fn cnode_mint_r(cnode: u64, dest: u64, src: u64, badge: u64) -> u64 {
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") cnode => _,
        inout("rsi") LBL_CNODE_MINT << 12 => reply,
        inout("r10") dest => _,
        inout("r8") src => _,
        inout("r9") badge => _,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    let label = reply >> 12;
    if label == 0 && cnode == CAP_INIT_THREAD_CNODE {
        root_slot_note_occupied(dest);
    }
    label
}
unsafe fn page_map_r(frame: u64, vaddr: u64, rights: u64, vspace: u64) -> u64 {
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") frame => _,
        inout("rsi") LBL_X86_PAGE_MAP << 12 => reply,
        inout("r10") vaddr => _,
        inout("r8") rights => _,
        inout("r9") vspace => _,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    reply >> 12
}
pub(crate) unsafe fn paging_struct_map_r(paging: u64, label: u64, vaddr: u64, vspace: u64) -> u64 {
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") paging => _,
        inout("rsi") label << 12 => reply,
        inout("r10") vaddr => _,
        inout("r8") vspace => _,
        inout("r9") 0u64 => _,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    reply >> 12
}
/// SYS_CALL variant of `tcb_set_space` — returns the invocation error label (0 = success).
/// (a2=fault_ep, a3=cnode, a4=vspace, per LBL_TCB_SET_SPACE.)
unsafe fn tcb_set_space_r(target: u64, fault_ep: u64, cnode: u64, vspace: u64) -> u64 {
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") target => _,
        inout("rsi") LBL_TCB_SET_SPACE << 12 => reply,
        inout("r10") fault_ep => _,
        inout("r8") cnode => _,
        inout("r9") vspace => _,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    reply >> 12
}
/// SYS_CALL variant of `tcb_set_ipc_buffer` — returns the invocation error label (0 = success).
/// (legacy ABI: a2=vaddr, a3=frame_cptr.)
unsafe fn tcb_set_ipc_buffer_r(target: u64, vaddr: u64, frame: u64) -> u64 {
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") target => _,
        inout("rsi") LBL_TCB_SET_IPC_BUFFER << 12 => reply,
        inout("r10") vaddr => _,
        inout("r8") frame => _,
        inout("r9") 0u64 => _,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    reply >> 12
}
/// SYS_CALL variant of `tcb_write_registers` (legacy length==0 shape) — returns the error label.
/// (a2=rip, a3=rsp, a4=arg0.)
unsafe fn tcb_write_registers_r(target: u64, rip: u64, rsp: u64, arg0: u64) -> u64 {
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") target => _,
        inout("rsi") LBL_TCB_WRITE_REGISTERS << 12 => reply,
        inout("r10") rip => _,
        inout("r8") rsp => _,
        inout("r9") arg0 => _,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    reply >> 12
}
/// Allocate a fresh 4 KiB frame, returning (slot, retype-error-label).
unsafe fn alloc_frame_r() -> (u64, u64) {
    let Some(s) = try_alloc_slot() else {
        return (0, 4);
    };
    let e = untyped_retype_r(CAP_INIT_UNTYPED, OBJ_X86_4K_PAGE, PAGING_BITS, 1, s);
    (s, e)
}

unsafe fn alloc_seeded_root_dma_mmio_frame(seed_va: u64) -> u64 {
    let (frame, frame_err) = alloc_frame_r();
    if frame_err != 0 {
        return 0;
    }
    let pt = alloc_slot();
    let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_X86_PAGE_TABLE, PAGING_BITS, 1, pt);
    let _ = paging_struct_map_r(pt, LBL_X86_PAGE_TABLE_MAP, seed_va, CAP_INIT_THREAD_VSPACE);
    if page_map_r(frame, seed_va, RW_NX, CAP_INIT_THREAD_VSPACE) != 0 {
        return 0;
    }
    let mut offset = 0u64;
    while offset < 0x1000 {
        core::ptr::write_volatile((seed_va + offset) as *mut u8, 0);
        offset += 1;
    }
    core::ptr::write_volatile(seed_va as *mut u32, ROOT_DMA_PROOF_ID_VALUE);
    frame
}

enum HostedDevnodeGrantKind {
    Pci { dev: u8, func: u8 },
    RootBus,
}

struct HostedDevnodeGrant {
    kind: HostedDevnodeGrantKind,
    resource_list: alloc::vec::Vec<u8>,
    mmio_phys: u64,
    mmio_len: u64,
    io_port_base: u64,
    io_port_len: u32,
    vector: u32,
    dma_len: u64,
}

fn print_hosted_devnode_grant(service: &[u8], devnode: &[u8], grant: &HostedDevnodeGrant) {
    match grant.kind {
        HostedDevnodeGrantKind::Pci { dev, func } => {
            print_str(b"[driver-launch] assigned PCI resources service=");
            print_str(service);
            print_str(b" devnode=");
            print_str(devnode);
            print_str(b" pci=0:");
            print_u64(dev as u64);
            print_str(b".");
            print_u64(func as u64);
        }
        HostedDevnodeGrantKind::RootBus => {
            print_str(b"[driver-launch] assigned root-bus resources service=");
            print_str(service);
            print_str(b" devnode=");
            print_str(devnode);
        }
    }
    print_str(b" mmio=0x");
    print_hex(grant.mmio_phys as u32);
    print_str(b" len=");
    print_u64(grant.mmio_len);
    if grant.io_port_len != 0 {
        print_str(b" io=0x");
        print_hex(grant.io_port_base as u32);
        print_str(b" io_len=");
        print_u64(grant.io_port_len as u64);
    }
    print_str(b" vector=");
    print_u64(grant.vector as u64);
    print_str(b" dma_len=");
    print_u64(grant.dma_len);
    print_str(b"\n");
}

unsafe fn grant_hosted_devnode_resources(
    device_id: u64,
    instance_id: &str,
    hardware_refs: &[&str],
    compatible_refs: &[&str],
    pci_devices: &[nt_pnp::PciDevice],
    pci_windows: &[HostedPnpPciResourceWindow],
    root_windows: &[HostedPnpRootResourceWindow],
) -> Result<Option<HostedDevnodeGrant>, nt_status::NtStatus> {
    if let Some(device) = nt_pnp::find_pci_device_for_devnode(
        pci_devices,
        instance_id,
        hardware_refs,
        compatible_refs,
    ) {
        let Some(window) = pci_windows.iter().find(|window| window.matches(device)) else {
            return Err(nt_status::NtStatus::INVALID_DEVICE_REQUEST);
        };
        let Some(grant) = build_devnode_pci_resource_grant(
            device,
            window.interrupt_vector,
            window.interrupt_latched,
            window.dma_len,
            window.granted_mmio_len(),
        ) else {
            return Err(nt_status::NtStatus::INVALID_DEVICE_REQUEST);
        };
        if grant.assignment.mmio_phys != window.mmio_phys
            || window.mmio_frame_base == 0
            || !window.dma_grant_valid()
        {
            return Err(nt_status::NtStatus::INVALID_DEVICE_REQUEST);
        }
        let mmio_len = grant.assignment.mmio_len;
        if mmio_len == 0 || mmio_len > window.mmio_pages * 0x1000 {
            return Err(nt_status::NtStatus::INVALID_DEVICE_REQUEST);
        }
        driver_launch::grant_hosted_device_resources(
            device_id,
            driver_launch::HostedBusIdentity::pci(
                grant.device.bus,
                grant.device.dev,
                grant.device.func,
                grant.device.vendor,
                grant.device.device,
                grant.device.class,
                grant.device.irq_line,
                grant.device.irq_pin,
            ),
            grant.assignment.mmio_phys,
            mmio_len,
            grant.assignment.io_port_base,
            grant.assignment.io_port_len,
            window.mmio_va,
            window.mmio_frame_base,
            window.mmio_pages,
            grant.assignment.int_vector,
            grant.assignment.int_latched,
            grant.assignment.int_affinity,
            window.dma_va,
            window.dma_frame_base,
            window.dma_pages,
            window.dma_logical,
            grant.assignment.dma_len,
        )?;
        return Ok(Some(HostedDevnodeGrant {
            kind: HostedDevnodeGrantKind::Pci {
                dev: grant.device.dev,
                func: grant.device.func,
            },
            resource_list: grant.resource_list,
            mmio_phys: grant.assignment.mmio_phys,
            mmio_len,
            io_port_base: grant.assignment.io_port_base,
            io_port_len: grant.assignment.io_port_len,
            vector: grant.assignment.int_vector,
            dma_len: grant.assignment.dma_len,
        }));
    }

    if let Some(profile) =
        root_bus_resource_profile_for_devnode(instance_id, hardware_refs, compatible_refs)
    {
        let Some(window) = root_windows
            .iter()
            .find(|window| window.matches_profile(profile))
        else {
            return Err(nt_status::NtStatus::INVALID_DEVICE_REQUEST);
        };
        let Some(grant) = assign_devnode_root_dma_resources(
            instance_id,
            hardware_refs,
            compatible_refs,
            window.interrupt_vector,
            window.interrupt_latched,
            window.dma_len,
            window.granted_mmio_len(),
        ) else {
            return Err(nt_status::NtStatus::INVALID_DEVICE_REQUEST);
        };
        if grant.assignment.mmio_phys != window.mmio_phys
            || window.mmio_frame_base == 0
            || window.dma_frame_base == 0
        {
            return Err(nt_status::NtStatus::INVALID_DEVICE_REQUEST);
        }
        let mmio_len = grant.assignment.mmio_len.min(window.mmio_pages * 0x1000);
        if mmio_len == 0 || mmio_len > window.mmio_pages * 0x1000 {
            return Err(nt_status::NtStatus::INVALID_DEVICE_REQUEST);
        }
        driver_launch::grant_hosted_device_resources(
            device_id,
            driver_launch::HostedBusIdentity::root_bus(),
            grant.assignment.mmio_phys,
            mmio_len,
            0,
            0,
            window.mmio_va,
            window.mmio_frame_base,
            window.mmio_pages,
            grant.assignment.int_vector,
            grant.assignment.int_latched,
            grant.assignment.int_affinity,
            window.dma_va,
            window.dma_frame_base,
            window.dma_pages,
            window.dma_logical,
            grant.assignment.dma_len,
        )?;
        return Ok(Some(HostedDevnodeGrant {
            kind: HostedDevnodeGrantKind::RootBus,
            resource_list: grant.resource_list,
            mmio_phys: grant.assignment.mmio_phys,
            mmio_len,
            io_port_base: 0,
            io_port_len: 0,
            vector: grant.assignment.int_vector,
            dma_len: grant.assignment.dma_len,
        }));
    }

    Ok(None)
}

unsafe fn make_object(obj: u64) -> u64 {
    let s = alloc_slot();
    let _ = untyped_retype(CAP_INIT_UNTYPED, obj, 0, 1, s);
    s
}

static mut EXEC_PAGING_SEEN: [u64; 8192] = [0; 8192];
static mut EXEC_PAGING_SEEN_N: usize = 0;
const EXEC_PAGING_SEEN_PDPT: u64 = 1u64 << 60;
const EXEC_PAGING_SEEN_PD: u64 = 2u64 << 60;
const EXEC_PAGING_SEEN_PT: u64 = 3u64 << 60;
const SEL4_DELETE_FIRST: u64 = 8;

unsafe fn exec_paging_seen(key: u64) -> bool {
    let n = core::ptr::read(core::ptr::addr_of!(EXEC_PAGING_SEEN_N));
    let entries = core::ptr::addr_of!(EXEC_PAGING_SEEN) as *const u64;
    for i in 0..n {
        if core::ptr::read(entries.add(i)) == key {
            return true;
        }
    }
    false
}

unsafe fn exec_paging_mark(key: u64) {
    let n = core::ptr::read(core::ptr::addr_of!(EXEC_PAGING_SEEN_N));
    if n < 8192 {
        core::ptr::write(
            (core::ptr::addr_of_mut!(EXEC_PAGING_SEEN) as *mut u64).add(n),
            key,
        );
        core::ptr::write(core::ptr::addr_of_mut!(EXEC_PAGING_SEEN_N), n + 1);
    }
}

#[inline]
fn exec_paging_keys(page: u64) -> (u64, u64, u64) {
    (
        EXEC_PAGING_SEEN_PDPT | (page >> 39),
        EXEC_PAGING_SEEN_PD | (page >> 30),
        EXEC_PAGING_SEEN_PT | (page >> 21),
    )
}

unsafe fn ensure_executive_paging_level(
    key: u64,
    object_type: u64,
    map_label: u64,
    page: u64,
    level: &[u8],
) -> bool {
    if exec_paging_seen(key) {
        return true;
    }
    let slot = alloc_slot();
    let retype = untyped_retype_r(CAP_INIT_UNTYPED, object_type, PAGING_BITS, 1, slot);
    if retype != 0 {
        print_str(b"[exec-paging] retype ");
        print_str(level);
        print_str(b" failed page=0x");
        print_hex((page >> 32) as u32);
        print_hex(page as u32);
        print_str(b" error=");
        print_u64(retype);
        print_str(b"\n");
        let _ = cnode_delete_recycle_r(slot);
        return false;
    }
    let map = paging_struct_map_r(slot, map_label, page, CAP_INIT_THREAD_VSPACE);
    if map == 0 {
        exec_paging_mark(key);
        return true;
    }
    if map == SEL4_DELETE_FIRST {
        let _ = cnode_delete_recycle_r(slot);
        exec_paging_mark(key);
        return true;
    }
    print_str(b"[exec-paging] map ");
    print_str(level);
    print_str(b" failed page=0x");
    print_hex((page >> 32) as u32);
    print_hex(page as u32);
    print_str(b" error=");
    print_u64(map);
    print_str(b"\n");
    let _ = cnode_delete_recycle_r(slot);
    false
}

pub(crate) unsafe fn ensure_executive_paging(page: u64) -> bool {
    let (pdpt, pd, pt) = exec_paging_keys(page);
    ensure_executive_paging_level(pdpt, OBJ_X86_PDPT, LBL_X86_PDPT_MAP, page, b"pdpt")
        && ensure_executive_paging_level(
            pd,
            OBJ_X86_PAGE_DIRECTORY,
            LBL_X86_PAGE_DIRECTORY_MAP,
            page,
            b"pd",
        )
        && ensure_executive_paging_level(
            pt,
            OBJ_X86_PAGE_TABLE,
            LBL_X86_PAGE_TABLE_MAP,
            page,
            b"pt",
        )
}

/// Map the page tables backing one hosted process's 64 MiB demand-fault scratch window
/// (`*_SCRATCH_BASE`) in the executive's own VSpace. Each demand fill takes a UNIQUE monotonic
/// scratch slot within this window (`scratch_base + faults*0x1000`), so it must cover FAULT_CAP
/// pages; 16 PTs = 8192 pages > FAULT_CAP (6000). Called once per process at spawn.
pub(crate) unsafe fn map_demand_scratch_pts(base: u64) {
    // 32 PTs × 2 MiB = the FULL 64 MiB DEMAND_SCRATCH_WINDOW (16384 scratch slots). Raised from 16
    // (32 MiB / 8192 slots) for (A) EAGER IMAGE-MAP: an eager whole-image fill front-loads every
    // per-process page of a process's DLL tree into scratch in one pass, so a service (lsass loads
    // ~57 DLLs) can need well over 8192 slots. Backing the full window keeps the fresh-fill's unique
    // monotonic scratch slot (`scratch_base + faults*0x1000`) inside mapped PTs. Cheap (16 extra PTs).
    for k in 0..32u64 {
        assert!(ensure_executive_paging(base + k * 0x20_0000));
    }
}
// --- ITEM 2b: seL4 MECHANISM teardown (reclamation) invocations, SYS_CALL so they RETURN the error
// label (0 = success). `TCBSuspend`=12 / `CNodeDelete`=23 (kernel InvocationLabel). CNodeDelete on a
// slot under the ROOT CNode is the FULL reclamation primitive — the kernel (src/invocation.rs
// cnode_delete) does, in one call: (1) suspend the TCB on a Thread-cap delete; (2) unmap a mapped
// Frame's PTE + TLB-shootdown; (3) release the object's pool slot when it was the last reference;
// (4) `reclaim_untyped_chain_at_tail` = roll the parent Untyped's `free_index` back so the bytes
// become allocatable again (return-to-Untyped). So full Untyped-return needs NO new kernel primitive.
const LBL_TCB_SUSPEND: u64 = 12;
const LBL_CNODE_DELETE: u64 = 23;
unsafe fn tcb_suspend_r(tcb: u64) -> u64 {
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") tcb => _,
        inout("rsi") LBL_TCB_SUSPEND << 12 => reply,
        inout("r10") 0u64 => _,
        inout("r8") 0u64 => _,
        inout("r9") 0u64 => _,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    reply >> 12
}
/// `CNodeDelete` slot `idx` under the caller's ROOT CNode. Same legacy invocation shape as
/// `copy_cap_r`/`cnode_copy` (index in a2=r10, msginfo length 0 → the kernel defaults depth to
/// WORD_BITS, which resolves a direct root-CNode slot). Returns the error label (0 = success).
unsafe fn cnode_delete_r(idx: u64) -> u64 {
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") CAP_INIT_THREAD_CNODE => _,
        inout("rsi") LBL_CNODE_DELETE << 12 => reply,
        inout("r10") idx => _, // a2 = slot index under the root CNode
        inout("r8") 0u64 => _, // a3 = depth (ignored; msginfo length 0 → WORD_BITS)
        inout("r9") 0u64 => _,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    reply >> 12
}

unsafe fn cnode_delete_recycle_r(idx: u64) -> u64 {
    let label = cnode_delete_r(idx);
    if label == 0 {
        recycle_deleted_root_slot(idx);
    }
    label
}
/// CNodeRevoke on the cap at `idx` under the root CNode: delete all its descendants (and, for an
/// Untyped cap, roll its `free_index` back to 0 = full-capacity reclamation). Mirror of
/// `cnode_delete_r`; used by the reclamation self-test to definitively reset a throwaway child
/// untyped between fill rounds (plain per-object delete didn't reset free_index under a deeper boot).
const LBL_CNODE_REVOKE: u64 = 22;
unsafe fn cnode_revoke_r(idx: u64) -> u64 {
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") CAP_INIT_THREAD_CNODE => _,
        inout("rsi") LBL_CNODE_REVOKE << 12 => reply,
        inout("r10") idx => _, // a2 = slot index under the root CNode
        inout("r8") 0u64 => _, // a3 = depth (ignored; msginfo length 0 → WORD_BITS)
        inout("r9") 0u64 => _,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    reply >> 12
}
/// Retype `num` objects of `obj` (size `bits`) from an ARBITRARY untyped cap `untyped` into `dest`.
/// (`untyped_retype_r` hardcodes `CAP_INIT_UNTYPED`; the reclamation self-test carves + fills a
/// throwaway CHILD untyped.) Returns the error label (0 = success; non-zero once the untyped is
/// exhausted).
unsafe fn untyped_retype_from_r(untyped: u64, obj: u64, bits: u32, num: u32, dest: u64) -> u64 {
    let size_num = ((bits as u64) << 32) | (num as u64);
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") untyped => _,
        inout("rsi") LBL_UNTYPED_RETYPE << 12 => reply,
        inout("r10") obj => _,
        inout("r8") size_num => _,
        inout("r9") dest => _,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    let label = reply >> 12;
    if label == 0 {
        root_slot_note_occupied(dest);
    }
    label
}

unsafe fn sched_control_configure_r(sc: u64, budget: u64, period: u64) -> u64 {
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") SLOT_SCHED_CONTROL => _,
        inout("rsi") LBL_SCHED_CONTROL_CONFIGURE << 12 => reply,
        inout("r10") sc => _,
        inout("r8") budget => _,
        inout("r9") period => _,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    reply >> 12
}

unsafe fn sched_context_bind_r(sc: u64, tcb: u64) -> u64 {
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") sc => _,
        inout("rsi") LBL_SCHED_CONTEXT_BIND << 12 => reply,
        inout("r10") tcb => _,
        inout("r8") 0u64 => _,
        inout("r9") 0u64 => _,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    reply >> 12
}

unsafe fn attach_sched_context(tcb: u64) -> Result<u64, u64> {
    let Some(sc) = try_alloc_slot() else {
        return Err(u64::MAX);
    };
    let e_retype = untyped_retype_r(
        CAP_INIT_UNTYPED,
        OBJ_SCHED_CONTEXT,
        SCHED_CONTEXT_BITS,
        1,
        sc,
    );
    if e_retype != 0 {
        recycle_deleted_root_slot(sc);
        return Err(e_retype);
    }
    let e_configure = sched_control_configure_r(sc, 10, 10);
    if e_configure != 0 {
        let _ = cnode_delete_recycle_r(sc);
        return Err(e_configure);
    }
    let e_bind = sched_context_bind_r(sc, tcb);
    if e_bind != 0 {
        let _ = cnode_delete_recycle_r(sc);
        return Err(e_bind);
    }
    Ok(sc)
}

/// Build the page table for the relocated shared "cluster" region (rings, stack, IPC buffer,
/// sysarg, device MMIO, driver code/arena) at `WORK_CLUSTER_BASE` in `pml4`. The cluster used to
/// piggyback the image's 2 MiB PT; now that the working VAs moved high (out of the 64 MiB ELF
/// reserve) it needs its own PT in every executive-image VSpace and in the executive's own.
pub(crate) unsafe fn map_cluster_pt(pml4: u64) {
    let pt = alloc_slot();
    let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_X86_PAGE_TABLE, PAGING_BITS, 1, pt);
    let _ = paging_struct_map(pt, LBL_X86_PAGE_TABLE_MAP, WORK_CLUSTER_BASE, pml4);
}

unsafe fn map_tp_worker_slot1_pt(pml4: u64) {
    let mut base = TP_WORKER_SLOT1_REGION_BASE;
    let end = LSA_WORKER_REGION_BASE + 0x20_0000;
    while base < end {
        let pt = alloc_slot();
        let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_X86_PAGE_TABLE, PAGING_BITS, 1, pt);
        let _ = paging_struct_map(pt, LBL_X86_PAGE_TABLE_MAP, base, pml4);
        base += 0x20_0000;
    }
}

/// Build the page table for the relocated heap region (`HEAP_BASE`) in `pml4`. The spawned-service
/// heap is deliberately smaller than the executive heap but still fits one 2 MiB PT.
unsafe fn map_heap_pt(pml4: u64) {
    map_heap_pts(pml4, allocator::SERVICE_HEAP_FRAMES);
}

/// Build enough leaf page tables at `HEAP_BASE` to cover `frames` 4 KiB pages (one PT per 2 MiB).
/// The executive's own heap is larger than a spawned service's, so the two callers differ only in
/// how many they ask for.
unsafe fn map_heap_pts(pml4: u64, frames: u64) {
    let windows = frames.div_ceil(512).max(1);
    for window in 0..windows {
        let pt = alloc_slot();
        let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_X86_PAGE_TABLE, PAGING_BITS, 1, pt);
        let _ = paging_struct_map(
            pt,
            LBL_X86_PAGE_TABLE_MAP,
            allocator::HEAP_BASE as u64 + window * 0x20_0000,
            pml4,
        );
    }
}

pub(crate) unsafe fn map_hosted_client_env_pt(pml4: u64) {
    let pt = alloc_slot();
    let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_X86_PAGE_TABLE, PAGING_BITS, 1, pt);
    let _ = paging_struct_map(pt, LBL_X86_PAGE_TABLE_MAP, HOSTED_CLIENT_ENV_BASE, pml4);
}

/// Build the standard executive-image paging skeleton in `pml4`: pdpt + pd for the image's 1 GiB
/// slot, one PT per 2 MiB of image (so the ELF can grow into its 64 MiB reserve), and the
/// relocated cluster PT. Callers then map the image frames + any region-specific buffer PTs. The
/// pd is 1 GiB-granular, so it also covers the cluster / heap / buffer PTs (all < 512 MiB).
pub(crate) unsafe fn map_image_skeleton(pml4: u64, img_count: u64) {
    let pdpt = alloc_slot();
    let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_X86_PDPT, PAGING_BITS, 1, pdpt);
    let pd = alloc_slot();
    let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_X86_PAGE_DIRECTORY, PAGING_BITS, 1, pd);
    let _ = paging_struct_map(pdpt, LBL_X86_PDPT_MAP, IMAGE_BASE, pml4);
    let _ = paging_struct_map(pd, LBL_X86_PAGE_DIRECTORY_MAP, IMAGE_BASE, pml4);
    // One PT per 2 MiB of image (512 4 KiB pages each). `.max(1)` keeps at least one even for a
    // trivially small image.
    let npt = ((img_count + 511) / 512).max(1);
    for k in 0..npt {
        let pt = alloc_slot();
        let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_X86_PAGE_TABLE, PAGING_BITS, 1, pt);
        let _ = paging_struct_map(pt, LBL_X86_PAGE_TABLE_MAP, IMAGE_BASE + k * 0x20_0000, pml4);
    }
    map_cluster_pt(pml4);
}

/// Map the executive's OWN heap (so its front-end can allocate). Builds the heap PT first (the
/// heap is relocated far above the image, so — unlike before — the kernel's ELF PTs don't cover
/// it), then maps all HEAP_FRAMES at the relocated `HEAP_BASE`.
unsafe fn map_own_heap() {
    map_heap_pts(CAP_INIT_THREAD_VSPACE, allocator::HEAP_FRAMES);
    for i in 0..allocator::HEAP_FRAMES {
        let f = alloc_slot();
        let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_X86_4K_PAGE, PAGING_BITS, 1, f);
        let _ = page_map(
            f,
            allocator::HEAP_BASE as u64 + i * 0x1000,
            RW_NX,
            CAP_INIT_THREAD_VSPACE,
        );
    }
}

/// Build a spawned service's VSpace: image RO+X, private heap, private stack, and
/// the four shared SURT frames at the shared vaddrs.
unsafe fn build_service_vspace(sub: u64, comp: u64, req: u64, rep: u64) -> u64 {
    let img_start = IMAGE_FRAMES_START.load(Ordering::Relaxed);
    let img_count = IMAGE_FRAMES_COUNT.load(Ordering::Relaxed);
    let pml4 = alloc_slot();
    let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_X86_PML4, PAGING_BITS, 1, pml4);
    map_image_skeleton(pml4, img_count);
    map_heap_pt(pml4);
    for i in 0..img_count {
        let cp = alloc_slot();
        let _ = syscall5(
            SYS_SEND,
            CAP_INIT_THREAD_CNODE,
            LBL_CNODE_COPY << 12,
            cp,
            img_start + i,
            0,
        );
        let _ = page_map(cp, IMAGE_BASE + i * 0x1000, /* RO */ 2, pml4);
    }
    for i in 0..allocator::SERVICE_HEAP_FRAMES {
        let f = alloc_slot();
        let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_X86_4K_PAGE, PAGING_BITS, 1, f);
        let _ = page_map(f, allocator::HEAP_BASE as u64 + i * 0x1000, RW_NX, pml4);
    }
    for i in 0..STACK_FRAMES {
        let f = alloc_slot();
        let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_X86_4K_PAGE, PAGING_BITS, 1, f);
        let _ = page_map(f, STACK_BASE + i * 0x1000, RW_NX, pml4);
    }
    let _ = page_map(sub, SUB_RING_VADDR, RW_NX, pml4);
    let _ = page_map(comp, COMP_RING_VADDR, RW_NX, pml4);
    let _ = page_map(req, REQ_DATA_VADDR, RW_NX, pml4);
    let _ = page_map(rep, REP_DATA_VADDR, RW_NX, pml4);
    pml4
}

/// Spawn one isolated service component at `entry`, seeded with `seeds`.
unsafe fn spawn_service(
    entry: unsafe extern "C" fn() -> !,
    seeds: &[(u64, u64)],
    sub: u64,
    comp: u64,
    req: u64,
    rep: u64,
) {
    let pml4 = build_service_vspace(sub, comp, req, rep);
    let ipcbuf = alloc_slot();
    let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_X86_4K_PAGE, PAGING_BITS, 1, ipcbuf);
    let _ = page_map(ipcbuf, IPCBUF_VADDR, RW_NX, pml4);
    let raw = alloc_slot();
    let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_CNODE, CN_RADIX, 1, raw);
    let cnode = alloc_slot();
    let _ = syscall5(
        SYS_SEND,
        CAP_INIT_THREAD_CNODE,
        LBL_CNODE_MINT << 12,
        cnode,
        raw,
        CN_GUARD_BADGE,
    );
    let _ = syscall5(SYS_SEND, cnode, LBL_CNODE_COPY << 12, CT_PML4, pml4, 0);
    for &(slot, src) in seeds {
        let _ = syscall5(SYS_SEND, cnode, LBL_CNODE_COPY << 12, slot, src, 0);
    }
    let tcb = alloc_slot();
    let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_TCB, 0, 1, tcb);
    let _ = tcb_set_space(tcb, 0, cnode, pml4);
    let _ = syscall5(
        SYS_SEND,
        tcb,
        LBL_TCB_SET_IPC_BUFFER << 12,
        IPCBUF_VADDR,
        ipcbuf,
        0,
    );
    let stack_top = STACK_BASE + STACK_FRAMES * 0x1000 - 16;
    let _ = tcb_write_registers(tcb, entry as u64, stack_top, 0);
    let _ = tcb_set_priority(tcb, 100);
    if let Err(e_sc) = attach_sched_context(tcb) {
        print_str(b"[thread-life] service SC attach failed tcb=0x");
        print_hex(tcb as u32);
        print_str(b" error=");
        print_u64(e_sc);
        print_str(b"\n");
        park();
    }
    let _ = tcb_resume(tcb);
}

// --- The executive's front-end: an ObjectClient over the SURT ring to the
// isolated Object Manager service. -------------------------------------------

/// One request/reply SURT channel to an isolated service, parameterized by its data
/// frame vaddrs — so the executive can hold several (one per service).
struct RingChannel<'a> {
    sq: Producer<SurtSqe>,
    cq: Consumer<SurtCqe>,
    signal: Sel4Notify<'a, KernelEnv>,
    wait: Sel4Notify<'a, KernelEnv>,
    req_vaddr: u64,
    rep_vaddr: u64,
    next_id: u64,
}
impl RingChannel<'_> {
    /// One synchronous request/reply: stage `in_buf` in the request frame, push the
    /// SQE, wait for the matching completion, copy the reply payload out. Returns
    /// `(status, flags, information, detail0, detail1)`.
    fn raw(&mut self, opcode: u16, in_buf: &[u8], out_buf: &mut [u8]) -> (i32, u32, u64, u64, u64) {
        // SAFETY: single request in flight; the ring push/pop orders these writes.
        unsafe {
            let dst = self.req_vaddr as *mut u8;
            for (i, b) in in_buf.iter().enumerate() {
                core::ptr::write_volatile(dst.add(i), *b);
            }
        }
        let id = self.next_id;
        self.next_id += 1;
        let sqe = SurtSqe {
            opcode,
            len: in_buf.len() as u32,
            request_id: id,
            offset: 0,
            ..Default::default()
        };
        while self.sq.try_push(sqe).is_err() {
            yield_now();
        }
        let _ = self.sq.notify_consumer(&self.signal);
        let mut out = (0i32, 0u32, 0u64, 0u64, 0u64);
        let _ = drain_blocking(&mut self.cq, &self.wait, |cqe: &SurtCqe| {
            if cqe.request_id == id {
                out = (
                    cqe.status,
                    cqe.flags,
                    cqe.information,
                    cqe.detail0,
                    cqe.detail1,
                );
                false
            } else {
                true
            }
        });
        let n = (out.2 as usize).min(out_buf.len());
        // SAFETY: reply frame holds `n` result bytes.
        unsafe {
            let src = self.rep_vaddr as *const u8;
            for (i, slot) in out_buf.iter_mut().enumerate().take(n) {
                *slot = core::ptr::read_volatile(src.add(i));
            }
        }
        out
    }
}

/// The Object Manager transport wrapper.
struct ObChan<'a>(RingChannel<'a>);
impl nt_object_client::Backend for ObChan<'_> {
    fn call(&mut self, opcode: u16, in_buf: &[u8], out_buf: &mut [u8]) -> ObReply {
        let (status, _flags, information, detail0, detail1) = self.0.raw(opcode, in_buf, out_buf);
        ObReply {
            status,
            information: information as u32,
            detail0,
            detail1,
        }
    }
}

