/// The executive's client to the isolated `lpc-server` component. Set once in
/// `_start` after `stand_up_service`; the LPC syscall handlers reach it via
/// [`lpc_client`] (single-threaded executive → the `static mut` is race-free).
static mut LPC_CLIENT: Option<LpcClient<LpcChan<'static>>> = None;

/// Borrow the LPC client (None until the service is stood up).
///
/// # Safety
/// Single-threaded executive; no aliasing across the one service loop.
unsafe fn lpc_client() -> Option<&'static mut LpcClient<LpcChan<'static>>> {
    (*core::ptr::addr_of_mut!(LPC_CLIENT)).as_mut()
}

// --- Native syscall trap front-end -----------------------------------------
// The executive catches a user thread's `syscall` (delivered as a seL4
// UnknownSyscall fault), routes it to the owning isolated service over SURT, and
// replies register-accurately so the user resumes past the syscall. (Trap/reply
// mechanics ported from driver-host-ntdll, which services real ntdll.)

unsafe fn ep_recv_full(ep: u64) -> (u64, u64, u64, u64, u64, u64) {
    let badge: u64;
    let msginfo: u64;
    let mr0: u64;
    let mr1: u64;
    let mr2: u64;
    let mr3: u64;
    core::arch::asm!(
        "syscall",
        in("rdx") SYS_RECV as u64,
        inout("rdi") ep => badge,
        lateout("rsi") msginfo,
        lateout("r10") mr0,
        lateout("r8") mr1,
        lateout("r9") mr2,
        lateout("r15") mr3,
        lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    (badge, msginfo, mr0, mr1, mr2, mr3)
}

/// Reply to the pending fault (resume the faulter with the staged registers) + recv
/// the next fault. `r0..r3` → reply MRs 0..3 (RAX,RBX,RCX,RDX); MRs 4+ from `set_reply_mr`.
unsafe fn reply_recv_full(
    recv_ep: u64,
    reply_len: u64,
    r0: u64,
    r1: u64,
    r2: u64,
    r3: u64,
) -> (u64, u64, u64, u64, u64) {
    let msginfo: u64;
    let mr0: u64;
    let mr1: u64;
    let mr2: u64;
    let mr3: u64;
    core::arch::asm!(
        "syscall",
        in("rdx") SYS_REPLY_RECV as u64,
        inout("rdi") recv_ep => _,
        inout("rsi") reply_len => msginfo,
        inout("r10") r0 => mr0,
        inout("r8") r1 => mr1,
        inout("r9") r2 => mr2,
        inout("r15") r3 => mr3,
        lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    (msginfo, mr0, mr1, mr2, mr3)
}

/// Resume the current caller and receive the next event, ALWAYS through the caller's **bound MCS
/// reply object** (`REPLY_MAIN`) — never through the legacy per-TCB `reply_to`. Also returns the
/// RECEIVED cap's badge (rdi on return): the service loop mints each hosted thread's fault-endpoint
/// cap with a distinct badge (smss=0, csrss=CSRSS_BADGE) so it can tell whose fault/syscall this is
/// and select that process's VSpace/image/scratch state.
///
/// ★ PHASE 3 (`docs/transport-migration.md` §7 item "the legacy `reply_to` reply"). This used to be
/// ONE `SYS_REPLY_RECV`, whose reply half targets `current.reply_to` (`syscall_handler.rs` →
/// `handle_reply`). That single per-TCB slot is written on the RECEIVER by every incoming `Call`, so
/// any component `Call` serviced while this client's syscall was in flight (an IRP/win32k dispatch
/// completion or one of its demand-page faults) silently re-pointed it at the COMPONENT — the
/// clobber that hung the first Phase-1 boot and that `COMPONENT_CALL_CLOBBERED_REPLY_TO` existed to
/// dodge. It is now two syscalls: `reply_on` on the object the kernel BOUND to this caller
/// (`decode_reply` → `replies[idx].bound_tcb`, which nothing else can re-point), then
/// `recv_full_r12` re-registering the same object for the next caller. Equivalent because the
/// executive is the sole replier, and correct by construction rather than by guard.
unsafe fn reply_recv_badge(
    recv_ep: u64,
    reply_len: u64,
    r0: u64,
    r1: u64,
    r2: u64,
    r3: u64,
) -> (u64, u64, u64, u64, u64, u64) {
    let reply_cptr = REPLY_MAIN_SLOT.load(Ordering::Relaxed);
    if reply_cptr == 0 {
        // Pre-retype (the demo/no-ntdll path reaches the loop before the reply objects exist):
        // fall back to the legacy `reply_to` reply. No component can have run yet, so `reply_to`
        // still names this caller.
        let badge: u64;
        let msginfo: u64;
        let mr0: u64;
        let mr1: u64;
        let mr2: u64;
        let mr3: u64;
        core::arch::asm!(
            "syscall",
            in("rdx") SYS_REPLY_RECV as u64,
            inout("rdi") recv_ep => badge,
            inout("rsi") reply_len => msginfo,
            inout("r10") r0 => mr0,
            inout("r8") r1 => mr1,
            inout("r9") r2 => mr2,
            inout("r15") r3 => mr3,
            lateout("rax") _, lateout("rcx") _, lateout("r11") _,
            options(nostack),
        );
        return (badge, msginfo, mr0, mr1, mr2, mr3);
    }
    client_reply_on(reply_cptr, reply_len, r0, r1, r2, r3);
    recv_full_r12(recv_ep, reply_cptr)
}

/// `seL4_Recv(ep)` that ALSO registers a reply capability via the MCS `replyRegister` (r12): the
/// kernel binds `reply_cptr`'s Reply object to whichever thread's Call pairs with this recv
/// (finish_call -> replies[idx].bound_tcb = caller). A later Send on `reply_cptr` (decode_reply)
/// then resumes exactly that caller regardless of the single per-TCB `reply_to` slot — so a nested
/// faulting dispatch can't orphan an outer caller's pending reply. The kernel preserves the user's
/// r12 across the syscall (it reads it, never writes it), so `in` is sufficient.
unsafe fn recv_full_r12(ep: u64, reply_cptr: u64) -> (u64, u64, u64, u64, u64, u64) {
    let badge: u64;
    let msginfo: u64;
    let mr0: u64;
    let mr1: u64;
    let mr2: u64;
    let mr3: u64;
    core::arch::asm!(
        "syscall",
        in("rdx") SYS_RECV as u64,
        inout("rdi") ep => badge,
        lateout("rsi") msginfo,
        lateout("r10") mr0,
        lateout("r8") mr1,
        lateout("r9") mr2,
        lateout("r15") mr3,
        in("r12") reply_cptr,
        lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    // ★ THE DEADMAN LIVES HERE, not at the service-loop top — this is the ONE place the executive
    // ever blocks, so a check here covers the nested component-pump receives a dispatch makes as
    // well as the loop's own. Cost on the hot path is one relaxed increment.
    if EXEC_DEADMAN_WATCHDOG {
        if badge == DELAY_TIMER_BADGE {
            watchdog_on_tick();
        } else {
            WATCHDOG_MSGS.fetch_add(1, Ordering::Relaxed);
        }
    }
    (badge, msginfo, mr0, mr1, mr2, mr3)
}

/// ★ THE reply primitive: resume a `Cap::Reply` object's BOUND caller (kernel `decode_reply`),
/// applying `apply_fault_reply` when that caller is blocked on a fault (the win32k/csrss demand-page
/// and syscall replies are all fault replies) and a full message transfer otherwise. MR0..3 ride in
/// r10/r8/r9/r15; MR4+ come from the IPC buffer (`set_reply_mr`).
///
/// It NEVER blocks: `decode_reply` either wakes `replies[idx].bound_tcb` or fails immediately. That
/// non-blocking property is the whole point of the migration — it is what replaced the executive's
/// blocking wake `Send` (`docs/transport-migration.md` defect 3).
///
/// Issued as **`SYS_CALL`**, not `SYS_SEND`, so the kernel's non-endpoint invocation arm
/// (`syscall_handler.rs` `handle_send`'s `other =>` → `decode_invocation` →
/// `invocation.rs::decode_reply`) writes the invocation's error label into `rsi` and this function
/// can RETURN it. `tasks/lessons.md`: *"seL4 SYS_SEND invocations HIDE ALL errors — use SYS_CALL
/// when a failure would be silent."* Replying to an UNBOUND reply object is exactly such a failure:
/// it means we believed a thread was blocked awaiting this reply when it was not, i.e. an invariant
/// break. This form returns `seL4_InvalidCapability` (**2**, `rust-micro/src/types.rs`) for it
/// instead of vanishing. `SYS_SEND`'s error-swallowing predecessor (`send_on_reply`) is DELETED —
/// kill-list item 3, the last of the 34.
///
/// Two wrappers add the bookkeeping their plane needs: [`client_reply_on`] (hosted clients) and
/// `spawn_hosts::pump_reply_on` (components). Nothing else calls this directly except the
/// deliberately-unbound negative-control probe in the gate.
unsafe fn reply_on(reply_cptr: u64, msginfo: u64, r0: u64, r1: u64, r2: u64, r3: u64) -> u64 {
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") reply_cptr => _,
        inout("rsi") msginfo => reply,
        inout("r10") r0 => _,
        inout("r8") r1 => _,
        inout("r9") r2 => _,
        inout("r15") r3 => _,
        lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    reply >> 12
}

/// ★ Non-zero `reply_on` labels on the **client** plane (`REPLY_MAIN` + the stolen/parked reply
/// objects), the counterpart of `spawn_hosts::PUMP_REPLY_ERRORS` for the component plane. A non-zero
/// label means we replied to an UNBOUND object — we believed a hosted thread was blocked awaiting
/// this reply and it was not. Reported by `exec_client_reply_bound`.
pub(crate) static CLIENT_REPLY_ERRORS: AtomicU64 = AtomicU64::new(0);
/// Client-plane replies issued through a bound reply object (`decode_reply`). Post-Phase-3 this is
/// EVERY reply the service loop makes: the legacy `reply_to` reply is retired.
pub(crate) static CLIENT_REPLY_BOUND: AtomicU64 = AtomicU64::new(0);

/// ★ THE ONE client-plane reply primitive (`docs/transport-migration.md` §7 item 3). Replaces the
/// error-SWALLOWING `send_on_reply` (a `SYS_SEND`, whose invocation errors vanish) with the
/// error-RETURNING [`reply_on`], counting any non-zero label into [`CLIENT_REPLY_ERRORS`] and
/// logging the first few. Identical register layout and identical kernel path
/// (`decode_invocation` → `decode_reply`); only the syscall number and the error visibility differ.
/// Every call site replies with message LABEL 0 (`msginfo` carries a length only) — a non-zero label
/// would be parsed as an `InvocationLabel` by `decode_invocation` and rejected before reaching
/// `decode_reply` (migration correction 1).
unsafe fn client_reply_on(reply_cptr: u64, msginfo: u64, r0: u64, r1: u64, r2: u64, r3: u64) {
    let label = reply_on(reply_cptr, msginfo, r0, r1, r2, r3);
    CLIENT_REPLY_BOUND.fetch_add(1, Ordering::Relaxed);
    if label != 0 && CLIENT_REPLY_ERRORS.fetch_add(1, Ordering::Relaxed) < 8 {
        print_str(b"[client-reply] UNBOUND reply object cptr=");
        print_u64(reply_cptr);
        print_str(b" label=");
        print_u64(label);
        print_str(b" mi=");
        print_u64(msginfo);
        print_str(b"\n");
    }
}

fn monotonic_time_100ns() -> u64 {
    let period = HPET_PERIOD_FS.load(Ordering::Relaxed);
    if period != 0 {
        let ticks =
            unsafe { core::ptr::read_volatile((HPET_VADDR + HPET_MAIN_COUNTER) as *const u64) };
        nt_delay_execution::ticks_to_100ns(ticks, period)
    } else {
        unsafe { core::arch::x86_64::_rdtsc() / 10 }
    }
}

fn nt_system_time_100ns() -> u64 {
    NT_SYSTEM_TIME_BOOT_100NS.saturating_add(monotonic_time_100ns())
}

unsafe fn publish_kuser_clocks() {
    let interrupt_time = monotonic_time_100ns();
    let system_time = NT_SYSTEM_TIME_BOOT_100NS.saturating_add(interrupt_time);
    for pi in 0..MAX_PI {
        let alias = kuser_page_alias_get(pi);
        if alias != 0 {
            nt_ntdll_layout::kuser::publish_clocks(alias as *mut u8, interrupt_time, system_time);
        }
    }
    KUSER_CLOCK_PUBLISH_COUNT.fetch_add(1, Ordering::Relaxed);
}

fn print_hex_u64(value: u64) {
    print_hex((value >> 32) as u32);
    print_hex(value as u32);
}

fn wait_reply_pool_bit(index: usize) -> Option<(usize, u64)> {
    if index >= WAIT_REPLY_POOL_N {
        return None;
    }
    Some((index / 64, 1u64 << (index % 64)))
}

fn wait_reply_pool_index_used(index: usize) -> bool {
    let Some((word, bit)) = wait_reply_pool_bit(index) else {
        return false;
    };
    WAIT_REPLY_POOL_USED[word].load(Ordering::Relaxed) & bit != 0
}

fn wait_reply_pool_mark_used(index: usize) {
    if let Some((word, bit)) = wait_reply_pool_bit(index) {
        WAIT_REPLY_POOL_USED[word].fetch_or(bit, Ordering::Relaxed);
    }
}

fn wait_reply_pool_mark_free(index: usize) {
    if let Some((word, bit)) = wait_reply_pool_bit(index) {
        WAIT_REPLY_POOL_USED[word].fetch_and(!bit, Ordering::Relaxed);
    }
}

fn wait_reply_pool_reset_used() {
    for word in 0..WAIT_REPLY_POOL_USED_WORDS {
        WAIT_REPLY_POOL_USED[word].store(0, Ordering::Relaxed);
    }
}

fn wait_reply_pool_find_free() -> Option<(usize, u64)> {
    (0..WAIT_REPLY_POOL_N).find_map(|index| {
        let cap = WAIT_REPLY_POOL[index].load(Ordering::Relaxed);
        (!wait_reply_pool_index_used(index) && cap != 0).then_some((index, cap))
    })
}

fn wait_reply_pool_has_free() -> bool {
    wait_reply_pool_find_free().is_some()
}

fn wait_reply_pool_used_count() -> u64 {
    (0..WAIT_REPLY_POOL_USED_WORDS)
        .map(|word| WAIT_REPLY_POOL_USED[word].load(Ordering::Relaxed).count_ones() as u64)
        .sum()
}

fn wait_reply_pool_live_count() -> u64 {
    (0..WAIT_REPLY_POOL_N)
        .filter(|index| WAIT_REPLY_POOL[*index].load(Ordering::Relaxed) != 0)
        .count() as u64
}

fn release_reply_pool_cap(cap: u64) {
    for index in 0..WAIT_REPLY_POOL_N {
        if WAIT_REPLY_POOL[index].load(Ordering::Relaxed) == cap {
            wait_reply_pool_mark_free(index);
            break;
        }
    }
}

/// ★ NEGATIVE CONTROL for `spawn_hosts::pump_recv`'s bound-notification screening (Phase 4).
///
/// Reproduce, deterministically and without touching the HPET, the delivery that WALLED npfs on the
/// first LSA-route boot: a notification BOUND to the executive's root TCB cancelling a
/// `component_pump` recv. The kernel's bound-notification pre-check
/// (`syscall_handler.rs::handle_recv`) returns `rdi = badge`, `rsi = 0` and leaves the message
/// registers untouched, so an unscreened pump reads `label = 0` with MR0 still holding the request
/// tag it just replied with — and suspends + retires the component.
///
/// Mint a notification badged **`DELAY_TIMER_BADGE`** (the pump screens on exactly that badge, so
/// this exercises the production path, not a test-only one), bind it to the root TCB, signal it, and
/// return. The caller then runs a REAL component dispatch, whose first `pump_recv` takes the
/// delivery. We unbind immediately: the notification is now Active-and-consumed by that recv, and
/// leaving a stray binding would let it interact with `delay_timer_init`'s own later bind.
///
/// Deliberately does NOT use the HPET: no comparator is armed, no IOAPIC route is claimed and no IRQ
/// is left needing an Ack, so the injection cannot perturb the real delay-timer plane (which the
/// LSA route DOES now initialise — this injection stays independent of it by construction).
unsafe fn inject_bound_notification_tick() -> bool {
    let notification = make_object(OBJ_NOTIFICATION);
    if notification == 0 {
        return false;
    }
    let badged = alloc_slot();
    if badged == 0 {
        return false;
    }
    let mint = syscall5(
        SYS_SEND,
        CAP_INIT_THREAD_CNODE,
        LBL_CNODE_MINT << 12,
        badged,
        notification,
        DELAY_TIMER_BADGE,
    );
    // The initial root TCB cap is slot 1 (same constant `delay_timer_init` uses).
    let bind = syscall5(
        SYS_SEND,
        1,
        LBL_TCB_BIND_NOTIFICATION << 12,
        notification,
        0,
        0,
    );
    // Send on a Notification cap IS `signal()` (`syscall_handler.rs::handle_send`), so the object
    // becomes Active with our badge and the next blocking Recv on ANY endpoint returns it.
    let signal = syscall5(SYS_SEND, badged, 0, 0, 0, 0);
    let _ = (mint, bind, signal);
    true
}

/// Undo [`inject_bound_notification_tick`]'s binding once the dispatch under test has consumed the
/// delivery, so nothing else on the boot can be interrupted by it.
unsafe fn retract_bound_notification_tick() {
    let _ = syscall5(SYS_SEND, 1, LBL_TCB_UNBIND_NOTIFICATION << 12, 0, 0, 0);
}

unsafe fn delay_timer_init() -> bool {
    if DELAY_TIMER_HANDLER.load(Ordering::Relaxed) != 0 {
        return true;
    }
    let period = HPET_PERIOD_FS.load(Ordering::Relaxed);
    if period == 0 {
        print_str(b"[delay] HPET unavailable; refusing nonzero immediate-success fallback\n");
        return false;
    }
    let route_cap =
        (core::ptr::read_volatile((HPET_VADDR + HPET_T0_CONFIG) as *const u64) >> 32) as u32;
    if route_cap == 0 {
        return false;
    }
    let already_used = 31 - route_cap.leading_zeros();
    let remaining = route_cap & !(1u32 << already_used);
    if remaining == 0 {
        print_str(b"[delay] HPET timer0 has no spare IOAPIC route\n");
        return false;
    }
    let pin = (31 - remaining.leading_zeros()) as u64;
    let notification = make_object(OBJ_NOTIFICATION);
    let badged = alloc_slot();
    let _ = syscall5(
        SYS_SEND,
        CAP_INIT_THREAD_CNODE,
        LBL_CNODE_MINT << 12,
        badged,
        notification,
        DELAY_TIMER_BADGE,
    );
    let handler = alloc_slot();
    ioapic_issue_irq_handler(handler, pin, DELAY_TIMER_IRQ, 1, 0);
    let _ = irq_handler_set_notification(handler, badged);
    // The initial root TCB cap is slot 1. Binding lets an HPET signal cancel the executive's
    // blocking Recv on the hosted-process endpoint, returning DELAY_TIMER_BADGE with empty msginfo.
    let _ = syscall5(
        SYS_SEND,
        1,
        LBL_TCB_BIND_NOTIFICATION << 12,
        notification,
        0,
        0,
    );
    core::ptr::write_volatile((HPET_VADDR + HPET_GEN_INT_STATUS) as *mut u64, 1);
    // LEVEL-triggered (matching the IOAPIC pin we just issued) and DISARMED: the timer delivers
    // only while `delay_timer_rearm` has a real deadline to arm it with. Init used to set
    // `Tn_INT_ENB` here and never clear it again, which is what made the disarm path a no-op.
    let config = HPET_TN_INT_TYPE_LEVEL | (pin << 9);
    core::ptr::write_volatile((HPET_VADDR + HPET_T0_CONFIG) as *mut u64, config);
    let general = core::ptr::read_volatile((HPET_VADDR + HPET_GEN_CONF) as *const u64);
    core::ptr::write_volatile((HPET_VADDR + HPET_GEN_CONF) as *mut u64, general | 1);
    DELAY_TIMER_HANDLER.store(handler, Ordering::Relaxed);
    print_str(b"[delay] timer ready pin=");
    print_u64(pin);
    print_str(b" irq=");
    print_u64(DELAY_TIMER_IRQ);
    print_str(b" period_fs=");
    print_u64(period);
    print_str(b" bound_badge=0x");
    print_hex_u64(DELAY_TIMER_BADGE);
    print_str(b"\n");
    true
}

unsafe fn delay_timer_rearm(queue: &nt_delay_execution::Queue<DELAY_WAITER_N>) {
    let handler = DELAY_TIMER_HANDLER.load(Ordering::Relaxed);
    if handler == 0 {
        return;
    }
    let mut config = core::ptr::read_volatile((HPET_VADDR + HPET_T0_CONFIG) as *const u64);
    let event_deadline = (0..WAITER_N)
        .filter(|slot| WAITER_EVENT_IDX[*slot].load(Ordering::Relaxed) != u64::MAX)
        .map(|slot| WAITER_DEADLINE[slot].load(Ordering::Relaxed))
        .filter(|deadline| *deadline != u64::MAX)
        .min();
    let keyed_deadline = (0..KEYED_WAITER_N)
        .filter(|slot| KEYED_WAITER_KEY[*slot].load(Ordering::Relaxed) != u64::MAX)
        .map(|slot| KEYED_WAITER_DEADLINE[slot].load(Ordering::Relaxed))
        .filter(|deadline| *deadline != u64::MAX)
        .min();
    let io_completion_deadline =
        unsafe { (&*core::ptr::addr_of!(IO_COMPLETION_WAITERS)).next_deadline() };
    let pipe_name_deadline = unsafe { (&*core::ptr::addr_of!(PIPE_NAME_WAITERS)).next_deadline() };
    // The deadman joins the same `min()` as every real waiter — it is a deadline like any other, so
    // the arm/disarm path (and `exec_delay_timer_disarms`' invariants) are untouched by it.
    let deadman_deadline = watchdog_deadline();
    let deadline = queue
        .next_deadline()
        .into_iter()
        .chain(event_deadline)
        .chain(keyed_deadline)
        .chain(io_completion_deadline)
        .chain(pipe_name_deadline)
        .chain(deadman_deadline)
        .min();
    if let Some(deadline) = deadline {
        let period = HPET_PERIOD_FS.load(Ordering::Relaxed);
        let target = nt_delay_execution::hundred_ns_to_ticks_ceil(deadline, period);
        let now = core::ptr::read_volatile((HPET_VADDR + HPET_MAIN_COUNTER) as *const u64);
        // DIAGNOSTIC: a deadline that is ALREADY PAST is clamped to `now + 1`, so the comparator
        // re-fires immediately. If the waiter holding it is not popped by any `*_wake_due`, that
        // is a self-sustaining interrupt storm, not a timer. Attribute the source.
        let source = if queue.next_deadline() == Some(deadline) {
            1
        } else if event_deadline == Some(deadline) {
            2
        } else if keyed_deadline == Some(deadline) {
            3
        } else if io_completion_deadline == Some(deadline) {
            4
        } else if pipe_name_deadline == Some(deadline) {
            6
        } else {
            5 // the deadman
        };
        if target <= now {
            TIMER_PAST_DEADLINE_REARMS.fetch_add(1, Ordering::Relaxed);
            TIMER_PAST_DEADLINE_SOURCE.store(source, Ordering::Relaxed);
        }
        LAST_REARM_DEADLINE.store(deadline, Ordering::Relaxed);
        LAST_REARM_SOURCE.store(source, Ordering::Relaxed);
        LAST_REARM_TARGET.store(target, Ordering::Relaxed);
        LAST_REARM_NOW.store(now, Ordering::Relaxed);
        LAST_REARM_ARMED.store(1, Ordering::Relaxed);
        core::ptr::write_volatile(
            (HPET_VADDR + HPET_T0_COMPARATOR) as *mut u64,
            target.max(now.saturating_add(1)),
        );
        // ARM. The comparator is written FIRST so the enable edge arms against the new deadline.
        config |= HPET_TN_INT_ENB;
    } else {
        // DISARM — nothing is waiting on time, so the timer must stop delivering entirely.
        // This used to clear `Tn_INT_TYPE_CNF` (bit 1) instead, leaving `Tn_INT_ENB` set with a
        // comparator now permanently BEHIND the main counter. The result was a self-sustaining
        // ~34 kHz interrupt storm: measured 2,745,189 spurious deliveries in one boot (99.9999% of
        // all ticks woke nothing), 80 s of the executive's single-threaded service loop, which
        // starved winlogon of the forward progress the desktop paint needs. See
        // `exec_delay_timer_disarms` and `docs/transport-migration.md` §5.
        LAST_REARM_ARMED.store(0, Ordering::Relaxed);
        config &= !HPET_TN_INT_ENB;
    }
    core::ptr::write_volatile((HPET_VADDR + HPET_T0_CONFIG) as *mut u64, config);
}

unsafe fn delay_park(
    queue: &mut nt_delay_execution::Queue<DELAY_WAITER_N>,
    deadline_100ns: u64,
    reply_cap: u64,
    resume_ip: u64,
    sp: u64,
    flags: u64,
    thread_id: u64,
    badge: u64,
) -> bool {
    if reply_cap == 0 || !delay_timer_init() {
        return false;
    }
    let Some((fresh_index, fresh)) = wait_reply_pool_find_free() else {
        return false;
    };
    let waiter = nt_delay_execution::Waiter {
        deadline_100ns,
        sequence: 0,
        reply_cap,
        resume_ip,
        resume_sp: sp,
        resume_flags: flags,
        thread_id,
        badge,
    };
    if queue.insert(waiter).is_err() {
        return false;
    }
    wait_reply_pool_mark_used(fresh_index);
    REPLY_MAIN_SLOT.store(fresh, Ordering::Relaxed);
    DELAY_PARKED_COUNT.fetch_add(1, Ordering::Relaxed);
    delay_timer_rearm(queue);
    true
}

unsafe fn delay_wake_due(queue: &mut nt_delay_execution::Queue<DELAY_WAITER_N>) -> u64 {
    let now = monotonic_time_100ns();
    let mut woken = 0;
    while let Some(waiter) = queue.pop_due(now) {
        set_reply_mr(15, waiter.resume_ip);
        set_reply_mr(16, waiter.resume_sp);
        set_reply_mr(17, waiter.resume_flags);
        client_reply_on(waiter.reply_cap, 18, 0, 0, 0, 0);
        release_reply_pool_cap(waiter.reply_cap);
        woken += 1;
        let wake_number = DELAY_WOKEN_COUNT.fetch_add(1, Ordering::Relaxed);
        if wake_number < 16 {
            print_str(b"[delay] WAKE #");
            print_u64(wake_number + 1);
            print_str(b" tid=");
            print_u64(waiter.thread_id);
            print_str(b" badge=");
            print_u64(waiter.badge);
            print_str(b" deadline_100ns=");
            print_u64(waiter.deadline_100ns);
            print_str(b" now_100ns=");
            print_u64(now);
            print_str(b" status=STATUS_SUCCESS\n");
        }
    }
    delay_timer_rearm(queue);
    woken
}

unsafe fn io_completion_wake_due(handler: &mut ExecNtHandler) -> u64 {
    let now = monotonic_time_100ns();
    let mut woken = 0;
    while let Some(waiter) =
        unsafe { (&mut *core::ptr::addr_of_mut!(IO_COMPLETION_WAITERS)).pop_due(now) }
    {
        set_reply_mr(15, waiter.resume_ip);
        set_reply_mr(16, waiter.resume_sp);
        set_reply_mr(17, waiter.resume_flags);
        client_reply_on(
            waiter.reply_cap,
            18,
            nt_io_completion::STATUS_TIMEOUT as u64,
            0,
            0,
            0,
        );
        release_reply_pool_cap(waiter.reply_cap);
        thread_wait_state_clear_badge(waiter.badge);
        let _ = handler.io_completion_ports.release(waiter.port_id);
        IO_COMPLETION_TIMEOUT_COUNT.fetch_add(1, Ordering::Relaxed);
        woken += 1;
    }
    woken
}

unsafe fn pipe_name_wait_wake_due(handler: &mut ExecNtHandler) -> u64 {
    let now = monotonic_time_100ns();
    let mut woken = 0;
    while let Some(waiter) =
        unsafe { (&mut *core::ptr::addr_of_mut!(PIPE_NAME_WAITERS)).pop_due(now) }
    {
        pipe_name_wait_complete_one(handler, waiter, STATUS_IO_TIMEOUT);
        PIPE_NAME_WAIT_TIMEOUT_COUNT.fetch_add(1, Ordering::Relaxed);
        woken += 1;
        if PIPE_NAME_WAIT_TRACE_COUNT.fetch_add(1, Ordering::Relaxed) < 16 {
            print_str(b"[pipe-name-wait] TIMEOUT name_hash=0x");
            print_hex_u64(waiter.name_hash);
            print_str(b" pi=");
            print_u64(waiter.pi as u64);
            print_str(b" badge=");
            print_u64(waiter.badge);
            print_str(b"\n");
        }
    }
    woken
}

fn thread_wait_state_reset() {
    unsafe {
        (&mut *core::ptr::addr_of_mut!(THREAD_WAIT_PARKED)).reset();
    }
}

fn thread_wait_state_park_badge(badge: u64) {
    unsafe {
        (&mut *core::ptr::addr_of_mut!(THREAD_WAIT_PARKED)).park(badge);
    }
}

fn thread_wait_state_clear_badge(badge: u64) {
    unsafe {
        (&mut *core::ptr::addr_of_mut!(THREAD_WAIT_PARKED)).clear(badge);
    }
}

fn thread_wait_state_clear_tid(handler: &ExecNtHandler, tid: u64) {
    if let Some(badge) = handler.hosted_thread_badge_for_tid(tid) {
        thread_wait_state_clear_badge(badge);
    }
}

fn thread_wait_state_badge_parked(badge: u64) -> bool {
    unsafe { (&*core::ptr::addr_of!(THREAD_WAIT_PARKED)).contains(badge) }
}

unsafe fn delay_timer_interrupt(
    queue: &mut nt_delay_execution::Queue<DELAY_WAITER_N>,
    handler: &mut ExecNtHandler,
) {
    core::ptr::write_volatile((HPET_VADDR + HPET_GEN_INT_STATUS) as *mut u64, 1);
    // A delivery the DEADMAN's own deadline produced did real work (it ran the deadlock check), so
    // it must not be counted as a spurious wake — `exec_delay_timer_disarms`' `spurious <= 64`
    // clause has to keep meaning "this timer woke nothing", or it stops detecting a storm.
    let watchdog_tick = WATCHDOG_TICK_IS_OURS.swap(0, Ordering::Relaxed);
    let woken = delay_wake_due(queue)
        + wait_wake_due(handler)
        + keyed_wait_wake_due(handler)
        + io_completion_wake_due(handler)
        + pipe_name_wait_wake_due(handler)
        + watchdog_tick;
    TIMER_TICKS_SEEN.fetch_add(1, Ordering::Relaxed);
    if woken == 0 {
        let n = TIMER_TICKS_SPURIOUS.fetch_add(1, Ordering::Relaxed);
        if n < 10 || n % 400_000 == 0 {
            let counter = core::ptr::read_volatile((HPET_VADDR + HPET_MAIN_COUNTER) as *const u64);
            let cmp = core::ptr::read_volatile((HPET_VADDR + HPET_T0_COMPARATOR) as *const u64);
            let cfg = core::ptr::read_volatile((HPET_VADDR + HPET_T0_CONFIG) as *const u64);
            print_str(b"[timer-storm] spurious #");
            print_u64(n);
            print_str(b" counter=0x");
            print_hex_u64(counter);
            print_str(b" cmp=0x");
            print_hex_u64(cmp);
            print_str(b" cfg=0x");
            print_hex_u64(cfg);
            print_str(b" armed=");
            print_u64(LAST_REARM_ARMED.load(Ordering::Relaxed));
            print_str(b" src=");
            print_u64(LAST_REARM_SOURCE.load(Ordering::Relaxed));
            print_str(b" deadline=");
            print_u64(LAST_REARM_DEADLINE.load(Ordering::Relaxed));
            print_str(b" now100=");
            print_u64(monotonic_time_100ns());
            print_str(b" delayq=");
            print_u64(queue.len() as u64);
            print_str(b"\n");
        }
    }
    delay_timer_rearm(queue);
    // Timer 0 is level-triggered. Disable/rearm the comparator and clear the status before Ack
    // unmasks the IOAPIC line; acknowledging first lets the still-asserted line immediately storm.
    core::ptr::write_volatile((HPET_VADDR + HPET_GEN_INT_STATUS) as *mut u64, 1);
    let handler = DELAY_TIMER_HANDLER.load(Ordering::Relaxed);
    if handler != 0 {
        let _ = syscall5(SYS_SEND, handler, LBL_IRQ_ACK << 12, 0, 0, 0);
    }
}

unsafe fn delay_timer_shutdown(queue: &nt_delay_execution::Queue<DELAY_WAITER_N>) {
    let completion_deadline =
        unsafe { (&*core::ptr::addr_of!(IO_COMPLETION_WAITERS)).next_deadline() };
    let pipe_name_deadline = unsafe { (&*core::ptr::addr_of!(PIPE_NAME_WAITERS)).next_deadline() };
    if DELAY_TIMER_HANDLER.load(Ordering::Relaxed) == 0
        || queue.len() != 0
        || completion_deadline.is_some()
        || pipe_name_deadline.is_some()
    {
        return;
    }
    let mut config = core::ptr::read_volatile((HPET_VADDR + HPET_T0_CONFIG) as *const u64);
    // Same correction as `delay_timer_rearm`'s disarm: clear the ENABLE bit, not the trigger-type.
    config &= !HPET_TN_INT_ENB;
    core::ptr::write_volatile((HPET_VADDR + HPET_T0_CONFIG) as *mut u64, config);
    core::ptr::write_volatile((HPET_VADDR + HPET_GEN_INT_STATUS) as *mut u64, 1);
    let _ = syscall5(SYS_SEND, 1, LBL_TCB_UNBIND_NOTIFICATION << 12, 0, 0, 0);
}

unsafe fn delay_cancel_thread(
    queue: &mut nt_delay_execution::Queue<DELAY_WAITER_N>,
    thread_id: u64,
) {
    while let Some(waiter) = queue.pop_thread(thread_id) {
        let cap = waiter.reply_cap;
        let deleted = cnode_delete_r(cap);
        let retyped = if deleted == 0 {
            untyped_retype_r(CAP_INIT_UNTYPED, OBJ_REPLY, 0, 1, cap)
        } else {
            u64::MAX
        };
        if deleted == 0 && retyped == 0 {
            release_reply_pool_cap(cap);
        }
        print_str(b"[delay] CANCEL tid=");
        print_u64(thread_id);
        print_str(b" reply=0x");
        print_hex_u64(cap);
        print_str(b" delete=");
        print_u64(deleted);
        print_str(b" retype=");
        print_u64(retyped);
        print_str(b"\n");
    }
    delay_timer_rearm(queue);
}

unsafe fn io_completion_cancel_thread(handler: &mut ExecNtHandler, thread_id: u64) {
    while let Some(waiter) =
        unsafe { (&mut *core::ptr::addr_of_mut!(IO_COMPLETION_WAITERS)).pop_thread(thread_id) }
    {
        let cap = waiter.reply_cap;
        let deleted = cnode_delete_r(cap);
        let retyped = if deleted == 0 {
            untyped_retype_r(CAP_INIT_UNTYPED, OBJ_REPLY, 0, 1, cap)
        } else {
            u64::MAX
        };
        if deleted == 0 && retyped == 0 {
            release_reply_pool_cap(cap);
        }
        thread_wait_state_clear_badge(waiter.badge);
        let _ = handler.io_completion_ports.release(waiter.port_id);
    }
}

unsafe fn io_completion_cancel_process(handler: &mut ExecNtHandler, process_index: u8) {
    while let Some(waiter) =
        unsafe { (&mut *core::ptr::addr_of_mut!(IO_COMPLETION_WAITERS)).pop_process(process_index) }
    {
        let cap = waiter.reply_cap;
        let deleted = cnode_delete_r(cap);
        let retyped = if deleted == 0 {
            untyped_retype_r(CAP_INIT_UNTYPED, OBJ_REPLY, 0, 1, cap)
        } else {
            u64::MAX
        };
        if deleted == 0 && retyped == 0 {
            release_reply_pool_cap(cap);
        }
        thread_wait_state_clear_badge(waiter.badge);
        let _ = handler.io_completion_ports.release(waiter.port_id);
    }
}

/// ═══ Checkpoint B park/wake helpers (real reply-cap parking) ═══
/// PARK the current caller on `object`: the reply object CURRENTLY installed in REPLY_MAIN_SLOT is
/// bound (by the last recv-with-r12) to THIS caller's blocked Call, so we STEAL it into a free waiter
/// slot and rotate a fresh POOL reply object into REPLY_MAIN_SLOT so the loop's next recv binds a
/// NEW object (never rebinding/orphaning the parked one). The caller stays blocked in-kernel until a
/// matching state transition sends on the stolen cap. Returns true on success; false if the
/// pool/waiter queue is exhausted.
unsafe fn wait_park(
    object: WaitObject,
    resume_ip: u64,
    sp: u64,
    flags: u64,
    tid: u64,
    deadline: Option<u64>,
) -> bool {
    // Single-object wait = a 1-object WaitAny set.
    wait_park_multi(&[object], &[0], false, resume_ip, sp, flags, tid, deadline)
}

unsafe fn wait_cancel_thread(handler: &ExecNtHandler, tid: u64) {
    for slot in 0..WAITER_N {
        if WAITER_EVENT_IDX[slot].load(Ordering::Relaxed) == u64::MAX
            || WAITER_TID[slot].load(Ordering::Relaxed) != tid
        {
            continue;
        }
        let cap = WAITER_REPLY_CAP[slot].load(Ordering::Relaxed);
        if cap != 0 {
            let deleted = cnode_delete_r(cap);
            let retyped = if deleted == 0 {
                untyped_retype_r(CAP_INIT_UNTYPED, OBJ_REPLY, 0, 1, cap)
            } else {
                u64::MAX
            };
            if deleted == 0 && retyped == 0 {
                release_reply_pool_cap(cap);
            }
        }
        WAITER_EVENT_IDX[slot].store(u64::MAX, Ordering::Relaxed);
        WAITER_EVENT_COUNT[slot].store(0, Ordering::Relaxed);
        WAITER_REPLY_CAP[slot].store(0, Ordering::Relaxed);
        WAITER_TID[slot].store(0, Ordering::Relaxed);
        WAITER_DEADLINE[slot].store(u64::MAX, Ordering::Relaxed);
    }
    thread_wait_state_clear_tid(handler, tid);
}

/// ═══ Dbgk TARGET-SIDE BLOCKING: park / resume / abandon a REPORTING thread ═══════════════════
///
/// `DbgkpQueueMessage` blocks the thread that reported a debug event on the event's `ContinueEvent`
/// until `NtDebugContinue` runs `DbgkpWakeTarget`. Our reporting thread is blocked in-kernel on the
/// Call that delivered its fault/syscall, so "park" is the SAME reply-capability steal every other
/// wait uses (`wait_park` / `keyed_wait_park` / `pipe_wait_park`): take the Reply object the last
/// recv bound to this caller and rotate a fresh pool object into `REPLY_MAIN_SLOT` so the loop's
/// next recv binds a NEW one. The stolen capability rides on the `DEBUG_EVENT` itself
/// ([`nt_process::dbgk::ReporterBlock`]) — exactly where NT keeps the waiting reporter.
///
/// Returns `None` (⇒ the caller must NOT block: it falls back to post-and-continue) when there is no
/// active reply object or the pool is exhausted. Never a hang.
#[allow(clippy::too_many_arguments)]
unsafe fn dbgk_reporter_park(
    kind: u8,
    pi: usize,
    tid: u64,
    badge: u64,
    resume_ip: u64,
    sp: u64,
    flags: u64,
    resume_status: u64,
) -> Option<nt_process::dbgk::ReporterBlock> {
    let stolen = REPLY_MAIN_SLOT.load(Ordering::Relaxed);
    if stolen == 0 {
        return None;
    }
    let (fresh_index, fresh) = wait_reply_pool_find_free()?;
    wait_reply_pool_mark_used(fresh_index);
    REPLY_MAIN_SLOT.store(fresh, Ordering::Relaxed);
    let block = nt_process::dbgk::ReporterBlock {
        kind,
        reply_cap: stolen,
        pi: pi as u32,
        tid,
        badge,
        resume_ip,
        resume_sp: sp,
        resume_flags: flags,
        resume_status,
    };
    DBGK_REPORTERS_BLOCKED.fetch_add(1, Ordering::Relaxed);
    block.is_blocked().then_some(block)
}

/// `DbgkpWakeTarget`'s RESUME half: reply to the blocked reporter so it CONTINUES EXECUTION.
///
/// ★ The reply SHAPE is per fault flavour — this is the whole reason target-side blocking needed its
/// own machinery. The kernel's `apply_fault_reply` transfers different registers per `pending_fault`:
/// * **UnknownSyscall** (a syscall reporter) — slots 0=RAX … 15=FaultIP, 16=SP, 17=FLAGS: the
///   ordinary syscall reply (status in MR0, resume context in MR15/16/17), length 18.
/// * **UserException** — slots 0=FaultIP, 1=SP, 2=FLAGS, length 3. Sending the *syscall* shape here
///   would write the status into the faulter's FaultIP and resume it at garbage.
/// * **VMFault / DebugException** — no register transfer at all; a length-0, label-0 reply restarts
///   the faulter (the `#PF` retries the faulting instruction, the int3 resumes past it).
/// In every case label 0 = restart (`handleFaultReply`'s `label == 0` rule).
unsafe fn dbgk_reporter_resume(block: &nt_process::dbgk::ReporterBlock) -> bool {
    use nt_process::dbgk::{DBGK_BLOCK_SYSCALL, DBGK_BLOCK_USER_EXCEPTION};
    if !block.is_blocked() {
        return false;
    }
    match block.kind {
        DBGK_BLOCK_SYSCALL => {
            set_reply_mr(15, block.resume_ip);
            set_reply_mr(16, block.resume_sp);
            set_reply_mr(17, block.resume_flags);
            client_reply_on(block.reply_cap, 18, block.resume_status, 0, 0, 0);
        }
        DBGK_BLOCK_USER_EXCEPTION => client_reply_on(
            block.reply_cap,
            3,
            block.resume_ip,
            block.resume_sp,
            block.resume_flags,
            0,
        ),
        // VMFault / DebugException: restart with no register transfer.
        _ => client_reply_on(block.reply_cap, 0, 0, 0, 0, 0),
    }
    release_reply_pool_cap(block.reply_cap);
    thread_wait_state_clear_badge(block.badge);
    DBGK_REPORTERS_RESUMED.fetch_add(1, Ordering::Relaxed);
    true
}

/// `DbgkpWakeTarget`'s NON-resuming half: the reporter is never woken (`DBG_EXCEPTION_NOT_HANDLED`
/// at a fault ⇒ the fault site's own unrecoverable handling stands; `DBG_TERMINATE_*` ⇒ the thread
/// is dead; a teardown release ⇒ the fault was unrecoverable anyway). The thread stays blocked
/// in-kernel exactly as `park_and_log!`'s recv-without-reply leaves it.
///
/// The Reply object is RECYCLED (delete → re-retype gives a fresh UNBOUND one) so a run of abandoned
/// reporters can never drain the reply pool — the same discipline `wait_cancel_thread` uses.
unsafe fn dbgk_reporter_abandon(block: &nt_process::dbgk::ReporterBlock) -> bool {
    if block.reply_cap == 0 {
        return false;
    }
    let deleted = cnode_delete_r(block.reply_cap);
    let retyped = if deleted == 0 {
        untyped_retype_r(CAP_INIT_UNTYPED, OBJ_REPLY, 0, 1, block.reply_cap)
    } else {
        u64::MAX
    };
    if deleted == 0 && retyped == 0 {
        release_reply_pool_cap(block.reply_cap);
    }
    true
}

fn keyed_wait_clear_slot(slot: usize) {
    KEYED_WAITER_KEY[slot].store(u64::MAX, Ordering::Relaxed);
    KEYED_WAITER_REPLY_CAP[slot].store(0, Ordering::Relaxed);
    KEYED_WAITER_TID[slot].store(0, Ordering::Relaxed);
    KEYED_WAITER_DEADLINE[slot].store(u64::MAX, Ordering::Relaxed);
    KEYED_WAITER_RESUME_IP[slot].store(0, Ordering::Relaxed);
    KEYED_WAITER_RESUME_SP[slot].store(0, Ordering::Relaxed);
    KEYED_WAITER_RESUME_FLAGS[slot].store(0, Ordering::Relaxed);
}

/// PARK the current caller on a keyed-event key (`NtWaitForKeyedEvent`). This is the same
/// reply-cap steal/rotate operation as `wait_park_multi`, with the wait condition keyed by a raw
/// user pointer instead of an executive event index.
unsafe fn keyed_wait_park(
    key: u64,
    resume_ip: u64,
    sp: u64,
    flags: u64,
    tid: u64,
    deadline: Option<u64>,
) -> bool {
    let mut slot = usize::MAX;
    for index in 0..KEYED_WAITER_N {
        if KEYED_WAITER_KEY[index].load(Ordering::Relaxed) == u64::MAX {
            slot = index;
            break;
        }
    }
    if slot == usize::MAX {
        return false;
    }

    let stolen = REPLY_MAIN_SLOT.load(Ordering::Relaxed);
    if stolen == 0 {
        return false;
    }
    let Some((fresh_index, fresh)) = wait_reply_pool_find_free() else {
        return false;
    };

    KEYED_WAITER_REPLY_CAP[slot].store(stolen, Ordering::Relaxed);
    KEYED_WAITER_TID[slot].store(tid, Ordering::Relaxed);
    KEYED_WAITER_DEADLINE[slot].store(deadline.unwrap_or(u64::MAX), Ordering::Relaxed);
    KEYED_WAITER_RESUME_IP[slot].store(resume_ip, Ordering::Relaxed);
    KEYED_WAITER_RESUME_SP[slot].store(sp, Ordering::Relaxed);
    KEYED_WAITER_RESUME_FLAGS[slot].store(flags, Ordering::Relaxed);
    KEYED_WAITER_KEY[slot].store(key, Ordering::Relaxed);
    wait_reply_pool_mark_used(fresh_index);
    REPLY_MAIN_SLOT.store(fresh, Ordering::Relaxed);
    KEYED_WAIT_PARKED_COUNT.fetch_add(1, Ordering::Relaxed);
    true
}

/// Wake one caller parked on `key`, returning `true` when a matching waiter was resumed.
unsafe fn keyed_wait_wake_one(handler: &ExecNtHandler, key: u64, status: u64) -> bool {
    for slot in 0..KEYED_WAITER_N {
        if KEYED_WAITER_KEY[slot].load(Ordering::Relaxed) != key {
            continue;
        }
        let cap = KEYED_WAITER_REPLY_CAP[slot].load(Ordering::Relaxed);
        if cap == 0 {
            keyed_wait_clear_slot(slot);
            return false;
        }
        set_reply_mr(15, KEYED_WAITER_RESUME_IP[slot].load(Ordering::Relaxed));
        set_reply_mr(16, KEYED_WAITER_RESUME_SP[slot].load(Ordering::Relaxed));
        set_reply_mr(17, KEYED_WAITER_RESUME_FLAGS[slot].load(Ordering::Relaxed));
        client_reply_on(cap, 18, status, 0, 0, 0);
        release_reply_pool_cap(cap);
        thread_wait_state_clear_tid(handler, KEYED_WAITER_TID[slot].load(Ordering::Relaxed));
        keyed_wait_clear_slot(slot);
        KEYED_WAIT_WOKEN_COUNT.fetch_add(1, Ordering::Relaxed);
        return true;
    }
    false
}

fn keyed_release_take_pending(key: u64) -> bool {
    for slot in 0..KEYED_RELEASE_N {
        if KEYED_RELEASE_KEY[slot].load(Ordering::Relaxed) != key {
            continue;
        }
        let count = KEYED_RELEASE_COUNT[slot].load(Ordering::Relaxed);
        if count <= 1 {
            KEYED_RELEASE_COUNT[slot].store(0, Ordering::Relaxed);
            KEYED_RELEASE_KEY[slot].store(u64::MAX, Ordering::Relaxed);
        } else {
            KEYED_RELEASE_COUNT[slot].store(count - 1, Ordering::Relaxed);
        }
        return true;
    }
    false
}

fn keyed_release_remember_pending(key: u64) -> bool {
    if key == u64::MAX {
        return false;
    }
    for slot in 0..KEYED_RELEASE_N {
        if KEYED_RELEASE_KEY[slot].load(Ordering::Relaxed) == key {
            KEYED_RELEASE_COUNT[slot].fetch_add(1, Ordering::Relaxed);
            return true;
        }
    }
    for slot in 0..KEYED_RELEASE_N {
        if KEYED_RELEASE_KEY[slot].load(Ordering::Relaxed) == u64::MAX {
            KEYED_RELEASE_COUNT[slot].store(1, Ordering::Relaxed);
            KEYED_RELEASE_KEY[slot].store(key, Ordering::Relaxed);
            return true;
        }
    }
    false
}

unsafe fn keyed_wait_wake_due(handler: &ExecNtHandler) -> u64 {
    let now = monotonic_time_100ns();
    let mut woken = 0;
    for slot in 0..KEYED_WAITER_N {
        if KEYED_WAITER_KEY[slot].load(Ordering::Relaxed) == u64::MAX
            || KEYED_WAITER_DEADLINE[slot].load(Ordering::Relaxed) > now
        {
            continue;
        }
        let cap = KEYED_WAITER_REPLY_CAP[slot].load(Ordering::Relaxed);
        if cap != 0 {
            set_reply_mr(15, KEYED_WAITER_RESUME_IP[slot].load(Ordering::Relaxed));
            set_reply_mr(16, KEYED_WAITER_RESUME_SP[slot].load(Ordering::Relaxed));
            set_reply_mr(17, KEYED_WAITER_RESUME_FLAGS[slot].load(Ordering::Relaxed));
            client_reply_on(cap, 18, 0x102, 0, 0, 0);
            release_reply_pool_cap(cap);
            thread_wait_state_clear_tid(handler, KEYED_WAITER_TID[slot].load(Ordering::Relaxed));
            woken += 1;
        }
        keyed_wait_clear_slot(slot);
    }
    woken
}

unsafe fn keyed_wait_cancel_thread(handler: &ExecNtHandler, tid: u64) {
    for slot in 0..KEYED_WAITER_N {
        if KEYED_WAITER_KEY[slot].load(Ordering::Relaxed) == u64::MAX
            || KEYED_WAITER_TID[slot].load(Ordering::Relaxed) != tid
        {
            continue;
        }
        let cap = KEYED_WAITER_REPLY_CAP[slot].load(Ordering::Relaxed);
        if cap != 0 {
            let deleted = cnode_delete_r(cap);
            let retyped = if deleted == 0 {
                untyped_retype_r(CAP_INIT_UNTYPED, OBJ_REPLY, 0, 1, cap)
            } else {
                u64::MAX
            };
            if deleted == 0 && retyped == 0 {
                release_reply_pool_cap(cap);
            }
        }
        keyed_wait_clear_slot(slot);
    }
    thread_wait_state_clear_tid(handler, tid);
}

/// Consume the Reply object bound to the current native-syscall fault without sending on it, then
/// rotate a fresh pool object into `REPLY_MAIN_SLOT`. Deleting the bound object clears the only
/// capability that can resume this Call; the caller remains blocked until its TCB is destroyed.
/// The vacated cptr is immediately retyped as an unbound Reply object and returned to the pool.
unsafe fn drop_current_syscall_reply() -> bool {
    let active = REPLY_MAIN_SLOT.load(Ordering::Relaxed);
    if active == 0 {
        return false;
    }
    let active_index = (0..WAIT_REPLY_POOL_N)
        .find(|&index| WAIT_REPLY_POOL[index].load(Ordering::Relaxed) == active);
    let fresh = wait_reply_pool_find_free();
    let (active_index, fresh_index, fresh) = match (active_index, fresh) {
        (Some(active_index), Some((fresh_index, fresh))) => (active_index, fresh_index, fresh),
        _ => return false,
    };
    let delete = cnode_delete_r(active);
    if delete != 0 {
        print_str(b"[thread-term] reply-drop cap=0x");
        print_hex(active as u32);
        print_str(b" delete=");
        print_u64(delete);
        print_str(b"\n");
        return false;
    }
    wait_reply_pool_mark_free(active_index);
    wait_reply_pool_mark_used(fresh_index);
    REPLY_MAIN_SLOT.store(fresh, Ordering::Relaxed);
    let retype = untyped_retype_r(CAP_INIT_UNTYPED, OBJ_REPLY, 0, 1, active);
    if retype != 0 {
        WAIT_REPLY_POOL[active_index].store(0, Ordering::Relaxed);
    }
    print_str(b"[thread-term] reply-drop cap=0x");
    print_hex(active as u32);
    print_str(b" next=0x");
    print_hex(fresh as u32);
    print_str(b" delete=0 retype=");
    print_u64(retype);
    print_str(b"\n");
    true
}

unsafe fn release_hosted_thread_mechanism_caps(tid: u64, mechanism: HostedThreadMechanismCaps) {
    if !mechanism.is_live() {
        return;
    }
    let sc_delete = if mechanism.sched_context != 0 {
        cnode_delete_recycle_r(mechanism.sched_context)
    } else {
        0
    };
    let cnode_delete = if mechanism.cnode != 0 {
        cnode_delete_recycle_r(mechanism.cnode)
    } else {
        0
    };
    let raw_delete = if mechanism.raw_cnode != 0 {
        cnode_delete_recycle_r(mechanism.raw_cnode)
    } else {
        0
    };
    if sc_delete == 0 && cnode_delete == 0 && raw_delete == 0 {
        HOSTED_THREAD_CNODE_RELEASES.fetch_add(1, Ordering::Relaxed);
    } else {
        if HOSTED_THREAD_CNODE_RELEASE_FAILS.fetch_add(1, Ordering::Relaxed) < 8 {
            print_str(b"[thread-term] mechanism CNode release failed tid=");
            print_u64(tid);
            print_str(b" sc=0x");
            print_hex_u64(mechanism.sched_context);
            print_str(b" cnode=0x");
            print_hex_u64(mechanism.cnode);
            print_str(b" raw=0x");
            print_hex_u64(mechanism.raw_cnode);
            print_str(b" delete=");
            print_u64(sc_delete);
            print_str(b"/");
            print_u64(cnode_delete);
            print_str(b"/");
            print_u64(raw_delete);
            print_str(b"\n");
        }
    }
}

unsafe fn release_hosted_thread_mechanism_cnodes(runtime: HostedThreadRuntime) {
    release_hosted_thread_mechanism_caps(runtime.tid, runtime.mechanism);
}

pub(crate) unsafe fn release_unregistered_hosted_thread_spawn(spawn: HostedThreadSpawnResult) {
    if spawn.tcb() > 1 {
        let _ = tcb_suspend_r(spawn.tcb());
        let _ = cnode_delete_recycle_r(spawn.tcb());
    }
    release_hosted_thread_mechanism_caps(0, spawn.mechanism());
}

unsafe fn pipe_io_cancel_thread(tid: u64, handler: &mut ExecNtHandler) {
    let table = &mut *core::ptr::addr_of_mut!(PIPE_WAITERS);
    let reply_caps = &mut *core::ptr::addr_of_mut!(PIPE_IO_CANCEL_REPLY_CAPS_WORK);
    let mut count = 0usize;
    for (_, waiter) in table
        .drain_all()
        .filter(|(_, waiter)| waiter.tid == tid && waiter.reply_cap != 0)
    {
        reply_caps[count] = waiter.reply_cap;
        count += 1;
    }
    let _ = table.detach_blocked_thread(tid);
    for index in 0..count {
        if reply_caps[index] != 0 {
            release_reply_pool_cap(reply_caps[index]);
        }
    }
    let listens = &mut *core::ptr::addr_of_mut!(PIPE_ASYNC_LISTENS);
    let mut listen_file_ids = [0u64; PIPE_ASYNC_LISTEN_N];
    let listen_count = listens.cancel_thread_collect_file_ids(tid, &mut listen_file_ids);
    for index in 0..listen_count.min(listen_file_ids.len()) {
        if listen_file_ids[index] != 0 {
            handler.release_file_reference(listen_file_ids[index]);
        }
    }
    let name_waiters = &mut *core::ptr::addr_of_mut!(PIPE_NAME_WAITERS);
    let name_wait_reply_caps = &mut *core::ptr::addr_of_mut!(PIPE_NAME_CANCEL_REPLY_CAPS_WORK);
    let name_wait_count = name_waiters.cancel_thread_collect_reply_caps(tid, name_wait_reply_caps);
    for index in 0..name_wait_count.min(name_wait_reply_caps.len()) {
        let cap = name_wait_reply_caps[index];
        if cap != 0 {
            let deleted = cnode_delete_r(cap);
            let retyped = if deleted == 0 {
                untyped_retype_r(CAP_INIT_UNTYPED, OBJ_REPLY, 0, 1, cap)
            } else {
                u64::MAX
            };
            if deleted == 0 && retyped == 0 {
                release_reply_pool_cap(cap);
            }
        }
    }
    thread_wait_state_clear_tid(handler, tid);
}

unsafe fn terminate_hosted_thread_mechanism(
    tid: u64,
    delay_queue: &mut nt_delay_execution::Queue<DELAY_WAITER_N>,
    handler: &mut ExecNtHandler,
) -> bool {
    delay_cancel_thread(delay_queue, tid);
    io_completion_cancel_thread(handler, tid);
    delay_timer_rearm(delay_queue);
    wait_cancel_thread(handler, tid);
    keyed_wait_cancel_thread(handler, tid);
    pipe_io_cancel_thread(tid, handler);
    let abandoned_mutants = handler.abandon_mutants_for_thread(tid);
    if abandoned_mutants != 0 {
        print_str(b"[thread-term] abandoned mutants tid=");
        print_u64(tid);
        print_str(b" count=");
        print_u64(abandoned_mutants);
        print_str(b"\n");
    }
    let tcb = match handler.hosted_thread_tcb(tid) {
        Some(tcb) if tcb > 1 => tcb,
        None => return false,
        Some(_) => return false,
    };
    let suspend = tcb_suspend_r(tcb);
    let delete = if suspend == 0 {
        cnode_delete_recycle_r(tcb)
    } else {
        u64::MAX
    };
    print_str(b"[thread-term] mechanism tid=");
    print_u64(tid);
    print_str(b" tcb=0x");
    print_hex(tcb as u32);
    print_str(b" suspend=");
    print_u64(suspend);
    print_str(b" delete=");
    print_u64(delete);
    print_str(b"\n");
    if suspend == 0 && delete == 0 {
        let pool_slot = handler.pm_pool_slot_for_tid(tid);
        let role = handler.hosted_thread_role(tid);
        let worker_slot = if let Some(HostedThreadRole::TpWorker { slot }) = role {
            pool_slot.map(|(pi, _)| (pi, slot))
        } else {
            None
        };
        let runtime = handler.release_hosted_thread_runtime(tid);
        if let Some((pi, slot)) = pool_slot {
            let _ = handler.release_pool_usage_slot(pi, slot);
            let _ = handler.set_pool_thread_suspended(pi, slot, false);
        }
        if let Some(runtime) = runtime {
            handler.release_hosted_thread_user_stack_vad(runtime);
            release_hosted_thread_mechanism_cnodes(runtime);
        }
        if let Some((pi, slot)) = worker_slot {
            release_hosted_tp_worker_window_resources(pi, slot);
            handler.clear_hosted_tp_worker_window_slot(pi, slot);
        }
        PM_TERMINATE_THREAD_TCB_RECLAIMED.fetch_add(1, Ordering::Relaxed);
        true
    } else {
        false
    }
}

unsafe fn terminate_hosted_process_mechanisms(
    process_index: u8,
    preserve_tid: Option<u64>,
    delay_queue: &mut nt_delay_execution::Queue<DELAY_WAITER_N>,
    handler: &mut ExecNtHandler,
) -> usize {
    const MAX_PROCESS_TERMINATE_TIDS: usize = 64;
    let mut tids = [0u64; MAX_PROCESS_TERMINATE_TIDS];
    let mut count = 0usize;
    if let Some(pid) = handler.pm_pid_for_pi(process_index as usize) {
        if let Some(process) = handler.pm.process(pid) {
            for tid in process.threads.iter().copied() {
                if count == tids.len() {
                    print_str(b"[process-term] tid-list-full pi=");
                    print_u64(process_index as u64);
                    print_str(b"\n");
                    break;
                }
                tids[count] = tid as u64;
                count += 1;
            }
        }
    }

    let mut reclaimed = 0usize;
    for tid in tids.iter().copied().take(count) {
        if preserve_tid == Some(tid) {
            continue;
        }
        if terminate_hosted_thread_mechanism(tid, delay_queue, handler) {
            reclaimed += 1;
        }
    }
    handler.clear_hosted_tp_worker_windows(process_index as usize);
    io_completion_cancel_process(handler, process_index);
    delay_timer_rearm(delay_queue);
    reclaimed
}

/// GENERAL park: block the current caller on a SET of wait objects (`objects`), with `wait_all`
/// selecting WaitAll (wake when all signalled → WAIT_0) vs WaitAny (wake on the first signalled →
/// WAIT_0+index). Steals this caller's bound reply object (REPLY_MAIN) into a free waiter slot and
/// rotates a fresh pool object into REPLY_MAIN so subsequent recvs bind a new object. Returns true on
/// success; false if the pool/queue is exhausted OR the set is too large (`objects.len() >
/// WAITER_MAX_EVENTS`).
unsafe fn wait_park_multi(
    objects: &[WaitObject],
    result_indices: &[u8],
    wait_all: bool,
    resume_ip: u64,
    sp: u64,
    flags: u64,
    tid: u64,
    deadline: Option<u64>,
) -> bool {
    if objects.is_empty()
        || objects.len() > WAITER_MAX_EVENTS
        || result_indices.len() != objects.len()
    {
        WAIT_PARK_INVALID_SET.fetch_add(1, Ordering::Relaxed);
        return false;
    }
    // Find a free waiter slot.
    let mut wslot = usize::MAX;
    for i in 0..WAITER_N {
        if WAITER_EVENT_IDX[i].load(Ordering::Relaxed) == u64::MAX {
            wslot = i;
            break;
        }
    }
    if wslot == usize::MAX {
        WAIT_PARK_NO_WAITER_SLOT.fetch_add(1, Ordering::Relaxed);
        return false;
    }
    // The reply object bound to this caller is the active REPLY_MAIN.
    let stolen = REPLY_MAIN_SLOT.load(Ordering::Relaxed);
    if stolen == 0 {
        WAIT_PARK_NO_REPLY_CAP.fetch_add(1, Ordering::Relaxed);
        return false;
    }
    // Find a FREE pool object to become the new active REPLY_MAIN. The stolen one is (still) marked
    // used; we need a different free bit.
    let Some((fresh_index, fresh)) = wait_reply_pool_find_free() else {
        WAIT_PARK_NO_REPLY_CAP.fetch_add(1, Ordering::Relaxed);
        return false; // pool exhausted → caller reports STATUS_INSUFFICIENT_RESOURCES
    };
    // Commit: record the waiter's object set + its syscall resume context, install the fresh object as
    // the active recv reply cap.
    for (k, &object) in objects.iter().enumerate() {
        WAITER_EVENTS[wslot][k].store(object.raw(), Ordering::Relaxed);
        WAITER_RESULT_INDEX[wslot][k].store(result_indices[k] as u64, Ordering::Relaxed);
    }
    for k in objects.len()..WAITER_MAX_EVENTS {
        WAITER_EVENTS[wslot][k].store(WaitObject::FREE.raw(), Ordering::Relaxed);
    }
    WAITER_EVENT_COUNT[wslot].store(objects.len() as u64, Ordering::Relaxed);
    WAITER_WAIT_ALL[wslot].store(wait_all as u64, Ordering::Relaxed);
    WAITER_REPLY_CAP[wslot].store(stolen, Ordering::Relaxed);
    WAITER_TID[wslot].store(tid, Ordering::Relaxed);
    WAITER_DEADLINE[wslot].store(deadline.unwrap_or(u64::MAX), Ordering::Relaxed);
    WAITER_RESUME_IP[wslot].store(resume_ip, Ordering::Relaxed);
    WAITER_RESUME_SP[wslot].store(sp, Ordering::Relaxed);
    WAITER_RESUME_FLAGS[wslot].store(flags, Ordering::Relaxed);
    // WAITER_EVENT_IDX doubles as the slot-free sentinel: set it LAST (after the set) so a slot never
    // looks "used but empty".
    WAITER_EVENT_IDX[wslot].store(objects[0].raw(), Ordering::Relaxed);
    wait_reply_pool_mark_used(fresh_index);
    REPLY_MAIN_SLOT.store(fresh, Ordering::Relaxed);
    WAIT_PARKED_COUNT.fetch_add(1, Ordering::Relaxed);
    true
}

/// Wake every waiter whose NT wait-object condition is satisfied. Synchronization events and
/// semaphore tokens are consumed in waiter-slot order; process/thread objects are level-signalled.
unsafe fn wait_wake_dispatcher_set(handler: &mut ExecNtHandler) -> u64 {
    wait_wake_dispatcher(handler, None)
}

/// Pulse uses the same waiter selection, but clears the event before any parked thread resumes.
unsafe fn wait_wake_dispatcher_pulse(just_set: usize, handler: &mut ExecNtHandler) -> u64 {
    wait_wake_dispatcher(handler, Some(just_set))
}

unsafe fn wait_wake_dispatcher(handler: &mut ExecNtHandler, pulse_event: Option<usize>) -> u64 {
    let wake_indices = &mut *core::ptr::addr_of_mut!(WAIT_WAKE_INDEX_WORK);
    let wake_objects = &mut *core::ptr::addr_of_mut!(WAIT_WAKE_OBJECT_WORK);
    for i in 0..WAITER_N {
        wake_indices[i] = u64::MAX;
        wake_objects[i] = WaitObject::FREE.raw();
    }
    for i in 0..WAITER_N {
        let slot_ev0 = WAITER_EVENT_IDX[i].load(Ordering::Relaxed);
        if slot_ev0 == u64::MAX {
            continue; // free slot
        }
        let count = WAITER_EVENT_COUNT[i].load(Ordering::Relaxed) as usize;
        if count == 0 {
            continue;
        }
        let wait_all = WAITER_WAIT_ALL[i].load(Ordering::Relaxed) != 0;
        // Does this waiter's condition hold, and if WaitAny, which index fired?
        let mut wake = false;
        let mut wake_index = 0u64;
        let mut selected_slot = 0usize;
        if wait_all {
            // Check the whole set before consuming anything so an unsatisfied WaitAll never reserves
            // an auto-reset event or semaphore token.
            let mut all = true;
            let waiter_tid = WAITER_TID[i].load(Ordering::Relaxed);
            for k in 0..count.min(WAITER_MAX_EVENTS) {
                let Some(object) =
                    WaitObject::from_raw(WAITER_EVENTS[i][k].load(Ordering::Relaxed))
                else {
                    all = false;
                    break;
                };
                if !handler.wait_object_ready_for(object, waiter_tid) {
                    all = false;
                    break;
                }
            }
            wake = all;
            wake_index = 0; // WaitAll returns WAIT_OBJECT_0
            if wake {
                wake_objects[i] = WAITER_EVENTS[i][0].load(Ordering::Relaxed);
            }
        } else {
            // WaitAny: the first (lowest-index) signalled event determines the return value.
            let waiter_tid = WAITER_TID[i].load(Ordering::Relaxed);
            for k in 0..count.min(WAITER_MAX_EVENTS) {
                let Some(object) =
                    WaitObject::from_raw(WAITER_EVENTS[i][k].load(Ordering::Relaxed))
                else {
                    continue;
                };
                if handler.wait_object_ready_for(object, waiter_tid) {
                    wake = true;
                    selected_slot = k;
                    wake_index = WAITER_RESULT_INDEX[i][k].load(Ordering::Relaxed);
                    wake_objects[i] = object.raw();
                    break;
                }
            }
        }
        if !wake {
            continue;
        }
        // Consume the selected dispatcher transaction only after the condition is known to hold.
        if wait_all {
            let waiter_tid = WAITER_TID[i].load(Ordering::Relaxed);
            for k in 0..count.min(WAITER_MAX_EVENTS) {
                if let Some(object) =
                    WaitObject::from_raw(WAITER_EVENTS[i][k].load(Ordering::Relaxed))
                {
                    handler.wait_object_consume_for(object, waiter_tid);
                }
            }
        } else {
            let waiter_tid = WAITER_TID[i].load(Ordering::Relaxed);
            if let Some(object) =
                WaitObject::from_raw(WAITER_EVENTS[i][selected_slot].load(Ordering::Relaxed))
            {
                handler.wait_object_consume_for(object, waiter_tid);
            }
        }
        wake_indices[i] = wake_index;
    }

    if let Some(index) = pulse_event {
        let _ = handler.events.reset_existing(index as u64);
    }

    let mut woken = 0u64;
    for i in 0..WAITER_N {
        let wake_index = wake_indices[i];
        if wake_index == u64::MAX {
            continue;
        }
        let cap = WAITER_REPLY_CAP[i].load(Ordering::Relaxed);
        if cap != 0 {
            // Resume the parked wait with STATUS_WAIT_0 + index. The waiter blocked as a native syscall
            // (UnknownSyscall fault); apply_fault_reply restores RCX←resume_ip, RSP←sp, RFLAGS←flags
            // (IPC MR15/16/17) and RAX/r10←status. r10 (status) = wake_index = WAIT_OBJECT_0+index.
            set_reply_mr(15, WAITER_RESUME_IP[i].load(Ordering::Relaxed));
            set_reply_mr(16, WAITER_RESUME_SP[i].load(Ordering::Relaxed));
            set_reply_mr(17, WAITER_RESUME_FLAGS[i].load(Ordering::Relaxed));
            client_reply_on(cap, 18, wake_index, 0, 0, 0);
            // Return this reply object to the pool (clear its used bit).
            release_reply_pool_cap(cap);
            let trace = WAIT_WAKE_TRACE_COUNT.fetch_add(1, Ordering::Relaxed);
            if trace < 96 {
                let tid = WAITER_TID[i].load(Ordering::Relaxed);
                let object = WaitObject::from_raw(wake_objects[i]).unwrap_or(WaitObject::FREE);
                print_str(b"[wait-wake] #");
                print_u64(trace);
                print_str(b" tid=");
                print_u64(tid);
                if let Some(badge) = handler.hosted_thread_badge_for_tid(tid) {
                    print_str(b" badge=");
                    print_u64(badge);
                }
                print_str(b" object=");
                print_str(object.describe());
                print_str(b"/");
                print_u64(object.id());
                print_str(b" result=");
                print_u64(wake_index);
                print_str(b" count=");
                print_u64(WAITER_EVENT_COUNT[i].load(Ordering::Relaxed));
                print_str(b" wait_all=");
                print_u64(WAITER_WAIT_ALL[i].load(Ordering::Relaxed));
                print_str(b"\n");
            }
            thread_wait_state_clear_tid(handler, WAITER_TID[i].load(Ordering::Relaxed));
            woken += 1;
            WAIT_WOKEN_COUNT.fetch_add(1, Ordering::Relaxed);
        }
        // Free the slot.
        WAITER_EVENT_IDX[i].store(u64::MAX, Ordering::Relaxed);
        WAITER_EVENT_COUNT[i].store(0, Ordering::Relaxed);
        WAITER_REPLY_CAP[i].store(0, Ordering::Relaxed);
        WAITER_TID[i].store(0, Ordering::Relaxed);
        WAITER_DEADLINE[i].store(u64::MAX, Ordering::Relaxed);
    }
    woken
}

unsafe fn wait_wake_due(handler: &ExecNtHandler) -> u64 {
    let now = monotonic_time_100ns();
    let mut woken = 0;
    for slot in 0..WAITER_N {
        if WAITER_EVENT_IDX[slot].load(Ordering::Relaxed) == u64::MAX
            || WAITER_DEADLINE[slot].load(Ordering::Relaxed) > now
        {
            continue;
        }
        let cap = WAITER_REPLY_CAP[slot].load(Ordering::Relaxed);
        if cap != 0 {
            set_reply_mr(15, WAITER_RESUME_IP[slot].load(Ordering::Relaxed));
            set_reply_mr(16, WAITER_RESUME_SP[slot].load(Ordering::Relaxed));
            set_reply_mr(17, WAITER_RESUME_FLAGS[slot].load(Ordering::Relaxed));
            client_reply_on(cap, 18, 0x102, 0, 0, 0);
            release_reply_pool_cap(cap);
            thread_wait_state_clear_tid(handler, WAITER_TID[slot].load(Ordering::Relaxed));
            woken += 1;
        }
        WAITER_EVENT_IDX[slot].store(u64::MAX, Ordering::Relaxed);
        WAITER_EVENT_COUNT[slot].store(0, Ordering::Relaxed);
        WAITER_REPLY_CAP[slot].store(0, Ordering::Relaxed);
        WAITER_TID[slot].store(0, Ordering::Relaxed);
        WAITER_DEADLINE[slot].store(u64::MAX, Ordering::Relaxed);
    }
    woken
}

unsafe fn set_reply_mr(i: usize, v: u64) {
    let base = IPC_BUFFER.load(Ordering::Relaxed);
    core::ptr::write_volatile((base + 8 + (i as u64) * 8) as *mut u64, v);
}
pub(crate) unsafe fn get_recv_mr(i: usize) -> u64 {
    let base = IPC_BUFFER.load(Ordering::Relaxed);
    core::ptr::read_volatile((base + 8 + (i as u64) * 8) as *const u64)
}
/// Stage a value into the executive's IPC-buffer RECEIVE MR slot `i` (ntdll_plan Step 6.A). Used to
/// NORMALIZE a native-seL4-Call NT_NATIVE_SYSCALL message into the register-slot layout the
/// `(mi>>12)==2` UnknownSyscall service arm reads (which reads args from the fault frame's saved
/// register slots via `get_recv_mr`), so the native transport reuses that arm's full servicing body
/// unchanged. Same address math as `set_reply_mr`/`get_recv_mr` (MR `i` at byte `8 + i*8`).
pub(crate) unsafe fn set_recv_mr(i: usize, v: u64) {
    let base = IPC_BUFFER.load(Ordering::Relaxed);
    core::ptr::write_volatile((base + 8 + (i as u64) * 8) as *mut u64, v);
}

/// Issue an IRQ-handler cap for a real IOAPIC `pin`, delivering `IRQ_VECTOR`, into
/// `dest_slot` of the executive's root CNode. This is `X86IRQIssueIRQHandlerIOAPIC`:
/// a 7-word message (msg_regs[0..6]) + one extra cap (the dest CNode root). mr0..2 go
/// in registers, mr3 (pin) in r15, mr4..6 in the IPC buffer, the extra cap at IPC
/// word 122. The kernel also programs IOAPIC RTE[pin] → pin fires vector+0x20.
unsafe fn ioapic_issue_irq_handler(
    dest_slot: u64,
    pin: u64,
    vector: u64,
    level: u64,
    polarity: u64,
) {
    let ipc = IPC_BUFFER.load(Ordering::Relaxed);
    core::ptr::write_volatile((ipc + 5 * 8) as *mut u64, level); // mr4 = level (0=edge, 1=level)
    core::ptr::write_volatile((ipc + 6 * 8) as *mut u64, polarity); // mr5 = polarity (1=active-low)
    core::ptr::write_volatile((ipc + 7 * 8) as *mut u64, vector); // mr6 = vector (irq table index)
                                                                  // caps_or_badges[0] = the dest CNode root (resolved in the caller's cspace).
    core::ptr::write_volatile((ipc + 122 * 8) as *mut u64, CAP_INIT_THREAD_CNODE);
    // msginfo: label=64, capsUnwrapped=1, extraCaps=1, length=7.
    let msginfo = (LBL_X86_IRQ_ISSUE_IOAPIC << 12) | (1 << 9) | (1 << 7) | 7;
    core::arch::asm!(
        "syscall",
        in("rdx") SYS_SEND as u64,
        in("rdi") SLOT_IRQ_CONTROL,
        in("rsi") msginfo,
        in("r10") dest_slot, // mr0 = index (dest slot)
        in("r8") 64u64,      // mr1 = depth (init CNode: guard=0, so depth 64 resolves the slot)
        in("r9") 0u64,       // mr2 = ioapic id (ignored)
        in("r15") pin,       // mr3 = pin
        lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
}

/// The fixed object path for a syscall's directory index.
fn path_for(i: u64) -> &'static str {
    match i {
        0 => "\\Device\\Syscall0",
        1 => "\\Device\\Syscall1",
        _ => "\\Device\\SyscallX",
    }
}

/// The x64 `UNICODE_STRING` a user thread passes to a name-based syscall: a 16-byte
/// header (4 bytes of tail padding before the 8-byte `Buffer`) + UTF-16LE chars the
/// `Buffer` points at. Both live in the shared arg frame (same vaddr in both VSpaces).
#[repr(C)]
#[derive(Copy, Clone)]
struct NtUnicodeString {
    length: u16,         // bytes of the name (excluding NUL)
    maximum_length: u16, // capacity in bytes
    _pad: u32,
    buffer: u64, // vaddr of the UTF-16 chars (into the shared arg frame)
}

/// Copyin a user-supplied path from a `UNICODE_STRING` at `ptr`. Probes like a real
/// kernel: both the header and the `Buffer` range must lie inside the one shared arg
/// frame `[SYSARG_VADDR, SYSARG_VADDR + 4096)` — a hostile user can't steer the read
/// at executive memory. Returns the decoded path.
unsafe fn copyin_user_path(ptr: u64) -> Option<alloc::string::String> {
    let frame_lo = SYSARG_VADDR;
    let frame_hi = SYSARG_VADDR + 0x1000;
    let hdr = core::mem::size_of::<NtUnicodeString>() as u64;
    if ptr < frame_lo || ptr.checked_add(hdr)? > frame_hi {
        return None;
    }
    let us = core::ptr::read_unaligned(ptr as *const NtUnicodeString);
    let len = us.length as u64;
    if len % 2 != 0 || len > 1024 || us.buffer < frame_lo || us.buffer.checked_add(len)? > frame_hi
    {
        return None;
    }
    let mut units = Vec::with_capacity((len / 2) as usize);
    for i in 0..(len / 2) {
        units.push(core::ptr::read_unaligned((us.buffer + i * 2) as *const u16));
    }
    Some(alloc::string::String::from_utf16_lossy(&units))
}

/// The x64 `OBJECT_ATTRIBUTES` a create/open syscall carries (48 bytes): `Length`,
/// `RootDirectory`, `ObjectName` (→ `UNICODE_STRING`), `Attributes`, and two security
/// pointers we don't use yet. Built by the user in the shared arg frame.
#[repr(C)]
#[derive(Copy, Clone)]
struct RawObjectAttributes {
    length: u32,
    _pad0: u32,
    root_directory: u64,
    object_name: u64, // *UNICODE_STRING
    attributes: u32,
    _pad1: u32,
    security_descriptor: u64,
    security_qos: u64,
}

/// Copyin + decode a user `OBJECT_ATTRIBUTES` at `ptr` into the kernel-side
/// [`ObjectAttributes`]. Probes the header + follows `ObjectName` through the same
/// bounds-checked path copyin — exactly what a real `Nt*` create/open does with the
/// pointer a real ntdll passes.
unsafe fn copyin_object_attributes(ptr: u64) -> Option<ObjectAttributes> {
    let hdr = core::mem::size_of::<RawObjectAttributes>() as u64;
    if ptr < SYSARG_VADDR || ptr.checked_add(hdr)? > SYSARG_VADDR + 0x1000 {
        return None;
    }
    let raw = core::ptr::read_unaligned(ptr as *const RawObjectAttributes);
    let object_name = if raw.object_name == 0 {
        None
    } else {
        Some(UnicodeString::from_str(&copyin_user_path(raw.object_name)?))
    };
    Some(ObjectAttributes {
        root_directory: None,
        object_name,
        attributes: ObjAttrFlags::from_bits_truncate(raw.attributes),
    })
}

/// The absolute NT path an `OBJECT_ATTRIBUTES` names (this cut ignores RootDirectory).
fn oa_path(oa: &ObjectAttributes) -> Option<alloc::string::String> {
    oa.object_name
        .as_ref()
        .map(|n| alloc::string::String::from_utf16_lossy(n.as_units()))
}

/// A raw native syscall from the isolated user thread: SSN in RAX, arg1 in R10
/// (the Windows x64 convention — RCX is clobbered by `syscall`), result in RAX.
unsafe fn native_syscall(ssn: u64, arg1: u64) -> u64 {
    native_syscall2(ssn, arg1, 0)
}

/// Like [`native_syscall`] but with a 2nd arg in RDX (Windows x64 convention).
unsafe fn native_syscall2(ssn: u64, arg1: u64, arg2: u64) -> u64 {
    let ret: u64;
    core::arch::asm!(
        "syscall",
        inout("rax") ssn => ret,
        // r10/rdx carry the args in, but the fault->reply path may leave them changed, so
        // declare them clobbered (=> _) rather than `in` (which implies preserved). Likewise
        // the other MR registers the reply may touch — else the compiler reuses stale values
        // (a wild write / #PF after a syscall that parks in between).
        inout("r10") arg1 => _,
        inout("rdx") arg2 => _,
        lateout("rcx") _, lateout("r11") _,
        lateout("r8") _, lateout("r9") _, lateout("r15") _,
        options(nostack),
    );
    ret
}

/// The isolated user thread: a separate VSpace/CSpace with no access to the Object
/// Manager — it reaches objects only by trapping `syscall`s the executive services.
#[no_mangle]
#[link_section = ".text.user_entry"]
/// Build a real x64 `OBJECT_ATTRIBUTES` naming `name` in the shared arg frame:
/// header @ 0 → `UNICODE_STRING` @ 48 → UTF-16 chars @ 64. Returns the OA pointer.
unsafe fn write_object_attributes(name: &[u8]) -> u64 {
    let oa_v = SYSARG_VADDR;
    let us_v = SYSARG_VADDR + 48;
    let buf_v = SYSARG_VADDR + 64;
    for (i, &ch) in name.iter().enumerate() {
        core::ptr::write_volatile((buf_v + (i as u64) * 2) as *mut u16, ch as u16);
    }
    core::ptr::write_unaligned(
        us_v as *mut NtUnicodeString,
        NtUnicodeString {
            length: (name.len() * 2) as u16,
            maximum_length: (name.len() * 2) as u16,
            _pad: 0,
            buffer: buf_v,
        },
    );
    core::ptr::write_unaligned(
        oa_v as *mut RawObjectAttributes,
        RawObjectAttributes {
            length: 48,
            _pad0: 0,
            root_directory: 0,
            object_name: us_v,
            attributes: 0,
            _pad1: 0,
            security_descriptor: 0,
            security_qos: 0,
        },
    );
    oa_v
}

/// A second thread the user process creates via NtCreateThreadEx. It runs in the PARENT's
/// VSpace (sharing its mappings), writes a marker the parent observes, then yields forever.
pub unsafe extern "C" fn thread2_entry() -> ! {
    core::ptr::write_volatile((SYSARG_VADDR + 0x468) as *mut u64, 0x7EAD2);
    loop {
        yield_now();
    }
}

/// A "loader" thread: maps a demand-paged, FILE-BACKED section whose backing is a REAL file
/// read off the disk (the SYSTEM.DAT hive), faults its first page IN, and reports the word it
/// read (the hive's `UNTHIVE1` magic) as its verdict — a section sourced from a real disk file.
pub unsafe extern "C" fn loader_entry() -> ! {
    let sec = native_syscall2(NT_CREATE_SECTION, 0x1000, 1); // file-backed = the disk hive frame
    let view = native_syscall(NT_MAP_VIEW, sec);
    let magic = if view != 0 {
        core::ptr::read_volatile(view as *const u64) // the page is demand-paged IN right here
    } else {
        0
    };
    let _ = native_syscall(SSN_DONE, magic);
    park()
}

pub unsafe extern "C" fn user_entry() -> ! {
    // Object Manager route (scalar args — fixed paths by index).
    let r0 = native_syscall(SSN_OB_CREATE_DIR, 0);
    let r0b = native_syscall(SSN_OB_LOOKUP_DIR, 0);
    let r1 = native_syscall(SSN_OB_CREATE_DIR, 1);

    // Object Manager route (pointer arg — a real OBJECT_ATTRIBUTES in the shared frame).
    let oa = write_object_attributes(b"\\Device\\FromUserString");
    let created = native_syscall(SSN_OB_CREATE_BYNAME, oa);
    let found = native_syscall(SSN_OB_LOOKUP_BYNAME, oa);

    // Registry route — REAL ntdll SSNs + a real OBJECT_ATTRIBUTES naming the key.
    let key_oa = write_object_attributes(REG_KEY.as_bytes());
    let ck = native_syscall(NT_CREATE_KEY, key_oa);
    let sk = native_syscall2(NT_SET_VALUE_KEY, key_oa, 42);
    let val = native_syscall(NT_QUERY_VALUE_KEY, key_oa);

    // P3: allocate virtual memory via a native syscall — the executive (Mm) maps a real
    // frame into this thread's VSpace — then prove it's usable by writing + reading it back.
    let vm = native_syscall(NT_ALLOCATE_VM, 0x1000);
    let pat = 0xDEAD_BEEF_CAFE_BABEu64;
    let readback = if vm != 0 {
        core::ptr::write_volatile(vm as *mut u64, pat);
        core::ptr::read_volatile(vm as *const u64) == pat
    } else {
        false
    };
    // P3: query the system clock twice — should be non-zero + monotonic.
    let t1 = native_syscall(NT_QUERY_SYSTEM_TIME, 0);
    let t2 = native_syscall(NT_QUERY_SYSTEM_TIME, 0);
    // Publish raw results to the shared sysarg frame for the executive to verify.
    core::ptr::write_volatile((SYSARG_VADDR + 0x400) as *mut u64, vm);
    core::ptr::write_volatile((SYSARG_VADDR + 0x408) as *mut u64, readback as u64);
    core::ptr::write_volatile((SYSARG_VADDR + 0x410) as *mut u64, t1);
    core::ptr::write_volatile((SYSARG_VADDR + 0x418) as *mut u64, t2);

    // P3 sync objects: a Synchronization (auto-reset) event — wait times out, a set satisfies
    // one wait, and the auto-reset then re-arms it (the next wait times out again).
    let ev = native_syscall2(SSN_CREATE_EVENT, 1, 0);
    let w1 = native_syscall(SSN_WAIT, ev); // not signaled → TIMEOUT (0x102)
    let _ = native_syscall(SSN_SET_EVENT, ev);
    let w2 = native_syscall(SSN_WAIT, ev); // signaled → OBJECT_0 (0), auto-reset consumes it
    let w3 = native_syscall(SSN_WAIT, ev); // consumed → TIMEOUT (0x102)
                                           // A Notification (manual-reset) event — a set stays signaled across waits until reset.
    let ev2 = native_syscall2(SSN_CREATE_EVENT, 0, 0);
    let _ = native_syscall(SSN_SET_EVENT, ev2);
    let m1 = native_syscall(SSN_WAIT, ev2); // OBJECT_0
    let m2 = native_syscall(SSN_WAIT, ev2); // still OBJECT_0 (manual-reset)
    let _ = native_syscall(SSN_RESET_EVENT, ev2);
    let m3 = native_syscall(SSN_WAIT, ev2); // TIMEOUT
    core::ptr::write_volatile((SYSARG_VADDR + 0x420) as *mut u64, w1);
    core::ptr::write_volatile((SYSARG_VADDR + 0x428) as *mut u64, w2);
    core::ptr::write_volatile((SYSARG_VADDR + 0x430) as *mut u64, w3);
    core::ptr::write_volatile((SYSARG_VADDR + 0x438) as *mut u64, m1);
    core::ptr::write_volatile((SYSARG_VADDR + 0x440) as *mut u64, m2);
    core::ptr::write_volatile((SYSARG_VADDR + 0x448) as *mut u64, m3);

    // P3 sections: create a section, map it as TWO views, write one + read the other — they
    // alias the same backing frame (the defining section property; the load vehicle for DLLs).
    let sec = native_syscall(NT_CREATE_SECTION, 0x1000);
    let sv1 = native_syscall(NT_MAP_VIEW, sec);
    let sv2 = native_syscall(NT_MAP_VIEW, sec);
    let smagic = 0x5EC7_10A5_ED00_1234u64;
    let sec_alias = if sv1 != 0 && sv2 != 0 {
        core::ptr::write_volatile(sv1 as *mut u64, smagic);
        core::ptr::read_volatile(sv2 as *const u64) == smagic
    } else {
        false
    };
    core::ptr::write_volatile((SYSARG_VADDR + 0x450) as *mut u64, sv1);
    core::ptr::write_volatile((SYSARG_VADDR + 0x458) as *mut u64, sv2);
    core::ptr::write_volatile((SYSARG_VADDR + 0x460) as *mut u64, sec_alias as u64);

    // P3 NtCreateThreadEx: create a SECOND thread in this process; it runs concurrently in our
    // VSpace and writes a marker we then observe (proving a real independent thread).
    core::ptr::write_volatile((SYSARG_VADDR + 0x468) as *mut u64, 0);
    let th = native_syscall(NT_CREATE_THREAD, thread2_entry as u64);
    let mut tmarker = 0u64;
    for _ in 0..2_000_000u64 {
        tmarker = core::ptr::read_volatile((SYSARG_VADDR + 0x468) as *const u64);
        if tmarker != 0 {
            break;
        }
        yield_now();
    }
    core::ptr::write_volatile((SYSARG_VADDR + 0x470) as *mut u64, th);
    core::ptr::write_volatile((SYSARG_VADDR + 0x478) as *mut u64, tmarker);

    // P3 demand paging: a FILE-BACKED section (arg2=1). NtMapViewOfSection RESERVES the view
    // VA without mapping the page; the first read below triggers a VMFault the executive
    // demand-pages in from the backing file — so the read returns the file's payload.
    let dsec = native_syscall2(NT_CREATE_SECTION, 0x1000, 1);
    let dview = native_syscall(NT_MAP_VIEW, dsec);
    let dpaged = if dview != 0 {
        core::ptr::read_volatile(dview as *const u64) // fault-in happens HERE
    } else {
        0
    };
    core::ptr::write_volatile((SYSARG_VADDR + 0x480) as *mut u64, dview);
    core::ptr::write_volatile((SYSARG_VADDR + 0x488) as *mut u64, dpaged);

    let ok = r0 == 1
        && r0b == 1
        && r1 == 1
        && created == 1
        && found == 1
        && ck == 1
        && sk == 1
        && val == 42
        && vm != 0
        && readback
        && t1 != 0
        && t2 >= t1
        && w1 == 0x102
        && w2 == 0
        && w3 == 0x102
        && m1 == 0
        && m2 == 0
        && m3 == 0x102
        && sv1 != 0
        && sv2 != 0
        && sec_alias
        && th != 0
        && tmarker == 0x7EAD2
        && dview != 0
        && dpaged == 0xDEAD_FACE_CAFE_F00D;
    let _ = native_syscall(SSN_DONE, ok as u64);
    park()
}

/// P3 blocking wait — the WAITER. Waits on a non-signaled event; the executive tells it to
/// block, so it PARKS on the wait notification (a real block) until the signaler wakes it,
/// then re-waits (now satisfied) and reads the signaler's handoff marker.
#[no_mangle]
#[link_section = ".text.waiter_entry"]
pub unsafe extern "C" fn waiter_entry() -> ! {
    let w_first = native_syscall(SSN_WAIT_BLOCK, BLOCK_EVENT_KEY);
    // Persist w_first to memory NOW — before the park below, which can clobber registers.
    core::ptr::write_volatile((SYSARG_VADDR + 0x510) as *mut u64, w_first);
    // Publish "the waiter has taken its first wait" so the signaler only sets the event AFTER
    // this (making the first wait deterministically observe a non-signaled event).
    core::ptr::write_volatile((SYSARG_VADDR + 0x528) as *mut u64, 1);
    if w_first != 0 {
        let _ = ep_recv(CT_WAIT_NTFN); // block until the signaler wakes us
    }
    let w_second = native_syscall(SSN_WAIT_BLOCK, BLOCK_EVENT_KEY);
    core::ptr::write_volatile((SYSARG_VADDR + 0x518) as *mut u64, w_second);
    // We could only observe the signaler's marker if we truly blocked until it ran.
    let handoff = core::ptr::read_volatile((SYSARG_VADDR + 0x500) as *const u64);
    core::ptr::write_volatile((SYSARG_VADDR + 0x520) as *mut u64, handoff);
    let _ = native_syscall(SSN_DONE_A, 0);
    park()
}

/// P3 blocking wait — the SIGNALER. Publishes a handoff marker, then sets + wakes the event.
/// Because the waiter is parked, it wakes only after this runs — and reads the marker.
#[no_mangle]
#[link_section = ".text.signaler_entry"]
pub unsafe extern "C" fn signaler_entry() -> ! {
    // Wait (yielding) until the waiter has taken its first, blocking wait — so our set lands
    // AFTER it, and the waiter genuinely parks rather than seeing a pre-signaled event.
    while core::ptr::read_volatile((SYSARG_VADDR + 0x528) as *const u64) == 0 {
        yield_now();
    }
    core::ptr::write_volatile((SYSARG_VADDR + 0x500) as *mut u64, 0xB0B);
    let _ = native_syscall(SSN_SET_WAKE, BLOCK_EVENT_KEY);
    let _ = native_syscall(SSN_DONE_B, 0);
    park()
}

/// The provided "ntdll" stub for NtQuerySystemTime: `mov rax,0x57; syscall; ret`. Mapped RX
/// at NTDLL_VA; the PE's IAT is resolved to point here, so the PE calls it like real code.
const NTDLL_STUB: &[u8] = &[
    0x48, 0xC7, 0xC0, 0x57, 0x00, 0x00, 0x00, // mov rax, 0x57  (NtQuerySystemTime)
    0x0F, 0x05, // syscall
    0xC3, // ret
];

/// The real NT syscall handler the dispatcher routes to (`nt_syscall::NativeSyscallHandler`).
/// This is the seam that replaces the ad-hoc broker: syscalls whose SSN is in the service table
/// are dispatched HERE (real subsystems), and everything else falls back to the broker match —
/// so syscalls migrate from fake to real one family at a time while the tree stays green. v0.1
/// covers only the trivial object calls; the registry family (real OBJECT_ATTRIBUTES copyin +
/// a real hive) lands next, then process/section/token/port against the smss trace.
/// Typed key target for the predefined machine root. This is stored inside process-local
/// `HandleObject::RegistryKey` entries; it is not a handle value.
const MACHINE_ROOT_KEY: KeyRef = 0xFFFF_FF02;
/// Typed key target for the predefined `HKEY_USERS` root (`\Registry\User`) — the container the
/// per-user hives mount INTO. advapi32's `MapDefaultKey(HKEY_USERS)` opens it by name and then
/// opens `.Default` / `<SID>` relative to it; `NtLoadKey`/`NtUnloadKey` name their target the same
/// way. Like `MACHINE_ROOT_KEY` this is a sentinel, not a hive cell: the root itself has no
/// backing regf (in NT it is a `\Registry` directory object, not a hive).
const USER_ROOT_KEY: KeyRef = 0xFFFF_FF04;
/// A registry `KeyRef` in the range `[MUTABLE_KEY_TAG, MUTABLE_KEY_TAG+MUTABLE_KEY_MAX)` names a
/// live mutable hive key; its low bits index `ExecNtHandler::mutable_key_handles`, whose entry
/// stores the owning mutable hive and cell. The range is below overlay/predefined-root targets and
/// above every mounted-hive selector.
const MUTABLE_KEY_TAG: u32 = 0x7000_0000;
const MUTABLE_KEY_MAX: u32 = 0x1000;
/// A registry `KeyRef` in the range `[OVERLAY_KEY_TAG, OVERLAY_KEY_TAG+OVERLAY_KEY_MAX)` names an
/// OVERLAY (created) key; its low bits are the index into `ExecNtHandler::overlay`. The range sits
/// far above any real cell offset and below the predefined-root sentinel targets.
const OVERLAY_KEY_TAG: u32 = 0x8000_0000;
const OVERLAY_KEY_MAX: u32 = 0x1000;
/// True if a `KeyRef` is an overlay/predefined-root target rather than a genuine mounted
/// hive cell offset. Real hive KeyRefs keep their selector below `OVERLAY_KEY_TAG`.
fn is_virtual_registry_key(kr: KeyRef) -> bool {
    (kr >= MUTABLE_KEY_TAG && kr < MUTABLE_KEY_TAG + MUTABLE_KEY_MAX) || kr >= OVERLAY_KEY_TAG
}
/// ── Mounted base hives ────────────────────────────────────────────────────────────────────────
/// FOUR REAL regf files are mounted read-only under `\Registry\Machine`: SYSTEM (::ROSSYS.HIV,
/// ~204 KiB), SOFTWARE (460 KiB), SECURITY and SAM (8 KiB each) — all read BY PATH off
/// `\reactos\system32\config`. A `KeyRef` is a cell offset inside ONE of them, so the top nibble
/// SELECTS the hive. Real cell offsets are far below 0x2000_0000 (the largest hive is 460 KiB), and
/// the tags stay below `OVERLAY_KEY_TAG` so `is_virtual_registry_key` is unchanged.
/// ★ WIDENED `0xE000_0000` -> `0xF000_0000` (batch 62). The mask must leave room for the hives
/// mounted at RUN time by `NtLoadKey` as well as the four mounted at boot, and every selector has
/// to stay strictly below [`OVERLAY_KEY_TAG`] (`0x8000_0000`) so `is_virtual_registry_key` is
/// unchanged. Four
/// tags of 3 bits gave exactly four mounts; four bits gives EIGHT (`0x0`-`0x7`), of which the four
/// boot mounts keep their existing values byte-for-byte and the odd ones are free for the
/// `\Registry\User` namespace. A widened mask is safe because a real cell offset is bounded by the
/// hive's file size and the largest hive on the image is 471040 B — three orders of magnitude
/// below the smallest tag.
pub(crate) const HIVE_SEL_MASK: u32 = 0xF000_0000;
/// Hive selector 0 — the SYSTEM hive (untagged, so every pre-existing SYSTEM `KeyRef` is unchanged).
pub(crate) const HIVE_SEL_SYSTEM: u32 = 0x0000_0000;
/// Hive selector for `\Registry\User\.Default` — the genuine `config\default` (`$$$PROTO.HIV`)
/// prototype hive `CmpInitializeHiveList` mounts on every NT boot, staged in `DEFHIVEBUF`.
pub(crate) const HIVE_SEL_USER_DEFAULT: u32 = 0x1000_0000;
/// Hive selector for `\Registry\Machine\SOFTWARE` (the 4th mount; 460 KiB, so its cell offsets stay
/// far below the 0x2000_0000 tag).
pub(crate) const HIVE_SEL_SOFTWARE: u32 = 0x2000_0000;
/// Hive selector for `\Registry\Machine\SECURITY`.
pub(crate) const HIVE_SEL_SECURITY: u32 = 0x4000_0000;
/// Hive selector for `\Registry\Machine\SAM`.
pub(crate) const HIVE_SEL_SAM: u32 = 0x6000_0000;
/// The selectors a DYNAMIC (`NtLoadKey`) mount can take, in allocation order. Same scheme as the
/// boot mounts — a dynamic mount differs only in WHEN it is created and in carrying its NT mount
/// path at run time; every consumer (`base_hive`, `resolve_key`, `registry_target_path`,
/// `open_key_from`) treats it identically.
pub(crate) const HIVE_SEL_DYNAMIC: [u32; 2] = [0x3000_0000, 0x5000_0000];
const _: () =
    assert!(HIVE_SEL_DYNAMIC[0] < OVERLAY_KEY_TAG && HIVE_SEL_DYNAMIC[1] < OVERLAY_KEY_TAG);
const _: () =
    assert!(HIVE_SEL_SAM < MUTABLE_KEY_TAG && MUTABLE_KEY_TAG + MUTABLE_KEY_MAX <= OVERLAY_KEY_TAG);
/// The hive selector bits of a `KeyRef` (meaningful only for a mounted-hive key).
pub(crate) fn hive_sel(kr: KeyRef) -> u32 {
    kr & HIVE_SEL_MASK
}
/// The in-hive cell offset of a `KeyRef` (strips the selector).
pub(crate) fn hive_cell(kr: KeyRef) -> KeyRef {
    kr & !HIVE_SEL_MASK
}
/// The NT mount path of a BOOT hive selector (the prefix its `key_path` results hang off).
/// Dynamic mounts carry their path at run time — see `ExecNtHandler::hive_mount_path`.
pub(crate) fn hive_mount(sel: u32) -> &'static str {
    match sel {
        HIVE_SEL_SOFTWARE => r"\Registry\Machine\SOFTWARE",
        HIVE_SEL_SECURITY => r"\Registry\Machine\SECURITY",
        HIVE_SEL_SAM => r"\Registry\Machine\SAM",
        HIVE_SEL_USER_DEFAULT => r"\Registry\User\.Default",
        _ => r"\Registry\Machine\System",
    }
}

pub(crate) fn hive_kind_for_selector(sel: u32) -> HiveKind {
    match sel {
        HIVE_SEL_SOFTWARE => HiveKind::Software,
        HIVE_SEL_SECURITY => HiveKind::Security,
        HIVE_SEL_SAM => HiveKind::Sam,
        HIVE_SEL_USER_DEFAULT => HiveKind::Default,
        sel if HIVE_SEL_DYNAMIC.iter().any(|candidate| *candidate == sel) => HiveKind::Default,
        _ => HiveKind::System,
    }
}

pub(crate) fn mount_mutable_regf_hive(
    mutable_hives: &mut MutableHiveSet,
    sel: u32,
    mount_path: &str,
    regf: &RegfHive<'_>,
) {
    let (hive, _stats) = import_regf_into_hive(regf, hive_kind_for_selector(sel));
    mutable_hives.mount(mount_path, sel, hive);
}

/// ── `NtLoadKey` / `NtUnloadKey` — the run-time hive mounts ────────────────────────────────────
/// One mounted `regf` hive that is NOT one of the four boot mounts: its selector, the NT path it
/// is mounted at, the file it was loaded from, and the parsed navigator over its bytes.
///
/// `\Registry\User\.Default` is mounted through this SAME table at boot (it is not a special
/// case — it simply has `dynamic == false`, so `NtUnloadKey` refuses to detach it, exactly as NT
/// refuses to unload a hive it did not load on request).
pub(crate) struct HiveMount {
    /// This mount's `HIVE_SEL_*` tag; `hive_sel(KeyRef) == sel` selects it.
    pub(crate) sel: u32,
    /// The canonical (folded) NT path the hive is mounted at, e.g. `\registry\user\.default`.
    pub(crate) canon: alloc::string::String,
    /// The original-case NT mount path, used to build `registry_target_path` results.
    pub(crate) mount: alloc::string::String,
    /// The NT file path `NtLoadKey` read the hive out of (empty for a boot mount).
    pub(crate) file: alloc::string::String,
    /// The read-only navigator over this mount's bytes when it came from a `regf` image.
    ///
    /// Hives loaded from an `nt-hive-core` checkpoint are mutable-only: `MutableHiveSet` owns their
    /// cells, and ordinary opens resolve through that authority before the borrowed-regf fallback.
    pub(crate) hive: Option<RegfHive<'static>>,
    /// Which static hive slot backs it (dynamic mounts only), so `NtUnloadKey` can free it.
    pub(crate) slot: Option<usize>,
    /// `true` iff created by `NtLoadKey` — the only mounts `NtUnloadKey` may detach.
    pub(crate) dynamic: bool,
}

/// Backing storage for a dynamically loaded hive. `RegfHive` BORROWS its bytes for the life of the
/// mount, and the writable volume's own buffers live on the bump heap (which the service loop
/// resets and which a later write could reallocate), so a loaded hive is COPIED into one of these
/// executive-lifetime statics. Sized for the largest per-user hive this image can produce: the
/// `config\default` prototype is 139264 B.
pub(crate) const USER_HIVE_SLOT_BYTES: usize = 192 * 1024;
pub(crate) const USER_HIVE_SLOTS: usize = HIVE_SEL_DYNAMIC.len();
pub(crate) static mut USER_HIVE_BUF: [[u8; USER_HIVE_SLOT_BYTES]; USER_HIVE_SLOTS] =
    [[0; USER_HIVE_SLOT_BYTES]; USER_HIVE_SLOTS];
/// Which slots are in use (bit per slot), so a load/unload pair really recycles storage.
pub(crate) static USER_HIVE_SLOT_USED: AtomicU64 = AtomicU64::new(0);

/// ★ BYPASS SWITCH for the `NtLoadKey*`/`NtUnloadKey*` family. `false` leaves the hive-load SSNs
/// OUT of the service table — exactly the pre-batch state, in which `RegLoadKeyW` reaches an
/// unserviced SSN. `exec_ntloadkey_serviced` FAILs. Verified.
pub(crate) const NT_LOAD_KEY_SERVICED: bool = true;

/// `NtLoadKey(POBJECT_ATTRIBUTES TargetKey, POBJECT_ATTRIBUTES SourceFile)` — ReactOS
/// `ntoskrnl/config/ntapi.c:1129` (→ `NtLoadKeyEx`, which requires `SeRestorePrivilege`).
pub const SSN_NT_LOAD_KEY: u64 = 102;
/// `NtLoadKey2(..., ULONG Flags)` — same load path with hive flags.
pub const SSN_NT_LOAD_KEY2: u64 = 103;
/// `NtLoadKeyEx(..., ULONG Flags, HANDLE TrustClassKey)` — same load path plus the trust-class arg.
pub const SSN_NT_LOAD_KEY_EX: u64 = 104;
/// `NtUnloadKey(POBJECT_ATTRIBUTES TargetKey)` — `ntoskrnl/config/ntapi.c:1789` (→ `NtUnloadKey2`,
/// which also requires `SeRestorePrivilege`).
pub const SSN_NT_UNLOAD_KEY: u64 = 272;
/// `NtUnloadKey2(POBJECT_ATTRIBUTES TargetKey, ULONG Flags)`.
pub const SSN_NT_UNLOAD_KEY2: u64 = 273;
/// `NtUnloadKeyEx(POBJECT_ATTRIBUTES TargetKey, HANDLE Event)`.
pub const SSN_NT_UNLOAD_KEY_EX: u64 = 274;
/// SCM driver control (`services.exe`): load/unload a service key under
/// `\Registry\Machine\System\CurrentControlSet\Services`.
pub const SSN_NT_LOAD_DRIVER: u64 = 101;
pub const SSN_NT_UNLOAD_DRIVER: u64 = 271;

/// Print a `str`'s printable ASCII to the debug console (`?` for anything else) — registry mount
/// paths and hive file names are runtime strings, so the trace has to be able to show them.
pub(crate) fn print_ascii_str(s: &str) {
    for byte in s.bytes() {
        debug_put_char(if (0x20..0x7f).contains(&byte) {
            byte
        } else {
            b'?'
        });
    }
}

fn registry_dword_from_bytes(data: &[u8]) -> Option<u32> {
    if data.len() < 4 {
        return None;
    }
    Some(u32::from_le_bytes([data[0], data[1], data[2], data[3]]))
}

fn registry_utf16_ascii(data: &[u8], out: &mut [u8]) -> Option<usize> {
    if data.len() < 2 {
        return None;
    }
    let mut n = 0usize;
    let mut i = 0usize;
    while i + 1 < data.len() {
        let unit = u16::from_le_bytes([data[i], data[i + 1]]);
        if unit == 0 {
            break;
        }
        if unit > 0x7f || n >= out.len() {
            return None;
        }
        let mut b = unit as u8;
        if b == b'/' {
            b = b'\\';
        }
        out[n] = b.to_ascii_lowercase();
        n += 1;
        i += 2;
    }
    if n == 0 {
        return None;
    }
    Some(n)
}

fn registry_ascii_path(path: &str, out: &mut [u8]) -> Option<usize> {
    let mut tmp = [0u8; 160];
    let mut n = 0usize;
    for mut b in path.bytes() {
        if b > 0x7f || n >= tmp.len() {
            return None;
        }
        if b == b'/' {
            b = b'\\';
        }
        tmp[n] = b.to_ascii_lowercase();
        n += 1;
    }
    if n == 0 {
        return None;
    }
    normalize_registry_ascii_path(&tmp[..n], out)
}

fn normalize_registry_ascii_path(path: &[u8], out: &mut [u8]) -> Option<usize> {
    let mut s = path;
    if s.starts_with(b"\\??\\") {
        s = &s[4..];
    }
    if s.len() >= 3 && s[1] == b':' && s[2] == b'\\' {
        s = &s[3..];
    }
    while s.first() == Some(&b'\\') {
        s = &s[1..];
    }

    let mut prefixed = [0u8; 180];
    let normalized = if let Some(rest) = s.strip_prefix(b"%systemroot%\\") {
        let prefix = b"reactos\\";
        if prefix.len() + rest.len() > prefixed.len() {
            return None;
        }
        prefixed[..prefix.len()].copy_from_slice(prefix);
        prefixed[prefix.len()..prefix.len() + rest.len()].copy_from_slice(rest);
        &prefixed[..prefix.len() + rest.len()]
    } else if let Some(rest) = s.strip_prefix(b"systemroot\\") {
        let prefix = b"reactos\\";
        if prefix.len() + rest.len() > prefixed.len() {
            return None;
        }
        prefixed[..prefix.len()].copy_from_slice(prefix);
        prefixed[prefix.len()..prefix.len() + rest.len()].copy_from_slice(rest);
        &prefixed[..prefix.len() + rest.len()]
    } else if s.starts_with(b"system32\\") {
        let prefix = b"reactos\\";
        if prefix.len() + s.len() > prefixed.len() {
            return None;
        }
        prefixed[..prefix.len()].copy_from_slice(prefix);
        prefixed[prefix.len()..prefix.len() + s.len()].copy_from_slice(s);
        &prefixed[..prefix.len() + s.len()]
    } else {
        s
    };

    if normalized.is_empty() || normalized.len() > out.len() {
        return None;
    }
    out[..normalized.len()].copy_from_slice(normalized);
    Some(normalized.len())
}

fn system_hive_regf() -> Option<RegfHive<'static>> {
    let hive_size = REAL_HIVE_SIZE.load(Ordering::Relaxed) as usize;
    if hive_size == 0 {
        return None;
    }
    let bytes = unsafe { core::slice::from_raw_parts(HIVEBUF_VADDR as *const u8, hive_size) };
    RegfHive::new(bytes)
}

