#[derive(Clone, Copy)]
struct InlineAscii<const N: usize> {
    bytes: [u8; N],
    len: usize,
}

impl<const N: usize> InlineAscii<N> {
    const fn empty() -> Self {
        Self {
            bytes: [0; N],
            len: 0,
        }
    }

    fn set_bytes(&mut self, src: &[u8]) -> bool {
        if src.len() > N || src.iter().any(|&b| b > 0x7f) {
            return false;
        }
        self.bytes[..src.len()].copy_from_slice(src);
        self.len = src.len();
        true
    }

    fn set_str(&mut self, src: &str) -> bool {
        self.set_bytes(src.as_bytes())
    }

    fn as_bytes(&self) -> &[u8] {
        &self.bytes[..self.len]
    }

    fn as_str(&self) -> &str {
        core::str::from_utf8(self.as_bytes()).unwrap_or("")
    }
}

fn ascii_starts_with_ignore_case(text: &[u8], prefix: &[u8]) -> bool {
    if text.len() < prefix.len() {
        return false;
    }
    let mut i = 0usize;
    while i < prefix.len() {
        if text[i].to_ascii_uppercase() != prefix[i].to_ascii_uppercase() {
            return false;
        }
        i += 1;
    }
    true
}

#[derive(Clone, Copy)]
struct InlineDriverDevnodeSpec {
    instance_id: InlineAscii<BOOT_DRIVER_DEVNODE_PATH_MAX>,
    pdo_name: InlineAscii<BOOT_DRIVER_DEVNODE_PATH_MAX>,
    pdo_name_present: bool,
    driver_key: InlineAscii<BOOT_DRIVER_DEVNODE_PATH_MAX>,
    driver_key_present: bool,
    linkage_export: InlineAscii<BOOT_DRIVER_DEVNODE_PATH_MAX>,
    linkage_export_present: bool,
    hardware_ids: [InlineAscii<BOOT_DRIVER_ID_BYTES_MAX>; BOOT_DRIVER_ID_MAX],
    hardware_id_count: usize,
    compatible_ids: [InlineAscii<BOOT_DRIVER_ID_BYTES_MAX>; BOOT_DRIVER_ID_MAX],
    compatible_id_count: usize,
}

impl InlineDriverDevnodeSpec {
    const fn empty() -> Self {
        Self {
            instance_id: InlineAscii::empty(),
            pdo_name: InlineAscii::empty(),
            pdo_name_present: false,
            driver_key: InlineAscii::empty(),
            driver_key_present: false,
            linkage_export: InlineAscii::empty(),
            linkage_export_present: false,
            hardware_ids: [InlineAscii::empty(); BOOT_DRIVER_ID_MAX],
            hardware_id_count: 0,
            compatible_ids: [InlineAscii::empty(); BOOT_DRIVER_ID_MAX],
            compatible_id_count: 0,
        }
    }

    fn hardware_refs<'a>(&'a self, out: &'a mut [&'a str; BOOT_DRIVER_ID_MAX]) -> &'a [&'a str] {
        let mut n = 0usize;
        while n < self.hardware_id_count && n < BOOT_DRIVER_ID_MAX {
            out[n] = self.hardware_ids[n].as_str();
            n += 1;
        }
        &out[..n]
    }

    fn compatible_refs<'a>(&'a self, out: &'a mut [&'a str; BOOT_DRIVER_ID_MAX]) -> &'a [&'a str] {
        let mut n = 0usize;
        while n < self.compatible_id_count && n < BOOT_DRIVER_ID_MAX {
            out[n] = self.compatible_ids[n].as_str();
            n += 1;
        }
        &out[..n]
    }
}

#[derive(Clone, Copy)]
struct InlineDriverLaunchSpec {
    service_name: InlineAscii<BOOT_DRIVER_SERVICE_NAME_MAX>,
    class_guid: InlineAscii<BOOT_DRIVER_CLASS_GUID_MAX>,
    class_guid_present: bool,
    driver_object_path: InlineAscii<BOOT_DRIVER_OBJECT_PATH_MAX>,
    image_path: InlineAscii<BOOT_DRIVER_IMAGE_PATH_MAX>,
    class: driver_launch::DriverClass,
    devnodes: [InlineDriverDevnodeSpec; BOOT_DRIVER_DEVNODE_MAX],
    devnode_count: usize,
}

impl InlineDriverLaunchSpec {
    const fn empty() -> Self {
        Self {
            service_name: InlineAscii::empty(),
            class_guid: InlineAscii::empty(),
            class_guid_present: false,
            driver_object_path: InlineAscii::empty(),
            image_path: InlineAscii::empty(),
            class: driver_launch::DriverClass::Fsd,
            devnodes: [InlineDriverDevnodeSpec::empty(); BOOT_DRIVER_DEVNODE_MAX],
            devnode_count: 0,
        }
    }
}

fn inline_launch_spec_has_pci_devnode(spec: &InlineDriverLaunchSpec) -> bool {
    for devnode in &spec.devnodes[..spec.devnode_count] {
        if ascii_starts_with_ignore_case(devnode.instance_id.as_bytes(), b"PCI\\") {
            return true;
        }
    }
    false
}

#[derive(Clone, Copy)]
struct InlineDriverLaunchPlan {
    specs: [InlineDriverLaunchSpec; BOOT_DRIVER_PLAN_MAX],
    len: usize,
}

impl InlineDriverLaunchPlan {
    const fn empty() -> Self {
        Self {
            specs: [InlineDriverLaunchSpec::empty(); BOOT_DRIVER_PLAN_MAX],
            len: 0,
        }
    }

    fn push(&mut self, spec: InlineDriverLaunchSpec) -> bool {
        if self.len >= BOOT_DRIVER_PLAN_MAX {
            return false;
        }
        self.specs[self.len] = spec;
        self.len += 1;
        true
    }

    fn as_slice(&self) -> &[InlineDriverLaunchSpec] {
        &self.specs[..self.len]
    }
}

static mut SYSTEM_BOOT_DRIVER_PLAN: InlineDriverLaunchPlan = InlineDriverLaunchPlan::empty();
static mut CONFIG_BOOT_PNP_DRIVER_PLAN: InlineDriverLaunchPlan = InlineDriverLaunchPlan::empty();

const WIN32_SERVICE_PROCESS_KIND_NONE: u8 = 0;
const WIN32_SERVICE_PROCESS_KIND_OWN: u8 = 1;
const WIN32_SERVICE_PROCESS_KIND_SHARED: u8 = 2;

#[derive(Clone, Copy)]
struct InlineServiceSelectionReport {
    auto_win32_count: u64,
    auto_win32_name: InlineAscii<BOOT_DRIVER_SERVICE_NAME_MAX>,
    auto_win32_image_path: InlineAscii<BOOT_DRIVER_IMAGE_PATH_MAX>,
    auto_win32_nt_image_path: InlineAscii<BOOT_DRIVER_IMAGE_PATH_MAX>,
    auto_win32_command_line: InlineAscii<BOOT_DRIVER_IMAGE_PATH_MAX>,
    auto_win32_process_kind: u8,
    auto_win32_interactive: bool,
    demand_win32_count: u64,
    demand_win32_name: InlineAscii<BOOT_DRIVER_SERVICE_NAME_MAX>,
    demand_win32_image_path: InlineAscii<BOOT_DRIVER_IMAGE_PATH_MAX>,
    demand_win32_nt_image_path: InlineAscii<BOOT_DRIVER_IMAGE_PATH_MAX>,
    demand_win32_command_line: InlineAscii<BOOT_DRIVER_IMAGE_PATH_MAX>,
    demand_win32_process_kind: u8,
    demand_win32_interactive: bool,
    demand_driver_count: u64,
    demand_driver_name: InlineAscii<BOOT_DRIVER_SERVICE_NAME_MAX>,
    demand_driver_image_path: InlineAscii<BOOT_DRIVER_IMAGE_PATH_MAX>,
    demand_driver_object_path: InlineAscii<BOOT_DRIVER_OBJECT_PATH_MAX>,
}

impl InlineServiceSelectionReport {
    const fn empty() -> Self {
        Self {
            auto_win32_count: 0,
            auto_win32_name: InlineAscii::empty(),
            auto_win32_image_path: InlineAscii::empty(),
            auto_win32_nt_image_path: InlineAscii::empty(),
            auto_win32_command_line: InlineAscii::empty(),
            auto_win32_process_kind: WIN32_SERVICE_PROCESS_KIND_NONE,
            auto_win32_interactive: false,
            demand_win32_count: 0,
            demand_win32_name: InlineAscii::empty(),
            demand_win32_image_path: InlineAscii::empty(),
            demand_win32_nt_image_path: InlineAscii::empty(),
            demand_win32_command_line: InlineAscii::empty(),
            demand_win32_process_kind: WIN32_SERVICE_PROCESS_KIND_NONE,
            demand_win32_interactive: false,
            demand_driver_count: 0,
            demand_driver_name: InlineAscii::empty(),
            demand_driver_image_path: InlineAscii::empty(),
            demand_driver_object_path: InlineAscii::empty(),
        }
    }

    fn auto_win32_ready(&self) -> bool {
        self.auto_win32_count != 0
            && self.auto_win32_name.len != 0
            && self.auto_win32_image_path.len != 0
            && self.auto_win32_nt_image_path.len != 0
            && self.auto_win32_command_line.len != 0
            && self.auto_win32_process_kind != WIN32_SERVICE_PROCESS_KIND_NONE
    }

    fn demand_win32_ready(&self) -> bool {
        self.demand_win32_count != 0
            && self.demand_win32_name.len != 0
            && self.demand_win32_image_path.len != 0
            && self.demand_win32_nt_image_path.len != 0
            && self.demand_win32_command_line.len != 0
            && self.demand_win32_process_kind != WIN32_SERVICE_PROCESS_KIND_NONE
    }

    fn demand_driver_ready(&self) -> bool {
        self.demand_driver_count != 0
            && self.demand_driver_name.len != 0
            && self.demand_driver_image_path.len != 0
            && self.demand_driver_object_path.len != 0
    }
}

const FILE_SYSTEM_LOAD_ORDER_GROUP: &str = "File System";

#[derive(Clone, Copy)]
struct HostedPciDmaGrant {
    frame_base: u64,
    pages: u64,
    logical: u64,
    len: u64,
}

impl HostedPciDmaGrant {
    const fn new(frame_base: u64, pages: u64, logical: u64, len: u64) -> Self {
        Self {
            frame_base,
            pages,
            logical,
            len,
        }
    }

    fn valid(&self) -> bool {
        self.frame_base != 0
            && self.pages != 0
            && self.logical != 0
            && self.len != 0
            && self.len <= self.pages.saturating_mul(0x1000)
    }
}

#[derive(Clone, Copy)]
struct HostedPciDmaIommuMap {
    io_space_cap: u64,
    mint_err: u64,
    iopt_err: u64,
    map_io_err: u64,
}

impl HostedPciDmaIommuMap {
    const fn failed() -> Self {
        Self {
            io_space_cap: 0,
            mint_err: 1,
            iopt_err: 1,
            map_io_err: 1,
        }
    }

    fn complete(&self) -> bool {
        self.io_space_cap != 0 && self.mint_err == 0 && self.iopt_err == 0 && self.map_io_err == 0
    }
}

#[derive(Clone, Copy)]
struct HostedPciHardwareGrant {
    bus: u8,
    dev: u8,
    func: u8,
    mmio_phys: u64,
    mmio_frame_base: u64,
    mmio_pages: u64,
    interrupt_vector: u32,
    interrupt_latched: bool,
    dma_frame_base: u64,
    dma_pages: u64,
    dma_logical: u64,
    dma_len: u64,
}

impl HostedPciHardwareGrant {
    fn for_device(
        device: &nt_pnp::PciDevice,
        mmio_frame_base: u64,
        mmio_pages: u64,
        interrupt_vector: u32,
        interrupt_latched: bool,
        dma: Option<HostedPciDmaGrant>,
    ) -> Option<Self> {
        let mem_bar = device.first_memory_bar()?;
        if mmio_frame_base == 0
            || mmio_pages == 0
            || mem_bar.size == 0
            || mem_bar.size > mmio_pages.saturating_mul(0x1000)
            || interrupt_vector == 0
        {
            return None;
        }
        let (dma_frame_base, dma_pages, dma_logical, dma_len) = match dma {
            Some(dma) if dma.valid() => (dma.frame_base, dma.pages, dma.logical, dma.len),
            Some(_) => return None,
            None => (0, 0, 0, 0),
        };
        Some(Self {
            bus: device.bus,
            dev: device.dev,
            func: device.func,
            mmio_phys: mem_bar.base,
            mmio_frame_base,
            mmio_pages,
            interrupt_vector,
            interrupt_latched,
            dma_frame_base,
            dma_pages,
            dma_logical,
            dma_len,
        })
    }

    fn matches(&self, device: &nt_pnp::PciDevice) -> bool {
        self.bus == device.bus && self.dev == device.dev && self.func == device.func
    }

    fn dma_grant_valid(&self) -> bool {
        let has_dma = self.dma_frame_base != 0
            || self.dma_pages != 0
            || self.dma_logical != 0
            || self.dma_len != 0;
        !has_dma
            || (self.dma_frame_base != 0
                && self.dma_pages != 0
                && self.dma_logical != 0
                && self.dma_len != 0)
    }
}

#[derive(Default)]
struct HostedPciGrantDiscoveryReport {
    selected_devnodes: u64,
    existing_grants: u64,
    claimed_grants: u64,
    dma_grants: u64,
    dma_failures: u64,
    missing_memory_bar: u64,
    missing_interrupt: u64,
    claim_failures: u64,
}

fn hosted_pci_interrupt_vector(device: &nt_pnp::PciDevice) -> Option<u32> {
    if device.irq_line == 0 || device.irq_line == 0xff {
        None
    } else {
        Some(device.irq_line as u32)
    }
}

fn hosted_pci_request_id(device: &nt_pnp::PciDevice) -> u64 {
    ((device.bus as u64) << 8) | ((device.dev as u64) << 3) | device.func as u64
}

fn hosted_pci_dma_domain(device: &nt_pnp::PciDevice) -> u64 {
    1 + hosted_pci_request_id(device)
}

fn hosted_pci_device_by_location<'a>(
    devices: &'a [nt_pnp::PciDevice],
    bus: u8,
    dev: u8,
    func: u8,
) -> Option<&'a nt_pnp::PciDevice> {
    devices
        .iter()
        .find(|device| device.bus == bus && device.dev == dev && device.func == func)
}

unsafe fn allocate_hosted_pci_dma_grant(
    pages: u64,
    logical: u64,
    len: u64,
) -> Option<HostedPciDmaGrant> {
    if pages == 0 || len == 0 || len > pages.saturating_mul(0x1000) || logical == 0 {
        return None;
    }
    let frame_base = try_alloc_slot_run(pages)?;
    let mut page = 0u64;
    while page < pages {
        if untyped_retype_r(
            CAP_INIT_UNTYPED,
            OBJ_X86_4K_PAGE,
            PAGING_BITS,
            1,
            frame_base + page,
        ) != 0
        {
            return None;
        }
        page += 1;
    }
    Some(HostedPciDmaGrant::new(frame_base, pages, logical, len))
}

unsafe fn map_hosted_pci_dma_grant_iova(
    device: &nt_pnp::PciDevice,
    grant: HostedPciDmaGrant,
) -> HostedPciDmaIommuMap {
    if !grant.valid() {
        return HostedPciDmaIommuMap::failed();
    }
    let Some(io_space_cap) = try_alloc_slot() else {
        return HostedPciDmaIommuMap::failed();
    };
    let domain = hosted_pci_dma_domain(device);
    let io_badge = (domain << 16) | hosted_pci_request_id(device);
    let mint_err = cnode_mint_r(CAP_INIT_THREAD_CNODE, io_space_cap, SLOT_IO_SPACE, io_badge);
    let mut iopt_err = mint_err;
    if mint_err == 0 {
        for _ in 0..4 {
            let Some(iopt) = try_alloc_slot() else {
                iopt_err = 4;
                break;
            };
            let retype_err = untyped_retype_r(
                CAP_INIT_UNTYPED,
                OBJ_X86_IO_PAGE_TABLE,
                PAGING_BITS,
                1,
                iopt,
            );
            if retype_err != 0 {
                iopt_err = retype_err;
                break;
            }
            let map_err = iopt_map(iopt, io_space_cap, grant.logical);
            if map_err != 0 {
                iopt_err = map_err;
            }
        }
    }
    let mut map_io_err = if iopt_err == 0 { 0 } else { iopt_err };
    if iopt_err == 0 {
        let mut page = 0u64;
        while page < grant.pages {
            let (frame_io, copy_err) = copy_cap_r(grant.frame_base + page);
            if copy_err != 0 {
                map_io_err = copy_err;
                break;
            }
            let err = map_io(frame_io, io_space_cap, 0x3, grant.logical + page * 0x1000);
            if err != 0 {
                map_io_err = err;
            }
            page += 1;
        }
    }
    HostedPciDmaIommuMap {
        io_space_cap,
        mint_err,
        iopt_err,
        map_io_err,
    }
}

unsafe fn allocate_mapped_hosted_pci_dma_grant(
    device: &nt_pnp::PciDevice,
) -> (Option<HostedPciDmaGrant>, HostedPciDmaIommuMap) {
    let Some(grant) = allocate_hosted_pci_dma_grant(
        HOSTED_PCI_COMMON_BUFFER_PAGES,
        HOSTED_PCI_COMMON_BUFFER_IOVA,
        HOSTED_PCI_COMMON_BUFFER_LEN,
    ) else {
        return (None, HostedPciDmaIommuMap::failed());
    };
    let iommu = map_hosted_pci_dma_grant_iova(device, grant);
    if iommu.complete() {
        (Some(grant), iommu)
    } else {
        (None, iommu)
    }
}

unsafe fn discover_hosted_pci_hardware_grants_for_launch_plans(
    bi: &BootInfo,
    pci_devices: &[nt_pnp::PciDevice],
    plans: &[&InlineDriverLaunchPlan],
    grants: &mut Vec<HostedPciHardwareGrant>,
) -> HostedPciGrantDiscoveryReport {
    let mut report = HostedPciGrantDiscoveryReport::default();
    let mut seen = Vec::new();
    for plan in plans {
        for spec in plan.as_slice() {
            for devnode in &spec.devnodes[..spec.devnode_count] {
                let mut hardware_refs = [""; BOOT_DRIVER_ID_MAX];
                let hardware_refs = devnode.hardware_refs(&mut hardware_refs);
                let mut compatible_refs = [""; BOOT_DRIVER_ID_MAX];
                let compatible_refs = devnode.compatible_refs(&mut compatible_refs);
                let Some(device) = nt_pnp::find_pci_device_for_devnode(
                    pci_devices,
                    devnode.instance_id.as_str(),
                    hardware_refs,
                    compatible_refs,
                ) else {
                    continue;
                };
                let key = (device.bus, device.dev, device.func);
                if seen.iter().any(|existing| *existing == key) {
                    continue;
                }
                seen.push(key);
                report.selected_devnodes += 1;
                if grants.iter().any(|grant| grant.matches(device)) {
                    report.existing_grants += 1;
                    continue;
                }
                let Some(mem_bar) = device.first_memory_bar() else {
                    report.missing_memory_bar += 1;
                    continue;
                };
                let Some(interrupt_vector) = hosted_pci_interrupt_vector(device) else {
                    report.missing_interrupt += 1;
                    continue;
                };
                let mmio_pages = mem_bar.size.div_ceil(0x1000).max(1);
                let mmio_frame_base = claim_device_frame_caps(bi, mem_bar.base, mmio_pages);
                if mmio_frame_base == 0 {
                    report.claim_failures += 1;
                    continue;
                }
                let (dma_grant, dma_iommu) = allocate_mapped_hosted_pci_dma_grant(device);
                if let Some(dma) = dma_grant {
                    report.dma_grants += 1;
                    let Some(grant) = HostedPciHardwareGrant::for_device(
                        device,
                        mmio_frame_base,
                        mmio_pages,
                        interrupt_vector,
                        false,
                        Some(dma),
                    ) else {
                        report.claim_failures += 1;
                        continue;
                    };
                    grants.push(grant);
                    report.claimed_grants += 1;
                } else {
                    report.dma_failures += 1;
                    print_str(b"[driver-launch] hosted PCI DMA grant failed bus=");
                    print_u64(device.bus as u64);
                    print_str(b" dev=");
                    print_u64(device.dev as u64);
                    print_str(b" func=");
                    print_u64(device.func as u64);
                    print_str(b" mint=");
                    print_u64(dma_iommu.mint_err);
                    print_str(b" iopt=");
                    print_u64(dma_iommu.iopt_err);
                    print_str(b" map=");
                    print_u64(dma_iommu.map_io_err);
                    print_str(b"\n");
                    report.claim_failures += 1;
                }
            }
        }
    }
    report
}

#[derive(Default)]
struct HostedPciWindowPublishReport {
    selected_devnodes: u64,
    published_windows: u64,
    missing_grants: u64,
    pci_va_exhausted: bool,
    selected_root_devnodes: u64,
    published_root_windows: u64,
    missing_root_grants: u64,
    root_va_exhausted: bool,
}

unsafe fn publish_hosted_pnp_context_for_launch_plans(
    pci_devices: &[nt_pnp::PciDevice],
    plans: &[&InlineDriverLaunchPlan],
    grants: &[HostedPciHardwareGrant],
) -> HostedPciWindowPublishReport {
    let mut report = HostedPciWindowPublishReport::default();
    let mut windows: Vec<HostedPnpPciResourceWindow> = Vec::new();
    let mut root_windows: Vec<HostedPnpRootResourceWindow> = Vec::new();
    let mut resource_vas = HostedPnpResourceVaAllocator::default();
    for plan in plans {
        for spec in plan.as_slice() {
            for devnode in &spec.devnodes[..spec.devnode_count] {
                let mut hardware_refs = [""; BOOT_DRIVER_ID_MAX];
                let hardware_refs = devnode.hardware_refs(&mut hardware_refs);
                let mut compatible_refs = [""; BOOT_DRIVER_ID_MAX];
                let compatible_refs = devnode.compatible_refs(&mut compatible_refs);
                if let Some(device) = nt_pnp::find_pci_device_for_devnode(
                    pci_devices,
                    devnode.instance_id.as_str(),
                    hardware_refs,
                    compatible_refs,
                ) {
                    report.selected_devnodes += 1;
                    if windows.iter().any(|window| window.matches(device)) {
                        continue;
                    }
                    let Some(grant) = grants.iter().find(|grant| grant.matches(device)) else {
                        report.missing_grants += 1;
                        continue;
                    };
                    let Some(mem_bar) = device.first_memory_bar() else {
                        report.missing_grants += 1;
                        continue;
                    };
                    if grant.mmio_phys != mem_bar.base
                        || grant.mmio_frame_base == 0
                        || !grant.dma_grant_valid()
                    {
                        report.missing_grants += 1;
                        continue;
                    }
                    let needs_dma = grant.dma_frame_base != 0
                        || grant.dma_pages != 0
                        || grant.dma_logical != 0
                        || grant.dma_len != 0;
                    let Some(mmio_va) = resource_vas.allocate_component_window() else {
                        report.pci_va_exhausted = true;
                        continue;
                    };
                    let dma_va = if needs_dma {
                        let Some(dma_va) = resource_vas.allocate_component_window() else {
                            report.pci_va_exhausted = true;
                            continue;
                        };
                        dma_va
                    } else {
                        0
                    };
                    let Some(window) = HostedPnpPciResourceWindow::new(
                        device.bus,
                        device.dev,
                        device.func,
                        grant.mmio_phys,
                        grant.mmio_frame_base,
                        grant.mmio_pages,
                        mmio_va,
                        grant.interrupt_vector,
                        grant.interrupt_latched,
                        grant.dma_frame_base,
                        grant.dma_pages,
                        dma_va,
                        grant.dma_logical,
                        grant.dma_len,
                    ) else {
                        report.missing_grants += 1;
                        continue;
                    };
                    windows.push(window);
                    continue;
                }

                let Some(profile) = root_bus_resource_profile_for_devnode(
                    devnode.instance_id.as_str(),
                    hardware_refs,
                    compatible_refs,
                ) else {
                    continue;
                };
                report.selected_root_devnodes += 1;
                if root_windows
                    .iter()
                    .any(|window| window.matches_profile(profile))
                {
                    continue;
                }
                let Some((mmio_va, dma_va)) = resource_vas.allocate_component_window_pair() else {
                    report.root_va_exhausted = true;
                    continue;
                };
                let Some(seed_va) = resource_vas.allocate_root_seed_window() else {
                    report.root_va_exhausted = true;
                    continue;
                };
                let Some(dma_logical) = resource_vas.allocate_root_dma_logical() else {
                    report.root_va_exhausted = true;
                    continue;
                };
                let mmio_frame = alloc_seeded_root_dma_mmio_frame(seed_va);
                let (dma_frame, dma_frame_err) = alloc_frame_r();
                if mmio_frame == 0 || dma_frame_err != 0 {
                    report.missing_root_grants += 1;
                    continue;
                }
                let Some(window) = HostedPnpRootResourceWindow::new(
                    profile,
                    mmio_frame,
                    profile.mmio_len.div_ceil(0x1000).max(1),
                    mmio_va,
                    seed_va,
                    ROOT_DMA_PROOF_INTERRUPT_VECTOR,
                    false,
                    dma_frame,
                    1,
                    dma_va,
                    dma_logical,
                    0x1000,
                ) else {
                    report.missing_root_grants += 1;
                    continue;
                };
                root_windows.push(window);
            }
        }
    }
    report.published_windows = windows.len() as u64;
    report.published_root_windows = root_windows.len() as u64;
    publish_hosted_pnp_resource_context(pci_devices, windows.as_slice(), root_windows.as_slice());
    report
}

fn driver_class_from_config(class: DriverServiceClass) -> driver_launch::DriverClass {
    match class {
        DriverServiceClass::FileSystem => driver_launch::DriverClass::Fsd,
        DriverServiceClass::Device => driver_launch::DriverClass::Device,
    }
}

fn driver_launch_spec_from_config_driver_spec(
    service: &nt_config_manager::DriverServiceLaunchSpec,
    out_path: &mut [u8],
    max_start: u32,
) -> Option<(usize, driver_launch::DriverClass)> {
    if service.start_type > max_start || service.start_type >= SERVICE_DISABLED {
        return None;
    };
    let class = driver_class_from_config(service.class);
    let path_len = registry_ascii_path(&service.image_path, out_path)?;
    Some((path_len, class))
}

fn driver_launch_spec_from_service_metadata(
    service: &nt_config_manager::ServiceMetadata,
    out_path: &mut [u8],
    max_start: u32,
) -> Option<(usize, driver_launch::DriverClass)> {
    let service = service.driver_launch_spec()?;
    driver_launch_spec_from_config_driver_spec(&service, out_path, max_start)
}

fn current_driver_host_can_boot_launch(
    cm: &nt_config_manager::ConfigManager,
    service: &nt_config_manager::ServiceMetadata,
) -> bool {
    match service.driver_service_class() {
        Some(DriverServiceClass::FileSystem) => service
            .load_order_group
            .as_deref()
            .is_some_and(|group| group.eq_ignore_ascii_case(FILE_SYSTEM_LOAD_ORDER_GROUP)),
        Some(DriverServiceClass::Device) => cm.service_has_devnodes(&service.name),
        None => false,
    }
}

fn owned_driver_launch_spec_from_config_driver_spec(
    service: nt_config_manager::DriverServiceLaunchSpec,
    max_start: u32,
    devnodes: alloc::vec::Vec<DriverServiceDevnodeSpec>,
) -> Option<DriverServiceLaunchSpec> {
    let mut image_path = [0u8; 180];
    let (image_path_len, class) =
        driver_launch_spec_from_config_driver_spec(&service, &mut image_path, max_start)?;
    let driver_object_path = service.driver_object_path;
    let service_name = service.service_name;
    let class_guid = service.class_guid;
    Some(DriverServiceLaunchSpec {
        service_name,
        class_guid,
        driver_object_path,
        image_path: alloc::vec::Vec::from(&image_path[..image_path_len]),
        class,
        devnodes,
    })
}

fn driver_service_devnode_specs(
    cm: &nt_config_manager::ConfigManager,
    service_name: &str,
) -> alloc::vec::Vec<DriverServiceDevnodeSpec> {
    cm.devnodes_for_service(service_name)
        .into_iter()
        .map(|devnode| DriverServiceDevnodeSpec {
            instance_id: devnode.instance_id.clone(),
            pdo_name: devnode.pdo_name.clone(),
            driver_key: devnode.driver_key.clone(),
            linkage_export: cm.devnode_linkage_export(devnode),
            hardware_ids: devnode.hardware_ids.clone(),
            compatible_ids: devnode.compatible_ids.clone(),
        })
        .collect()
}

fn copy_inline_string_list<const N: usize>(
    src: &[alloc::string::String],
    dst: &mut [InlineAscii<N>],
) -> usize {
    let mut count = 0usize;
    for value in src {
        if count >= dst.len() {
            break;
        }
        if dst[count].set_str(value) {
            count += 1;
        }
    }
    count
}

fn inline_devnode_spec_from_record(
    cm: &nt_config_manager::ConfigManager,
    devnode: &nt_config_manager::DevnodeRecord,
) -> Option<InlineDriverDevnodeSpec> {
    let mut dst = InlineDriverDevnodeSpec::empty();
    if !dst.instance_id.set_str(&devnode.instance_id) {
        return None;
    }
    if let Some(pdo_name) = devnode.pdo_name.as_deref() {
        dst.pdo_name_present = dst.pdo_name.set_str(pdo_name);
    }
    if let Some(driver_key) = devnode.driver_key.as_deref() {
        if !dst.driver_key.set_str(driver_key) {
            return None;
        }
        dst.driver_key_present = true;
    }
    if let Some(linkage_export) = cm.devnode_linkage_export(devnode).as_deref() {
        if !dst.linkage_export.set_str(linkage_export) {
            return None;
        }
        dst.linkage_export_present = true;
    }
    dst.hardware_id_count = copy_inline_string_list(&devnode.hardware_ids, &mut dst.hardware_ids);
    dst.compatible_id_count =
        copy_inline_string_list(&devnode.compatible_ids, &mut dst.compatible_ids);
    Some(dst)
}

fn fill_inline_devnodes_from_records(
    cm: &nt_config_manager::ConfigManager,
    records: &[nt_config_manager::DevnodeRecord],
    out: &mut [InlineDriverDevnodeSpec],
) -> usize {
    let mut count = 0usize;
    for devnode in records {
        if count >= out.len() {
            break;
        }
        if let Some(dst) = inline_devnode_spec_from_record(cm, devnode) {
            out[count] = dst;
            count += 1;
        }
    }
    count
}

fn fill_inline_devnodes(
    cm: &nt_config_manager::ConfigManager,
    service_name: &str,
    out: &mut [InlineDriverDevnodeSpec],
) -> usize {
    let mut count = 0usize;
    for devnode in cm.devnodes_for_service(service_name) {
        if count >= out.len() {
            break;
        }
        if let Some(dst) = inline_devnode_spec_from_record(cm, devnode) {
            out[count] = dst;
            count += 1;
        }
    }
    count
}

fn inline_driver_launch_spec_from_service_metadata(
    cm: &nt_config_manager::ConfigManager,
    service: &nt_config_manager::ServiceMetadata,
    max_start: u32,
) -> Option<InlineDriverLaunchSpec> {
    let mut image_path = [0u8; BOOT_DRIVER_IMAGE_PATH_MAX];
    let (image_path_len, class) =
        driver_launch_spec_from_service_metadata(service, &mut image_path, max_start)?;
    let driver_object_path = service.driver_object_path()?;
    let mut spec = InlineDriverLaunchSpec::empty();
    if !spec.service_name.set_str(&service.name)
        || !spec.driver_object_path.set_str(&driver_object_path)
        || !spec.image_path.set_bytes(&image_path[..image_path_len])
    {
        return None;
    }
    if let Some(class_guid) = service.class_guid.as_deref() {
        if !spec.class_guid.set_str(class_guid) {
            return None;
        }
        spec.class_guid_present = true;
    }
    spec.class = class;
    spec.devnode_count = fill_inline_devnodes(cm, &service.name, &mut spec.devnodes);
    Some(spec)
}

fn inline_driver_launch_spec_from_pnp_binding(
    cm: &nt_config_manager::ConfigManager,
    binding: nt_config_manager::PnpDriverBinding,
    max_start: u32,
) -> Option<InlineDriverLaunchSpec> {
    let mut image_path = [0u8; BOOT_DRIVER_IMAGE_PATH_MAX];
    let (image_path_len, class) =
        driver_launch_spec_from_service_metadata(&binding.service, &mut image_path, max_start)?;
    let driver_object_path = binding.service.driver_object_path()?;
    let mut spec = InlineDriverLaunchSpec::empty();
    if !spec.service_name.set_str(&binding.service.name)
        || !spec.driver_object_path.set_str(&driver_object_path)
        || !spec.image_path.set_bytes(&image_path[..image_path_len])
    {
        return None;
    }
    if let Some(class_guid) = binding.service.class_guid.as_deref() {
        if !spec.class_guid.set_str(class_guid) {
            return None;
        }
        spec.class_guid_present = true;
    }
    spec.class = class;
    spec.devnode_count =
        fill_inline_devnodes_from_records(cm, &binding.devnodes, &mut spec.devnodes);
    (spec.devnode_count != 0).then_some(spec)
}

fn config_hive_config_manager() -> Option<nt_config_manager::ConfigManager> {
    let hive_size =
        unsafe { core::ptr::read_volatile((STORAGE_SHARED_VADDR + 0x18) as *const u32) } as usize;
    if hive_size == 0 || hive_size > STORAGE_HIVE_IMAGE_CAP {
        return None;
    }
    let hive_bytes = unsafe {
        core::slice::from_raw_parts(
            (STORAGE_SHARED_VADDR + STORAGE_HIVE_IMAGE_OFFSET) as *const u8,
            hive_size,
        )
    };
    let hive = nt_hive_core::decode_image(hive_bytes).ok()?;
    let mut cm = nt_config_manager::ConfigManager::new();
    if nt_hive_core::import_control_set_services_into_config_manager(
        &hive,
        &mut cm,
        nt_hive_core::CURRENT_CONTROL_SET_TARGET,
    ) == 0
    {
        return None;
    }
    let _ = nt_hive_core::import_control_set_enum_into_config_manager(
        &hive,
        &mut cm,
        nt_hive_core::CURRENT_CONTROL_SET_TARGET,
    );
    let _ = nt_hive_core::import_control_set_class_into_config_manager(
        &hive,
        &mut cm,
        nt_hive_core::CURRENT_CONTROL_SET_TARGET,
    );
    Some(cm)
}

fn config_hive_boot_system_driver_launch_spec(
    out_path: &mut [u8],
) -> Option<ConfigHiveDriverLaunchSpec> {
    let cm = config_hive_config_manager()?;
    let service = cm
        .boot_system_driver_candidates()
        .into_iter()
        .find(|service| service.driver_service_class() == Some(DriverServiceClass::FileSystem))?;
    let (image_path_len, class) =
        driver_launch_spec_from_service_metadata(&service, out_path, SERVICE_SYSTEM_START)?;
    let driver_object_path = service.driver_object_path()?;
    Some(ConfigHiveDriverLaunchSpec {
        service_name: service.name,
        driver_object_path,
        image_path_len,
        class,
    })
}

fn config_hive_boot_system_pnp_driver_launch_plan() -> &'static InlineDriverLaunchPlan {
    let heap_mark = allocator::mark();
    let plan = unsafe { &mut *core::ptr::addr_of_mut!(CONFIG_BOOT_PNP_DRIVER_PLAN) };
    *plan = InlineDriverLaunchPlan::empty();
    if let Some(cm) = config_hive_config_manager() {
        for binding in cm.boot_system_pnp_driver_bindings() {
            if let Some(spec) =
                inline_driver_launch_spec_from_pnp_binding(&cm, binding, SERVICE_SYSTEM_START)
            {
                if !plan.push(spec) {
                    break;
                }
            }
        }
    }
    unsafe { allocator::reset_to(heap_mark) };
    plan
}

fn system_hive_config_manager() -> Option<nt_config_manager::ConfigManager> {
    let hive = system_hive_regf()?;
    let mut cm = nt_config_manager::ConfigManager::new();
    let counts = nt_hive_regf::import_control_set_boot_config_into_config_manager(
        &hive,
        &mut cm,
        nt_hive_core::CURRENT_CONTROL_SET_TARGET,
    );
    if counts.services == 0 {
        return None;
    }
    Some(cm)
}

fn win32_service_process_kind_code(kind: nt_config_manager::Win32ServiceProcessKind) -> u8 {
    match kind {
        nt_config_manager::Win32ServiceProcessKind::Own => WIN32_SERVICE_PROCESS_KIND_OWN,
        nt_config_manager::Win32ServiceProcessKind::Shared => WIN32_SERVICE_PROCESS_KIND_SHARED,
    }
}

fn win32_service_process_kind_label(kind: u8) -> &'static [u8] {
    match kind {
        WIN32_SERVICE_PROCESS_KIND_OWN => b"own",
        WIN32_SERVICE_PROCESS_KIND_SHARED => b"shared",
        _ => b"none",
    }
}

fn copy_win32_service_launch_selection(
    spec: &nt_config_manager::Win32ServiceLaunchSpec,
    name: &mut InlineAscii<BOOT_DRIVER_SERVICE_NAME_MAX>,
    image_path: &mut InlineAscii<BOOT_DRIVER_IMAGE_PATH_MAX>,
    nt_image_path: &mut InlineAscii<BOOT_DRIVER_IMAGE_PATH_MAX>,
    command_line: &mut InlineAscii<BOOT_DRIVER_IMAGE_PATH_MAX>,
    process_kind: &mut u8,
    interactive: &mut bool,
) -> bool {
    let Ok(process_launch) = spec.process_launch() else {
        return false;
    };
    if !name.set_str(&spec.service_name)
        || !image_path.set_str(&spec.image_path)
        || !nt_image_path.set_str(&process_launch.nt_image_path)
        || !command_line.set_str(&process_launch.command_line)
    {
        return false;
    }
    *process_kind = win32_service_process_kind_code(spec.process_kind);
    *interactive = spec.interactive;
    true
}

fn copy_driver_service_selection(
    service: &nt_config_manager::DriverServiceLaunchSpec,
    name: &mut InlineAscii<BOOT_DRIVER_SERVICE_NAME_MAX>,
    image_path: &mut InlineAscii<BOOT_DRIVER_IMAGE_PATH_MAX>,
) -> bool {
    name.set_str(&service.service_name) && image_path.set_str(&service.image_path)
}

fn system_hive_service_selection_report() -> InlineServiceSelectionReport {
    let heap_mark = allocator::mark();
    let mut report = InlineServiceSelectionReport::empty();
    if let Some(cm) = system_hive_config_manager() {
        let auto_win32 = cm.auto_start_win32_service_launch_specs();
        report.auto_win32_count = auto_win32.len() as u64;
        if let Some(spec) = auto_win32.first() {
            let _ = copy_win32_service_launch_selection(
                spec,
                &mut report.auto_win32_name,
                &mut report.auto_win32_image_path,
                &mut report.auto_win32_nt_image_path,
                &mut report.auto_win32_command_line,
                &mut report.auto_win32_process_kind,
                &mut report.auto_win32_interactive,
            );
        }

        let demand_win32 = cm.demand_start_win32_service_launch_specs();
        report.demand_win32_count = demand_win32.len() as u64;
        if let Some(spec) = demand_win32.first() {
            let _ = copy_win32_service_launch_selection(
                spec,
                &mut report.demand_win32_name,
                &mut report.demand_win32_image_path,
                &mut report.demand_win32_nt_image_path,
                &mut report.demand_win32_command_line,
                &mut report.demand_win32_process_kind,
                &mut report.demand_win32_interactive,
            );
        }

        let demand_drivers = cm.demand_start_driver_launch_specs();
        report.demand_driver_count = demand_drivers.len() as u64;
        if let Some(service) = demand_drivers.first() {
            let _ = copy_driver_service_selection(
                service,
                &mut report.demand_driver_name,
                &mut report.demand_driver_image_path,
            );
            let _ = report
                .demand_driver_object_path
                .set_str(&service.driver_object_path);
        }
    }
    unsafe { allocator::reset_to(heap_mark) };
    report
}

fn system_hive_boot_driver_launch_plan() -> &'static InlineDriverLaunchPlan {
    let heap_mark = allocator::mark();
    let plan = unsafe { &mut *core::ptr::addr_of_mut!(SYSTEM_BOOT_DRIVER_PLAN) };
    *plan = InlineDriverLaunchPlan::empty();
    {
        if let Some(cm) = system_hive_config_manager() {
            for service in cm.boot_system_driver_candidates() {
                if !current_driver_host_can_boot_launch(&cm, &service) {
                    continue;
                }
                if let Some(spec) = inline_driver_launch_spec_from_service_metadata(
                    &cm,
                    &service,
                    SERVICE_SYSTEM_START,
                ) {
                    if !plan.push(spec) {
                        break;
                    }
                }
            }
        }
    }
    unsafe { allocator::reset_to(heap_mark) };
    plan
}

pub(crate) fn system_hive_driver_service_launch_spec(
    service_name: &str,
    max_start: u32,
) -> Option<DriverServiceLaunchSpec> {
    let cm = system_hive_config_manager()?;
    let nt_config_manager::ServiceStartSpec::Driver(service) =
        cm.service_start_spec(service_name)?
    else {
        return None;
    };
    let devnodes = driver_service_devnode_specs(&cm, service_name);
    owned_driver_launch_spec_from_config_driver_spec(service, max_start, devnodes)
}

pub(crate) fn system_hive_driver_service_object_path(
    service_name: &str,
    max_start: u32,
) -> Option<alloc::string::String> {
    let cm = system_hive_config_manager()?;
    let nt_config_manager::ServiceStartSpec::Driver(service) =
        cm.service_start_spec(service_name)?
    else {
        return None;
    };
    if service.start_type > max_start || service.start_type >= SERVICE_DISABLED {
        return None;
    };
    Some(service.driver_object_path)
}

fn registry_ascii_hex_digit(b: u8) -> bool {
    b.is_ascii_digit() || (b'a'..=b'f').contains(&b)
}

fn registry_layout_id_from_value(data: &[u8], out: &mut [u8]) -> Option<usize> {
    let mut tmp = [0u8; 16];
    let n = registry_utf16_ascii(data, &mut tmp)?;
    let src = &tmp[..n];
    if !src.iter().copied().all(registry_ascii_hex_digit) {
        return None;
    }
    match n {
        8 => {
            if out.len() < 8 {
                return None;
            }
            out[..8].copy_from_slice(src);
            Some(8)
        }
        4 => {
            if out.len() < 8 {
                return None;
            }
            out[..4].copy_from_slice(b"0000");
            out[4..8].copy_from_slice(src);
            Some(8)
        }
        _ => None,
    }
}

fn default_hive_keyboard_layout_id(out: &mut [u8]) -> Option<usize> {
    // DEFHIVEBUF is a fixed executive-lifetime mapping, and `default_hive_bytes` bounds the slice by
    // the storage-host reported hive size before exposing it.
    let hive = unsafe { writable_fs::default_hive_bytes() }.and_then(RegfHive::new)?;
    let key = hive.open_key("Keyboard Layout\\Preload")?;
    let value = hive.value(key, "1")?;
    registry_layout_id_from_value(&value.1, out)
}

fn system_hive_nls_keyboard_layout_id(out: &mut [u8]) -> Option<usize> {
    let hive = system_hive_regf()?;
    let key = hive.open_key("ControlSet001\\Control\\Nls\\Language")?;
    let value = hive.value(key, "Default")?;
    registry_layout_id_from_value(&value.1, out)
}

fn registry_keyboard_layout_id(out: &mut [u8]) -> Option<(usize, &'static [u8])> {
    if let Some(n) = default_hive_keyboard_layout_id(out) {
        return Some((n, b"default-preload"));
    }
    system_hive_nls_keyboard_layout_id(out).map(|n| (n, b"system-nls-default".as_slice()))
}

fn registry_driver_leaf_is_safe(leaf: &[u8]) -> bool {
    !leaf.is_empty()
        && leaf.iter().copied().all(|b| {
            b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'_' || b == b'-' || b == b'.'
        })
        && !leaf.windows(2).any(|w| w == b"..")
}

fn system_hive_keyboard_layout_file(layout_id: &[u8], out: &mut [u8]) -> Option<usize> {
    if layout_id.len() != 8 || !layout_id.iter().copied().all(registry_ascii_hex_digit) {
        return None;
    }
    let hive = system_hive_regf()?;
    let mut key_path = alloc::string::String::from("ControlSet001\\Control\\Keyboard Layouts\\");
    for &b in layout_id {
        key_path.push(b as char);
    }
    let key = hive.open_key(&key_path)?;
    let value = hive.value(key, "Layout File")?;
    let n = registry_utf16_ascii(&value.1, out)?;
    if !registry_driver_leaf_is_safe(&out[..n]) {
        return None;
    }
    Some(n)
}

const DISPLAY_SERVICE_NAME_CAP: usize = 32;
const DISPLAY_SERVICE_KEY_CAP: usize = 96;
const DISPLAY_REGISTRY_PATH_CAP: usize = 96;
const DISPLAY_DRIVER_VALUE_CAP: usize = 32;
const DISPLAY_DRIVER_LEAF_CAP: usize = 32;
const DISPLAY_DESCRIPTION_CAP: usize = 96;

struct SystemHiveDisplayDriverSpec {
    service_name: [u8; DISPLAY_SERVICE_NAME_CAP],
    service_name_len: usize,
    service_key_pattern: [u8; DISPLAY_SERVICE_KEY_CAP],
    service_key_pattern_len: usize,
    service_registry_path: [u8; DISPLAY_REGISTRY_PATH_CAP],
    service_registry_path_len: usize,
    installed_display_driver: [u8; DISPLAY_DRIVER_VALUE_CAP],
    installed_display_driver_len: usize,
    display_driver_leaf: [u8; DISPLAY_DRIVER_LEAF_CAP],
    display_driver_leaf_len: usize,
    device_description: [u8; DISPLAY_DESCRIPTION_CAP],
    device_description_len: usize,
    vga_compatible: u32,
}

impl SystemHiveDisplayDriverSpec {
    const fn empty() -> Self {
        Self {
            service_name: [0; DISPLAY_SERVICE_NAME_CAP],
            service_name_len: 0,
            service_key_pattern: [0; DISPLAY_SERVICE_KEY_CAP],
            service_key_pattern_len: 0,
            service_registry_path: [0; DISPLAY_REGISTRY_PATH_CAP],
            service_registry_path_len: 0,
            installed_display_driver: [0; DISPLAY_DRIVER_VALUE_CAP],
            installed_display_driver_len: 0,
            display_driver_leaf: [0; DISPLAY_DRIVER_LEAF_CAP],
            display_driver_leaf_len: 0,
            device_description: [0; DISPLAY_DESCRIPTION_CAP],
            device_description_len: 0,
            vga_compatible: 0,
        }
    }

    fn win32k_spec(&self) -> win32k_subsystem::DisplayRegistrySpec<'_> {
        win32k_subsystem::DisplayRegistrySpec {
            service_name: &self.service_name[..self.service_name_len],
            service_key_pattern: &self.service_key_pattern[..self.service_key_pattern_len],
            service_registry_path: &self.service_registry_path[..self.service_registry_path_len],
            installed_display_driver: &self.installed_display_driver
                [..self.installed_display_driver_len],
            display_driver_leaf: &self.display_driver_leaf[..self.display_driver_leaf_len],
            device_description: &self.device_description[..self.device_description_len],
            vga_compatible: self.vga_compatible,
            framebuffer_size: FB_SIZE_BYTES.load(Ordering::Relaxed),
            mode: win32k_subsystem::DisplayModeSpec {
                width: FB_WIDTH.load(Ordering::Relaxed) as u32,
                height: FB_HEIGHT.load(Ordering::Relaxed) as u32,
                stride: FB_SCANLINE.load(Ordering::Relaxed) as u32,
                bits_per_plane: FB_BITS_PER_PLANE.load(Ordering::Relaxed) as u32,
            },
        }
    }

    fn service_name(&self) -> &[u8] {
        &self.service_name[..self.service_name_len]
    }
}

static mut SYSTEM_HIVE_DISPLAY_DRIVER_SPEC: SystemHiveDisplayDriverSpec =
    SystemHiveDisplayDriverSpec::empty();
static SYSTEM_HIVE_DISPLAY_DRIVER_SPEC_READY: AtomicU64 = AtomicU64::new(0);

fn registry_copy_ascii_lower_str(s: &str, out: &mut [u8]) -> Option<usize> {
    if s.is_empty() || s.len() > out.len() {
        return None;
    }
    let mut n = 0usize;
    for b in s.bytes() {
        if !(b.is_ascii_alphanumeric() || b == b'_' || b == b'-') {
            return None;
        }
        out[n] = b.to_ascii_lowercase();
        n += 1;
    }
    Some(n)
}

fn registry_append_bytes(out: &mut [u8], mut pos: usize, bytes: &[u8]) -> Option<usize> {
    if pos + bytes.len() > out.len() {
        return None;
    }
    out[pos..pos + bytes.len()].copy_from_slice(bytes);
    pos += bytes.len();
    Some(pos)
}

fn registry_build_display_service_paths(
    service_name: &[u8],
    key_pattern: &mut [u8],
    registry_path: &mut [u8],
) -> Option<(usize, usize)> {
    let mut key_len =
        registry_append_bytes(key_pattern, 0, b"SYSTEM\\CURRENTCONTROLSET\\SERVICES\\")?;
    key_len = registry_append_bytes(key_pattern, key_len, service_name)?;
    key_len = registry_append_bytes(key_pattern, key_len, b"\\DEVICE0")?;

    let mut path_len = registry_append_bytes(
        registry_path,
        0,
        b"\\Registry\\Machine\\System\\CurrentControlSet\\Services\\",
    )?;
    path_len = registry_append_bytes(registry_path, path_len, service_name)?;
    path_len = registry_append_bytes(registry_path, path_len, b"\\Device0")?;
    Some((key_len, path_len))
}

fn registry_display_driver_leaf(installed_driver: &[u8], out: &mut [u8]) -> Option<usize> {
    if installed_driver.is_empty() || installed_driver.len() > out.len() {
        return None;
    }
    if !registry_driver_leaf_is_safe(installed_driver) {
        return None;
    }
    out[..installed_driver.len()].copy_from_slice(installed_driver);
    let mut n = installed_driver.len();
    if !installed_driver.contains(&b'.') {
        n = registry_append_bytes(out, n, b".dll")?;
    }
    if !registry_driver_leaf_is_safe(&out[..n]) {
        return None;
    }
    Some(n)
}

fn system_hive_display_driver_spec() -> Option<&'static SystemHiveDisplayDriverSpec> {
    if SYSTEM_HIVE_DISPLAY_DRIVER_SPEC_READY.load(Ordering::Relaxed) != 0 {
        return Some(unsafe { &*core::ptr::addr_of!(SYSTEM_HIVE_DISPLAY_DRIVER_SPEC) });
    }
    let hive = system_hive_regf()?;
    let services = hive.open_key("ControlSet001\\Services")?;
    for (service_name, service_key) in hive.subkeys(services) {
        let Some(device_key) = hive.open_key_from(service_key, "Device0") else {
            continue;
        };
        let Some(installed_value) = hive.value(device_key, "InstalledDisplayDrivers") else {
            continue;
        };
        let Some(description_value) = hive.value(device_key, "Device Description") else {
            continue;
        };
        let Some(vga_compatible) = hive
            .value(device_key, "VgaCompatible")
            .and_then(|(_, data)| registry_dword_from_bytes(&data))
        else {
            continue;
        };

        let spec = unsafe { &mut *core::ptr::addr_of_mut!(SYSTEM_HIVE_DISPLAY_DRIVER_SPEC) };
        *spec = SystemHiveDisplayDriverSpec::empty();
        let Some(service_name_len) =
            registry_copy_ascii_lower_str(&service_name, &mut spec.service_name)
        else {
            continue;
        };
        let Some(installed_len) =
            registry_utf16_ascii(&installed_value.1, &mut spec.installed_display_driver)
        else {
            continue;
        };
        let Some(display_leaf_len) = registry_display_driver_leaf(
            &spec.installed_display_driver[..installed_len],
            &mut spec.display_driver_leaf,
        ) else {
            continue;
        };
        if unsafe { !crate::fs_loader::sys32_exists(&spec.display_driver_leaf[..display_leaf_len]) }
        {
            continue;
        }
        let Some(description_len) =
            registry_utf16_ascii(&description_value.1, &mut spec.device_description)
        else {
            continue;
        };
        let Some((service_key_pattern_len, service_registry_path_len)) =
            registry_build_display_service_paths(
                &spec.service_name[..service_name_len],
                &mut spec.service_key_pattern,
                &mut spec.service_registry_path,
            )
        else {
            continue;
        };

        spec.service_name_len = service_name_len;
        spec.service_key_pattern_len = service_key_pattern_len;
        spec.service_registry_path_len = service_registry_path_len;
        spec.installed_display_driver_len = installed_len;
        spec.display_driver_leaf_len = display_leaf_len;
        spec.device_description_len = description_len;
        spec.vga_compatible = vga_compatible;
        SYSTEM_HIVE_DISPLAY_DRIVER_SPEC_READY.store(1, Ordering::Relaxed);
        return Some(unsafe { &*core::ptr::addr_of!(SYSTEM_HIVE_DISPLAY_DRIVER_SPEC) });
    }
    None
}

