/// Spawn the isolated user thread: its own VSpace (image RO + stack + IPC buffer),
/// its own CNode holding a cap to `fault_ep_c`, and its faults routed there (the
/// kernel's legacy TCBSetSpace resolves the fault cptr in the FAULTER's cspace).
unsafe fn spawn_user_thread(
    entry: unsafe extern "C" fn() -> !,
    fault_ep_c: u64,
    sysarg_c: u64,
    prio: u64,
    extra_ntfn: u64,
) -> u64 {
    let img_start = IMAGE_FRAMES_START.load(Ordering::Relaxed);
    let img_count = IMAGE_FRAMES_COUNT.load(Ordering::Relaxed);
    let pml4 = alloc_slot();
    let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_X86_PML4, PAGING_BITS, 1, pml4);
    map_image_skeleton(pml4, img_count);
    for i in 0..img_count {
        let cp = alloc_slot();
        let _ = syscall5(
            SYS_SEND,
            CAP_INIT_THREAD_CNODE,
            LBL_CNODE_COPY << 12,
            cp,
            img_start + i,
            0,
        );
        let _ = page_map(cp, IMAGE_BASE + i * 0x1000, /* RO */ 2, pml4);
    }
    for i in 0..STACK_FRAMES {
        let f = alloc_slot();
        let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_X86_4K_PAGE, PAGING_BITS, 1, f);
        let _ = page_map(f, STACK_BASE + i * 0x1000, RW_NX, pml4);
    }
    let ipcbuf = alloc_slot();
    let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_X86_4K_PAGE, PAGING_BITS, 1, ipcbuf);
    let _ = page_map(ipcbuf, IPCBUF_VADDR, RW_NX, pml4);
    // The shared syscall-arg frame, at the SAME vaddr as in the executive.
    let _ = page_map(sysarg_c, SYSARG_VADDR, RW_NX, pml4);
    let raw = alloc_slot();
    let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_CNODE, CN_RADIX, 1, raw);
    let cnode = alloc_slot();
    let _ = syscall5(
        SYS_SEND,
        CAP_INIT_THREAD_CNODE,
        LBL_CNODE_MINT << 12,
        cnode,
        raw,
        CN_GUARD_BADGE,
    );
    let _ = syscall5(SYS_SEND, cnode, LBL_CNODE_COPY << 12, CT_PML4, pml4, 0);
    let _ = syscall5(
        SYS_SEND,
        cnode,
        LBL_CNODE_COPY << 12,
        CT_FAULT,
        fault_ep_c,
        0,
    );
    // A waiter thread gets a cap to the notification it parks on; others don't (least priv).
    if extra_ntfn != 0 {
        let _ = syscall5(
            SYS_SEND,
            cnode,
            LBL_CNODE_COPY << 12,
            CT_WAIT_NTFN,
            extra_ntfn,
            0,
        );
    }
    let tcb = alloc_slot();
    let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_TCB, 0, 1, tcb);
    let _ = tcb_set_space(tcb, CT_FAULT, cnode, pml4);
    let _ = syscall5(
        SYS_SEND,
        tcb,
        LBL_TCB_SET_IPC_BUFFER << 12,
        IPCBUF_VADDR,
        ipcbuf,
        0,
    );
    let stack_top = STACK_BASE + STACK_FRAMES * 0x1000 - 16;
    let _ = tcb_write_registers(tcb, entry as u64, stack_top, 0);
    let _ = tcb_set_priority(tcb, prio);
    if let Err(e_sc) = attach_sched_context(tcb) {
        print_str(b"[thread-life] initial SC attach failed tcb=0x");
        print_hex(tcb as u32);
        print_str(b" error=");
        print_u64(e_sc);
        print_str(b"\n");
        park();
    }
    let _ = tcb_resume(tcb);
    pml4 // the executive keeps this cap to map on-demand NtAllocateVirtualMemory frames
}

/// Create a NEW thread in an EXISTING VSpace `pml4` (NtCreateThreadEx): a fresh stack + IPC
/// buffer + CNode (fault ep) at bumped user vaddrs, starting at `entry`. The thread shares the
/// caller's address space (so it sees the caller's mappings). Returns the TCB cap.
unsafe fn spawn_thread_in(pml4: u64, entry: u64) -> u64 {
    let stack_base = NEXT_USER_VADDR.fetch_add(0x4000, Ordering::Relaxed);
    for i in 0..4u64 {
        let _ = page_map(alloc_frame(), stack_base + i * 0x1000, RW_NX, pml4);
    }
    let ipcbuf_va = NEXT_USER_VADDR.fetch_add(0x1000, Ordering::Relaxed);
    let ipcbuf = alloc_frame();
    let _ = page_map(ipcbuf, ipcbuf_va, RW_NX, pml4);
    let fault_ep = make_object(OBJ_ENDPOINT);
    let raw = alloc_slot();
    let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_CNODE, CN_RADIX, 1, raw);
    let cnode = alloc_slot();
    let _ = syscall5(
        SYS_SEND,
        CAP_INIT_THREAD_CNODE,
        LBL_CNODE_MINT << 12,
        cnode,
        raw,
        CN_GUARD_BADGE,
    );
    let _ = syscall5(SYS_SEND, cnode, LBL_CNODE_COPY << 12, CT_PML4, pml4, 0);
    let _ = syscall5(
        SYS_SEND,
        cnode,
        LBL_CNODE_COPY << 12,
        CT_FAULT,
        copy_cap(fault_ep),
        0,
    );
    let tcb = alloc_slot();
    let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_TCB, 0, 1, tcb);
    let _ = tcb_set_space(tcb, CT_FAULT, cnode, pml4);
    let _ = syscall5(
        SYS_SEND,
        tcb,
        LBL_TCB_SET_IPC_BUFFER << 12,
        ipcbuf_va,
        ipcbuf,
        0,
    );
    let _ = tcb_write_registers(tcb, entry, stack_base + 0x4000 - 16, 0);
    let _ = tcb_set_priority(tcb, 100);
    if let Err(e_sc) = attach_sched_context(tcb) {
        print_str(b"[thread-life] legacy SC attach failed tcb=0x");
        print_hex(tcb as u32);
        print_str(b" error=");
        print_u64(e_sc);
        print_str(b"\n");
        park();
    }
    let _ = tcb_resume(tcb);
    tcb
}

/// Parameters describing a hosted second thread for [`spawn_hosted_thread`]. All VAs in the
/// `*_va`/`*_base` fields live in the TARGET process's VSpace (`pml4`) except `scr` and
/// `stack_mirror_va`, which are in the EXECUTIVE's VSpace (`CAP_INIT_THREAD_VSPACE`).
#[derive(Clone, Copy)]
struct LoaderThreadContext {
    loader_va: u64,
    start: nt_thread_start::Amd64ThreadContext,
    initial_teb: nt_thread_start::InitialTeb64,
}

struct HostedThread {
    /// The target process's VSpace (PML4) cap — the thread runs here, sharing the main thread's
    /// image/ntdll/PEB/KUSER mappings.
    pml4: u64,
    /// Hosted-process index owning this address space. Non-zero GUI clients publish their stack
    /// frames for win32k's per-client identity attach; zero is smss and has no win32k attachment.
    client_pi: u64,
    /// The thread's instruction pointer and first two Windows x64 argument registers.
    entry_rip: u64,
    arg0: u64,
    arg1: u64,
    /// Native loader initialization state. `None` retains the direct-entry trampoline.
    loader_context: Option<LoaderThreadContext>,
    /// Executive-side scratch base (≥ 3 pages: TEB, TEB2/ACS, trampoline) used to write the env
    /// before the frames are mapped into `pml4`.
    scr: u64,
    /// TEB base VA (2 pages), stack base VA + frame count, IPC buffer VA, trampoline VA — all in `pml4`.
    teb_va: u64,
    stack_base: u64,
    stack_frames: u64,
    ipcbuf_va: u64,
    tramp_va: u64,
    /// The shared PEB VA (the process's PEB, mapped by the main thread's spawn).
    peb_va: u64,
    /// Executive-side stack-mirror base (`0` = don't mirror). Only threads driven by a nested
    /// rendezvous that writes their syscall out-params need a mirror (SM/CSR); a park-only thread
    /// (the RPC listener) needs none.
    stack_mirror_va: u64,
    /// The dedicated fault endpoint this thread faults to (no standing receiver → it PARKS until a
    /// rendezvous drives it, or forever for a park-only listener).
    fault_ep: u64,
    /// The `ClientId` written into the TEB (`0,0` leaves the TEB's zero-fill).
    cid_proc: u64,
    cid_thread: u64,
    /// Resume immediately (SM/listener) or leave suspended for a lazy rendezvous-time resume (CSR).
    resume: bool,
    /// Scheduling priority (default 100). The services RPC listener uses a value above the hosted
    /// processes so that, once services' main thread parks (NtTerminateThread), the listener is the
    /// highest runnable thread → it faults into the main multiplex (proving the N-threads mechanism).
    prio: u8,
    /// NATIVE seL4-Call transport (ntdll_plan Step 6.A / BATCH 6). When set, this thread runs on
    /// OUR ntdll's native transport: its explicit `Call(CT_FAULT, label=0x4E54)` dispatches natively
    /// with MR0=SSN even though the thread also has rust-micro's hosted-syscalls flag. Raw ReactOS DLL
    /// syscall stubs still fault as NT syscalls. Every thread owns a distinct IPC frame at `ipcbuf_va`;
    /// ntdll derives that VA from the active TEB through `gs:[0x30]`.
    native: bool,
    /// BATCH 36 DIAG: when true, `spawn_hosted_thread` uses the SYS_CALL/`_r` variants for the
    /// resource-critical invocations (retype/copy/map/set_space/write_registers/set_ipc/resume)
    /// and PRINTS every non-zero error label — to surface the silent SYS_SEND failure that leaves
    /// the 3rd hosted thread with a bad RSP/RIP (cr2=0 trampoline fault). Off = fire-and-forget.
    diag: bool,
}

/// Spawn a REAL 2nd (or Nth) thread in a hosted process's VSpace — the GENERAL hosted-thread
/// mechanism behind `NtCreateThread`. It builds the full hosted-Windows-thread env (own TEB + GS
/// base, StaticUnicodeString, an ACTIVATION_CONTEXT_STACK, an IPC buffer, the hosted-syscalls flag,
/// a dedicated fault EP, a stack, an SC) — a trimmed `spawn_sec_image` (the image/ntdll/PEB/KUSER are
/// already mapped, shared with the main thread) — then a trampoline that restores RCX/RDX and
/// `call`s the context RIP (`call` keeps rsp ≡ 8 mod 16 at entry; the trailing jmp$ is a net).
/// Returns the TCB cap. This is the single path the SM-loop / CSR-API / RPC-listener
/// spawns all express (see the thin wrappers below).
unsafe fn spawn_hosted_thread(t: &HostedThread) -> HostedThreadSpawnResult {
    let scr = t.scr;
    let resource_pi = t.client_pi as usize;
    let resource_slot = hosted_tp_worker_slot_from_layout(
        resource_pi,
        t.stack_base,
        t.teb_va,
        t.ipcbuf_va,
        t.tramp_va,
    );
    let mut window_resources = HostedTpWorkerWindowResources::empty();
    if resource_slot.is_some() {
        window_resources.live = true;
    }
    if t.stack_mirror_va != 0 {
        let pt_base = t.stack_mirror_va & !0x1f_ffffu64;
        let dynamic_base = SVC_LISTENER_STACK_MIRROR_VA & !0x1f_ffffu64;
        // Low SM/CSR mirrors already live in FILEBUF's page table. Only create page tables for the
        // dedicated high mirror window; checked_sub prevents low addresses wrapping the bit index.
        if let Some(offset) = pt_base.checked_sub(dynamic_base) {
            let pt_index = (offset >> 21) as u32;
            if pt_index < 64 {
                let bit = 1u64 << pt_index;
                if HOSTED_STACK_MIRROR_PT_BITS.fetch_or(bit, Ordering::Relaxed) & bit == 0 {
                    let pt = alloc_slot();
                    let _ =
                        untyped_retype(CAP_INIT_UNTYPED, OBJ_X86_PAGE_TABLE, PAGING_BITS, 1, pt);
                    let _ = paging_struct_map(
                        pt,
                        LBL_X86_PAGE_TABLE_MAP,
                        pt_base,
                        CAP_INIT_THREAD_VSPACE,
                    );
                }
            }
        }
    }
    // Stack, mapped into the target VSpace AND (optionally) mirrored into the executive for a
    // rendezvous's out-param copyout. GUI-client stacks must also be discoverable by win32k's
    // KeStackAttachProcess model. Without this registration, a pointer to a worker's stack local
    // faults in win32k and is incorrectly backed by a fresh unrelated page.
    for i in 0..t.stack_frames {
        let f = alloc_frame();
        let page = t.stack_base + i * 0x1000;
        let target_cap = copy_cap(f);
        page_map(target_cap, page, RW_NX, t.pml4);
        let mut mirror_cap = 0;
        if t.stack_mirror_va != 0 {
            mirror_cap = copy_cap(f);
            page_map(
                mirror_cap,
                t.stack_mirror_va + i * 0x1000,
                RW_NX,
                CAP_INIT_THREAD_VSPACE,
            );
        }
        if window_resources.live && (i as usize) < TP_WORKER_STACK_FRAME_COUNT {
            let index = i as usize;
            window_resources.stack_owner[index] = f;
            window_resources.stack_target[index] = target_cap;
            window_resources.stack_mirror[index] = mirror_cap;
        }
        if t.client_pi != 0 {
            csrss_frame_put(t.client_pi, page, f);
        }
    }
    // TEB page 1: self@0x30, ClientId@0x40/0x48, PEB@0x60 (shared), StackBase@0x08/StackLimit@0x10,
    // ActivationContextStackPointer@0x2C8 → an empty ACS in the 2nd TEB page.
    let teb = alloc_frame();
    let teb_client = copy_cap(teb);
    let teb_scratch = copy_cap(teb);
    let teb_live_mirror = copy_cap(teb);
    let teb_target_map = page_map(teb_client, t.teb_va, RW_NX, t.pml4);
    let teb_live_alias = if t.client_pi != 0 && t.stack_mirror_va != 0 {
        t.stack_mirror_va + t.stack_frames * 0x1000
    } else {
        0
    };
    let teb_scratch_map = page_map(teb_scratch, scr, RW_NX, CAP_INIT_THREAD_VSPACE);
    let teb_live_map = if teb_live_alias != 0 {
        page_map(
            teb_live_mirror,
            teb_live_alias,
            RW_NX,
            CAP_INIT_THREAD_VSPACE,
        )
    } else {
        0
    };
    if window_resources.live {
        window_resources.teb_owner = teb;
        window_resources.teb_target = teb_client;
        window_resources.teb_scratch = teb_scratch;
    }
    if t.client_pi != 0 {
        let source_cap =
            csrss_frame_create_source_copy(teb_client, t.client_pi, t.teb_va, b"thread-teb");
        let alias = if teb_live_map == 0 { teb_live_alias } else { 0 };
        let alias_cap = if teb_live_map == 0 {
            teb_live_mirror
        } else {
            0
        };
        let registered = source_cap != 0
            && csrss_frame_put_at_cap_source(
                t.client_pi,
                t.teb_va,
                teb_client,
                alias,
                alias_cap,
                source_cap,
            );
        if registered {
            csrss_frame_probe_source_copy(t.client_pi, t.teb_va, source_cap, b"thread-teb");
        } else {
            if source_cap != 0 {
                let _ = cnode_delete_recycle_r(source_cap);
            }
            print_str(b"[thread-life] failed to register thread TEB client frame pi=");
            print_u64(t.client_pi);
            print_str(b" page=0x");
            print_hex((t.teb_va >> 32) as u32);
            print_hex(t.teb_va as u32);
            print_str(b"\n");
        }
    }
    core::ptr::write_volatile((scr + 0x30) as *mut u64, t.teb_va);
    core::ptr::write_volatile((scr + 0x40) as *mut u64, t.cid_proc);
    core::ptr::write_volatile((scr + 0x48) as *mut u64, t.cid_thread);
    core::ptr::write_volatile((scr + 0x60) as *mut u64, t.peb_va);
    let (teb_stack_base, teb_stack_limit, deallocation_stack) = match t.loader_context {
        Some(loader) => (
            loader.initial_teb.stack_base,
            loader.initial_teb.stack_limit,
            loader.initial_teb.allocated_stack_base,
        ),
        None => (
            t.stack_base + t.stack_frames * 0x1000,
            t.stack_base,
            t.stack_base,
        ),
    };
    core::ptr::write_volatile((scr + 0x08) as *mut u64, teb_stack_base);
    core::ptr::write_volatile((scr + 0x10) as *mut u64, teb_stack_limit);
    // ★ The ACTIVATION_CONTEXT_STACK gets its OWN private page, one past the two TEB pages — it
    // must not share a page with the TEB. Both TEB pages are registered as client frames
    // (`csrss_frame_put`) so a win32k fault at either is answered with THIS client's frame (the
    // KeStackAttachProcess model); anything win32k writes at those VAs lands in the client's real
    // TEB. Measured (batch 53) on winlogon's main thread: the whole 2nd TEB page came back
    // overwritten with USER server-side data, so the ACS that used to live at TEB+0x1800 held the
    // non-pointer `ActiveFrame = 0x0000_0006_0010_0000`. Real NT keeps this structure on the heap.
    let acs_va = t.teb_va + 0x2000;
    core::ptr::write_volatile((scr + 0x2c8) as *mut u64, acs_va);
    // TEB page 2: StaticUnicodeString (MaximumLength=522, Buffer in TEB) + DeallocationStack.
    let teb2 = alloc_frame();
    let teb2_client = copy_cap(teb2);
    let teb2_scratch = copy_cap(teb2);
    let teb2_live_mirror = copy_cap(teb2);
    let teb2_target_map = page_map(teb2_client, t.teb_va + 0x1000, RW_NX, t.pml4);
    let teb2_live_alias = if t.client_pi != 0 && t.stack_mirror_va != 0 {
        t.stack_mirror_va + (t.stack_frames + 1) * 0x1000
    } else {
        0
    };
    let teb2_scratch_map = page_map(teb2_scratch, scr + 0x1000, RW_NX, CAP_INIT_THREAD_VSPACE);
    // DeallocationStack is in TEB page 2; populate it only after its scratch alias is mapped.
    core::ptr::write_volatile((scr + 0x1478) as *mut u64, deallocation_stack);
    let teb2_live_map = if teb2_live_alias != 0 {
        page_map(
            teb2_live_mirror,
            teb2_live_alias,
            RW_NX,
            CAP_INIT_THREAD_VSPACE,
        )
    } else {
        0
    };
    if window_resources.live {
        window_resources.teb2_owner = teb2;
        window_resources.teb2_target = teb2_client;
        window_resources.teb2_scratch = teb2_scratch;
    }
    if t.client_pi != 0 {
        let source_cap = csrss_frame_create_source_copy(
            teb2_client,
            t.client_pi,
            t.teb_va + 0x1000,
            b"thread-teb-tail",
        );
        let alias = if teb2_live_map == 0 {
            teb2_live_alias
        } else {
            0
        };
        let alias_cap = if teb2_live_map == 0 {
            teb2_live_mirror
        } else {
            0
        };
        let registered = source_cap != 0
            && csrss_frame_put_at_cap_source(
                t.client_pi,
                t.teb_va + 0x1000,
                teb2_client,
                alias,
                alias_cap,
                source_cap,
            );
        if registered {
            csrss_frame_probe_source_copy(
                t.client_pi,
                t.teb_va + 0x1000,
                source_cap,
                b"thread-teb-tail",
            );
        } else {
            if source_cap != 0 {
                let _ = cnode_delete_recycle_r(source_cap);
            }
            print_str(b"[thread-life] failed to register thread TEB tail client frame pi=");
            print_u64(t.client_pi);
            print_str(b" page=0x");
            let page = t.teb_va + 0x1000;
            print_hex((page >> 32) as u32);
            print_hex(page as u32);
            print_str(b"\n");
        }
        // Read-only to win32k + copy-on-write on the first store (`W32_CLIENT_TEB_TAIL_PROTECTED`).
        teb_tail_register(t.teb_va + 0x1000);
    }
    // The private ACS page: written through its own scratch alias, then mapped at `acs_va` in the
    // target VSpace. Deliberately NOT `csrss_frame_put`-registered — win32k has no business with a
    // thread's activation-context stack, and not registering it means a win32k fault at that VA can
    // never be answered with this page.
    let acs_frame = alloc_frame();
    let acs_scratch_map = page_map(acs_frame, scr + 0x4000, RW_NX, CAP_INIT_THREAD_VSPACE);
    let acs = scr + 0x4000;
    core::ptr::write_volatile((acs + 0x00) as *mut u64, 0);
    core::ptr::write_volatile((acs + 0x08) as *mut u64, acs_va + 0x08);
    core::ptr::write_volatile((acs + 0x10) as *mut u64, acs_va + 0x08);
    core::ptr::write_volatile((acs + 0x18) as *mut u32, 0);
    core::ptr::write_volatile((acs + 0x1c) as *mut u32, 1);
    core::ptr::write_volatile((acs + 0x20) as *mut u32, 1);
    let acs_target_cap = copy_cap(acs_frame);
    let acs_target_map = page_map(acs_target_cap, acs_va, RW_NX, t.pml4);
    if window_resources.live {
        window_resources.acs_owner = acs_frame;
        window_resources.acs_target = acs_target_cap;
    }
    if acs_scratch_map != 0 || acs_target_map != 0 {
        print_str(b"[thread-life] ACS map failure scratch/target=");
        print_u64(acs_scratch_map);
        print_str(b"/");
        print_u64(acs_target_map);
        print_str(b"\n");
    }
    core::ptr::write_volatile((scr + 0x1000 + 0x25a) as *mut u16, 522); // StaticUnicodeString.MaximumLength
    core::ptr::write_volatile((scr + 0x1000 + 0x260) as *mut u64, t.teb_va + 0x1268); // .Buffer
    seed_teb_tail_canary(scr + 0x1000);
    if teb_target_map != 0
        || teb_scratch_map != 0
        || teb_live_map != 0
        || teb2_target_map != 0
        || teb2_scratch_map != 0
        || teb2_live_map != 0
    {
        print_str(b"[thread-life] TEB map failure target/scratch/live=");
        print_u64(teb_target_map);
        print_str(b"/");
        print_u64(teb_scratch_map);
        print_str(b"/");
        print_u64(teb_live_map);
        print_str(b" second=");
        print_u64(teb2_target_map);
        print_str(b"/");
        print_u64(teb2_scratch_map);
        print_str(b"/");
        print_u64(teb2_live_map);
        print_str(b"\n");
    }
    // Every hosted thread gets a distinct IPC frame. Native ntdll derives `ipcbuf_va` from the
    // active TEB; trap threads use the same binding directly through the kernel fault transport.
    let ipcbuf = alloc_frame();
    let e_ipc_target_map = if t.diag {
        page_map_r(ipcbuf, t.ipcbuf_va, RW_NX, t.pml4)
    } else {
        page_map(ipcbuf, t.ipcbuf_va, RW_NX, t.pml4)
    };
    if window_resources.live {
        window_resources.ipc_target = ipcbuf;
    }
    // Trampoline: restore the Windows x64 thread-entry ABI, then call CONTEXT.Rip.
    let (tramp, e_tramp_frame) = if t.diag {
        alloc_frame_r()
    } else {
        (alloc_frame(), 0)
    };
    let e_tramp_exec_map = if t.diag {
        page_map_r(tramp, scr + 0x2000, RW_NX, CAP_INIT_THREAD_VSPACE)
    } else {
        page_map(tramp, scr + 0x2000, RW_NX, CAP_INIT_THREAD_VSPACE)
    };
    if let Some(loader) = t.loader_context {
        const CONTEXT_OFFSET: u64 = 0x1900;
        let context_scratch = scr + CONTEXT_OFFSET;
        let context_target = t.teb_va + CONTEXT_OFFSET;
        core::ptr::write_volatile(
            (context_scratch + nt_thread_start::CONTEXT_RCX_OFFSET) as *mut u64,
            loader.start.rcx,
        );
        core::ptr::write_volatile(
            (context_scratch + nt_thread_start::CONTEXT_RDX_OFFSET) as *mut u64,
            loader.start.rdx,
        );
        core::ptr::write_volatile(
            (context_scratch + nt_thread_start::CONTEXT_RSP_OFFSET) as *mut u64,
            loader.start.rsp,
        );
        core::ptr::write_volatile(
            (context_scratch + nt_thread_start::CONTEXT_RIP_OFFSET) as *mut u64,
            loader.start.rip,
        );
        let tb = nt_thread_start::Amd64ThreadContext::loader_trampoline(
            loader.loader_va,
            NTDLL_BASE,
            context_target,
        );
        for (j, &b) in tb.iter().enumerate() {
            core::ptr::write_volatile((scr + 0x2000 + j as u64) as *mut u8, b);
        }
    } else {
        let tb = nt_thread_start::Amd64ThreadContext {
            rip: t.entry_rip,
            rsp: 0,
            rcx: t.arg0,
            rdx: t.arg1,
        }
        .call_trampoline();
        for (j, &b) in tb.iter().enumerate() {
            core::ptr::write_volatile((scr + 0x2000 + j as u64) as *mut u8, b);
        }
    }
    let tramp_tgt_cap = copy_cap(tramp);
    let e_tramp_tgt_map = if t.diag {
        page_map_r(tramp_tgt_cap, t.tramp_va, /* RX */ 2, t.pml4)
    } else {
        page_map(tramp_tgt_cap, t.tramp_va, /* RX */ 2, t.pml4)
    };
    if window_resources.live {
        window_resources.tramp_owner = tramp;
        window_resources.tramp_target = tramp_tgt_cap;
    }
    if let Some(slot) = resource_slot {
        store_hosted_tp_worker_window_resources(resource_pi, slot, window_resources);
    }
    if t.diag {
        // Read the FIRST 8 bytes back through what we WROTE (executive alias) AND through a FRESH,
        // independent alias of the SAME `tramp` frame mapped at a throwaway VA — if these disagree, the
        // executive-side write and the target map are hitting DIFFERENT physical frames (the silent
        // SYS_SEND alias-map failure that leaves the target trampoline zero-filled → cr2=0 at entry).
        let wrote = core::ptr::read_volatile((scr + 0x2000) as *const u64);
        let verify_va = scr + 0x3000; // 4th page of this thread's scratch PT — unused, same PT so mapped
        let fresh = copy_cap(tramp);
        let e_fresh = page_map_r(fresh, verify_va, RW_NX, CAP_INIT_THREAD_VSPACE);
        let via_fresh = if e_fresh == 0 {
            core::ptr::read_volatile(verify_va as *const u64)
        } else {
            0xDEAD_DEAD_DEAD_DEADu64
        };
        print_str(b"[spawn-diag] tramp_frame_retype=");
        print_u64(e_tramp_frame);
        print_str(b" exec_map=");
        print_u64(e_tramp_exec_map);
        print_str(b" tgt_map=");
        print_u64(e_tramp_tgt_map);
        print_str(b" fresh_map=");
        print_u64(e_fresh);
        print_str(b"\n[spawn-diag] tramp[0..8] wrote=0x");
        print_hex((wrote >> 32) as u32);
        print_hex(wrote as u32);
        print_str(b" via_fresh_alias=0x");
        print_hex((via_fresh >> 32) as u32);
        print_hex(via_fresh as u32);
        print_str(b" (must match; expect 0x...48b9)\n");
    }
    // CNode (PML4 + the dedicated fault EP) + TCB.
    let Some(raw) = try_alloc_slot() else {
        if let Some(slot) = resource_slot {
            release_hosted_tp_worker_window_resources(resource_pi, slot);
        }
        return HostedThreadSpawnResult::failed();
    };
    let e_cn = untyped_retype_r(CAP_INIT_UNTYPED, OBJ_CNODE, CN_RADIX, 1, raw);
    if e_cn != 0 {
        recycle_deleted_root_slot(raw);
        if let Some(slot) = resource_slot {
            release_hosted_tp_worker_window_resources(resource_pi, slot);
        }
        return HostedThreadSpawnResult::failed();
    }
    let Some(cnode) = try_alloc_slot() else {
        let _ = cnode_delete_recycle_r(raw);
        if let Some(slot) = resource_slot {
            release_hosted_tp_worker_window_resources(resource_pi, slot);
        }
        return HostedThreadSpawnResult::failed();
    };
    let e_cnode_mint = cnode_mint_r(CAP_INIT_THREAD_CNODE, cnode, raw, CN_GUARD_BADGE);
    if e_cnode_mint != 0 {
        recycle_deleted_root_slot(cnode);
        let _ = cnode_delete_recycle_r(raw);
        if let Some(slot) = resource_slot {
            release_hosted_tp_worker_window_resources(resource_pi, slot);
        }
        return HostedThreadSpawnResult::failed();
    }
    let e_cnode_pml4 = cnode_copy_at_r(cnode, CT_PML4, t.pml4);
    let e_cnode_fault = cnode_copy_at_r(cnode, CT_FAULT, t.fault_ep);
    if e_cnode_pml4 != 0 || e_cnode_fault != 0 {
        let _ = cnode_delete_recycle_r(cnode);
        let _ = cnode_delete_recycle_r(raw);
        if let Some(slot) = resource_slot {
            release_hosted_tp_worker_window_resources(resource_pi, slot);
        }
        return HostedThreadSpawnResult::failed();
    }
    let Some(tcb) = try_alloc_slot() else {
        let _ = cnode_delete_recycle_r(cnode);
        let _ = cnode_delete_recycle_r(raw);
        if let Some(slot) = resource_slot {
            release_hosted_tp_worker_window_resources(resource_pi, slot);
        }
        return HostedThreadSpawnResult::failed();
    };
    let new_sp = t.stack_base + t.stack_frames * 0x1000 - 16;
    let e_tcb = untyped_retype_r(CAP_INIT_UNTYPED, OBJ_TCB, 0, 1, tcb);
    let e_space = if e_tcb == 0 {
        tcb_set_space_r(tcb, CT_FAULT, cnode, t.pml4)
    } else {
        u64::MAX
    };
    let e_ipc = if e_tcb == 0 && e_space == 0 {
        tcb_set_ipc_buffer_r(tcb, t.ipcbuf_va, ipcbuf)
    } else {
        u64::MAX
    };
    let e_regs = if e_tcb == 0 && e_space == 0 && e_ipc == 0 {
        tcb_write_registers_r(tcb, t.tramp_va, new_sp, 0)
    } else {
        u64::MAX
    };
    if e_tcb != 0 || e_space != 0 || e_ipc != 0 || e_regs != 0 {
        if e_tcb == 0 {
            let _ = cnode_delete_recycle_r(tcb);
        } else {
            recycle_deleted_root_slot(tcb);
        }
        let _ = cnode_delete_recycle_r(cnode);
        let _ = cnode_delete_recycle_r(raw);
        if let Some(slot) = resource_slot {
            release_hosted_tp_worker_window_resources(resource_pi, slot);
        }
        return HostedThreadSpawnResult::failed();
    }
    let _ = tcb_set_gs_base(tcb, t.teb_va);
    let _ = tcb_set_priority(tcb, if t.prio != 0 { t.prio as u64 } else { 100 });
    if t.diag {
        print_str(b"[spawn-diag] tcb=0x");
        print_hex(tcb as u32);
        print_str(b" cnode_retype=");
        print_u64(e_cn);
        print_str(b" tcb_retype=");
        print_u64(e_tcb);
        print_str(b" set_space=");
        print_u64(e_space);
        print_str(b" ipc_map=");
        print_u64(e_ipc_target_map);
        print_str(b" set_ipc=");
        print_u64(e_ipc);
        print_str(b" write_regs=");
        print_u64(e_regs);
        print_str(b"\n[spawn-diag] tramp_va=0x");
        print_hex((t.tramp_va >> 32) as u32);
        print_hex(t.tramp_va as u32);
        print_str(b" new_sp=0x");
        print_hex((new_sp >> 32) as u32);
        print_hex(new_sp as u32);
        print_str(b" pml4=0x");
        print_hex(t.pml4 as u32);
        print_str(b" ipcbuf=0x");
        print_hex(ipcbuf as u32);
        print_str(b" fault_ep=0x");
        print_hex(t.fault_ep as u32);
        print_str(b"\n");
    }
    // Transport (ntdll_plan Step 6.A / BATCH 6): all hosted Windows threads get the hosted-syscalls
    // flag. rust-micro now treats it as hybrid: OUR ntdll's `Call(CT_FAULT, label=0x4E54)` envelope
    // still dispatches natively (MR0=SSN), while raw ReactOS DLL syscall stubs fault to the executive
    // instead of colliding with seL4 syscall numbers such as `GWLP_WNDPROC=-4`.
    const LBL_TCB_SET_HOSTED_SYSCALLS: u64 = 66;
    let _native_transport = t.native;
    let _ = syscall5(SYS_SEND, tcb, LBL_TCB_SET_HOSTED_SYSCALLS << 12, 0, 0, 0);
    let sched_context = match attach_sched_context(tcb) {
        Ok(sc) => sc,
        Err(e_sc) => {
            print_str(b"[thread-life] hosted SC attach failed tcb=0x");
            print_hex(tcb as u32);
            print_str(b" error=");
            print_u64(e_sc);
            print_str(b"\n");
            let _ = cnode_delete_recycle_r(tcb);
            let _ = cnode_delete_recycle_r(cnode);
            let _ = cnode_delete_recycle_r(raw);
            if let Some(slot) = resource_slot {
                release_hosted_tp_worker_window_resources(resource_pi, slot);
            }
            return HostedThreadSpawnResult::failed();
        }
    };
    if t.resume {
        let _ = tcb_resume(tcb);
    }
    HostedThreadSpawnResult::new(
        tcb,
        HostedThreadMechanismCaps::new(raw, cnode, sched_context),
    )
}

